INSERT INTO `curriculum_contenidos` (`espacio_id`, `tipo`, `titulo`, `descripcion`, `fuente`, `vigente`, `meta`, `indicadores`, `pagina`) VALUES
(1, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis, en intercambios orales, de enunciados que expresan puntos de vista referidos a problemáticas de la convivencia en el aula y en la escuela.', 'pda_2025', 1, 'Poner en juego convenciones genéricas y estrategias de cortesía en intercambios orales sobre problemáticas cotidianas.', '["Escucha y expresa puntos de vista sobre situaciones relativas a la convivencia escolar.","Consulta en reglamentos de convivencia escolar los enunciados asertivos o negativos, el vocabulario para expresar aserción y prohibición, el modo y tiempo de los verbos, y el uso de hiperónimos y otras expresiones generalizadoras.","Contrasta el texto del reglamento con la situación objeto de análisis.","Revisa puntos de vista a partir de la lectura del texto."]', 'PdA p. 82'),
(1, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reflexión sobre el impacto del uso de estrategias verbales de cortesía.', 'pda_2025', 1, 'Poner en juego convenciones genéricas y estrategias de cortesía en intercambios orales sobre problemáticas cotidianas.', '["Emplea variados conectores de causa y consecuencia.","Identifica recursos verbales de cortesía en enunciados ajenos, en particular, el uso del condicional y de diminutivos."]', 'PdA p. 82'),
(1, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interpretación de textos literarios fundada tanto en transformaciones narrativas como en criterios genéricos (subgéneros a partir del eje de lo real: realista, fantástico, maravilloso, entre otros).', 'pda_2025', 1, 'Leer obras literarias de diversos subgéneros, seleccionados a partir del eje de lo real, y poner en juego conocimientos sobre procedimientos literarios, en la definición de preferencias y el establecimiento de relaciones con otros lenguajes artísticos.', '["Lee y escucha leer textos de diversos subgéneros literarios narrativos propuestos por la/el docente.","Formula hipótesis en el marco de conversaciones literarias y relee partes del texto para fundamentar y revisar interpretaciones.","Reconoce el efecto estético de recursos que generan suspenso o sorpresa (como la dosificación de la información en el subgénero policial, inversiones narrativas en el subgénero maravilloso o finales abiertos en el fantástico).","Localiza los indicios que anticipan el avance narrativo y el desenlace.","Identifica el orden narrativo en la organización de sagas, a partir de precuelas y secuelas.","Explica cambios y permanencias en personajes de novelas y sagas."]', 'PdA p. 85'),
(1, 'eje_contenido', 'Progresiones de Aprendizaje', 'Exploración de las posibilidades estéticas y expresivas de recursos del plano sonoro en textos poéticos.', 'pda_2025', 1, 'Leer obras literarias de diversos subgéneros, seleccionados a partir del eje de lo real, y poner en juego conocimientos sobre procedimientos literarios, en la definición de preferencias y el establecimiento de relaciones con otros lenguajes artísticos.', '["Lee textos poéticos propuestos por la/el docente, seleccionados a partir de la inclusión de recursos del plano sonoro (aliteración, repetición, rima, versificación, entre otros).","Comparte, en conversaciones sobre lo leído, impresiones sobre los efectos que producen los recursos sonoros de los textos poéticos.","Reflexiona sobre el efecto estético de la sonoridad de los textos, a través de la relectura en voz alta y de la escucha de la lectura de los textos.","Identifica los recursos sonoros y sistematiza conocimientos sobre sus efectos estéticos y de sentido.","Selecciona poemas para gestionar itinerarios de lectura, personales y/o compartidos, organizados a partir de los efectos sonoros."]', 'PdA p. 85'),
(1, 'eje_contenido', 'Progresiones de Aprendizaje', 'Establecimiento de relaciones intertextuales, tanto entre textos literarios leídos, como con obras narrativas en otros lenguajes artísticos.', 'pda_2025', 1, 'Leer obras literarias de diversos subgéneros, seleccionados a partir del eje de lo real, y poner en juego conocimientos sobre procedimientos literarios, en la definición de preferencias y el establecimiento de relaciones con otros lenguajes artísticos.', '["Reconoce, entre distintos textos literarios que conforman un itinerario, la relación existente, fundada en las transformaciones narrativas (suspenso, finales o conflictos abiertos, inversiones sorpresivas).","Sugiere nuevos textos para sumar a un itinerario.","Relaciona el procedimiento narrativo (suspenso, finales o conflictos abiertos, inversiones sorpresivas) con obras narrativas en otros lenguajes, como películas, series, historietas."]', 'PdA p. 86'),
(1, 'eje_contenido', 'Progresiones de Aprendizaje', 'Participación en las distintas instancias del proceso de escritura de textos, en situaciones de escritura colectiva, grupal e individual.', 'pda_2025', 1, 'Producir textos ficcionales que pongan en juego rasgos textuales acordes al género y rasgos lingüísticos, y que desplieguen la potencialidad expresiva y estética del lenguaje.', '["Interviene a partir de la lectura de la consigna de escritura, en la delimitación de los distintos aspectos del problema retórico.","Relee y toma decisiones durante la redacción del texto en función del problema retórico definido.","Propone, de ser necesario, reformulaciones y ajustes en situaciones de revisión colectiva, grupal e individual, de aspectos globales y puntuales del texto.","Analiza e implementa las sugerencias de revisión de los propios textos, aportadas por la/el docente y sus pares.","Selecciona y consulta fuentes de información adecuadas al problema que se busca resolver."]', 'PdA p. 92'),
(1, 'eje_contenido', 'Progresiones de Aprendizaje', 'Experimentación con el plano sonoro del lenguaje en la escritura de invención.', 'pda_2025', 1, 'Producir textos ficcionales que pongan en juego rasgos textuales acordes al género y rasgos lingüísticos, y que desplieguen la potencialidad expresiva y estética del lenguaje.', '["Escucha la lectura o la oralización de textos que juegan con el plano sonoro del lenguaje y reconoce en qué consiste la condición lúdica de aliteraciones, parónimos, onomatopeyas, interjecciones, entre otros.","Reconoce la restricción que plantean las consignas en el plano sonoro y colabora con ejemplos.","Ensaya posibilidades de combinación en la escritura colectiva y grupal de textos."]', 'PdA p. 92'),
(1, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de recursos lingüísticos y textuales en la escritura de textos narrativos.', 'pda_2025', 1, 'Producir textos ficcionales que pongan en juego rasgos textuales acordes al género y rasgos lingüísticos, y que desplieguen la potencialidad expresiva y estética del lenguaje.', '["Analiza, en los textos narrativos leídos, cómo se expresan el marco temporal y espacial de los hechos, la presentación de personajes, la introducción de conflictos, la secuencia narrativa.","Explora y compara variadas alternativas de reformulación (ampliación, variación y recolocación) de los segmentos analizados, a partir de adverbios, adjetivos y construcciones preposicionales y adjetivas, y discute su coherencia con el texto.","Recrea las alternativas analizadas para explorar otros modos de expresar esos segmentos y afianzar estrategias de reformulación.","Resuelve problemas orientados a reflexionar sobre el uso de los verbos en pretérito perfecto simple, en pretérito imperfecto del modo indicativo, y la tilde en pretéritos terminados en -uve.","Explora y emplea variedad de conectores temporales y causales, para explicitar las relaciones entre los hechos narrados, así como sinónimos, hiperónimos y pronombres personales y demostrativos, para evitar repeticiones innecesarias y ampliar el repertorio personal de estos recursos.","Resuelve problemas orientados a la reflexionar sobre la introducción de diálogos en las narraciones, en particular: • la coherencia de los parlamentos con las características y motivaciones de los personajes, • el uso de raya, dos puntos y signos de interrogación y exclamación, • la ampliación del bagaje de verbos de decir y de adjetivos, adverbios y construcciones preposicionales que expresan cómo hablan los personajes, • el efecto de sentido que genera el uso de diminutivos, aumentativos o despectivos para nombrar a los personajes.","Emplea los recursos analizados en la redacción de textos narrativos y en su revisión colectiva y grupal."]', 'PdA p. 93'),
(1, 'eje_contenido', 'Progresiones de Aprendizaje', 'Descripción de objetos poniendo en juego un amplio repertorio de recursos lingüísticos y textuales.', 'pda_2025', 1, 'Producir textos ficcionales que pongan en juego rasgos textuales acordes al género y rasgos lingüísticos, y que desplieguen la potencialidad expresiva y estética del lenguaje.', '["Analiza en descripciones de objetos, qué aspectos se elige describir (partes, función, cómo se usa), a través de qué recursos se los nombra y describe, y la relación entre esas elecciones y el propósito del texto.","Explora y compara alternativas posibles para nombrar las partes del objeto (sinónimos y construcciones sustantivas), caracterizarlas (adjetivos en grado positivo y superlativo, construcciones adjetivas, preposicionales y comparativas) e indicar para qué sirve y cómo se usa (variación y expansión de estructuras oracionales).","Resuelve problemas orientados a reflexionar acerca de la ortografía del nuevo vocabulario.","Recrea las alternativas analizadas para explorar otros modos de describir objetos y afianzar estrategias de reformulación.","Organiza los recursos lingüísticos analizados en listados, fichas o cuadros, y los emplea en la producción de descripciones de objetos."]', 'PdA p. 93'),
(1, 'eje_contenido', 'Progresiones de Aprendizaje', 'Selección de la información transmitida por diferentes fuentes, en función de un tema, para su estudio.', 'pda_2025', 1, 'Producir exposiciones orales y escritas con diversos propósitos, que pongan en juego recursos lingüísticos y textuales adecuados al género.', '["Escucha leer a otras/os lectoras/es, y lee por sí misma/o, textos expositivos de diferentes géneros referidos a temas de la lengua y la literatura, por ejemplo, relación entre identidad y lenguaje, géneros literarios, habla adolescente, palabras de creación reciente vinculadas con temas de interés (como ecocidio, ecoladrillo, ecoamigable), entre otros.","Implementa estrategias de relectura de partes o de la totalidad del texto para resolver contradicciones o dudas sobre la información e inferir el significado de palabras desconocidas.","Identifica el tipo de relación entre el texto verbal y los recursos paratextuales (títulos y subtítulos, cuadros y gráficos, plaquetas de información secundaria, entre otros)."]', 'PdA p. 97'),
(1, 'eje_contenido', 'Progresiones de Aprendizaje', 'Integración de la información seleccionada en un texto expositivo.', 'pda_2025', 1, 'Producir exposiciones orales y escritas con diversos propósitos, que pongan en juego recursos lingüísticos y textuales adecuados al género.', '["Planifica la producción a partir de la definición del tema, el propósito y el género discursivo.","Integra la información seleccionada en un nuevo texto, por ejemplo, organiza la información en párrafos, agrega subtítulos y/u otros recursos visuales (gráficos, cuadros, fotografías, esquemas), sustituye palabras desconocidas por sinónimos conocidos.","Explora alternativas de reformulación, como definiciones de estructuras complejas en estructuras más sencillas (término-verbo ser-definición) y, a la inversa, de estructuras sencillas a estructuras más complejas (definición-verbo denominar-término).","Resuelve problemas orientados a reflexionar sobre el uso en el texto de organizadores textuales (en primer lugar, en segundo lugar) y variados conectores para relacionar oraciones y párrafos, y sobre el valor atemporal del presente del modo indicativo.","Participa en la revisión grupal del nuevo texto, con especial atención a la coherencia, la adecuación al propósito del texto y los aspectos formales (ortografía, puntuación, repetición inadecuada de palabras)."]', 'PdA p. 97'),
(1, 'eje_contenido', 'Progresiones de Aprendizaje', 'Diferenciación de información de opinión en géneros de comunicación pública de conocimiento especializado.', 'pda_2025', 1, 'Producir exposiciones orales y escritas con diversos propósitos, que pongan en juego recursos lingüísticos y textuales adecuados al género.', '["Identifica, en situaciones de lectura colectiva, en qué zonas del texto se brinda información y en cuáles se expresan opiniones.","Relee partes o la totalidad del texto para resolver dudas sobre el contenido, inferir el significado de palabras desconocidas y debatir acerca de si la opinión está fundamentada.","Identifica, en situaciones de relectura colectiva, el uso de palabras y expresiones para introducir y dar cuenta de la opinión y de la primera persona gramatical en la desinencia verbal y en determinantes posesivos (mi)."]', 'PdA p. 98'),
(1, 'objetivo', 'Objetivo', 'Apropiarse de prácticas de lenguaje diversas que le permitan una participación cada vez más plena en el contexto, tanto escolar como extraescolar.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'objetivo', 'Objetivo', 'Reflexionar acerca de las incidencias del contexto en las formas de expresión.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'objetivo', 'Objetivo', 'Ampliar y fortalecer su capacidad de expresar y compartir emociones, ideas, conocimientos y opiniones por medio de la lengua oral y escrita.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'objetivo', 'Objetivo', 'Utilizar el lenguaje de manera cada vez más libre, personal y autónoma para reconstruir y comunicar la experiencia propia y crear mundos de ficción.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'objetivo', 'Objetivo', 'Desarrollar su capacidad para interactuar, narrar, exponer y debatir utilizando cada vez con mayor fluidez y adecuación la lengua oral.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'objetivo', 'Objetivo', 'Fortalecer y ampliar habilidades estratégicas para leer diversidad de textos, con diferentes propósitos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'objetivo', 'Objetivo', 'Fortalecer su proceso de formación como lector crítico y autónomo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'objetivo', 'Objetivo', 'Abordar proyectos de escritura (de narraciones, exposiciones, cartas y argumentaciones) atendiendo al proceso de producción y con ajuste cada vez más satisfactorio a las condiciones discursivas, textuales, gramaticales y ortográficas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'eje_contenido', 'Comprensión y producción oral', 'Desempeño participativo en situaciones de intercambio dialógico: conversaciones y discusiones sobre temas propios del área y del mundo de la cultura.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'eje_contenido', 'Comprensión y producción oral', 'Organización de estructura y contenido en las exposiciones.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'eje_contenido', 'Comprensión y producción oral', 'Empleo de recursos paraverbales (entonación, tonos de voz, volumen, ritmo) y no verbales (postura corporal, gestos) como refuerzo de la oralidad.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'eje_contenido', 'Lectura y producción escrita', 'Construcción (a partir de la lectura asidua) de saberes específicos en relación con géneros discursivos propios del ámbito personal (cartas, mensajes en soporte papel y electrónico, notas personales, anécdotas, autobiografías) y social (crónicas de viajes, noticias, cartas de lectores, géneros publicitarios).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'eje_contenido', 'Lectura y producción escrita', 'Construcción de estrategias de lectura adecuadas al género textual y al propósito de lectura.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'eje_contenido', 'Lectura y producción escrita', 'Producción de textos narrativos (relatos de experiencias y viajes, anécdotas, autobiografías) atendiendo a la elección de la voz narrativa, la caracterización de personas y personajes, la organización (episodios y sucesos, marco espacio temporal; secuencia lógica y cronológica) y los procedimientos (inclusión de descripciones y diálogos).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'eje_contenido', 'Literatura', 'Escucha atenta y lectura frecuente de textos literarios de la tradición oral y de autores regionales, nacionales y universales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'eje_contenido', 'Literatura', 'Escucha, lectura e interpretación de relatos tradicionales (mitos, leyendas, parábolas, cuentos) y de autor (realistas, maravillosos, de misterio, policiales).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'eje_contenido', 'Reflexión sobre el lenguaje, la lengua (sistema, norma y uso) y los textos', 'Apropiación de las nociones de dialecto (geográfico y social), registro y usos locales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(1, 'eje_contenido', 'Reflexión sobre el lenguaje, la lengua (sistema, norma y uso) y los textos', 'Conocimiento de la ortografía correspondiente al vocabulario cotidiano y escolar.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(2, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interpretación de regularidades con números naturales, incluidas las representadas geométricamente.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Identifica y expresa coloquialmente la regla de formación (patrón) de regularidades numéricas.","Explica cómo usa el patrón para escribir una cierta cantidad de términos de una regularidad numérica."]', 'PdA p. 52'),
(2, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de la multiplicación y la división entera entre números naturales en situaciones de combinatoria.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Organiza y determina el número total de casos a través de diagramas de árbol y cuadros de doble entrada, para encontrar las soluciones a situaciones de permutación, variación y combinación.","Reconoce, compara y explica características propias de la permutación, la variación y la combinación.","Lee una situación y distingue el tipo de combinatoria (permutación, variación y combinación) para resolverla.","Determina el número total de casos al permutar, variar y combinar elementos recurriendo al uso de multiplicaciones y divisiones cuando sea necesario."]', 'PdA p. 52'),
(2, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis y escritura algebraica de las propiedades de la suma y la multiplicación con números naturales.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Selecciona las propiedades (asociativa, conmutativa de la suma y la multiplicación, distributiva de la multiplicación, con respecto a la suma y resta) que permiten resolver cálculos con números naturales y justifica la elección realizada.","Compara y explica expresiones algebraicas que contienen paréntesis y modifican las reglas de precedencia (jerarquía) de las operaciones","Elabora y explica expresiones algebraicas para comunicar propiedades de la suma y la multiplicación con números naturales."]', 'PdA p. 52'),
(2, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de las relaciones de múltiplos y divisores de números naturales en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Lee una situación y diferencia la información relevante de la irrelevante para resolverla.","Determina múltiplos y divisores comunes entre dos o más números naturales, recurriendo a la descomposición en factores primos cuando sea necesario.","Anticipa y justifica productos, cocientes y restos entre dos números naturales, recurriendo a la descomposición en factores primos cuando sea necesario.","Reconoce y justifica propiedades de la divisibilidad entre números naturales (sumas de pares, impares, sumas de múltiplos).","Interpreta escrituras algebraicas referidas a propiedades de la divisibilidad.","Justifica la equivalencia entre escrituras algebraicas referidas a propiedades de la divisibilidad.","Elabora escrituras algebraicas para comunicar propiedades de sumas de pares, sumas de impares, sumas de múltiplos."]', 'PdA p. 53'),
(2, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interpretación de la potenciación con números naturales en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Reconoce en expresiones numéricas la utilización de la potenciación y el significado de base y exponente.","Explica cómo usa potencias de números naturales en situaciones de conteo de casos, con repetición de elementos, de cálculo de áreas y volúmenes."]', 'PdA p. 53'),
(2, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de diferentes representaciones de un mismo número racional positivo (expresión fraccionaria, decimal finita, porcentaje y punto de la recta numérica) en situaciones de comunicación y comparación.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Interpreta el número racional positivo como razón en situaciones de proporcionalidad, probabilidad y estadística.","Interpreta y representa números racionales positivos en la recta numérica.","Selecciona y justifica la forma de representar los números racionales positivos en función del contexto de uso.","Compara y encuadra números racionales positivos empleando diferentes criterios y recurriendo a su representación en la recta numérica cuando sea necesario."]', 'PdA p. 53'),
(2, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de la suma, la resta, la multiplicación y la división con números racionales positivos en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Lee una situación extramatemática, selecciona la información relevante y busca, en distintas fuentes, la información que falta para resolverla.","Produce, compara y explica diferentes procedimientos, propios y de otras/os, para dividir expresiones fraccionarias entre sí, a partir del uso inverso multiplicativo.","Produce, compara y explica diferentes procedimientos, propios y de otras/os, para dividir expresiones decimales entre sí.","Selecciona y justifica la operación (suma, resta, multiplicación, división) que permite resolver las situaciones extramatemáticas leídas.","Selecciona un tipo de cálculo —no algorítmico o algorítmico— que resulta más adecuado según los números racionales positivos involucrados al sumar, restar, multiplicar y dividir, justificando la elección realizada","Anticipa el resultado de un cálculo, evaluando su razonabilidad de acuerdo a los números racionales positivos involucrados y al contexto de uso."]', 'PdA p. 54'),
(2, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de tablas y gráficos de relaciones entre dos variables discretas y/o continuas en situaciones extramatemáticas.', 'pda_2025', 1, 'Modelizar situaciones vinculadas a las relaciones de proporcionalidad directa e inversa y variaciones lineales.', '["Lee una situación extramatemática y reconoce las variables, discretas y/o continuas, involucradas.","Produce tablas para expresar relaciones entre dos variables, discretas y/o continuas.","Representa en un sistema de ejes cartesianos los pares ordenados expresados en una tabla.","Describe cualitativamente la relación entre variables discretas y/o continuas representada en una tabla y en un sistema de coordenadas cartesianas, incluida la fluctuación de divisas.","Interpreta máximos, mínimos, crecimientos, decrecimientos de la relación funcional entre dos variables (discretas y/o continuas), representada en un sistema de coordenadas cartesianas, en el contexto de la situación extramatemática.","Compara con otras/os las formas de presentación de relaciones entre dos variables (tablas y gráficos), selecciona las más conveniente para la situación propuesta y justifica su elección."]', 'PdA p. 58'),
(2, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de características y propiedades de relaciones de proporcionalidad directa e inversa, presentadas en textos, tablas y gráficos, en situaciones extramatemáticas.', 'pda_2025', 1, 'Modelizar situaciones vinculadas a las relaciones de proporcionalidad directa e inversa y variaciones lineales.', '["Lee una situación extramatemática (en textos, tablas y gráficos), selecciona la información relevante y/o busca, en distintas fuentes, la información que falta para resolver la situación.","Explicita, emplea y explica la constante y propiedades (al doble, el doble; a la suma, la suma) de relaciones de proporcionalidad directa entre dos magnitudes, presentadas en textos y tablas.","Explicita, emplea y explica la constante y propiedades (al doble, la mitad; al triple, la tercera parte) de relaciones de proporcionalidad inversa entre dos magnitudes, presentadas en textos y tablas.","Interpreta y explica las características de los gráficos de las relaciones de proporcionalidad directa e inversa. Diferencia relaciones de proporcionalidad directa e inversa, y justifica su decisión en base a las propiedades e interpretación de textos, tablas y gráficos.","Diferencia relaciones de proporcionalidad directa e inversa, y justifica su decisión en base a las propiedades e interpretación de textos, tablas y gráficos.","Representa mediante tablas y/o gráficos situaciones que se modelizan con relaciones de proporcionalidad directa e inversa."]', 'PdA p. 58'),
(2, 'eje_contenido', 'Progresiones de Aprendizaje', 'Cuantificación de la incertidumbre de fenómenos aleatorios.', 'pda_2025', 1, 'Cuantificar la incertidumbre recurriendo a las nociones de probabilidad clásica y comunicar información estadística.', '["Lee una situación extramatemática y distingue fenómenos y experimentos aleatorios de aquellos que son determinísticos.","Comunica el espacio muestral finito de un fenómeno o experimento aleatorio.","Distingue y explica eventos imposibles, en el conjunto de resultados de un experimento.","Reconoce y explica la frecuencia relativa, como la probabilidad frecuencial de un evento, en tablas de frecuencias absolutas y relativas en las que se registran los resultados de un experimento aleatorio que se repite muchas veces.","Reconoce y explica que la probabilidad frecuencial de un evento aleatorio es un número racional entre 0 y 1, la de un evento imposible es 0 y la de un evento seguro es 1."]', 'PdA p. 61'),
(2, 'eje_contenido', 'Progresiones de Aprendizaje', 'Representación de datos recolectados de variables cualitativas nominales y cuantitativas discretas en tablas de distribución de frecuencias y gráficos de barras y bastones.', 'pda_2025', 1, 'Cuantificar la incertidumbre recurriendo a las nociones de probabilidad clásica y comunicar información estadística.', '["Lee una situación extramatemática e identifica variables cualitativas nominales y cuantitativas discretas contenidas en un conjunto de datos.","Organiza datos en tablas de distribución de frecuencias absoluta y relativa, apelando al uso de software cuando sea posible.","Confecciona gráficos de barras (variables cualitativas nominales) y bastones (cuantitativas discretas), apelando al uso de software cuando sea posible, para comunicar la información de las tablas de distribución de frecuencias.","Elabora textos que integran la información estadística presentada en tablas de frecuencia y gráficos de barras y bastones, y la medida estadística denominada moda."]', 'PdA p. 61'),
(2, 'eje_contenido', 'Progresiones de Aprendizaje', 'Formulación de argumentaciones sobre condiciones geométricas de triángulos y cuadriláteros convexos y propiedades de pares de ángulos, en situaciones de construcción y comunicación.', 'pda_2025', 1, 'Usar propiedades de polígonos convexos, criterios de congruencia y semejanza de triángulos, en situaciones de construcción de figuras geométricas y cálculo de áreas y volúmenes.', '["Explica la construcción de triángulos a partir de algunos de sus elementos (lados, ángulos, alturas y bisectrices) y la justifica desde las propiedades.","Reconoce y explica propiedades de lados, ángulos y diagonales que justifican la construcción de cuadriláteros convexos, apelando al uso de software, de ser posible.","Fundamenta la cantidad de triángulos diferentes que se pueden construir a partir de la información sobre sus lados y ángulos.","Identifica ángulos alternos internos, opuestos por el vértice y adyacentes determinados en un paralelogramo al trazar una o dos diagonales.","Anticipa y justifica propiedades de ángulos alternos internos, opuestos por el vértice y adyacentes, a partir de las propiedades de los paralelogramos."]', 'PdA p. 65'),
(2, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de fórmulas para el cálculo de áreas de cuadriláteros paralelogramos, triángulos y círculos, y perímetros de círculos, en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Usar propiedades de polígonos convexos, criterios de congruencia y semejanza de triángulos, en situaciones de construcción de figuras geométricas y cálculo de áreas y volúmenes.', '["Elabora, explica y compara fórmulas propias y de otras/ os que permiten calcular el área de cuadriláteros, paralelogramos y triángulos.","Explica la diferencia entre el perímetro y el área de un círculo.","Interpreta fórmulas para el cálculo de perímetro y área del círculo.","Selecciona las fórmulas de acuerdo a la información disponible en la situación leída, para el cálculo del área de figuras compuestas por paralelogramos, triángulos y círculos, y justifica su elección."]', 'PdA p. 65'),
(2, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de fórmulas para el cálculo de volúmenes de prismas y cilindros, en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Usar propiedades de polígonos convexos, criterios de congruencia y semejanza de triángulos, en situaciones de construcción de figuras geométricas y cálculo de áreas y volúmenes.', '["Determina el volumen de cubos y prismas rectos de base rectangular mediante el uso de unidades no convencionales (cubos pequeños iguales).","Reconoce que el volumen de cubos y prismas rectos de base rectangular se determina a partir del producto de las longitudes de sus aristas.","Justifica la selección y uso de unidades de medida adecuadas para realizar mediciones y estimaciones de volúmenes de prismas..","Elabora, explica y compara fórmulas propias y de otras/ os, que permiten calcular el volumen de prismas (regulares y no regulares) cuyas bases son cuadriláteros, paralelogramos y triángulos, y de cilindros.","Selecciona las fórmulas de acuerdo con la información disponible en la situación leída, para realizar el cálculo del volumen de cuerpos compuestos por prismas y cilindros, y justifica su elección."]', 'PdA p. 66'),
(2, 'objetivo', 'Objetivo', 'Comprender y usar la organización decimal del sistema de numeración.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'objetivo', 'Objetivo', 'Reflexionar sobre la necesidad de acudir a diferentes tipos de cálculo- mental o exacto, con o sin calculadora- de acuerdo al problema.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'objetivo', 'Objetivo', 'Usar números naturales, expresiones fraccionarias y decimales para resolver problemas extramatemáticos e intramatemáticos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'objetivo', 'Objetivo', 'Utilizar y analizar funciones - proporcionalidad directa, crecimiento lineal no proporcional, proporcionalidad inversa-, para resolver problemas extramatemáticos, recurriendo cuando sea posible al uso reflexivo de recursos tecnológicos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'objetivo', 'Objetivo', 'Reflexionar sobre la necesidad de estimar y de medir efectivamente.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'objetivo', 'Objetivo', 'Organizar e interpretar datos estadísticos mediante tablas (de serie simple, de frecuencia) y gráficos, eligiendo la forma más adecuada.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'objetivo', 'Objetivo', 'Recurrir a nociones de probabilidad para cuantificar la incertidumbre.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'eje_contenido', 'Número y operaciones', 'Interpretación, registro, comunicación y comparación de cantidades y números naturales y racionales positivos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'eje_contenido', 'Número y operaciones', 'Uso de diferentes representaciones de un número natural (descomposiciones polinómicas, punto de la recta), y de un número racional positivo (expresiones fraccionarias y decimales, punto de la recta, etc.), seleccionando la representación más adecuada de acuerdo al problema.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'eje_contenido', 'Número y operaciones', 'Análisis de las operaciones en N y sus propiedades.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'eje_contenido', 'Número y operaciones', 'Producción de cálculos que combinen varias operaciones -con números naturales y racionales positivos- en relación con un problema y producción de un problema en relación con un cálculo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'eje_contenido', 'Álgebra y funciones', 'Reconocimiento, explicitación y diferenciación de propiedades de relaciones directa (al triple el triple, a la suma la suma, constante de proporcionalidad) e inversamente proporcionales (al triple la tercera parte, constante de proporcionalidad).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'eje_contenido', 'Álgebra y funciones', 'Interpretación de relaciones entre magnitudes discretas y/ o continuas en tablas y gráficos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'eje_contenido', 'Álgebra y funciones', 'Obtención de expresiones algebraicas equivalentes usando propiedades para resolver ecuaciones del tipo ax+b = cx+d.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'eje_contenido', 'Geometría y medida', 'Análisis de figuras bidimensionales (triángulos, cuadriláteros y círculos) y tridimensionales (prismas, pirámides, cilindros, conos y esferas) para caracterizarlas y clasificarlas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'eje_contenido', 'Geometría y medida', 'Selección y uso de unidades para realizar mediciones y estimaciones de volúmenes de acuerdo al problema.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'eje_contenido', 'Estadística y probabilidad', 'Identificación de variables cuantitativas y cualitativas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'eje_contenido', 'Estadística y probabilidad', 'Interpretación de información presentada en tablas y gráficos estadísticos-pictogramas, diagramas de barra, gráficos circulares, de línea, de punto- y análisis de las ventajas y desventajas de acuerdo a la información que se persigue comunicar.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(2, 'eje_contenido', 'Estadística y probabilidad', 'Uso de diferentes estrategias para resolver problemas de conteo, entre ellas el uso de diagrama de árbol.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(3, 'eje_contenido', 'Progresiones de Aprendizaje', 'Vinculación de los órganos del sistema genital con la reproducción y el placer.', 'pda_2025', 1, 'Tomar decisiones, responsables y fundamentadas, en torno al cuidado del propio cuerpo y el de las demás personas, desde una visión integral de salud.', '["Reconoce el sistema genital de personas con pene y vulva, identificando las principales partes y órganos con sus capacidades.","Interpreta y reconoce que no solo las mujeres pueden gestar, atendiendo la construcción del género como categoría desligada de lo genital.","Reconoce los órganos reproductivos, identificando a los testículos y ovarios como generadores de células sexuales (espermatozoides y óvulos), y al útero, como el órgano con capacidad de gestar.","Comprende que existen más de dos tipos de sistema genital, considerando a las personas intersexuales.","Relaciona los principales órganos del sistema genital con sus capacidades, identificando aquellos que se vinculan con el placer."]', 'PdA p. 96'),
(3, 'eje_contenido', 'Progresiones de Aprendizaje', 'Conocimiento de las prácticas de cuidado propio y de las/os otras/os, en los vínculos sexoafectivos, desde un enfoque que promueve el ejercicio pleno y consciente de la sexualidad integral.', 'pda_2025', 1, 'Tomar decisiones, responsables y fundamentadas, en torno al cuidado del propio cuerpo y el de las demás personas, desde una visión integral de salud.', '["Reconoce que existen diferentes métodos de prevención de infecciones de transmisión sexual (ITS) y embarazo.","Identifica al preservativo como único método capaz de prevenir embarazo e ITS.","Comprende el uso correcto del preservativo, la construcción y la utilización del campo de látex, cómo métodos de prevención de ITS.","Analiza y selecciona información pertinente, de distintas fuentes, en relación con los cuidados en vínculos sexoafectivos.","Reconoce que los encuentros sexoafectivos deben ser consensuados y pactados.","Identifica interacciones inadecuadas y situaciones de abuso, expresando sus dudas e inquietudes al respecto.","Fundamenta la importancia de acudir a centros de salud y hospitales, conociendo los derechos que la/o asisten en relación con la atención en estos espacios."]', 'PdA p. 96'),
(3, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación de la fecundación con la unión de las células sexuales y de las condiciones en que puede ocurrir.', 'pda_2025', 1, 'Tomar decisiones, responsables y fundamentadas, en torno al cuidado del propio cuerpo y el de las demás personas, desde una visión integral de salud.', '["Diferencia óvulos y espermatozoides, considerando su estructura, función y los órganos que le dan origen.","Esquematiza, de manera sencilla, el camino que recorren los espermatozoides hasta fecundar el óvulo.","Identifica las condiciones biológicas en las que se produce el cigoto.","Elabora justificaciones a partir de análisis/discusión de mitos y creencias populares vinculados a la fecundidad (por ejemplo, qué pasa si la persona con útero se lava luego del coito, si la primera vez que se mantienen relaciones sexuales puede producirse un embarazo o no, si durante el ciclo menstrual la fertilidad es la misma, entre otros)."]', 'PdA p. 97'),
(3, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión del ciclo menstrual incluyendo aspectos biológicos y culturales.', 'pda_2025', 1, 'Tomar decisiones, responsables y fundamentadas, en torno al cuidado del propio cuerpo y el de las demás personas, desde una visión integral de salud.', '["Reconoce la importancia de conocer los síntomas e indicadores de cada etapa del ciclo menstrual, atendiendo a registrar, en su propio cuerpo, posibles situaciones que requieran atención.","Analiza situaciones donde se hipotetiza sobre ventanas de fertilidad, estados emocionales, sangrado, ovulación, entre otras posibilidades, proponiendo explicaciones basadas en evidencia científica.","Contrasta sus explicaciones y argumentos en relación al ciclo menstrual y la fertilidad con las de sus compañeras/os, para enriquecer su comprensión y fundamentación.","Valora la importancia de comprender la ciclicidad de las personas con útero, en el marco de una convivencia democrática y respetuosa.","Propone alternativas de salud menstrual de impacto ambiental reducido, valorando sus costos a corto y largo plazo, su accesibilidad y su sostenibilidad."]', 'PdA p. 97'),
(3, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interpretación de las características de los seres vivos, reconociéndolos como sistemas abiertos y autónomos que intercambian materia y energía con el ambiente, realizando funciones vitales (respiración, nutrición, excreción y homeostasis).', 'pda_2025', 1, 'Reconocer lo común, presente en la diversidad de formas de vida, comparando distintos niveles de organización biológica (célula, tejidos, organismo, comunidad, entre otros).', '["Reconoce características comunes de todos los organismos para construir un concepto de ser vivo.","Identifica los intercambios de materia y energía entre diferentes organismos y el ambiente, utilizando representaciones (esquemas o dibujos) y denominaciones sencillas.","Observa y analiza la función de autorregulación en los seres vivos, a partir de experimentos sencillos relacionados con respuestas a estímulos, como tropismos y taxismos.","Construye anticipaciones en torno al intercambio de materia y energía entre seres vivos y el medio, utilizando experimentaciones sencillas para comprobarlas.","Propone y valora diferentes estrategias y diseños experimentales ,para reconocer e interpretar los intercambios de materia y energía entre un ser vivo y su entorno.","Identifica y/o manipula variables en el contexto de experimentaciones, poniendo de manifiesto el intercambio de materia y energía entre un ser vivo y el entorno (por ejemplo, observando la evapotranspiración en plantas).","Relaciona los intercambios de materia y energía con las funciones vitales en su propio cuerpo.","Reconoce características y patrones comunes en relación con la nutrición, la excreción y la homeostasis, a partir de la comparación de seres vivos de diferentes grupos."]', 'PdA p. 100'),
(3, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de los planes corporales de los grandes grupos de seres vivos (animales, plantas, hongos, microorganismos), desde un enfoque evolutivo, relacionando las estructuras con las funciones que realizan.', 'pda_2025', 1, 'Reconocer lo común, presente en la diversidad de formas de vida, comparando distintos niveles de organización biológica (célula, tejidos, organismo, comunidad, entre otros).', '["Reconoce y nombra los principales planes corporales de los seres vivos, a partir de la observación directa y de imágenes.","Sistematiza información proveniente de la observación directa y de imágenes, en relación con los planes corporales de los seres vivos y sus funciones.","Esquematiza los planes corporales de los distintos grupos de seres vivos, incluyendo esponjas, cnidarios, microorganismos, animales, plantas y hongos.","Relaciona las funciones que realizan algunos seres vivos (por ejemplo, las aves voladoras) con los planes corporales que poseen (por ejemplo, presencia de alas)."]', 'PdA p. 100'),
(3, 'eje_contenido', 'Progresiones de Aprendizaje', 'Conocimiento de los diferentes niveles de biodiversidad (variabilidad de organismos en una población, de especies, de ambientes, entre otros) reconociendo la ecodependencia y el valor de todas las formas de vida.', 'pda_2025', 1, 'Reconocer lo común, presente en la diversidad de formas de vida, comparando distintos niveles de organización biológica (célula, tejidos, organismo, comunidad, entre otros).', '["Reconoce la diversidad de formas de vida y de planes corporales en observaciones realizadas en el ambiente.","Realiza búsquedas de información para ejemplificar relaciones interespecíficas, como una aproximación a la compleja trama de la vida en los ecosistemas.","Identifica las diversidad de ambientes y de especies que los habitan, reconociendo las relaciones entre ambos niveles de biodiversidad.","Reflexiona sobre el valor de la biodiversidad para las comunidades humanas, a partir del concepto de ecodependencia.","Demuestra una actitud de valoración y respeto por todas las formas de vida."]', 'PdA p. 101'),
(3, 'eje_contenido', 'Progresiones de Aprendizaje', 'Exploración del mecanismo de selección natural como modelador de la adaptación de las poblaciones.', 'pda_2025', 1, 'Reconocer lo común, presente en la diversidad de formas de vida, comparando distintos niveles de organización biológica (célula, tejidos, organismo, comunidad, entre otros).', '["Identifica la existencia de la variabilidad de características dentro de las poblaciones (mediante observaciones, encuestas o ejemplos), como condición para la selección natural.","Participa en actividades de modelización (juegos, simuladores, entre otros) que permiten comprender el mecanismo de selección natural.","Reconoce las adaptaciones de los seres vivos como resultado de la acción de la selección natural sobre la variabilidad de las poblaciones, a lo largo del tiempo.","Se aproxima a explicar el mecanismo de selección natural (a nivel poblacional), y las adaptaciones biológicas, interpretando la biodiversidad presente y pasada."]', 'PdA p. 101'),
(3, 'eje_contenido', 'Progresiones de Aprendizaje', 'Compresión de la reproducción de los seres vivos, como una capacidad que se manifiesta en diferentes formas (sexual o asexual) y tipos de desarrollo (directo e indirecto).', 'pda_2025', 1, 'Reconocer lo común, presente en la diversidad de formas de vida, comparando distintos niveles de organización biológica (célula, tejidos, organismo, comunidad, entre otros).', '["Agrupa diferentes seres vivos según el tipo de reproducción que presentan.","Reconoce grupos de seres vivos que realizan desarrollo directo e indirecto.","Analiza ventajas y desventajas de los diferentes tipos de reproducción y desarrollo.","Relaciona los modos reproductivos y tipos de desarrollo con el ambiente en que habitan los seres vivos.","Interpreta la diversidad de estrategias reproductivas y de desarrollo, como respuestas adaptativas de las poblaciones a su ambiente."]', 'PdA p. 101'),
(3, 'eje_contenido', 'Progresiones de Aprendizaje', 'Conocimiento y comparación de las ideas científicas que explican el origen de la vida (generación espontánea, biogénesis, quimiosíntesis), interpretando el conocimiento científico como una construcción contextual y provisoria.', 'pda_2025', 1, 'Reconoce los aportes del enfoque evolutivo para explicar cambios y permanencias, así como también características, funciones y estructuras celulares en relación con la biodiversidad.', '["Participa en conversaciones sobre las ideas que existen en el grupo de clase acerca del origen de la vida.","Compara y contrasta las diferentes ideas científicas sobre el origen de la vida (ideas de la antigua Grecia, generación espontánea, quimiogénesis, biogénesis —Oparin y Haldane—), identificando dilemas relativos a la producción del conocimiento científico (experimentos de Redi, Spallanzani, Pasteur, Stanley y Miller).","Identifica elementos del contexto histórico vinculados con el surgimiento y postulación de las diferentes teorías (pensamiento dominante, instrumentos de observación, entre otros).","Reconoce nociones y argumentos de las teorías sobre el origen de la vida, para refutar la generación espontánea como explicación en situaciones cotidianas (por ejemplo, el origen de las enfermedades, contaminación de alimentos, entre otras).","Reconoce cómo las ideas científicas cambian a partir de nuevas evidencias.","Examina y reflexiona, desde una perspectiva de género, acerca de cómo se produce el conocimiento científico."]', 'PdA p. 104'),
(3, 'eje_contenido', 'Progresiones de Aprendizaje', 'Conocimiento de los postulados de la teoría celular y ejemplificación a través de fenómenos observables.', 'pda_2025', 1, 'Reconoce los aportes del enfoque evolutivo para explicar cambios y permanencias, así como también características, funciones y estructuras celulares en relación con la biodiversidad.', '["Utiliza los postulados de la teoría celular para construir explicaciones sobre situaciones problemáticas o fenómenos observables en la vida cotidiana, por ejemplo, presencia del moho del pan, producción de yogur, producción de panificados, entre otros.","Reconoce los postulados de la teoría celular, en diferentes formas de representación (por ejemplo, videos, imágenes, maquetas, observaciones directas).","Realiza experiencias que ejemplifican los postulados de la teoría celular, a través de fenómenos observables en células (reproducción celular usando levaduras, observación de diversas células al microscopio).","Confronta sus resultados y conclusiones de experiencias sobre los postulados de la teoría celular con los obtenidos por su grupo de clase, reconociendo diferencias y valorando nuevos aportes.","Reconoce eventos o sucesos del contexto histórico que acunaron la postulación de la teoría celular (por ejemplo, el surgimiento del microscopio) para el desarrollo de la Biología."]', 'PdA p. 105'),
(3, 'eje_contenido', 'Progresiones de Aprendizaje', 'Valoración de la importancia de los instrumentos de observación en el campo de las ciencias naturales, con foco en el microscopio.', 'pda_2025', 1, 'Reconoce los aportes del enfoque evolutivo para explicar cambios y permanencias, así como también características, funciones y estructuras celulares en relación con la biodiversidad.', '["Manipula el microscopio óptico, adecuando el aumento al tipo de muestra y/o utiliza simuladores y otros recursos.","Relaciona la invención del microscopio con la observación de células y microorganismos, y con la posterior formulación de la Teoría Celular.","Nombra las principales partes de un microscopio, a partir del objeto real o de imágenes y videos, identificando las funciones de cada una de ellas.","Utiliza el microscopio, respetando las recomendaciones de seguridad del para el uso del instrumento."]', 'PdA p. 105'),
(3, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación, en los diferentes tipos celulares, de patrones de funcionamiento y dinámicas celulares comunes.', 'pda_2025', 1, 'Reconoce los aportes del enfoque evolutivo para explicar cambios y permanencias, así como también características, funciones y estructuras celulares en relación con la biodiversidad.', '["Diseña y realiza experiencias con relación a la respiración celular (por ejemplo: inflar un globo a partir de la respiración de levaduras).","Identifica variables sencillas involucradas en los procesos de nutrición y respiración celular (temperatura, presencia de azúcar, entre otros) y analiza su efecto a partir de experimentaciones sencillas.","Distingue diferentes tipos celulares (animal, vegetal, fungi y bacteria) a partir de observaciones directas al microscopio o de microfotografías, representando, mediante dibujos o esquemas, lo observado.","Identifica características comunes y diferencias entre tipos celulares (animal, vegetal, fungi y bacteria).","Reconoce la diversidad celular del cuerpo humano, estableciendo relaciones entre la estructura de algunos tipos celulares y sus funciones."]', 'PdA p. 106'),
(3, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión de la relación entre los distintos niveles de organización que conforman los sistemas biológicos (célula, tejido, órgano, sistema de órganos, organismo, población, comunidad, ecosistema, ecorregión, biosfera).', 'pda_2025', 1, 'Reconoce los aportes del enfoque evolutivo para explicar cambios y permanencias, así como también características, funciones y estructuras celulares en relación con la biodiversidad.', '["Identifica los niveles de organización mediante ejemplos de su entorno cotidiano y en formas de representación (maquetas, imágenes, videos, entre otras).","Reconoce la relación entre los niveles de organización, según su complejidad.","Reconoce los niveles de organización como un aporte fundamental para la sistematización de la complejidad de los sistemas vivos.","Aplica los conceptos relativos a niveles de organización, para construir explicaciones en torno al funcionamiento y la complejidad de la biosfera."]', 'PdA p. 106'),
(3, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de algunos impactos que el cambio climático provoca en la biodiversidad local.', 'pda_2025', 1, 'Establecer relaciones causa-efecto en torno al cambio climático, reconociendo medidas de adaptación climática y otras alternativas viables para la sostenibilidad.', '["Realiza y analiza experimentos, para aproximarse a comprender el efecto invernadero natural.","Distingue las causas del cambio climático (naturales y de las actividades humanas) y sus principales consecuencias.","Utiliza datos científicos para argumentar acerca de por qué existe el cambio climático.","Identifica, en imágenes satelitales, los cambios del paisaje (deforestación, desarrollo urbano, fragmentación de hábitat, conservación de territorios, apertura de canales de riego, entre otros) y reflexiona sobre cómo se relacionan con el cambio climático.","Analiza y opina acerca de las consecuencias y efectos que el cambio climático tiene en la ecodependencia.","Identifica, desde su propia experiencia personal, algunos impactos del cambio climático (aumento de temperaturas, mayor frecuencia e intensidad de fenómenos meteorológicos, como olas de calor, sequías, inundaciones, incendios, entre otros).","Elabora materiales de comunicación que incluyen acciones ciudadanas, para estimular el cuidado de la biodiversidad local en relación con el cambio climático."]', 'PdA p. 110'),
(3, 'objetivo', 'Objetivo', 'Valorar los aportes de las Ciencias Naturales a la sociedad a lo largo de la historia.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'objetivo', 'Objetivo', 'Reconocer el conocimiento científico y sus procesos de producción como una construcción histórico-social de carácter provisorio.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'objetivo', 'Objetivo', 'Reconocer e interpretar a los modelos como representaciones que se elaboran y utilizan para explicar y predecir hechos y fenómenos de la naturaleza.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'objetivo', 'Objetivo', 'Interpretar e inferir la diversidad de las consecuencias que implican las decisiones y acciones humanas sobre el ambiente y la salud.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'objetivo', 'Objetivo', 'Conceptualizar la diversidad biológica en las escalas de diversidad de genes, de especies y de ecosistemas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'objetivo', 'Objetivo', 'Reconocer a la célula como unidad estructural y funcional de todo ser vivo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'objetivo', 'Objetivo', 'Comprender la función de nutrición como mecanismo de intercambio de materia y energía con el medio que caracteriza a los seres vivos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'objetivo', 'Objetivo', 'Reconocer al organismo humano como sistema complejo, abierto e integrado.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'eje_contenido', 'Los seres vivos: diversidad, unidad, interrelaciones, continuidad y cambio', 'Conceptualización sobre niveles de organización de los seres vivos; en especial las nociones de célula, tejido, órgano y sistemas de órganos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'eje_contenido', 'Los seres vivos: diversidad, unidad, interrelaciones, continuidad y cambio', 'Interpretación de la nutrición como conjunto integrado de varias funciones que se producen en los seres vivos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'eje_contenido', 'Los seres vivos: diversidad, unidad, interrelaciones, continuidad y cambio', 'Interpretación de los modelos de organización animal y vegetal caracterizándolos por el tipo de nutrición y el modo en que se relacionan con el medio.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'eje_contenido', 'Los seres vivos: diversidad, unidad, interrelaciones, continuidad y cambio', 'Caracterización de los ecosistemas como sistemas abiertos, considerando los factores que los componen.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'eje_contenido', 'Los seres vivos: diversidad, unidad, interrelaciones, continuidad y cambio', 'Reconocimiento de productores, consumidores y descomponedores y su importancia en la estabilidad de los ecosistemas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'eje_contenido', 'El organismo humano desde una visión integral', 'Construcción de la noción del organismo humano como sistema complejo, abierto e integrado.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'eje_contenido', 'El organismo humano desde una visión integral', 'Reconocimiento de nutrientes y sustancias relacionadas con la nutrición y los hábitos alimentarios.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'eje_contenido', 'El organismo humano desde una visión integral', 'Reconocimiento y caracterización de las estructuras y funciones involucradas en los procesos de nutrición en los animales: digestión, respiración, circulación, excreción.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(3, 'eje_contenido', 'El organismo humano desde una visión integral', 'Conocimiento de los aspectos biológicos, sociales y culturales de los problemas de salud asociados con la nutrición: bulimia, anorexia, obesidad y desnutrición.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(4, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de diferentes tipos de energía (potencial gravitatoria, cinética, potencial elástica, térmica), en relación con las variables asociadas e identificando al joule como su unidad de medida.', 'pda_2025', 1, 'Analizar y explicar las dinámicas de transformación y transferencia de energía entre un sistema y su entorno, reconociendo variables macroscópicas y microscópicas e identificando los modos de producción energética en el país.', '["Identifica diferentes tipos de energía en situaciones cotidianas, analizando los cambios y efectos que pueden producir en el entorno.","Analiza diversas situaciones cotidianas relacionadas con cambios de la energía cinética, identificando la masa y la velocidad como variables intervinientes.","Advierte los cambios de la energía potencial gravitatoria en diversas situaciones cotidianas, identificando la masa y la posición como las variables implicadas.","Identifica cambios de la energía térmica en diversas situaciones cotidianas, reconociendo a la temperatura y la masa como las variables participantes.","Experimenta con cuerpos elásticos para reconocer los cambios de la energía, identificando la deformación y la naturaleza del material como variables implicadas.","Reconoce que la energía puede ser cuantificada y utiliza el joule como la unidad de medida."]', 'PdA p. 113'),
(4, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interpretación del trabajo y del calor como formas de transferencia de energía entre un sistema y su entorno.', 'pda_2025', 1, 'Analizar y explicar las dinámicas de transformación y transferencia de energía entre un sistema y su entorno, reconociendo variables macroscópicas y microscópicas e identificando los modos de producción energética en el país.', '["Interpreta el concepto de sistemas en el campo de las ciencias naturales, entendido como conjunto de elementos que interaccionan entre sí.","Clasifica a los sistemas en abiertos, cerrados y aislados, según su interacción con el entorno.","Describe un fenómeno energético, diferenciando el sistema de análisis, de su entorno.","Comprende el trabajo como el resultado de la intervención de una fuerza, a lo largo y en la dirección de desplazamiento de un sistema, a partir del análisis de situaciones cotidianas.","Identifica al calor como la transferencia de energía térmica, a partir de experiencias sencillas.","Describe las variaciones energéticas de un sistema, reconociendo el/los agente/s del entorno con el/los que interactúa/n, ya sea en forma de calor o trabajo."]', 'PdA p. 113'),
(4, 'eje_contenido', 'Progresiones de Aprendizaje', 'Validación de la conservación de la energía en un sistema aislado, identificando los alcances explicativos de este principio en entornos cotidianos, y reconociendo que la energía, aunque se conserve, tiende a degradarse en formas menos útiles.', 'pda_2025', 1, 'Analizar y explicar las dinámicas de transformación y transferencia de energía entre un sistema y su entorno, reconociendo variables macroscópicas y microscópicas e identificando los modos de producción energética en el país.', '["Anticipa transformaciones energéticas en un sistema, utilizando la idea de conservación de la energía.","Realiza experiencias de laboratorio o explora simulaciones educativas en las que puede analizar la validez de la conservación de la energía.","Contrasta los resultados obtenidos en experiencias o simulaciones con los de sus compañeras/os, reconociendo similitudes y diferencias en los procedimientos realizados.","Reconoce los alcances de la conservación de la energía, cuando el sistema no está aislado del entorno.","Utiliza la idea de degradación de la energía para interpretar situaciones de la vida cotidiana."]', 'PdA p. 114'),
(4, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de las relaciones entre los componentes del sistema solar, identificando los tipos de movimientos que realizan los planetas (traslación y rotación).', 'pda_2025', 1, 'Interpretar diferentes modelos sobre fenómenos físicos mecánicos y ondulatorios, analizando sus alcances y limitaciones explicativas, tanto en escalas astronómicas como cotidianas.', '["Compara los movimientos de los planetas del sistema solar, relacionando los períodos de traslación y las temperaturas medias con las distancias al Sol, y la rotación con la duración de los días.","Registra las fases de la luna durante un período de tiempo, y las relaciona con el movimiento del sistema Tierra-Luna-Sol.","Explora las condiciones que deben darse para que ocurra un eclipse de Sol y las compara con aquellas necesarias para un eclipse de Luna.","Identifica, en el cielo nocturno, algunos planetas y estrellas, seleccionando recursos y herramientas adecuados como referencia.","Explica las estaciones del año mediante esquemas y modelos, reconociendo, como causas, la inclinación del eje de la Tierra y el movimiento de traslación alrededor del Sol."]', 'PdA p. 116'),
(4, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión, desde una perspectiva histórica y mecánica, de los modelos cosmogónicos, tanto del sistema solar como de la evolución del universo, reconociendo la relevancia de los instrumentos tecnológicos para su desarrollo.', 'pda_2025', 1, 'Interpretar diferentes modelos sobre fenómenos físicos mecánicos y ondulatorios, analizando sus alcances y limitaciones explicativas, tanto en escalas astronómicas como cotidianas.', '["Diferencia modelos cosmogónicos del sistema solar, los ubica en el tiempo, y reconoce sus capacidades explicativas.","Identifica las evidencias que formaron parte de la evolución de los modelos del sistema solar.","Destaca el rol de los instrumentos de observación en la construcción de evidencias.","Reconoce las evidencias actuales que son consistentes con la Teoría del Big Bang.","Describe la historia del universo, ubicando temporalmente hitos como la formación del Sol, de los planetas, el surgimiento de la vida y la aparición de la especie humana en la Tierra."]', 'PdA p. 116'),
(4, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de grandes objetos cósmicos, a partir de la comparación de sus diversas características.', 'pda_2025', 1, 'Interpretar diferentes modelos sobre fenómenos físicos mecánicos y ondulatorios, analizando sus alcances y limitaciones explicativas, tanto en escalas astronómicas como cotidianas.', '["Compara, a escala doméstica o cotidiana, las dimensiones de distintos objetos cósmicos.","Indaga acerca de la clasificación de estrellas, según su tamaño y temperatura.","Utiliza unidades de medida adecuadas para describir fenómenos a gran escala (Unidad astronómica-UA, masa solar-Mʘ, entre otras)."]', 'PdA p. 117'),
(4, 'eje_contenido', 'Progresiones de Aprendizaje', 'Diferenciación del concepto de masa respecto del concepto de peso, interpretando la relación existente entre ambos contextos.', 'pda_2025', 1, 'Interpretar diferentes modelos sobre fenómenos físicos mecánicos y ondulatorios, analizando sus alcances y limitaciones explicativas, tanto en escalas astronómicas como cotidianas.', '["Advierte la conservación de la masa, en situaciones hipotéticas de ausencia de la gravedad de la Tierra y sus efectos.","Compara el peso de un mismo objeto ubicado en la superficie de distintos cuerpos celestes, como por ejemplo en la Luna y la Tierra."]', 'PdA p. 117'),
(4, 'eje_contenido', 'Progresiones de Aprendizaje', 'Diferenciación de las características del sonido y su relación con el proceso de modelización ondulatoria (tono, intensidad y timbre), reconociendo los rangos de audición humana y de otras especies animales.', 'pda_2025', 1, 'Interpretar diferentes modelos sobre fenómenos físicos mecánicos y ondulatorios, analizando sus alcances y limitaciones explicativas, tanto en escalas astronómicas como cotidianas.', '["Clasifica sonidos, según su frecuencia, en graves o agudos, y según su amplitud de onda, en intensos o débiles.","Reconoce, por medio de experiencias (con cuerdas o cubetas de agua) o simulaciones digitales, los parámetros de las ondas mecánicas y los relaciona con las características del sonido.","Experimenta los rangos auditivos de frecuencia humana.","Indaga sobre los rangos auditivos de frecuencia de algunas especies animales.","Analiza al eco como un fenómeno de reflexión del sonido, reconociendo que algunos animales utilizan la ecolocalización para orientarse.","Indaga acerca de los efectos de los ruidos en la salud.","Realiza mediciones de intensidad del sonido mediante aplicaciones, y utiliza el decibelio (dB) como unidad de medición para expresar sus valores."]', 'PdA p. 117'),
(4, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación de los usos tecnológicos del sonido, por ejemplo, en la medicina (ultrasonido para tratamientos musculares, ecografías para diagnósticos por imágenes) y en seguridad (reconocimiento de voz para autentificación).', 'pda_2025', 1, 'Interpretar diferentes modelos sobre fenómenos físicos mecánicos y ondulatorios, analizando sus alcances y limitaciones explicativas, tanto en escalas astronómicas como cotidianas.', '["Busca información sobre aplicaciones tecnológicas del sonido y las analiza teniendo en cuenta las características de las ondas sonoras que utilizan.","Reconoce al sonido como un fenómeno que implica movimiento y, por lo tanto, puede asociarse a la energía.","Realiza experiencias con sonidos de distintas frecuencias, para evidenciar la relación entre la intensidad del sonido y la distancia respecto de la fuente generadora."]', 'PdA p. 118'),
(4, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de las características de la luz y su relación con el proceso de modelización ondulatoria (intensidad y color), reconociendo el rango de visión humana y diferenciándolo de otros tipos de radiaciones electromagnéticas.', 'pda_2025', 1, 'Interpretar diferentes modelos sobre fenómenos físicos mecánicos y ondulatorios, analizando sus alcances y limitaciones explicativas, tanto en escalas astronómicas como cotidianas.', '["Relaciona el color de la luz visible a los parámetros frecuencia y longitud de onda.","Identifica la luz como una onda electromagnética y como un proceso de transmisión de energía, relacionando su frecuencia con la cantidad de energía.","Explica, a partir de la energía, las consecuencias que puede generar la exposición a radiaciones electromagnéticas de alta frecuencia (como los UV, los rayos X, entre otros).","Indaga sobre las aplicaciones tecnológicas de ondas electromagnéticas de baja frecuencia."]', 'PdA p. 118'),
(4, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de las aplicaciones de los fenómenos de reflexión y refracción de la luz.', 'pda_2025', 1, 'Interpretar diferentes modelos sobre fenómenos físicos mecánicos y ondulatorios, analizando sus alcances y limitaciones explicativas, tanto en escalas astronómicas como cotidianas.', '["Experimenta con espejos planos para caracterizar el fenómeno de reflexión.","Experimenta con lentes (utilizando simulaciones o laboratorios reales) para evidenciar el fenómeno de refracción de la luz.","Describe al arcoiris como producto de la descomposición de la luz blanca por refracción.","Asocia el color con el que se ve un objeto con la longitud de onda de la luz reflejada por su superficie.","Describe, cualitativamente, el funcionamiento de instrumentos ópticos como la lupa, los anteojos de lectura, el telescopio y el microscopio, para comprender la formación de imágenes asociadas."]', 'PdA p. 118'),
(4, 'eje_contenido', 'Progresiones de Aprendizaje', 'Problematización del uso de diferentes fuentes de energía (renovables y no renovables), considerando sus ventajas y desventajas para integrar la matriz energética del país y la región.', 'pda_2025', 1, 'Establecer relaciones causa-efecto en torno al cambio climático, reconociendo medidas de adaptación climática y otras alternativas viables para la sostenibilidad.', '["Clasifica las distintas fuentes de energía como renovables y no renovables.","Indaga sobre la matriz energética del país y elabora un nuevo diseño que propone formas más sostenibles, argumentando sus decisiones.","Reconoce las fuentes de energía que utiliza cotidianamente: gas natural o envasado, electricidad (y su origen), combustibles de medios de transporte, entre otros.","Reflexiona sobre hábitos individuales y colectivos referidos al uso responsable de la energía."]', 'PdA p. 121'),
(4, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de los minerales asociados con la producción de energía, así como las formas en que esta se produce, distribuye y almacena.', 'pda_2025', 1, 'Establecer relaciones causa-efecto en torno al cambio climático, reconociendo medidas de adaptación climática y otras alternativas viables para la sostenibilidad.', '["Indaga sobre los recursos minerales asociados a las fuentes de energía y su extracción en el territorio nacional.","Reflexiona acerca de los efectos que causan, en el ambiente, los modos de obtención de los minerales.","Reconoce los recursos minerales implicados en el almacenamiento y distribución de energía (por ejemplo, litio y cobre)."]', 'PdA p. 121'),
(4, 'objetivo', 'Objetivo', 'Valorar el cuidado del ambiente desarrollando una actitud crítica frente a la utilización de los recursos naturales y el deterioro del medio.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(4, 'objetivo', 'Objetivo', 'Desarrollar actitudes de curiosidad, exploración y búsqueda sistemática de explicaciones a hechos y fenómenos naturales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(4, 'objetivo', 'Objetivo', 'Utilizar el concepto de energía para interpretar una gran variedad de fenómenos físicos, reconociendo la transformación y conservación, así como al trabajo y el calor como transferencias de energía.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(4, 'objetivo', 'Objetivo', 'Reconocer las propiedades de los materiales presentes en aplicaciones tecnológicas relacionadas con la electricidad y el comportamiento térmico.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(4, 'objetivo', 'Objetivo', 'Reconocer los campos de fuerza, en particular los gravitatorios, eléctricos y magnéticos así como sus interrelaciones.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(4, 'objetivo', 'Objetivo', 'Interpretar que la posibilidad de renovación-reutilización de los recursos naturales energéticos condiciona la obtención y uso de los mismos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(4, 'eje_contenido', 'Los fenómenos del mundo físico', 'Conceptualización de la energía como generadora de cambios (físicos, biológicos y químicos), como propiedad de un sistema y como una magnitud física.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(4, 'eje_contenido', 'Los fenómenos del mundo físico', 'Identificación de la presencia de los procesos energéticos en la vida cotidiana, incluyendo los seres vivos y el ambiente, así como su importancia en los procesos naturales y artificiales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(4, 'eje_contenido', 'Los fenómenos del mundo físico', 'Identificación de la energía potencial y cinética como formas en que se presenta la energía en la materia.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(4, 'eje_contenido', 'Los fenómenos del mundo físico', 'Realización de actividades experimentales adecuadas a la edad y al contexto, sobre fenómenos mecánicos, térmicos y electromagnéticos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(4, 'eje_contenido', 'Los fenómenos del mundo físico', 'Identificación de los factores de los cuales dependen los cambios – cambio de velocidad y deformación – que produce la acción de una fuerza.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(4, 'eje_contenido', 'Los fenómenos del mundo físico', 'Aproximación al concepto de la masa en su relación con la cantidad de materia y su diferenciación con el peso - fuerza con que la Tierra atrae a un cuerpo -, interpretando su relación.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(4, 'eje_contenido', 'Los fenómenos del mundo físico', 'Caracterización de las formas en que se produce tecnológicamente la energía (por combustibles fósiles, eólica, geotérmica, solar, nuclear, etc.).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(4, 'eje_contenido', 'Los fenómenos del mundo físico', 'Identificación de los recursos energéticos naturales -en particular en Argentina- reconociendo que las posibilidades de renovación-reutilización condicionan su obtención y usos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(4, 'eje_contenido', 'Los fenómenos del mundo físico', 'Identificación de algunas interrelaciones entre fenómenos eléctricos y magnéticos, tomando como ejemplo el electroimán.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 55-58'),
(5, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión del espacio geográfico, como una construcción social en la que convergen relaciones y procesos políticos, económicos, culturales y ambientales, en distintas escalas y tiempos.', 'pda_2025', 1, 'Analizar las sociedades y sus transformaciones, considerando cambios y continuidades y la interrelación entre sociedad-espacio-tiempo, a partir de procesos vinculados a identidades, diversidad y alteridad, desigualdad y multiplicidad de voces y saberes.', '["Explica, mediante ejemplos, las interacciones entre las múltiples dimensiones del espacio geográfico (sociales, económicas, ambientales, entre otras) y diversas problemáticas y transformaciones territoriales (deforestación, expansión urbana, entre otras).","Construye, de manera individual y/o colectiva, una definición propia de espacio geográfico, y la pone en juego al analizar diversos procesos sociales (migraciones rurales-urbanas/urbanas-rurales, prácticas sociales de la vida cotidiana, entre otras) a escala local, en relación con otras escalas.","Reflexiona sobre la experiencia de analizar problemáticas territoriales desde definiciones propias.","Ejemplifica y expresa, de manera oral y/o escrita, formas de producción y apropiación diferencial de los espacios, tanto en relación con género e identidades de género, como respecto de otras identidades, desde lo intercultural (migrantes, personas en situación de discapacidad, entre otras)."]', 'PdA p. 93'),
(5, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de características, dinámicas y articulaciones entre espacios urbanos y rurales en la provincia de Córdoba, en la actualidad, y su conexión con procesos y espacios en diversas escalas (regional, global, entre otras).', 'pda_2025', 1, 'Analizar las sociedades y sus transformaciones, considerando cambios y continuidades y la interrelación entre sociedad-espacio-tiempo, a partir de procesos vinculados a identidades, diversidad y alteridad, desigualdad y multiplicidad de voces y saberes.', '["Reconoce, a partir de ejercicios lúdicos y primeras aproximaciones, las características de los espacios urbanos y rurales, y sus interfaces o articulaciones (nuevas ruralidades, periurbanización, entre otras).","Utiliza diversas escalas para el análisis de diferentes espacios urbanos y rurales, y de sus principales actores sociales en la provincia de Córdoba.","Diferencia procesos de transformación territorial actual en los espacios urbanos y rurales (avances de las fronteras agrícolas y del desarrollo inmobiliario, espacios periurbanos, déficit de infraestructura, equipamientos y servicios, situaciones de pobreza y de elitización de los espacios, conurbanizaciones, asentamientos urbanos populares o espontáneos, entre otros).","Identifica y explica dinámicas demográficas, en relación con espacios urbanos y rurales, en diversas escalas.","Establece relaciones entre transformaciones territoriales, a diversas escalas y trayectorias históricas, y procesos de migración (rural-urbano/urbano-rural).","Construye con otros, mapeos colectivos acerca de diversas situaciones de disparidad económica y desigualdad social y territorial en la provincia de Córdoba, en contextos históricos situados.","Conversa sobre las acciones puestas en juego durante la construcción de mapeos, reflexionando sobre su valor para el aprendizaje del tema abordado.","Identifica fortalezas y debilidades en el proceso personal y colectivo de aprendizaje."]', 'PdA p. 94'),
(5, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis social de procesos geofísicos a escala local, y de su vinculación con actividades humanas, problemáticas/desafíos ambientales y transformaciones territoriales.', 'pda_2025', 1, 'Analizar las sociedades y sus transformaciones, considerando cambios y continuidades y la interrelación entre sociedad-espacio-tiempo, a partir de procesos vinculados a identidades, diversidad y alteridad, desigualdad y multiplicidad de voces y saberes.', '["Emplea diversas fuentes de información para el análisis de transformaciones territoriales vinculadas con lo ambiental, reconociendo múltiples voces, saberes y prácticas.","Establece relaciones entre las dimensiones sociales, políticas, culturales y económicas, al interpretar procesos geofísicos y transformaciones territoriales en contextos locales.","Reconoce conflictos ambientales locales y actores sociales implicados, desde un abordaje multiescalar.","Relaciona procesos geofísicos, con diversas causas y factores de riesgos ambientales, y simula con soportes digitales diferentes escenarios, evaluando los impactos de los cambios ambientales en diferentes espacios a escala local."]', 'PdA p. 94'),
(5, 'eje_contenido', 'Progresiones de Aprendizaje', 'Conocimiento de la interacción de diversas escalas espaciales, en el análisis de las configuraciones territoriales y de los procesos sociales.', 'pda_2025', 1, 'Interpretar y construir, de manera individual y colaborativa, diversos dispositivos y representaciones gráficas, cartográficas, audiovisuales y multimediales para la problematización y/o comunicación de procesos y problemáticas históricas y socio-territoriales.', '["Indaga, a partir de casos de estudio, una misma problemática territorial en diferentes escalas (municipal, provincial, internacional), identificando los actores sociales intervinientes.","Explica, a partir de ejemplos, la interrelación local-global, analizando cómo los procesos y decisiones globales impactan en los territorios locales y, a su vez, cómo las dinámicas locales generan transformaciones en diversas escalas geográficas.","Conversa con el grupo acerca de los modos en que se analizaron los casos seleccionados (aspectos que se observaron en cada uno, desafíos que se presentaron durante la tarea, qué se pudo descubrir/observar)."]', 'PdA p. 97'),
(5, 'eje_contenido', 'Progresiones de Aprendizaje', 'Utilización de diversas prácticas cartográficas y formas de representación espacial, analógicas y digitales, como herramientas clave para la comprensión de fenómenos, procesos y acontecimientos producidos en variados territorios.', 'pda_2025', 1, 'Interpretar y construir, de manera individual y colaborativa, diversos dispositivos y representaciones gráficas, cartográficas, audiovisuales y multimediales para la problematización y/o comunicación de procesos y problemáticas históricas y socio-territoriales.', '["Selecciona estrategias para aprender (técnicas de estudio, uso de dispositivos computacionales, tutorías, entre otras).","Emplea diversas prácticas y representaciones cartográficas (como mapas sociales, cartografías participativas, cartografías digitales, croquis, planos, maquetas, mapas políticos y mapas temáticos, entre otras) en el estudio de procesos sociales y problemáticas territoriales.","Explica, mediante representaciones gráficas (croquis, mapas, cartografía social, entre otras), procesos y fenómenos sociales locales, y su relación con procesos regionales, nacionales y globales.","Aplica lenguaje cartográfico, y crea iconografía y símbolos en la construcción, colectiva y colaborativa, de cartografías propias, a partir de problemáticas situadas.","Identifica localizaciones de diversos procesos territoriales y se orienta en diversas escalas, reconociendo las propias fortalezas y dificultades en la adquisición de este conocimiento."]', 'PdA p. 97'),
(5, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación y análisis de los diversos sectores económicos y actores sociales, con énfasis en los usos del suelo, en los espacios urbanos y rurales (agricultura, ganadería, agronegocio, turismo y servicios, entre otros).', 'pda_2025', 1, 'Comprender la complejidad y dinamismo de los procesos sociales, con énfasis en los actores individuales y colectivos involucrados, y su capacidad de acción, decisión e intención, reflexionando en torno al conflicto y las posibilidades de consensos como formas de organización e integración de las sociedades en diferentes escalas.', '["Identifica los usos del suelo en los espacios urbanos (residencial, comercial, industrial, servicios, entre otros), rurales, (productivo, conservación y protección, entre otros) y en los espacios de interfase.","Reconoce diversos sectores económicos (primario, secundario, terciario, entre otros), los actores sociales, y su vinculación con las transformaciones en los usos del suelo.","Identifica variadas prácticas de turismo en espacios urbanos y rurales, y sus implicancias en el contexto local, a partir del abordaje y resolución de situaciones problemáticas.","Busca y consulta, en diversas fuentes de información (bibliográfica, estadística, audiovisual y multimedial), acerca de actividades económicas y usos del suelo que permiten problematizar transformaciones territoriales desde múltiples dimensiones.","Identifica y caracteriza diversas actividades y modos de producción en los espacios rurales (agroecología, agricultura familiar, ganadería, agronegocio, entre otros), y en los espacios urbanos (turismo y servicios, industrial, entre otros), a través de esquemas y otras representaciones gráficas.","Confecciona una lista de las acciones realizadas en situaciones de estudio/actividades, individuales o grupales, y advierte cuáles son más valiosas para su proceso de aprendizaje."]', 'PdA p. 99'),
(5, 'eje_contenido', 'Progresiones de Aprendizaje', 'Conocimiento de la división del trabajo y generación de riqueza en diversas actividades económicas, y los procesos territoriales que estas generan a distintas escalas (municipal, provincial, nacional, internacional).', 'pda_2025', 1, 'Comprender la complejidad y dinamismo de los procesos sociales, con énfasis en los actores individuales y colectivos involucrados, y su capacidad de acción, decisión e intención, reflexionando en torno al conflicto y las posibilidades de consensos como formas de organización e integración de las sociedades en diferentes escalas.', '["Articula escalas espaciales para el análisis de ciertas actividades económicas, a través del estudio de casos (industria automotriz, agroexportación, entre otros).","Identifica diferentes etapas en los procesos de producción y reconoce la distribución de tareas entre grupos de personas involucradas.","Comunica, a través de enunciados argumentativos, acerca de las diversas formas de organización económica (cooperativas, empresas multinacionales, empresas públicas, entre otras) y las implicancias territoriales que estas tienen en la generación de riqueza, desigualdades sociales y espaciales, entre otras.","Reconoce intereses y posicionamientos de actores sociales de diversos sectores económicos, en relación con la intensificación o desaceleración de las transformaciones territoriales, en distintas escalas.","Integra y contrasta la multiplicidad de voces y saberes en estudios de caso acerca de conflictos territoriales, reflexionando sobre la necesidad de trascender las barreras de pensamiento socialmente construidas."]', 'PdA p. 100'),
(5, 'eje_contenido', 'Progresiones de Aprendizaje', 'Diferenciación entre recursos naturales, bienes naturales y bienes comunes, en relación con los modos de producir y habitar los territorios.', 'pda_2025', 1, 'Asumir una participación crítica y activa, como sujetos de derechos con responsabilidades, ante problemas socialmente relevantes en debates vinculados a los principios de justicia social y ambiental, igualdad socioeconómica, diversidad socio-cultural y derechos humanos.', '["Elabora definiciones propias en torno a recursos naturales, bienes naturales o bienes comunes y reconoce nuevos saberes.","Analiza, mediante ejercicios de comparación, formas de apropiación y uso de bienes o recursos, modos de habitar y construir los territorios en grupos distintos (apropiación de un bosque nativo por una empresa multinacional o por comunidades indígenas o campesinas con producción familiar, entre otras).","Identifica bienes naturales, comunes o recursos naturales vinculados con actividades económicas y sociales en Córdoba, y a otras escalas, enfatizando en las cuencas hidrográficas y la accesibilidad al agua.","Construye, de manera individual o colaborativa, desde una mirada hidrosocial, argumentaciones sobre procesos de sequía e inundaciones en Córdoba.","Ejemplifica, a partir de casos y fuentes de información, diversos modos de habitar los territorios, a partir de la vinculación entre sociedad y naturalezas.","Realiza diversas prácticas cartográficas (individuales y colectivas), en las que da cuenta de problemáticas ambientales, en particular de procesos de deforestación e incendios en la provincia de Córdoba.","Reflexiona en torno a cómo, los nuevos conocimientos sobre cartografía, interpelan los que existían.","Debate con otras/otros sobre lo que fue posible aprender acerca de los modos de habitar los territorios (por ejemplo, qué ejercicios o prácticas cartográficas fueron más significativos)."]', 'PdA p. 102'),
(5, 'eje_contenido', 'Progresiones de Aprendizaje', 'Conocimiento de procesos de organización territorial de comunidades indígenas, campesinas y afro de Córdoba, en la actualidad (procesos de reemergencia y comunalización contemporánea).', 'pda_2025', 1, 'Asumir una participación crítica y activa, como sujetos de derechos con responsabilidades, ante problemas socialmente relevantes en debates vinculados a los principios de justicia social y ambiental, igualdad socioeconómica, diversidad socio-cultural y derechos humanos.', '["Identifica, en diversas fuentes (representaciones gráficas y cartográficas, materiales audiovisuales, fuentes históricas escritas y orales, dispositivos multimediales, entre otras), la presencia contemporánea de comunidades indígenas, afro y campesinas en la provincia de Córdoba, y en otras escalas.","Conoce diversos modos de vivir y habitar los territorios de comunidades indígenas, afro y campesinas, en espacios urbanos y rurales de la provincia de Córdoba, y en otras escalas.","Esquematiza aspectos relevantes que caracterizan la organización territorial indígena, campesina o afro en la actualidad, reflexionando acerca de si el resultado es adecuado para un abordaje del tema desde la complejidad.","Usa diversos dispositivos (gráficos, cartográficos, audiovisuales, escritos, entre otros) para expresar la relación comunidad-territorio, en comunidades indígenas, campesinas o afro."]', 'PdA p. 103'),
(5, 'objetivo', 'Objetivo', 'Reconocer la importancia de la Geografía en el campo de las Ciencias Sociales y su interrelación con otras disciplinas para explicar la realidad social.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'objetivo', 'Objetivo', 'Afianzar el concepto de espacio geográfico para aplicarlo a distintos contextos espaciales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'objetivo', 'Objetivo', 'Conocer la organización de los diversos espacios geográficos y su problemáticas territoriales, ambientales y socio-económicas utilizando diferentes escalas geográficas de análisis.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'objetivo', 'Objetivo', 'Desarrollar sensibilidad frente a las problemáticas sociales y ambientales e interés por aportar al mejoramiento de las condiciones de vida.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'objetivo', 'Objetivo', 'Reconocer la importancia de los factores ambientales, de los recursos naturales y de las condiciones sociales en la organización de los espacios geográficos americanos y de distintos continentes.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'objetivo', 'Objetivo', 'Comprender los diversos grados de desarrollo de los espacios geográficos a través de la multicausalidad.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'objetivo', 'Objetivo', 'Interpretar diversas representaciones gráficas y cartográficas del espacio geográfico para el análisis de las problemáticas ambientales, sociales y económicas, incorporando el uso de las TIC.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'eje_contenido', 'Dimensión ambiental del espacio geográfico', 'Conocimiento de los elementos que constituyen el espacio geográfico utilizando la escala local como referencia del análisis.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'eje_contenido', 'Dimensión ambiental del espacio geográfico', 'Conocimiento del mapa político actual de América, teniendo en cuenta las distintas formas de organización política y la localización de las principales áreas de conflicto.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'eje_contenido', 'Dimensión ambiental del espacio geográfico', 'Conocimiento de la diversidad de ambientes de América y otros continentes, identificando recursos naturales y valorando el desarrollo sustentable como alternativa válida como aprovechamiento a lo largo del tiempo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'eje_contenido', 'Dimensión ambiental del espacio geográfico', 'Reconocimiento y análisis de los principales problemas ambientales de América y otros continentes resultantes de las actividades humanas a través del estudio de casos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'eje_contenido', 'Dimensión social y cultural del espacio geográfico', 'Conocimiento de las características de la población americana - estructura y dinámica- estableciendo semejanzas y diferencias con otros continentes.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'eje_contenido', 'Dimensión social y cultural del espacio geográfico', 'Reconocimiento de las principales problemáticas sociales en relación con la movilidad geográfica en América y otros continentes.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'eje_contenido', 'Dimensión social y cultural del espacio geográfico', 'Conocimiento de la diversidad cultural (creencias, valores, prácticas y tradiciones) y sus manifestaciones a partir del estudio de casos en distintos países americanos y regiones de otros continentes.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'eje_contenido', 'Dimensión económica del espacio geográfico', 'Conocimiento de las actividades económicas a través de estudios de casos en América y otros continentes.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'eje_contenido', 'Dimensión económica del espacio geográfico', 'Conocimiento de la organización de los espacios urbanos y rurales a través del estudio de casos en América y otros continentes.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(5, 'eje_contenido', 'Dimensión económica del espacio geográfico', 'Conocimiento de los procesos de urbanización y principales problemáticas asociadas, reconociendo las grandes aglomeraciones urbanas: metrópolis y megalópolis de América y otros continentes.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 87-88'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comparación de situaciones cotidianas en la lengua-cultura inglesa y la propia, en relación con la familia, la escuela, las ocupaciones, el tiempo libre y la organización del tiempo.', 'pda_2025', 1, 'Reconocer y valorar la diversidad de orígenes, prácticas culturales y variedades lingüísticas del inglés; establecer comparaciones con la propia cultura, e identificar y cuestionar estereotipos, para promover una convivencia sensible y responsable en las diferencias.', '["Comparte información personal propia y de otras/os, sobre la familia, la escuela, las/os amigas/os y su barrio, y establece comparaciones con el entorno de compañeras/os o personas de otros lugares.","Reconoce distintas conformaciones familiares y usa un trato respetuoso al hablar de las personas.","Compara diferentes trabajos y ocupaciones (trabajos de su familia, de su barrio, atípicos para nuestra cultura, trabajos sin distinción de género, empleos verdes).","Accede a información sobre deportes, deportistas y actividades recreativas (mundiales y olimpíadas) y la integra con otros temas (por ejemplo, países y nacionalidades).","Utiliza diferentes unidades de tiempo (los momentos del día, la hora, los días de la semana), de acuerdo con diferentes contextos.","Valora la diversidad de preferencias, formas de ser, sentir y pensar, mediante la lectura y/o escucha atenta y respetuosa de las producciones de otras/os."]', 'PdA p. 63');
INSERT INTO `curriculum_contenidos` (`espacio_id`, `tipo`, `titulo`, `descripcion`, `fuente`, `vigente`, `meta`, `indicadores`, `pagina`) VALUES
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento y valoración de la diversidad de entornos (barrios, pueblos, ciudades, zonas rurales), diferentes modos de vivir y prácticas de cuidado del ambiente.', 'pda_2025', 1, 'Reconocer y valorar la diversidad de orígenes, prácticas culturales y variedades lingüísticas del inglés; establecer comparaciones con la propia cultura, e identificar y cuestionar estereotipos, para promover una convivencia sensible y responsable en las diferencias.', '["Describe su barrio, ciudad o entorno, y lo compara con otros lugares.","Identifica señales viales básicas del entorno escolar y su función (cruce peatonal, semáforo, zona de escuela).","Compara las ciudades y sus lugares emblemáticos, así como las actividades que se pueden realizar allí.","Identifica y valora prácticas de consumo responsable y sostenible de recursos, en los entornos trabajados.","Compara diferentes modos de vivir y las actividades que son propias de entornos rurales y urbanos."]', 'PdA p. 63'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento y valoración de la diversidad de orígenes, en relación con los lugares de procedencia y la identidad, con distintos países, ciudades y lenguas del mundo.', 'pda_2025', 1, 'Reconocer y valorar la diversidad de orígenes, prácticas culturales y variedades lingüísticas del inglés; establecer comparaciones con la propia cultura, e identificar y cuestionar estereotipos, para promover una convivencia sensible y responsable en las diferencias.', '["Describe el lugar de procedencia como parte constitutiva de su identidad.","Identifica distintos países y ciudades, y los relaciona con las lenguas que allí se hablan.","Identifica los países del mundo en los que se habla inglés."]', 'PdA p. 64'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interpretación de indicaciones, preguntas e instrucciones simples, tanto en actividades individuales como grupales (classroom language).', 'pda_2025', 1, 'Comprender el sentido global e identificar información específica en textos orales, de creciente complejidad, provenientes de diversas fuentes, utilizando diferentes estrategias con la guía de la/el docente.', '["Entiende y sigue instrucciones que implican dos o más acciones para desarrollar distintas tareas, con apoyo docente.","Escucha y comprende el sentido de preguntas (yes-no questions o alternative questions) que formula la/el docente, a partir de imágenes o temas trabajados.","Reconoce palabras clave en instrucciones o preguntas, para realizar una actividad o tarea."]', 'PdA p. 67'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación de información relevante en textos orales breves y simples de circulación social, como presentaciones personales, descripciones de lugares o diálogos sobre intereses cotidianos.', 'pda_2025', 1, 'Comprender el sentido global e identificar información específica en textos orales, de creciente complejidad, provenientes de diversas fuentes, utilizando diferentes estrategias con la guía de la/el docente.', '["Comprende la idea general en textos orales, por ejemplo, en descripciones, exposiciones e interacciones claras y simples.","Identifica el tema al escuchar un audio claro y pausado, por ejemplo, en un programa de radio.","Detecta información específica en textos orales (datos personales, profesiones, lugares y horarios) a partir de los temas trabajados, y resuelve consignas en función de ello."]', 'PdA p. 67'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación y uso inicial de estrategias de escucha, como la predicción, la inferencia y el reconocimiento de pistas visuales, gestuales y contextuales, para comprender textos orales simples y breves.', 'pda_2025', 1, 'Comprender el sentido global e identificar información específica en textos orales, de creciente complejidad, provenientes de diversas fuentes, utilizando diferentes estrategias con la guía de la/el docente.', '["Predice el contenido de un texto oral a partir del título y las imágenes que se ofrecen, así como por los sonidos del contexto de enunciación.","Relaciona palabras nuevas con las imágenes o los gestos que ofrece la/el docente."]', 'PdA p. 68'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación de aspectos globales y expresiones de uso frecuente en textos literarios breves en lengua inglesa, con reconocimiento inicial de su dimensión lúdica y estética.', 'pda_2025', 1, 'Comprender el sentido global e identificar información específica en textos orales, de creciente complejidad, provenientes de diversas fuentes, utilizando diferentes estrategias con la guía de la/el docente.', '["Participa en actividades de escucha de textos literarios y reconoce, con apoyo docente, el tema principal.","Reconoce la trama general de un texto literario breve, con apoyo visual y contextual, a partir de palabras o frases clave.","Observa aspectos creativos en los textos literarios trabajados, como por ejemplo, la descripción de lugares, y comenta su valor estético con ayuda de la/del docente."]', 'PdA p. 68'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Producción oral en el aula, en respuestas breves y guiadas, a partir de consignas e instrucciones simples, con apoyo visual o gestual.', 'pda_2025', 1, 'Participar en la producción oral de textos simples, con diversos propósitos, e interactuar en situaciones cotidianas de intercambio de ideas e información que incluyan algunos recursos paraverbales y no verbales, adecuados a la situación comunicativa, al destinatario y al propósito.', '["Responde oralmente a instrucciones y preguntas de la/ del docente, con palabras o frases breves, con apoyo visual o gestual.","Usa expresiones básicas para participar en rutinas del aula (pedir permiso, señalar objetos, saludar, expresar necesidad)."]', 'PdA p. 71'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Intercambios orales en situaciones comunicativas cotidianas, sobre temáticas conocidas, vinculadas con la experiencia del estudiante y su entorno, con apoyo docente.', 'pda_2025', 1, 'Participar en la producción oral de textos simples, con diversos propósitos, e interactuar en situaciones cotidianas de intercambio de ideas e información que incluyan algunos recursos paraverbales y no verbales, adecuados a la situación comunicativa, al destinatario y al propósito.', '["Contesta preguntas (Yes/No questions o alternative questions) relacionadas con temas cotidianos, por ejemplo, si vive en Córdoba, si le gusta determinada materia, a través del uso de oraciones simples y comprensibles.","Interviene en intercambios comunicativos con la/el docente o sus compañeras/os, a partir de funciones comunicativas que implican el uso de estructuras trabajadas sobre los temas abordados, aún con presencia de errores.","Formula preguntas de manera clara y adecuada al contexto, a partir de ejemplos proporcionados por la/el docente.","Utiliza expresiones funcionales, como pedidos simples, en contextos cotidianos dentro del aula.","Usa fórmulas de cortesía y evita expresiones discriminatorias en los intercambios orales que se producen en el aula."]', 'PdA p. 71'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Producción oral de presentaciones breves sobre sí misma/o, otras personas o temas conocidos, con uso de vocabulario simple y expresiones trabajadas.', 'pda_2025', 1, 'Participar en la producción oral de textos simples, con diversos propósitos, e interactuar en situaciones cotidianas de intercambio de ideas e información que incluyan algunos recursos paraverbales y no verbales, adecuados a la situación comunicativa, al destinatario y al propósito.', '["Se presenta de manera oral, con frases breves que incluyen nombre, edad, lugar donde vive y aspectos personales básicos.","Realiza presentaciones orales breves sobre objetos, lugares o animales familiares, con uso de vocabulario específico del tema tratado.","Describe a compañeras/os o personas conocidas con apoyo docente, a partir de modelos trabajados, e incluye características físicas simples.","Participa en presentaciones individuales o grupales breves, con expresiones básicas para introducir información y apoyo docente."]', 'PdA p. 71'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Intervención oral guiada en actividades grupales sencillas, como diálogos breves, juegos o dramatizaciones.', 'pda_2025', 1, 'Participar en la producción oral de textos simples, con diversos propósitos, e interactuar en situaciones cotidianas de intercambio de ideas e información que incluyan algunos recursos paraverbales y no verbales, adecuados a la situación comunicativa, al destinatario y al propósito.', '["Representa personajes en dramatizaciones sencillas, respetando turnos de habla y colaborando con sus compañeras/os.","Usa fórmulas básicas de interacción social, en juegos e intercambios orales, como por ejemplo, saludos, despedidas, pedir turnos o responder preguntas, e incorpora recursos paraverbales y no verbales básicos.","Memoriza y recita oralmente rimas y poemas, con apoyo constante de la/del docente."]', 'PdA p. 72'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Desarrollo de la comprensión global y específica de breves textos escritos, vinculados con situaciones cotidianas, escolares y familiares, tales como consignas, artículos de revistas, descripciones, relatos, indicaciones, recetas y órdenes.', 'pda_2025', 1, 'Leer y comprender textos variados, cortos y simples, ficcionales y no ficcionales, sobre temas familiares y de cultura general con diferentes propósitos comunicativos; haciendo uso de estrategias de lectura conocidas.', '["Realiza tareas concretas a partir de la lectura de consignas escritas simples, acompañadas de íconos/imágenes.","Interpreta la idea global de un texto simple y breve, a partir de la identificación del tema correcto, y con el apoyo de imágenes, acompañada/o por la/el docente.","Identifica ideas específicas de un texto simple y breve, relacionadas con palabras conocidas y transparentes, referidas a temáticas trabajadas, con ayuda docente."]', 'PdA p. 75'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de elementos visuales y palabras clave, para anticipar el tema y el propósito de textos simples.', 'pda_2025', 1, 'Leer y comprender textos variados, cortos y simples, ficcionales y no ficcionales, sobre temas familiares y de cultura general con diferentes propósitos comunicativos; haciendo uso de estrategias de lectura conocidas.', '["Reconoce palabras simples y compuestas de uso internacional (como smartphone, app, tablet, snack, biking), para inferir significados del texto y su idea general, con ayuda docente.","Distingue, con apoyo docente, si un texto simple tiene como propósito describir, informar, relatar o invitar.","Reconoce, con apoyo docente, partes visibles de un texto simple (inicio y final), para comprender su sentido general.","Anticipa el tema del texto a partir del título o de la imagen."]', 'PdA p. 75'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Exploración de textos literarios breves, como historietas, poemas, canciones, diálogos, textos instructivos o mensajes simples, con apoyo visual y de la/del docente.', 'pda_2025', 1, 'Leer y comprender textos variados, cortos y simples, ficcionales y no ficcionales, sobre temas familiares y de cultura general con diferentes propósitos comunicativos; haciendo uso de estrategias de lectura conocidas.', '["Infiere el sentido general de una historieta, poema o canción, a partir de palabras conocidas e imágenes, con ayuda docente.","Lee en voz alta fragmentos breves de textos literarios, como diálogos o versos, a partir de un modelo provisto por la/el docente.","Reconoce expresiones frecuentes y recursos simples del lenguaje literario, en historietas y poemas breves, con apoyo docente.","Identifica personajes o situaciones principales en textos literarios breves, a partir de imágenes y palabras conocidas."]', 'PdA p. 76'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de conectores básicos, en relatos breves y secuencias narrativas, con apoyo docente.', 'pda_2025', 1, 'Leer y comprender textos variados, cortos y simples, ficcionales y no ficcionales, sobre temas familiares y de cultura general con diferentes propósitos comunicativos; haciendo uso de estrategias de lectura conocidas.', '["Ordena cronológicamente algunos elementos básicos en una historia simple y breve, con ayuda de las ilustraciones provistas y la guía docente.","Comprende palabras que acompañan secuenciaciones, por ejemplo, first, second, finally."]', 'PdA p. 76'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Escritura de textos simples vinculados con situaciones familiares, escolares y cotidianas, a partir de modelos proporcionados por la/el docente, como fichas personales, e-mails informales, intercambios breves entre pares y notas simples.', 'pda_2025', 1, 'Escribir textos de variada complejidad sobre diversos temas; tener en cuenta el proceso de producción; respetar las convenciones de la lengua inglesa escrita y hacer uso de manera procesual de estrategias de escritura.', '["Escribe mensajes informales breves (como fichas personales o notas simples) sobre información básica, por ejemplo, nombre, edad y preferencias, a partir de modelos provistos por la/el docente.","Redacta descripciones sencillas de personas, lugares o actividades, a través del uso de oraciones simples y del vocabulario trabajado.","Contribuye a la escritura grupal de textos sencillos, como diálogos o listas, incorporando ideas propias y respetando acuerdos con sus compañeras/os.","Utiliza recursos digitales o en papel para escribir textos breves, como notas personales, listas o descripciones simples.","Revisa que su texto respete reglas simples de ortografía y puntuación (mayúsculas y punto final), con la guía de la/del docente."]', 'PdA p. 80'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Producción de frases estructuradas para expresar gustos y habilidades personales, con apoyo docente, y en relación con las convenciones básicas de la lengua escrita.', 'pda_2025', 1, 'Escribir textos de variada complejidad sobre diversos temas; tener en cuenta el proceso de producción; respetar las convenciones de la lengua inglesa escrita y hacer uso de manera procesual de estrategias de escritura.', '["Usa frases simples para expresar gustos, preferencias u opiniones sobre temas cotidianos, como I like pizza; I don’t like fish.","Identifica algunas convenciones de la lengua escrita, como la coma después de dirigirse a alguien (en lugar de los dos puntos) o el uso de la mayúscula para referirse a la primera persona del singular.","Emplea signos básicos de puntuación, como la coma o el punto, para organizar oraciones breves y separar acciones."]', 'PdA p. 80'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de estrategias de escritura, como la planificación y la revisión, a partir de modelos o guías proporcionadas por la/el docente.', 'pda_2025', 1, 'Escribir textos de variada complejidad sobre diversos temas; tener en cuenta el proceso de producción; respetar las convenciones de la lengua inglesa escrita y hacer uso de manera procesual de estrategias de escritura.', '["Identifica elementos clave en un plan o guía, como el propósito, la estructura básica (introducción, desarrollo, conclusión) y el vocabulario sugerido.","Organiza ideas e identifica palabras clave, a partir de preguntas o esquemas guiados, para planificar un texto breve.","Completa una primera versión del texto como borrador, a partir de indicaciones para identificar y corregir errores básicos.","Revisa el texto, con ayuda de la/del docente, incorporando correcciones básicas sobre vocabulario, contenido y organización."]', 'PdA p. 81'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación y reflexión, con ayuda docente, de las diferencias de algunos sonidos entre la lengua de escolarización y el inglés —en relación con su ortografía y pronunciación—, y de la entonación, como portadora de sentidos.', 'pda_2025', 1, 'Identificar, reflexionar y sistematizar aspectos fundamentales del funcionamiento de la lengua extranjera, de manera inductiva, en uso y contextualizada, a partir de textos orales y escritos que son parte de situaciones comunicativas concretas.', '["Reconoce, con apoyo docente, algunas diferencias básicas entre sonidos del inglés y del español, en palabras o frases simples.","Reconoce con ayuda docente, diferencias básicas de ritmo y entonación entre el español y el inglés, en frases simples."]', 'PdA p. 84'),
(6, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento y uso de aspectos léxico-gramaticales básicos de la lengua inglesa, en comparación con la lengua de escolarización, cuando sea de utilidad para comprender y comunicar información simple.', 'pda_2025', 1, 'Identificar, reflexionar y sistematizar aspectos fundamentales del funcionamiento de la lengua extranjera, de manera inductiva, en uso y contextualizada, a partir de textos orales y escritos que son parte de situaciones comunicativas concretas.', '["Distingue categorías como sustantivos (places in town) y adjetivos (big, small, huge, popular) para comprender y comunicar información.","Identifica las terminaciones más comunes para formar sustantivos (ocupaciones y profesiones: -er, teacher, -ian, electrician) y adjetivos gentilicios (-ish, Irish, -ian, Argentinian, entre otros).","Reconoce y emplea expresiones frecuentes formadas por un verbo y otra palabra que suelen ir juntas (collocations), como play football, go swimming o have lunch, con apoyo docente.","Reconoce y utiliza las formas del verbo to be (am, is, are) en afirmaciones, interrogaciones y negaciones, para comprender y comunicar información personal.","Reconoce las formas de expresar habilidades sobre sí misma/o y sobre otras personas (can/can’t).","Reconoce y utiliza el verbo have got en afirmaciones, negaciones e interrogaciones para expresar posesión, pertenencia y vínculos familiares en contextos cotidianos.","Describe personas, lugares y objetos de su entorno cercano, como la escuela, el barrio o su familia, con el uso de there is / there are en frases afirmativas, negativas e interrogativas."]', 'PdA p. 84'),
(6, 'objetivo', 'Objetivo', 'Desarrollar gradual y progresivamente estrategias de comprensión y producción de textos orales y escritos, ficcionales y no ficcionales a través de la exploración de la organización textual, la comprensión del léxico, el sentido del texto, mediante la participación en situaciones comunicativas orales y escritas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'objetivo', 'Objetivo', 'Desarrollar habilidades lingüísticas, pragmáticas y discursivas, para la comprensión y la producción de textos orales y escritos, en forma gradual y progresiva a partir del abordaje de textos de estructura simple y respondiendo a consignas de no más de una instrucción.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'objetivo', 'Objetivo', 'Iniciarse en el uso de los recursos tecnológicos que facilitan el proceso de aprendizaje del inglés, de acuerdo con los formatos seleccionados.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'objetivo', 'Objetivo', 'Formarse progresivamente como lector autónomo, mediante el acceso a textos informativos de interés general y al discurso literario, a través de la interacción con distintos géneros adaptados al nivel de los estudiantes.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'objetivo', 'Objetivo', 'Iniciarse en la reflexión en relación con las capacidades requeridas para el aprendizaje de la lengua en los aspectos metacognitivo, metacomunicativo, metalingüístico e intercultural.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'objetivo', 'Objetivo', 'Desarrollar progresivamente estrategias para regular logros y dificultades en la comprensión y producción de textos orales y escritos, la adquisición gradual de habilidades lingüísticas, pragmáticas, discursivas, estratégicas y sociolingüísticas, y la formación intercultural.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'objetivo', 'Objetivo', 'Desarrollar gradualmente las actitudes vinculadas con las relaciones interpersonales, la confianza en sus propias posibilidades, la relación con el conocimiento y el respeto por lo diferente.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'eje_contenido', 'Oralidad (hablar)', 'Participación en intercambios sencillos y directos de información, de uso frecuente, en situaciones cotidianas, sobre temáticas conocidas relacionadas con la experiencia del estudiante, la realidad que lo circunda, que le son significativas (con énfasis gradual en la fluidez y precisión gramatical).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'eje_contenido', 'Oralidad (hablar)', 'Uso de fórmulas sociales en intercambios cotidianos básicos, formales e informales, teniendo en cuenta los recursos no verbales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'eje_contenido', 'Oralidad (escuchar)', 'Adquisición de estrategias de comprensión de enunciados de uso frecuente y cotidiano relacionados con la experiencia del estudiante y que le son significativos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'eje_contenido', 'Oralidad (escuchar)', 'Reconocimiento de los rasgos distintivos de la pronunciación de esta lengua.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'eje_contenido', 'Escritura', 'Producción de instrucciones simples, listados, diálogos cortos, narraciones con descripciones sencillas en forma de párrafo, postales y/o cartas breves, completado de formularios y tablas horarias.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'eje_contenido', 'Escritura', 'Interacción por medios tecnológicos: e-mails, postales, folletos, formularios, mensajes de texto.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'eje_contenido', 'Lectura', 'Comprensión global de textos sencillos relacionados con temáticas conocidas, cotidianas o del interés de los estudiantes, para extraer la información requerida.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'eje_contenido', 'Lectura', 'Reconocimiento de los propósitos del texto escrito de acuerdo con la situación comunicativa.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'eje_contenido', 'Lectura', 'Desarrollo de habilidades para la búsqueda de significados en el diccionario bilingüe de acuerdo con las posibilidades de comprensión de los estudiantes.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(6, 'eje_contenido', 'Lectura', 'Práctica de comprensión de textos literarios simples implementando estrategias básicas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Reconocimiento del entorno natural y artificial/cultural como espacio susceptible de ser interpretado y/o intervenido estéticamente (paisajes visuales), a través de diferentes recursos visuales (safaris fotográficos, aplicaciones digitales, realidad aumentada, entre otros).', 'pda_2025', 1, 'Construir una perspectiva que integre los componentes del código visual en diferentes experiencias, prácticas y producciones artísticas contemporáneas, para desarrollar lecturas divergentes de las intencionalidades expresivo-comunicativas y de la valoración del patrimonio cultural.', '["Observa, a través de registros mediados por tecnologías (videos, imágenes satelitales, uso de visores, apuntes gráficos, fotografías, entre otros), en caso de ser posible, el entorno urbano y/o natural, para reconocer características de diferentes zonas y/o barrios de la ciudad de Córdoba y de otras ciudades.","Identifica vinculaciones entre entornos y producciones artísticas, avanzando en la conceptualización de “construcciones culturales”.","Formula hipótesis sobre las diferentes funciones comunicativo-culturales que pueden tener las obras artísticas en el espacio público.","Identifica la saturación visual y su relación con la industria publicitaria, para construir nociones vinculadas con la contaminación visual del paisaje.","Distingue entre imágenes con movimiento real de aquellas con movimiento ilusorio o aparente (fenómenos de ilusión óptica), y sus funciones en el espacio urbano.","Evidencia su percepción del espacio a través de las nociones de proximidad/lejanía, superposición de formas y horizonte del paisaje urbano y/o natural."]', 'PdA p. 62'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Análisis de producciones visuales, propias y ajenas, con observación de la diversidad simbólica y las intenciones comunicativas, para identificar las decisiones tomadas a lo largo del proceso de producción y establecer relaciones entre la intencionalidad comunicativa y la producción de sentido estético.', 'pda_2025', 1, 'Construir una perspectiva que integre los componentes del código visual en diferentes experiencias, prácticas y producciones artísticas contemporáneas, para desarrollar lecturas divergentes de las intencionalidades expresivo-comunicativas y de la valoración del patrimonio cultural.', '["Identifica y nombra componentes formales y compositivos utilizados en su producción, reconociendo su efecto visual y expresivo a través de un vocabulario técnico adecuado.","Describe su proceso creativo, para evidenciar las decisiones técnicas adoptadas y cómo estas expresan su intención estética y comunicativa.","Reflexiona sobre su proceso de producción, identifica decisiones estéticas o temáticas que le resultaron significativas y expresa sus motivaciones personales.","Comparte su valoración personal sobre las producciones de pares o artistas (locales, nacionales o internacionales) y reconoce elementos que le generan identificación, extrañamiento o cuestionamiento","Expresa su mirada crítica sobre los resultados obtenidos, interpretando las características visuales de su obra en diálogo con movimientos artísticos o referentes abordados.","Interpreta visualmente, de forma diferenciada, los sentidos literales y metafóricos de las imágenes observadas, proponiendo hipótesis desde su perspectiva sensible y cultural."]', 'PdA p. 62'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Participación reflexiva en encuentros, muestras y espectáculos, dentro y fuera de la escuela, para valorar las producciones artísticas de diversos lenguajes visuales (plateros, fotógrafos, ceramistas, tejedores, ilustradores, artesanos, escenógrafos, entre otros) que conforman el patrimonio cultural local, provincial y nacional.', 'pda_2025', 1, 'Construir una perspectiva que integre los componentes del código visual en diferentes experiencias, prácticas y producciones artísticas contemporáneas, para desarrollar lecturas divergentes de las intencionalidades expresivo-comunicativas y de la valoración del patrimonio cultural.', '["Indaga vivencialmente acerca de las producciones artísticas que integran el patrimonio cultural local, provincial y nacional, como parte del ejercicio de una ciudadanía cultural plena.","Describe las características de los diversos lenguajes artísticos, sus similitudes y diferencias, como parte del patrimonio cultural local.","Reconoce el valor artístico y cultural de variadas producciones y prácticas, y su vinculación con la identidad cultural.","Argumenta, de manera oral o escrita, acerca de los sentidos estético-comunicativos de las prácticas y producciones vivenciadas."]', 'PdA p. 63'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Análisis de propuestas culturales presentes en su entorno inmediato, para favorecer la identificación de algunos de los circuitos de producción (talleres, cursos), exhibición (centros culturales, galerías, centros vecinales) y circulación (ferias, eventos especiales, concursos) artístico-culturales.', 'pda_2025', 1, 'Construir una perspectiva que integre los componentes del código visual en diferentes experiencias, prácticas y producciones artísticas contemporáneas, para desarrollar lecturas divergentes de las intencionalidades expresivo-comunicativas y de la valoración del patrimonio cultural.', '["Indaga a través de fuentes diversas (páginas web oficiales y/o privadas, publicidades, artículos periodísticos, entrevistas a referentes —vecinas/os, familiares, entre otros— ) acerca de los espacios artísticos-culturales cercanos, sus características, propuestas, horarios y otra información relevante.","Desarrolla dispositivos comunicacionales analógicos y/o digitales (folletos, afiches publicitarios, vídeos promocionales, podcast, entre otros) para compartir la información relevada.","Participa de instancias escolares de socialización y difusión de producciones desarrolladas.","Compara y valora similitudes y diferencias entre las distintas prácticas y lenguajes artísticos (visuales, audiovisuales, performáticos) presentes en su entorno inmediato, para evidenciar su interpretación.","Reflexiona acerca de las propuestas, posibilidades de acceso y la participación de la oferta cultural próxima y su variedad."]', 'PdA p. 63'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Indagación sobre producciones visuales propias y ajenas (imágenes fijas o en movimiento), reconocimiento de los factores culturales presentes (tensiones culturales, hibridaciones, entre otras) y establecimiento de vínculos entre la propia sensibilidad y otras posibilidades estético-expresivas.', 'pda_2025', 1, 'Construir una perspectiva que integre los componentes del código visual en diferentes experiencias, prácticas y producciones artísticas contemporáneas, para desarrollar lecturas divergentes de las intencionalidades expresivo-comunicativas y de la valoración del patrimonio cultural.', '["Realiza lecturas personales de una misma obra y reconoce las sensaciones, los recuerdos o las ideas que le provoca.","Diferencia entre el significado literal y el metafórico en producciones visuales, vinculando esos sentidos con su propia experiencia.","Compara, con actitud reflexiva y respetuosa, producciones ajenas e identifica decisiones estéticas, recursos expresivos y sentidos construidos, reconociendo la diversidad cultural.","Identifica elementos visuales que expresan la interacción cultural entre pueblos originarios, afrodescendientes, europeos, entre otros, tanto históricos como contemporáneos.","Reconoce expresiones artísticas que dialogan con memorias colectivas, territorios, conflictos sociales, problemáticas de género y diversidades.","Expresa su mirada sobre los vínculos entre arte, identidad y pertenencia cultural, en diferentes regiones."]', 'PdA p. 64'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Aproximación a prácticas de diferentes culturas (de pueblos originarios, latinoamericanas, afrodescendientes, europeas, entre otras) presentes en el entorno cercano, para identificar vínculos entre arte, territorio, memoria e identidad y vivenciar, a través de registros audiovisuales (documentales, cortometrajes), fotográficos, el rol social del arte en su comunidad.', 'pda_2025', 1, 'Construir una perspectiva que integre los componentes del código visual en diferentes experiencias, prácticas y producciones artísticas contemporáneas, para desarrollar lecturas divergentes de las intencionalidades expresivo-comunicativas y de la valoración del patrimonio cultural.', '["Reconoce elementos visuales que expresan tradiciones, tensiones o hibridaciones culturales, en prácticas de diferentes regiones.","Establece relaciones entre producciones visuales y contextos territoriales, sociales o históricos, con una mirada reflexiva.","Participa, con compromiso y respeto, en experiencias culturales (rituales, eventos festivos, entre otros) e interpreta sentidos simbólicos y/o comunicativos.","Elabora producciones visuales, textuales o digitales, que expresan una perspectiva crítica acerca del valor del arte en su comunidad.","Identifica expresiones culturales locales, como formas de construcción de identidad y memoria colectiva."]', 'PdA p. 64'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Indagación en torno a prácticas y/o producciones visuales de variadas épocas, espacios, géneros y estilos, y detección de características formales, compositivas y expresivas que despierten su interés,curiosidad,reflexión y le permitan construir interpretaciones situadas acerca de las diferentes maneras de ver el mundo y de representarlo.', 'pda_2025', 1, 'Construir conocimientos significativos en relación con la identidad y la valoración del patrimonio cultural, comprendiendo el sentido de las prácticas y producciones artísticas en el marco del contexto sociohistórico y cultural en el que se producen.', '["Identifica y describe elementos compositivos (relación figurafondo, equilibrio visual, entre otros) y componentes expresivo-comunicativos (lo connotado, lo denotado, entre otros), en obras de diferentes contextos.","Reconoce y reflexiona sobre el papel de la/del espectadora/or o público en cada producción y/o práctica abordada, y analiza cómo su presencia o ausencia modifica el sentido de la obra en diferentes contextos.","Compara y valora similitudes y diferencias en el tratamiento estético-visual y sus funciones en la representación de la figura humana en las obras de arte, publicidades y medios de comunicación e identifica entre retratos naturalistas y representaciones estilizadas (geometrización, síntesis, exaltación de rasgos, entre otras).","Analiza y evalúa las características del arte urbano (monumentos, murales, esténcil, grafiti, entre otros) mediante registros propios o ajenos, y/o recorridos físicos y/o virtuales, y construye la noción de arte urbano, diferenciando entre el arte en el espacio público y el espacio privado.","Reflexiona acerca de los modos de representación de los paisajes urbanos, rurales y naturales (de artistas viajeras/os del siglo XIX, paisajistas cordobesas/es, artistas contemporáneas/os, entre otros) y las representaciones idealizadas (Xul Solar, Gyula Kosice, entre otros), para detectar características representativas."]', 'PdA p. 65'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Valoración de las prácticas y producciones artísticas que integran el patrimonio cultural local, provincial y nacional, como parte del ejercicio de una ciudadanía cultural plena.', 'pda_2025', 1, 'Construir conocimientos significativos en relación con la identidad y la valoración del patrimonio cultural, comprendiendo el sentido de las prácticas y producciones artísticas en el marco del contexto sociohistórico y cultural en el que se producen.', '["Identifica factores que determinan el valor artístico (trayectoria, legitimación, entre otros) y cultural de variadas producciones artísticas.","Reconoce la vinculación entre producciones, identidad cultural y contextos de producción, circulación y exhibición.","Construye progresivamente, desde lo experimentado, el respeto por la diversidad cultural y sus manifestaciones.","Ensaya argumentaciones, orales y/o escritas, para expresar la diferencia entre el concepto de visión (como acto fisiológico) y la noción de mirada (como construcción cultural), a través del uso de ejemplos que recupera de obras y/o prácticas estudiadas."]', 'PdA p. 66'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Reflexión crítica acerca de la relación entre las temáticas de las prácticas artísticas y los contextos culturales de circulación (el barrio, el entorno urbano, el entorno rural, la provincia, el país, la región, las redes sociales, entre otros), a través de diferentes épocas y geografías.', 'pda_2025', 1, 'Construir conocimientos significativos en relación con la identidad y la valoración del patrimonio cultural, comprendiendo el sentido de las prácticas y producciones artísticas en el marco del contexto sociohistórico y cultural en el que se producen.', '["Relaciona los contextos con las posibilidades estético-expresivas y temáticas de las manifestaciones artísticas que albergan.","Detecta similitudes y diferencias entre las prácticas y las producciones artísticas, según el contexto.","Reconoce la construcción de metáforas en lo observado y la noción de poéticas, en función de las temáticas abordadas.","Utiliza aplicaciones digitales y de realidad aumentada para conocer estéticas urbanas del pasado y del presente, en distintas ciudades del mundo."]', 'PdA p. 66'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Reflexión crítica acerca de la relación entre las imágenes visuales, los contextos y los circuitos de circulación (museos, clubes, teatros, plazas, calles, cine, redes sociales, entre otros), con especial énfasis en los medios de comunicación.', 'pda_2025', 1, 'Construir conocimientos significativos en relación con la identidad y la valoración del patrimonio cultural, comprendiendo el sentido de las prácticas y producciones artísticas en el marco del contexto sociohistórico y cultural en el que se producen.', '["Identifica las prácticas culturales que desarrolla individualmente, con su grupo de pares y/o con su familia.","Describe los factores (económicos, psicológicos, sociales, culturales, entre otros) que determinan sus elecciones de prácticas y consumos culturales.","Indaga, de acuerdo con sus intereses personales, acerca de procesos creativos de artistas locales, nacionales y latinoamericanas/os y reconoce las relaciones entre contexto, técnica y discurso visual (ámbitos y herramientas de la creación contemporánea).","Analiza los aspectos éticos y estéticos en la difusión y circulación de imágenes, como imagen pública y privada, consentimiento expreso para la difusión de imágenes, respeto por las diferencias, libertad de expresión y censura.","Problematiza la circulación de imágenes (la fotografía, la fotocopia, los memes, las modificaciones con aplicaciones de IA, entre otras) a través de las plataformas digitales, en el mundo contemporáneo.","Establece relaciones entre circulación de imágenes y prácticas intimidatorias (bullying, ciberacoso, grooming, entre otras) por medio de las tecnológicas digitales."]', 'PdA p. 66'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Análisis de los procesos de producción artística, decisiones autorales e intencionalidades comunicativas, según las dimensiones históricas, sociales, culturales y políticas, a partir de sus aspectos formales y estéticos.', 'pda_2025', 1, 'Construir conocimientos significativos en relación con la identidad y la valoración del patrimonio cultural, comprendiendo el sentido de las prácticas y producciones artísticas en el marco del contexto sociohistórico y cultural en el que se producen.', '["Reconoce las relaciones entre el contexto histórico-social y las temáticas abordadas en obras artísticas de distintas épocas y culturas.","Analiza cómo las decisiones autorales en una obra (técnica, formato, temática, tratamiento estético) responden o reaccionan frente a las problemáticas sociales, políticas o culturales de su tiempo.","Interpreta el rol del arte como medio de comunicación, denuncia, resistencia o transformación social, a partir del análisis de producciones artísticas contextualizadas.","Establece comparaciones entre producciones artísticas de distintos contextos, e identifica las continuidades o rupturas en relación con los discursos sociales, culturales y/o políticos que expresan.","Ensaya argumentaciones acerca del sentido y la función social de las obras analizadas, integrando referencias al contexto y al lenguaje artístico."]', 'PdA p. 67'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Indagación sobre las formas de representación de la figura humana (retratos, autorretratos, cuerpo completo, estereotipos, estática, en movimiento, entre otras), en diferentes contextos y períodos históricos.', 'pda_2025', 1, 'Construir conocimientos significativos en relación con la identidad y la valoración del patrimonio cultural, comprendiendo el sentido de las prácticas y producciones artísticas en el marco del contexto sociohistórico y cultural en el que se producen.', '["Explora la noción de canon estético y representaciones de género estereotipadas e invisibilizadas, en diferentes producciones.","Reconoce las diversas representaciones e intencionalidades en el uso de la figura humana.","Demuestra una mirada crítica en los análisis que desarrolla acerca de las representaciones vinculadas con la figura humana.","Participa en debates sobre las representaciones estereotipadas de género, el lugar asignado en los circuitos de producción artística y el rol en la construcción identitaria."]', 'PdA p. 67'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Realización de producciones bidimensionales exploratorias (dibujos, pinturas, grabados, collage, fotografías, entre otras) utilizando diversos materiales y soportes (analógicos, digitales, convencionales, reutilizables, recuperados) a partir de diferentes estrategias constructivas, en busca de una imagen propia.', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Reconoce, en diversas producciones artísticas (cuadros, fotografías, murales) y entornos cotidianos (avenidas, paisajes), los elementos formales de la perspectiva (línea de horizonte, puntos de fuga, posición de la/del observadora/or, entre otros).","Implementa el uso de la perspectiva para representar el mundo que la/o rodea y los escenarios imaginarios.","Experimenta con el grabado y sus diferentes variantes (monocopia, sellos, xilografía, entre otras).","Investiga las posibilidades estéticas de técnicas fotográficas antiguas y sostenibles, como cianotipia, antotipia, cromotipia, entre otras.","Explora diferentes estrategias constructivas a partir del uso del color (mancha, transparencia, veladuras, mezclas, tono, contraste, entre otras), de la textura (visual, táctil, propia, generada), del collage, la fotografía, el fotomontaje, reconociendo las similitudes y diferencias de sus posibilidades expresivas, estéticas y formales (paleta pigmentaria, paleta gráfica, paleta lumínica).","Construye, progresivamente, una imagen propia en cada producción bidimensional desarrollada."]', 'PdA p. 68'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Organización de la composición y selección de opciones con mayores niveles de intencionalidad estética, entre las formas, los espacios y los grados de relación (simple-simple, complejo-simple, complejo-complejo).', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Indaga acerca de la noción de equilibrio visual, por medio de la experimentación con diferentes variantes (simétrico, asimétrico, radial).","Ensaya composiciones bidimensionales, atendiendo a la organización intencional de las formas (figurativas y no figurativas, entre otras), los espacios, los indicadores y los grados de relación (figura simple o compleja sobre fondos simples o complejos y variantes).","Ordena las composiciones, considerando tamaños del plano, marco, encuadre, formas, luces y sombras.","Explora las tipografías e íconos, como elementos estéticos y narrativos, en las imágenes seriadas.","Experimenta las posibilidades del registro fotográfico secuencial para la representación o ilusión de movimiento, a partir del uso de diferentes tipos de encuadre y de su relación con el contenido significativo de la imagen.","Describe las decisiones compositivas tomadas a lo largo del proceso creativo, se hace preguntas o responde sobre posibles alternativas, proponiendo modificaciones o ajustes y evidenciando sus intencionalidades expresivas."]', 'PdA p. 68'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Experimentación de las cualidades formales y expresivas de materiales, herramientas, soportes, técnicas y procedimientos propios del lenguaje visual, en la representación bidimensional, tanto analógica como digital.', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Combina procedimientos, materialidades y soportes, en función de sus aportes expresivos y simbólicos a lo creado.","Identifica características y usos diversos de las herramientas gráficas y pictóricas, analógicas y digitales.","Relaciona técnicas con los materiales y sus posibilidades plásticas y visuales, y los diferentes componentes con el todo.","Crea herramientas no convencionales para el dibujo, la pintura y las impresiones, de pequeño, mediano y gran formato.","Recupera materiales en desuso y de elementos orgánicos, y reconoce sus cualidades, posibilidades estéticas y de afectación ambiental."]', 'PdA p. 69'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Participación en actividades grupales de producción artística que potencien la socialización, el diálogo y la argumentación, inspiradas en prácticas contemporáneas.', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Trabaja con sus pares ocupando diferentes roles, sin distinción de género, para producir colaborativamente y promoviendo la resolución conjunta de conflictos creativos y/o de ideas divergentes.","Respeta las opiniones de pares, expresa la propia y construye acuerdos de trabajo colaborativo.","Explora las posibilidades del cuerpo como soporte y contenido expresivo en el arte contemporáneo, así como las alternativas que proponen las tecnologías de proyección y ampliación de la imagen (por ejemplo, mapping).","Reconoce las características del tableau vivant, como práctica artística performática, en la que se resignifican obras del pasado.","Selecciona obras artísticas para su apropiación y resignificación considerando sentidos, gestos y contextos."]', 'PdA p. 69'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Creación de dibujos, pinturas, grabados, collage, fotografías, fotomontajes, stopmotion, y vídeos mediante la utilización de diversos materiales y soportes (analógicos, digitales, convencionales, reutilizables, recuperados, no convencionales) y reconocimiento de la dimensión procesual de toda producción artística.', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Reconoce las cualidades del color, como tono, saturación, valor, y explora sus variantes a través de manchas, transparencias, veladuras, mezclas, entre otras.","Juega con diferentes texturas, visuales y táctiles, para enriquecer y complejizar sus producciones, tanto analógicas como digitales.","Emplea los elementos del lenguaje fotográfico y audiovisual (planos, encuadre, ángulos de visión, ley de los tercios, ley de la mirada, entre otros) en producciones con intencionalidad estético-expresiva.","Desarrolla historietas identificando sus elementos formales (viñetas, globos, cartelas, entre otros) y sus posibilidades narrativas y expresivas, en formatos analógicos y/o digitales.","Utiliza la técnica de la perspectiva con diferentes grados de complejidad (a uno, dos y tres puntos de fuga, caballera, isométrica, entre otras) y proyecta instalaciones y/o intervenciones en el espacio.","Avanza en la consolidación de una imagen propia en cada producción bidimensional que desarrolla, a partir del uso de diversas materialidades y soportes, distinguiendo los diferentes momentos del proceso creativo propio y el de sus pares."]', 'PdA p. 70'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Elección de diferentes criterios compositivos para sus producciones, con mayores niveles de intencionalidad estética, vinculada con el uso de formas figurativas y no figurativas, espacios llenos y vacíos, relación entre figura y fondo, equilibrio visual, entre otros.', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Experimenta con diversos criterios compositivos, atendiendo a indicadores espaciales y formales (organización, tamaños y orientación del plano; encuadre; formas, luces, sombras, marco).","Distribuye las formas en el plano a partir de diferentes estrategias (superposición, yuxtaposición, entre otras), para generar la ilusión de cercanía o distancia a través de la distorsión, la deformación expresiva, el extrañamiento, los diferentes tamaños, la variación de la escala.","Explica los criterios compositivos usados en sus producciones cuando opera con figuras y fondos, como, por ejemplo, la dirección (relación entre la posición de las figuras respecto del límite de la imagen) y el intervalo (medida del espacio entre las figuras), evidenciando decisiones tomadas y posibles modificaciones o mejoras.","Utiliza técnicas de calado, troquelado, collage, haciendo uso de diseños en positivo, negativo y fragmentos.","Distingue entre tipos de figuras y formas (abiertas, como las integradas parcial o totalmente al fondo; cerradas, como las aisladas del fondo mediante la presencia de un contorno continuo) y la relación entre el soporte y los elementos visuales.","Incorpora nociones de simetría (aparente, radial, axial, rotacional, traslacional) y asimetría en sus producciones."]', 'PdA p. 70'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Empleo estratégico, en diferentes producciones visuales, de componentes, materiales, herramientas, soportes, técnicas, recursos y procedimientos propios del lenguaje visual, en el espacio bidimensional analógico y/o digital.', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Utiliza diferentes materiales, herramientas, soportes, técnicas y procedimientos —analógicos y digitales— y reconoce sus cualidades formales y expresivas, en función de sus intenciones creativas.","Conoce y hace uso de los elementos característicos de la historieta (viñetas, globos, onomatopeyas, cartelas, entre otros).","Construye una imagen personal de acuerdo con el propio imaginario y las habilidades técnicas adquiridas.","Adquiere experiencia y destreza en la manipulación de materiales, para generar formas singulares e improntas personales que evidencian las marcas gestuales.","Identifica marcas de la gestualidad y la factura, como el trazo, la pincelada, los empastes, entre otros, y su aporte a la creación gráfico-pictórica."]', 'PdA p. 71'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Participación en actividades grupales de producción artística que vinculen problemáticas comunitarias con espacios institucionales, internos y/o externos.', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Trabaja con sus pares, ocupando diferentes roles, sin distinción de género, para producir acuerdos de trabajo colaborativo en proyectos interdisciplinarios.","Argumenta oralmente sus opiniones sobre la propuesta temática a desarrollar y respeta opiniones diferentes.","Realiza un trabajo procesual, reconociendo y respetando los tiempos de desarrollo para cada etapa.","Explora el arte textil contemporáneo con el uso de materiales y técnicas tradicionales de pueblos originarios y los combina con materiales no convencionales (como plástico, celuloide, cables, mediante anudados, trenzados) para reconocer los cruces culturales e identitarios vinculados con la producción artística.","Indaga recursos técnicos no tradicionales en producciones artísticas contemporáneas, como el uso de fotocopias, impresiones láser o inkjet , en la confección de historietas de edición limitada, libros de artistas seriados, fanzines, entre otras creaciones vinculadas con los derechos humanos, la niñez y la juventud."]', 'PdA p. 71'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Realización de exploraciones espaciales (interiores, exteriores, tamaños, volúmenes, luces, sombras, formas) por medio de ejercicios con bocetos, programas de diseño, estructuras en pequeños formatos —maquetas, cajas escenográficas— entre otros.', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Experimenta con procedimientos propios de la tridimensionalidad y los volúmenes (agrupar, reducir, yuxtaponer, superponer, adicionar, sustraer, encastrar, entre otros).","Descubre las posibilidades narrativas que brinda la resignificación de objetos, espacios, sonidos, movimientos corporales.","Relaciona producciones escultóricas u objetos resignificados, con fuentes de luz y espacios de emplazamiento, como una unidad expresiva.","Distingue diversos procedimientos compositivos en la producción volumétrico/espacial.","Selecciona y hace uso de espacios, objetos, sonidos o textos, según sus cualidades narrativas, simbólicas y de relación con la historia o respecto de la sensación que se quiere comunicar."]', 'PdA p. 72'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Reconocimiento de cualidades formales y expresivas de materiales, técnicas y procedimientos propios del lenguaje visual, en la representación tridimensional.', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Relaciona materiales y procedimientos técnicos para su tratamiento en el desarrollo de representaciones tridimensionales, de acuerdo con sus características (volúmenes, espacio, tamaños, formas, interiores, exteriores, entre otras).","Identifica técnicas de manipulación (amasado, plegado, encastre, entre otras) y materiales donde se emplean, según sus intenciones estético-expresivas.","Manipula los diferentes elementos, materiales, soportes, técnicas y procedimientos propios del lenguaje visual en la tridimensión y reconoce sus cualidades formales y expresivas."]', 'PdA p. 72'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Exploración de diferentes herramientas digitales para la planificación y el desarrollo de composiciones tridimensionales.', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Descubre la imagen y las experiencias inmersivas, a través de las posibilidades estéticas de la “realidad simulada” y la “realidad aumentada”.","Combina procedimientos en la producción de intervenciones en el espacio arquitectónico (físico o simulado) y sobre el propio cuerpo (a través de máscaras y vestuarios, entre otros).","Determina y utiliza el encuadre, la luz y el movimiento, en función de la intención representativa de las escenas configuradas."]', 'PdA p. 73'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Realización de un proyecto artístico interdisciplinario y colaborativo en el espacio institucional — interior o exterior— con objetos, volúmenes, luces, colores, tiempos, entre otros elementos.', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Crea, en colaboración con sus pares, a partir de acuerdos y roles definidos, sin distinción de género, producciones artísticas espaciales.","Desarrolla bocetos, maquetas preliminares y pruebas con materiales, antes de la ejecución definitiva, para anticipar y ensayar decisiones alternativas.","Explora experiencias artísticas performáticas, como la interacción de lo visual con otros lenguajes (música, teatro, literatura, cine).","Construye lo planificado y lo emplaza en el espacio/ entorno elegido.","Incorpora, progresivamente, la dimensión procesual en sus proyectos artísticos."]', 'PdA p. 73'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Realización de construcciones espaciales en diferentes entornos (dentro del aula, fuera de ella, en plazas, entre otros) y en función de temáticas variadas.', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Desarrolla instalaciones por ensambles, objetuales, móviles con diversos materiales (cajas, desechos, bultos, telas, píxeles, luces, entre otros)","Genera producciones espaciales, identifica sus diferentes posibilidades de organización, y distingue diversos procedimientos compositivos.","Experimenta con el espacio (interiores, exteriores) y sus posibilidades de organización (grados de orden, desorden o caos), con materiales no convencionales y genera paisajes visuales, sonoros, táctiles, multisensoriales.","Explora la policromía y la modificación del color de los materiales en la tridimensión, las sombras propias y las proyectadas en el entorno."]', 'PdA p. 73'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Selección de materiales y procedimientos técnicos adecuados para el desarrollo de construcciones tridimensionales, en sus diferentes variantes.', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Elige materiales que le permitan dar forma, a través del agregado o la supresión de diferentes cantidades.","Trabaja con materiales que le permiten liberar gradualmente la forma en el tallado, por ejemplo el poliuretano, denominado comercialmente como esponja (usando tijeras de punta fina para obtener formas) o el jabón.","Experimenta con diferentes materiales que le permiten desarrollar esculturas de bulto, alto y bajo relieve, para el tratamiento del volumen, el modelado y/o tallado de modo/s (por ejemplo, cóncavo, convexo, hueco, sólido, entrantes, salientes, abierto, cerrado).","Explora el tratamiento lateral, frontal, integral del volumen, según opte por una producción de bulto o un relieve."]', 'PdA p. 74'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Representación virtual del espacio, generando la ilusión de entrar en un nuevo tipo de plano con propiedades diferentes, de manera analógica y/o digital.', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Explora las posibilidades expresivas de la realidad virtual y sus propiedades.","Experimenta con las ilusiones ópticas, las anamorfosis e interactúa con el cuerpo como soporte y materialidad en el espacio.","Expresa su opinión sobre las sensaciones y/o ideas que experimenta, a partir de las exploraciones desarrolladas."]', 'PdA p. 74'),
(7, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Desarrollo de un proyecto analítico sobre contenidos plásticos y visuales tridimensionales (que implique dispositivos, contexto de producción, exposición y recepción, entre otras posibilidades).', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Selecciona, según sus preferencias, la producción de una/un artista, una corriente artística y/o fenómeno estético-visual contemporáneo que hace uso del espacio.","Investiga procesos de producción, técnicas, materiales, circulación y recepción de obras tridimensionales.","Analiza producciones tridimensionales y contempla la dimensión creativa, expositiva y de recepción.","Trabaja en colaboración con sus pares, a partir de acuerdos y roles definidos, sin distinción de género."]', 'PdA p. 74'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Análisis y comprensión de las diferentes formas de organización rítmica, melódica, textural, tímbrica y formal de los diversos discursos musicales, para la comunicación de la experiencia sonora.', 'pda_2025', 1, 'Reconocer la música como una representación cultural, identificando elementos, estructuras y características propias de los lenguajes musicales, para crear composiciones mediante tecnologías, instrumentos y objetos sonoros.', '["Explora la diversidad de formas en que diferentes culturas crean, interpretan y transmiten sus músicas y reconoce la pluralidad de lenguajes sonoros.","Relaciona las cualidades del sonido y el uso del silencio con los lenguajes musicales y acuerda formas colectivas de comunicarlo en repertorios y creaciones simples.","Incorpora el uso de términos como pulso, compás, movimiento melódico, silencio, para describir fragmentos musicales.","Reconoce diferentes grafías para representar los elementos discursivos de los lenguajes sonoro-musicales y considera a las organizaciones rítmicas y melódicas.","Distingue el sonido del ruido y reconoce su valor expresivo y comunicativo."]', 'PdA p. 129'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Construcción de nociones rítmicas, melódicas y armónicas, y exploración de las relaciones entre los elementos de un discurso musical, a través de la práctica instrumental, vocal y la escucha activa.', 'pda_2025', 1, 'Reconocer la música como una representación cultural, identificando elementos, estructuras y características propias de los lenguajes musicales, para crear composiciones mediante tecnologías, instrumentos y objetos sonoros.', '["Diferencia, a través de juegos con percusión corporal, patrones rítmicos con divisiones binarias y ternarias, polirritmias y otras acentuaciones.","Reconoce patrones de claves afrolatinas (clave de son, de rumba, de candombe, entre otras), a través de actividades lúdicas y escucha activa.","Explora secuencias melódicas a partir de la experimentación con escalas, modos y patrones melódicos de diferentes repertorios.","Identifica las funciones rítmicas, melódicas y armónicas de los instrumentos y objetos sonoros, en los repertorios que interpreta o escucha.","Explora, a través de juegos de percepción y de la práctica instrumental, las funciones armónicas como la tensión, el reposo y otras posibles asociaciones en repertorios diversos."]', 'PdA p. 129'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Exploración de los lenguajes sonoro-musicales, a través del uso de instrumentos tradicionales, cotidiáfonos, objetos sonoros y/o tecnologías.', 'pda_2025', 1, 'Reconocer la música como una representación cultural, identificando elementos, estructuras y características propias de los lenguajes musicales, para crear composiciones mediante tecnologías, instrumentos y objetos sonoros.', '["Experimenta el sonido y sus posibilidades de transformación tímbrica a través de instrumentos, objetos sonoros y/o herramientas tecnológicas.","Compara las posibilidades expresivas de instrumentos acústicos, electrónicos y digitales.","Utiliza herramientas tecnológicas, en caso de ser posible, para crear sonidos y organizarlos de acuerdo con los elementos constitutivos de la música, explicando cómo lo hace.","Indaga medios analógicos, digitales y/o gráficos para registrar material sonoro e ideas musicales."]', 'PdA p. 130'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Construcción colectiva de un discurso común, para nombrar, describir y analizar diferentes músicas, integrando vocabulario técnico en referencia a la procedencia cultural de los repertorios y las experiencias sonoras abordadas.', 'pda_2025', 1, 'Reconocer la música como una representación cultural, identificando elementos, estructuras y características propias de los lenguajes musicales, para crear composiciones mediante tecnologías, instrumentos y objetos sonoros.', '["Comunica las características rítmicas y melódicas de repertorios trabajados, reconociendo su procedencia.","Establece relaciones entre sus preferencias musicales y los elementos sonoros que las sustentan.","Incorpora términos para argumentar la elección de repertorios en la creación de listas de reproducción personales.","Compara cómo diferentes formas de hablar sobre la música reflejan distintas miradas, tradiciones o experiencias (por ejemplo, la forma en que se describe el canto en una copla vs en un tema de freestyle)."]', 'PdA p. 130'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Integración de los elementos del discurso musical en prácticas instrumentales y reconocimiento del resultado expresivo de la combinación sonora.', 'pda_2025', 1, 'Reconocer la música como una representación cultural, identificando elementos, estructuras y características propias de los lenguajes musicales, para crear composiciones mediante tecnologías, instrumentos y objetos sonoros.', '["Relaciona patrones rítmicos, con los géneros musicales que interpreta (por ejemplo: chacarera, zamba, malambo, cueca, cumbia, pop, rock, trap, entre otros).","Incorpora las claves latinoamericanas y sus variaciones, para ordenar la rítmica de los géneros musicales en los que se insertan (salsa, son, rumba, candombe, samba, bossa nova, entre otros).","Experimenta a través de la práctica de distintos repertorios, las sonoridades que generan las diferentes escalas (mayores, menores, modales, pentatónicos).","Toma decisiones musicales (inicio, dinámica, tempo) en composiciones colectivas, justificando sus elecciones desde lo expresivo y lo funcional.","Indaga páginas web con cancioneros, para interpretar repertorios cantados con acompañamiento instrumental."]', 'PdA p. 130'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Reconocimiento y combinación de los elementos constitutivos de la música, a través de la improvisación con instrumentos tradicionales y digitales.', 'pda_2025', 1, 'Reconocer la música como una representación cultural, identificando elementos, estructuras y características propias de los lenguajes musicales, para crear composiciones mediante tecnologías, instrumentos y objetos sonoros.', '["Participa en improvisaciones individuales o grupales y genera frases musicales a partir de sonidos, ritmos y melodías espontáneas.","Identifica, en sus propias improvisaciones, elementos de los lenguajes musicales (el pulso, la dirección del movimiento melódico, claves rítmicas, entre otros).","Experimenta con modelos de improvisación de preguntas y respuestas, sobre bases con distintas métricas.","Integra recursos de sampleo y secuencias pregrabadas en producciones grupales.","Utiliza métodos de registro para reutilizar y combinar material producido, o para evaluar posibles cambios/ mejoras en su producción."]', 'PdA p. 131'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Apropiación progresiva de las posibilidades sonoras de la voz hablada y cantada.', 'pda_2025', 1, 'Comprender las características de la voz humana, analizando diferentes técnicas vocales, para utilizarlas expresivamente en la interpretación de diversos repertorios, de manera individual y colectiva.', '["Participa en vocalizaciones grupales, apropiándose de técnicas básicas de respiración, emisión y resonancia vocal.","Reconoce, a partir de la escucha de cantantes de su interés, los diferentes usos de la voz hablada y cantada.","Diferencia sensaciones corporales al utilizar su voz, en distintas extensiones vocales, y elige cantar en el rango que más cómodo le sienta.","Experimenta y compara formas de emisión vocal en repertorios, y reconoce intenciones expresivas básicas.","Incorpora arreglos a dos o más voces y sostiene su propia línea, en coordinación con el grupo."]', 'PdA p. 132'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Desarrollo de la expresión vocal como herramienta que contribuye a la construcción de identidades.', 'pda_2025', 1, 'Comprender las características de la voz humana, analizando diferentes técnicas vocales, para utilizarlas expresivamente en la interpretación de diversos repertorios, de manera individual y colectiva.', '["Canta diversos repertorios en forma individual y colectiva, y muestra mayor seguridad al expresarse.","Identifica los cambios de su voz y la de sus pares, y los reconoce como parte de su crecimiento.","Reflexiona, desde una perspectiva de género, sobre la diversidad de voces en el marco del canto colectivo (por ejemplo, historización sobre el surgimiento de las categorías vocales y su vinculación con estereotipos de género)."]', 'PdA p. 132'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Exploración estilística de repertorios musicales a través del canto individual y colectivo.', 'pda_2025', 1, 'Comprender las características de la voz humana, analizando diferentes técnicas vocales, para utilizarlas expresivamente en la interpretación de diversos repertorios, de manera individual y colectiva.', '["Interpreta, en la práctica del canto, melodías de distintos estilos, y comprende las posibilidades de su voz.","Identifica, en la práctica vocal, características estilísticas y culturales de las voces, en los distintos géneros y estilos.","Experimenta la diversidad de formas de cantar, en repertorios de diferentes expresiones culturales (baguala, canto con caja, freestyle, trap, entre otros).","Reflexiona sobre las diferencias y similitudes vocales entre los repertorios explorados."]', 'PdA p. 132'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Experimentación de técnicas vocales y utilización de recursos expresivos vinculados con el análisis de géneros y estilos musicales.', 'pda_2025', 1, 'Comprender las características de la voz humana, analizando diferentes técnicas vocales, para utilizarlas expresivamente en la interpretación de diversos repertorios, de manera individual y colectiva.', '["Utiliza técnicas vocales de respiración, articulación y proyección, en interpretaciones colectivas e individuales.","Explora, a través de la técnica, recursos expresivos como dinámica y fraseo, en la interpretación de repertorios musicales de diferentes géneros y estilos.","Analiza interpretaciones de cantantes e identifica el uso intencional de técnicas vocales.","Reflexiona sobre su interpretación vocal e identifica, en el uso de técnicas y recursos expresivos, fortalezas y aspectos a mejorar."]', 'PdA p. 133'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Interpretación vocal como medio de expresión, comunicación personal y colectiva y valoración de la diversidad y el trabajo colaborativo.', 'pda_2025', 1, 'Comprender las características de la voz humana, analizando diferentes técnicas vocales, para utilizarlas expresivamente en la interpretación de diversos repertorios, de manera individual y colectiva.', '["Identifica los sentimientos que puede transmitir un determinado repertorio y utiliza la voz para interpretarlos de manera intencional, dentro y fuera del espacio áulico (actos escolares, encuentros con otras escuelas, espacios públicos).","Integra diferentes posibilidades sonoras de la voz y el cuerpo en distintos contextos expresivos.","Reconoce y acepta, en la diversidad de voces y posibilidades expresivas, las diferencias existentes y las considera como potencialidades."]', 'PdA p. 133'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Comunicación de sus preferencias musicales, para incorporar repertorios a través del canto individual y colectivo.', 'pda_2025', 1, 'Comprender las características de la voz humana, analizando diferentes técnicas vocales, para utilizarlas expresivamente en la interpretación de diversos repertorios, de manera individual y colectiva.', '["Propone canciones de distintos estilos y comprende sus posibilidades en la práctica del canto.","Relaciona características estéticas del canto individual y colectivo, con los géneros o estilos que le resultan interesantes.","Reconoce el carácter colectivo del canto, en distintos rituales culturales y expresiones comunitarias.","Reflexiona sobre cómo sus preferencias musicales influyen en su interpretación e identifica maneras de enriquecer su práctica vocal."]', 'PdA p. 133'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Desarrollo de la noción de textura, a través de actividades de percepción y producción musical colectiva.', 'pda_2025', 1, 'Participar en ensambles, atendiendo a la colaboración y sincronización entre las/os integrantes, utilizando instrumentos y aplicaciones móviles.', '["Explora y compara las texturas presentes en distintas formaciones musicales (orquesta, banda de rock, coro, ensamble de percusión).","Percibe los cambios y las combinaciones tímbricas, al superponer diferentes capas sonoras en la interpretación grupal.","Identifica, en los repertorios que escucha e interpreta, distintas texturas musicales (monofonía, melodía con acompañamiento, homofonía, polifonía).","Reconoce los roles melódicos, rítmicos y armónicos en los ensambles de los que participa."]', 'PdA p. 134'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Reconocimiento de la forma musical como guía, para incorporar pautas de sincronización y cohesión en la interpretación colectiva.', 'pda_2025', 1, 'Participar en ensambles, atendiendo a la colaboración y sincronización entre las/os integrantes, utilizando instrumentos y aplicaciones móviles.', '["Analiza, a través de la escucha activa y la interpretación de repertorios, las características rítmicas, melódicas y dinámicas de cada sección de la forma musical.","Identifica las diferentes secciones de la forma musical, en diversos géneros y estilos.","Anticipa y sincroniza entradas y salidas en la interpretación colectiva, corrige errores espontáneamente y reconoce elementos de la forma musical, para ajustar su interpretación al ensamble.","Reconoce, en el repertorio que interpreta, estructuras formales típicas de determinados géneros y estilos musicales."]', 'PdA p. 134'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Participación en ensambles vocales e instrumentales, explorando diferentes texturas para crear, colaborativamente, arreglos musicales sencillos.', 'pda_2025', 1, 'Participar en ensambles, atendiendo a la colaboración y sincronización entre las/os integrantes, utilizando instrumentos y aplicaciones móviles.', '["Vincula los diferentes géneros y estilos que interpreta con determinadas texturas (por ejemplo, la homofonía con el pop, el contrapunto con el folclore o el tango).","Explora la posibilidad de construir acordes, superponiendo melodías, con instrumentos o a través del canto.","Interviene en el ensamble y asume un rol musical para construir la textura (acompañamiento, melodía principal, contrapunto, entre otros).","Propone repertorios y asocia lo que escucha a las posibilidades interpretativas y tímbricas del ensamble."]', 'PdA p. 135'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Toma de decisiones colaborativas dentro del ensamble, en relación con la interpretación y la organización musical.', 'pda_2025', 1, 'Participar en ensambles, atendiendo a la colaboración y sincronización entre las/os integrantes, utilizando instrumentos y aplicaciones móviles.', '["Propone soluciones ante posibles dificultades que puedan surgir en las interpretaciones musicales colectivas.","Colabora en la construcción de acuerdos interpretativos (entradas, salidas, matices, articulaciones) y promueve la unidad y fluidez del ensamble.","Adapta la interpretación colectiva a la estructura formal propia del género o estilo musical.","Propone cambios o ajustes en la interpretación colectiva, basándose en la escucha activa y el trabajo colaborativo.","Asume con responsabilidad su rol dentro del ensamble.","Comprende que la colaboración entre las/os integrantes resulta indispensable para la producción musical colaborativa."]', 'PdA p. 135'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Exploración de diferentes herramientas y recursos que aporten a la conformación de ensambles musicales.', 'pda_2025', 1, 'Participar en ensambles, atendiendo a la colaboración y sincronización entre las/os integrantes, utilizando instrumentos y aplicaciones móviles.', '["Experimenta e investiga con sonoridades, instrumentos y/o dispositivos móviles, que aportan al ensamble.","Identifica las funciones de herramientas tecnológicas (metrónomo, sintetizadores, grabadoras) en la organización y sincronización del ensamble.","Reconoce las posibilidades creativas de combinar, en una producción musical, recursos tecnológicos con instrumentos tradicionales."]', 'PdA p. 135'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Valoración e indagación del patrimonio musical local, con reconocimiento y reflexión acerca de su papel en la construcción de las identidades.', 'pda_2025', 1, 'Apreciar el patrimonio musical a través de la escucha reflexiva de diversos géneros y estilos, analizando sus raíces culturales y los cambios a lo largo de la historia, reconociendo de qué manera contribuyen a la construcción de la identidad.', '["Identifica los géneros y estilos musicales presentes en su entorno cultural y los diferentes ámbitos en los que circulan (medios, festivales, bailes, espacios comunitarios, entre otros).","Reflexiona sobre cómo ciertas músicas expresan sentidos de pertenencia, memorias y diferencias culturales, y reconoce tensiones entre lo académico, lo popular y lo personal.","Analiza los repertorios patrios, vinculándolos con sucesos de representación histórica del pasado y de la actualidad.","Reconoce cómo las diversas manifestaciones musicales influyen en la construcción de su identidad y en la de las demás personas.","Elabora y comparte una lista de repertorios musicales, basándose en la escucha activa y sus gustos personales."]', 'PdA p. 136'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Reconocimiento del contexto cultural en el que se inscriben y transforman las producciones sonoras.', 'pda_2025', 1, 'Apreciar el patrimonio musical a través de la escucha reflexiva de diversos géneros y estilos, analizando sus raíces culturales y los cambios a lo largo de la historia, reconociendo de qué manera contribuyen a la construcción de la identidad.', '["Incorpora, a través de la escucha activa y crítica, repertorios que representan distintos contextos culturales, y comparte reflexiones sobre sus particularidades.","Distingue elementos característicos de músicas provenientes de diversas regiones o comunidades, y comparte reflexiones personales sobre lo que le generan o comunican.","Identifica las relaciones entre los géneros, estilos musicales y el entorno natural, social, geográfico e histórico en el que se inscriben."]', 'PdA p. 136'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Identificación de las diferentes formas de producir y reproducir sonidos a lo largo del tiempo.', 'pda_2025', 1, 'Apreciar el patrimonio musical a través de la escucha reflexiva de diversos géneros y estilos, analizando sus raíces culturales y los cambios a lo largo de la historia, reconociendo de qué manera contribuyen a la construcción de la identidad.', '["Analiza las diferentes formas de producir sonidos, desde métodos tradicionales, hasta tecnologías modernas (instrumentos acústicos, electrónicos, software musical).","Reconoce cómo las innovaciones tecnológicas han influido en la manera de producir y consumir música."]', 'PdA p. 136'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Asociación entre las características estéticas del patrimonio musical y el rol histórico, en la música, de personas con diferentes identidades de género (mujeres, varones, personas trans, entre otros).', 'pda_2025', 1, 'Apreciar el patrimonio musical a través de la escucha reflexiva de diversos géneros y estilos, analizando sus raíces culturales y los cambios a lo largo de la historia, reconociendo de qué manera contribuyen a la construcción de la identidad.', '["Analiza el rol de personas con diferentes identidades de género, en la música, a lo largo de la historia.","Contextualiza los cambios estéticos en los distintos repertorios musicales, en relación con la participación de personas con diferentes identidades de género."]', 'PdA p. 137'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Desarrollo de la reflexión crítica en relación con el patrimonio musical y sus implicancias sociales.', 'pda_2025', 1, 'Apreciar el patrimonio musical a través de la escucha reflexiva de diversos géneros y estilos, analizando sus raíces culturales y los cambios a lo largo de la historia, reconociendo de qué manera contribuyen a la construcción de la identidad.', '["Evalúa críticamente las influencias y el impacto de eventos históricos, sociales y culturales en el surgimiento y/o desarrollo de los distintos géneros musicales (por ejemplo, lo sucedido con el rock en el contexto de la última dictadura militar).","Contextualiza las producciones sonoras que escucha, y establece conexiones con los acontecimientos tecnológicos y las dinámicas culturales de la realidad actual.","Analiza cómo los diferentes géneros y estilos del patrimonio musical pueden vincularse con conflictos o transformaciones sociales."]', 'PdA p. 137'),
(7, 'eje_contenido', 'Música (por ciclo)', 'Análisis de las diferentes formas de producir y reproducir sonidos en la actualidad, considerando su impacto social (creación, distribución y consumo).', 'pda_2025', 1, 'Apreciar el patrimonio musical a través de la escucha reflexiva de diversos géneros y estilos, analizando sus raíces culturales y los cambios a lo largo de la historia, reconociendo de qué manera contribuyen a la construcción de la identidad.', '["Identifica, a través de la escucha activa, la incidencia de las tecnologías y sus usos en las distintas maneras de producir música, según diferentes contextos culturales.","Compara los cambios históricos y culturales, en las formas de producir y consumir música y destaca sus similitudes, diferencias y aportes a la creación musical.","Analiza las formas de consumo personal de la música (redes sociales, medios masivos, encuentros comunitarios, entre otras).","Reflexiona sobre el impacto social y cultural de las plataformas digitales, en la creación y el consumo musical."]', 'PdA p. 137'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Profundización de la relación entre apoyo y peso corporal, e identificación de las necesidades y variaciones del tono muscular.', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Explora caídas, deslizamientos y rodadas controladas, identificando los apoyos en cada acción.","Diferencia momentos de relajación y tensión en caídas suaves, frenadas o impulsos.","Integra peso, apoyos y variaciones de tono en secuencias de movimiento más complejas, combinando transiciones fluidas (caer–rodar–deslizar)."]', 'PdA p. 190'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Investigación de las posibilidades de ir contra la gravedad (equilibrios, saltos, giros) y posturas invertidas (medialuna, parada de manos, parada de cabeza, vela, arado, entre otras).', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Realiza saltos y giros simples, manteniendo la coordinación y la estabilidad en la conclusión del movimiento.","Experimenta posturas invertidas con asistencia o apoyos (pared, compañeras/os), y registra la respiración, la alineación y el uso seguro de la fuerza.","Integra equilibrios, saltos, giros y posturas invertidas, en secuencias de movimiento simples."]', 'PdA p. 190'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Reconocimiento de las calidades de movimiento (ligado, cortado, vibrar, suspender, torcer, etc) y su relación con las variantes de tensión-relajación, fuerza e intensidad.', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Identifica y reproduce distintas calidades de movimiento (ligado, cortado, vibrar, suspender, torcer).","Explora variaciones de tensión y relajación muscular, para generar cambios de fuerza, e intensidad en los movimientos.","Combina calidades de movimiento con variaciones de tensión-relajación, fuerza e intensidad, con transiciones conscientes entre una y otra."]', 'PdA p. 190'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Investigación de las posibilidades de contacto corporal con pares, e integración de soportes, arrastres, movimientos pendulares y la entrega consciente del peso en el lugar o en diferentes trayectorias espaciales.', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Explora el contacto corporal básico con una/un compañera/o, reconociendo apoyos simples y la confianza necesaria para compartir el peso en situaciones estáticas.","Realiza arrastres y movimientos pendulares con una/un compañera/o, experimentando la entrega y recepción consciente del peso en distintas trayectorias (verticales, diagonales, circulares).","Integra soportes, arrastres, pendulaciones y entrega de peso en exploraciones duales o grupales."]', 'PdA p. 191'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Exploración y regulación de las tensiones corporales para favorecer la alineación desde el centro, para el desarrollo de una relación consciente y eficiente entre esfuerzo, peso, flujo energético y movimiento.', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Explora e integra la regulación de tensiones corporales, para mantener la alineación y equilibrio durante el movimiento.","Experimenta el uso del centro corporal (zona abdominal/lumbar/pélvica), como sostén y punto de partida del movimiento.","Regula el flujo energético en tanto consigue diferenciar entre energía continua y libre, o controlada y contenida en la ejecución de los movimientos de su danza.","Ajusta dinámicamente el esfuerzo, el peso y el flujo energético, para optimizar la expresividad de cada movimiento.","Diferencia entre movimientos que requieren entrega al peso y otros que necesitan suspensión o impulso."]', 'PdA p. 191'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Investigar la relación con el suelo, explorando formas de entrar y salir de él mediante la generación de espirales, a partir de la conexión entre el centro y las extremidades.', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Experimenta, de manera consciente, la relación con el suelo y ejecuta entradas y salidas fluidas, distribuyendo eficientemente el peso.","Reconoce cómo el uso de espirales facilita el pasaje entre niveles y favorece la continuidad en las transiciones.","Explora secuencias que implican giros, torsiones o espirales, como principios organizadores del movimiento.","Utiliza el centro como punto de partida para mover brazos, piernas o cabeza de forma coordinada."]', 'PdA p. 191'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Experimentación de las calidades de movimiento, distinguiendo los factores que las componen (tiempo, peso, flujo y espacio), así como su relación con las variantes de tensión-relajación, fuerza e intensidad.', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Explora e investiga, de manera consciente, distintas calidades de movimiento (ligado, cortado, vibratoria, suspender, torcer, entre otras) en la práctica de la danza.","Regula la tensión, relajación, fuerza e intensidad necesaria para cada movimiento, ampliando sus posibilidades expresivas.","Relaciona ciertas calidades con combinaciones específicas de los factores que la componen (por ejemplo, vibratorio equivale a la sumatoria de rápido, restringido y directo)."]', 'PdA p. 192'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Complejización del uso de elementos técnicos (saltos, giros, roladas, deslizadas, entre otros), en vínculo con el contacto corporal con pares, integrando tomas, agarres y soportes con formas de traslación en el espacio.', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Ejecuta movimientos reconociendo los elementos técnicos (saltos, giros, roladas, deslizadas).","Aplica, en la interacción con sus pares, tomas, agarres y soportes de manera segura.","Combina diversos elementos técnicos a partir de desplazamientos y traslaciones en el espacio, en frases de movimiento de complejidad avanzada."]', 'PdA p. 192'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Conceptualización de una idea compleja de cuerpo desde diversas líneas teóricas para su abordaje, como cuerpo jerarquizado (división mente-cuerpo), cuerpo fragmentario (una sumatoria de partes), cuerpo holístico (un sistema de sistemas que se interrelacionan).', 'pda_2025', 1, 'Comprender un concepto complejo de cuerpo, tanto teórica como prácticamente, reconociendo su importancia en la construcción identitaria, el valor cultural de sus manifestaciones expresivas y el disfrute del movimiento.', '["Reconoce y describe diferentes concepciones del cuerpo, a partir de la información presentada.","Compara las distintas perspectivas, identificando similitudes, diferencias y modos en que cada una organiza la idea de cuerpo.","Comprende y relaciona las concepciones teóricas con experiencias corporales concretas, evidenciando dónde es posible apreciarlas."]', 'PdA p. 193'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Exploración de la relación cuerpo-mente-emoción y del vínculo con el entorno, a partir del movimiento expresivo y subjetivo, así como de la toma de conciencia de la presencia de huesos, músculos, articulaciones, respiración, flujo energético.', 'pda_2025', 1, 'Comprender un concepto complejo de cuerpo, tanto teórica como prácticamente, reconociendo su importancia en la construcción identitaria, el valor cultural de sus manifestaciones expresivas y el disfrute del movimiento.', '["Explora movimientos a partir de sensaciones, percepciones, imágenes poéticas, pensamientos o emociones.","Expresa sensaciones y emociones surgidas del movimiento.","Reconoce y nombra los huesos, los músculos y las articulaciones que se involucran en diferentes movimientos."]', 'PdA p. 193'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Reflexión sobre la autoimagen y su relación con el movimiento (torpeza, inseguridad, potencia, exploración), y desnaturalización de modelos hegemónicos (cuerpos delgados, fuertes, ágiles, normados).', 'pda_2025', 1, 'Comprender un concepto complejo de cuerpo, tanto teórica como prácticamente, reconociendo su importancia en la construcción identitaria, el valor cultural de sus manifestaciones expresivas y el disfrute del movimiento.', '["Participa en conversaciones grupales desde el respeto a la diversidad corporal","Relaciona las elaboraciones y sus reflexiones sobre imagen corporal surgidas en el grupo a partir del movimiento.","Valora y respeta la diversidad de corporalidades presentes en el grupo, participando en experiencias de movimiento que amplían las posibilidades expresivas, más allá de modelos hegemónicos."]', 'PdA p. 193'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Historización del concepto de cuerpo y su vínculo con la(s) danza(s) a lo largo del tiempo.', 'pda_2025', 1, 'Comprender un concepto complejo de cuerpo, tanto teórica como prácticamente, reconociendo su importancia en la construcción identitaria, el valor cultural de sus manifestaciones expresivas y el disfrute del movimiento.', '["Reconoce relatos e imágenes históricas, que muestran diferentes concepciones del cuerpo y la danza (por ejemplo, ritual, social, escénico).","Compara distintas concepciones del cuerpo.","Argumenta y relaciona, críticamente, cómo las concepciones históricas del cuerpo influyen en las formas actuales de entender y practicar la danza."]', 'PdA p. 194'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Profundización de la relación cuerpo-mente-emoción en el movimiento expresivo y subjetivo, con la incorporación de objetos de diferentes texturas, formas, colores, tamaños, peso y sonoridad y valorando su relación con el cuerpo y el movimiento.', 'pda_2025', 1, 'Comprender un concepto complejo de cuerpo, tanto teórica como prácticamente, reconociendo su importancia en la construcción identitaria, el valor cultural de sus manifestaciones expresivas y el disfrute del movimiento.', '["Explora el movimiento expresivo, a partir del uso de objetos variados.","Investiga el movimiento con objetos, diferenciando las posibilidades expresivas que brinda cada uno (textura, forma, peso, color, sonoridad).","Expresa sus pensamientos, sentires y emociones a partir del movimiento que realiza con objetos."]', 'PdA p. 194'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Reconocimiento del movimiento en su dimensión física y como lenguaje identitario que configura modos de estar en el mundo, así como de presentarse frente a otras/os.', 'pda_2025', 1, 'Comprender un concepto complejo de cuerpo, tanto teórica como prácticamente, reconociendo su importancia en la construcción identitaria, el valor cultural de sus manifestaciones expresivas y el disfrute del movimiento.', '["Observa y describe tanto de manera oral como escrita, movimientos propios y de otras/os, reconociendo su dimensión física y poética/expresiva.","Explora y experimenta gestos/modos de moverse, como forma de expresión identitaria.","Reflexiona y comunica ideas, deseos y/o conceptos, a través del propio movimiento/la propia danza."]', 'PdA p. 194'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Exploración del espacio personal (parcial y total), y diferenciación respecto de la proximidad con el propio cuerpo, del espacio compartido con otras/os y del general (del aula, la sala o escenario).', 'pda_2025', 1, 'Construir un abordaje relacional del espacio (personal, parcial y total), integrando los niveles y planos, trayectorias y direcciones.', '["Explora y reconoce las zonas limítrofes del propio espacio (cerca/lejos, periferia/centro), regulando la proximidad con sus pares.","Explora el espacio personal y compartido a través de desplazamientos.","Utiliza, de manera consciente, el espacio total (aula, sala o escenario)."]', 'PdA p. 195'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Exploración de los niveles espaciales (alto, medio, bajo), en relación con los planos corporales, las trayectorias y direcciones posibles.', 'pda_2025', 1, 'Construir un abordaje relacional del espacio (personal, parcial y total), integrando los niveles y planos, trayectorias y direcciones.', '["Explora y diferencia los niveles espaciales (alto, medio, bajo).","Relaciona los niveles espaciales con planos corporales y direcciones, en movimientos individuales o grupales.","Integra trayectorias y desplazamientos variados en los distintos niveles espaciales."]', 'PdA p. 195'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Investigación de las posibilidades del espacio, desde un abordaje relacional, en propuestas de improvisación tanto individuales como grupales.', 'pda_2025', 1, 'Construir un abordaje relacional del espacio (personal, parcial y total), integrando los niveles y planos, trayectorias y direcciones.', '["Explora el espacio de manera individual e identifica niveles, direcciones y trayectorias básicas.","Interactúa con el espacio en relación con otras/os y ajusta su movimiento a distancias, cercanías y configuraciones grupales.","Integra el uso relacional del espacio en improvisaciones colectivas, con especial atención a la propia presencia y la de las/os demás."]', 'PdA p. 195'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Experimentación de desplazamientos y posturas en el nivel bajo, medio y alto, variando la orientación y profundidad en diferentes trayectorias y direcciones (creación de recorridos en línea recta, curva, zigzag, espiral u otras).', 'pda_2025', 1, 'Construir un abordaje relacional del espacio (personal, parcial y total), integrando los niveles y planos, trayectorias y direcciones.', '["Explora y reconoce diferencias de orientación y profundidad, en desplazamientos y posturas en los tres niveles (bajo, medio y alto).","Varía e integra cambios de nivel, posturas, trayectorias y direcciones (recta, curva, zigzag, espiral, entre otras) en sus desplazamientos.","Ejecuta recorridos espaciales, combinando niveles, orientaciones y trayectorias, de manera intencionada y expresiva."]', 'PdA p. 196'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Percepción y registro de las características del espacio físico habitado en la práctica de danza, como sus dimensiones, forma, superficie, altura y niveles, límites y fronteras, iluminación y visibilidad, condiciones ambientales, entre otras.', 'pda_2025', 1, 'Reconocer los diferentes ámbitos donde la danza se manifiesta —espacios físicos, escénicos, comunitarios y digitales— reconociendo sus transformaciones, limitaciones y potencialidades, según el contexto en que se practiquen o escenifiquen, tanto en lo concreto como en lo simbólico.', '["Describe características del espacio físico (dimensiones, forma, superficie, altura y niveles).","Percibe e Identifica variables (iluminación, temperatura, entre otras), en el espacio donde se desarrolla la práctica.","Vincula, conscientemente, características y particularidades del espacio físico en la práctica del movimiento."]', 'PdA p. 197'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Consideración de lo concreto y lo simbólico del espacio para bailar, con atención tanto a las condiciones materiales de cada ámbito, como a los significados culturales y expresivos que se construyen en ellos.', 'pda_2025', 1, 'Reconocer los diferentes ámbitos donde la danza se manifiesta —espacios físicos, escénicos, comunitarios y digitales— reconociendo sus transformaciones, limitaciones y potencialidades, según el contexto en que se practiquen o escenifiquen, tanto en lo concreto como en lo simbólico.', '["Identifica las características materiales del espacio y sus límites.","Reflexiona sobre los significados simbólicos y culturales del espacio, y los relaciona con la experiencia de la danza.","Integra lo concreto y lo simbólico del espacio en propuestas de movimiento."]', 'PdA p. 197'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Exploración y reflexión para la danza (video-danza, performance, redes sociales), entendiendo sus potencialidades, límites, y precauciones.', 'pda_2025', 1, 'Reconocer los diferentes ámbitos donde la danza se manifiesta —espacios físicos, escénicos, comunitarios y digitales— reconociendo sus transformaciones, limitaciones y potencialidades, según el contexto en que se practiquen o escenifiquen, tanto en lo concreto como en lo simbólico.', '["Reconoce las características del espacio digital (plataformas, formatos, visibilidad, alcance, entre otras).","Identifica los límites y precauciones necesarias al crear o compartir danza en entornos digitales.","Dispone creativamente de los recursos digitales en propuestas de movimiento o performance."]', 'PdA p. 197'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Distinguir tipos de espacio: espacio físico (lugar real donde se danza), espacio de práctica (disposición y organización para el trabajo corporal) y espacio escénico (configuración estética y simbólica para la presentación).', 'pda_2025', 1, 'Reconocer los diferentes ámbitos donde la danza se manifiesta —espacios físicos, escénicos, comunitarios y digitales— reconociendo sus transformaciones, limitaciones y potencialidades, según el contexto en que se practiquen o escenifiquen, tanto en lo concreto como en lo simbólico.', '["Reconoce los distintos tipos de espacio y señala ejemplos de espacio físico, de práctica y escénico.","Distingue funciones y características de cada tipo de espacio, en relación con la danza o la práctica corporal.","Idea y proyecta espacios donde podría desarrollarse la práctica corporal o producciones artístico-educativas (obras, muestras, clases, residencias, entre otras)."]', 'PdA p. 198'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Investigación de las posibilidades de resignificación del espacio físico, a partir de elementos escenotécnicos (luces, maquillaje, vestuario, escenografía, utilería, entre otros).', 'pda_2025', 1, 'Reconocer los diferentes ámbitos donde la danza se manifiesta —espacios físicos, escénicos, comunitarios y digitales— reconociendo sus transformaciones, limitaciones y potencialidades, según el contexto en que se practiquen o escenifiquen, tanto en lo concreto como en lo simbólico.', '["Reconoce los elementos escenotécnicos y sus funciones en el espacio físico, de un modo introductorio.","Analiza el efecto de los elementos escenotécnicos en la resignificación del espacio físico y su relación con la puesta en escena.","Diseña propuestas básicas de intervención del espacio físico utilizando elementos escenotécnicos."]', 'PdA p. 198'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Exploración y reflexión del espacio digital como espacio para la danza (video-danza, performance, redes sociales), entendiendo sus potencialidades, límites, y precauciones, con atención a la noción de autoría, plagio y reproducibilidad.', 'pda_2025', 1, 'Reconocer los diferentes ámbitos donde la danza se manifiesta —espacios físicos, escénicos, comunitarios y digitales— reconociendo sus transformaciones, limitaciones y potencialidades, según el contexto en que se practiquen o escenifiquen, tanto en lo concreto como en lo simbólico.', '["Reconoce el espacio digital como un lugar posible para llevar a cabo una danza y reflexiona sobre sus características, potencialidades y límites.","Analiza la influencia del espacio digital en la producción y difusión de la danza, considerando autoría, plagio y reproducibilidad.","Propone producciones de danza en el espacio digital, que integren las reflexiones surgidas en clase."]', 'PdA p. 198'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Desarrollo de la escucha, el acompañamiento entre pares y la construcción colectiva del movimiento, a través de composiciones basadas en intereses propios.', 'pda_2025', 1, 'Experimentar el vínculo cooperativo y desarrollar composiciones individuales, duales y colectivas en diferentes géneros y estilos locales, nacionales, regionales e internacionales, reconociendo diversos parámetros de la composición coreográfica como el canon, unísono, figura-fondo, pregunta-respuesta, entre otros.', '["Practica la escucha activa y la atención a las señales de sus pares durante la práctica danzada.","Ejercita el diálogo y la cooperación en la construcción de secuencias o composiciones conjuntas.","Intercambia ideas, de manera respetuosa, en instancias grupales de creación."]', 'PdA p. 199'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Creación de composiciones individuales, duales y grupales, reconociendo e implementando parámetros de la composición coreográfica (canon, unísono, figura/fondo, alternancia, sustracción, acumulación, entre otros).', 'pda_2025', 1, 'Experimentar el vínculo cooperativo y desarrollar composiciones individuales, duales y colectivas en diferentes géneros y estilos locales, nacionales, regionales e internacionales, reconociendo diversos parámetros de la composición coreográfica como el canon, unísono, figura-fondo, pregunta-respuesta, entre otros.', '["Reconoce parámetros básicos de composición coreográfica (canon, unísono, figura/fondo, alternancia, sustracción, acumulación).","Integra criterios de composición, en creaciones o composiciones duales y grupales.","Identifica y relaciona las características de las composiciones propias con las de sus pares. Pudiendo explicitarlas en debates, análisis escritos, observaciones, etc."]', 'PdA p. 199'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Aproximación y abordaje de manifestaciones de danzas locales, nacionales, regionales e internacionales, para favorecer la ampliación de referentes estéticos y culturales.', 'pda_2025', 1, 'Experimentar el vínculo cooperativo y desarrollar composiciones individuales, duales y colectivas en diferentes géneros y estilos locales, nacionales, regionales e internacionales, reconociendo diversos parámetros de la composición coreográfica como el canon, unísono, figura-fondo, pregunta-respuesta, entre otros.', '["Describe diversas manifestaciones de la danza en ámbitos locales, nacionales, regionales e internacionales.","Compara elementos estéticos y culturales que están presentes en diferentes manifestaciones de la danza.","Valora la diversidad de expresiones dancísticas, como parte del patrimonio cultural."]', 'PdA p. 199'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Profundización de la instancia compositiva, con desarrollo de la interdependencia, el diálogo corporal y la complementariedad, a partir de diversos intereses, aportes y de la organización conjunta.', 'pda_2025', 1, 'Experimentar el vínculo cooperativo y desarrollar composiciones individuales, duales y colectivas en diferentes géneros y estilos locales, nacionales, regionales e internacionales, reconociendo diversos parámetros de la composición coreográfica como el canon, unísono, figura-fondo, pregunta-respuesta, entre otros.', '["Identifica y diferencia los roles y aportes de cada participante en la composición.","Participa de propuestas compositivas que integran la diversidad de aportes, revisando o ajustando formas y secuencias en conjunto.","Participa en la creación de composiciones grupales que desarrollan la interdependencia, el diálogo corporal y la complementariedad."]', 'PdA p. 200'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Complejización de las composiciones coreográficas, con incorporación de las nociones de reversibilidad del movimiento (detenerse y regresar en cualquier punto), sincronía, contrapunto, aceleración y desaceleración, entre otras.', 'pda_2025', 1, 'Experimentar el vínculo cooperativo y desarrollar composiciones individuales, duales y colectivas en diferentes géneros y estilos locales, nacionales, regionales e internacionales, reconociendo diversos parámetros de la composición coreográfica como el canon, unísono, figura-fondo, pregunta-respuesta, entre otros.', '["Reconoce la posibilidad de detener un movimiento, volverlo al origen o retomarlo desde un punto previo.","Coordina movimientos, en simultáneo, e integra el contrapunto como recurso expresivo en las composiciones que produce con sus pares.","Varía la velocidad de los movimientos (aceleración y desaceleración), para generar contrastes y matices en la composición."]', 'PdA p. 200'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Utilización de referencias de diversos estilos/géneros de danza en composiciones propias.', 'pda_2025', 1, 'Experimentar el vínculo cooperativo y desarrollar composiciones individuales, duales y colectivas en diferentes géneros y estilos locales, nacionales, regionales e internacionales, reconociendo diversos parámetros de la composición coreográfica como el canon, unísono, figura-fondo, pregunta-respuesta, entre otros.', '["Reconoce características de distintos estilos/géneros de danza y selecciona elementos que se pueden incorporar en composiciones propias.","Integra elementos de diferentes estilos/géneros en sus composiciones y los adapta a su intención expresiva.","Crea composiciones que articulan, de manera consciente,referencias de diversos estilos/géneros."]', 'PdA p. 200'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Reconocimiento, valoración y respeto por la importancia del consentimiento en las interacciones durante la práctica de danza.', 'pda_2025', 1, 'Desarrollar prácticas de danza que consideren el consentimiento y el respeto de los límites en los vínculos con otras/os, y que cuestionen la generalización de roles tradicionales y su representación en diversas producciones y analizar cómo se ponen en juego estas relaciones en producciones apreciadas en diferentes soportes (video, imagen, función en vivo).', '["Reconoce y respeta la necesidad del consentimiento en las interacciones durante la práctica de danza.","Valora el consentimiento como principio fundamental para construir vínculos de cuidado y confianza.","Construye modos saludables de habitar el espacio compartido."]', 'PdA p. 201'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Problematización de los estereotipos de género y exploración de las posibilidades diversas de los roles, dentro de la práctica de la danza y la composición.', 'pda_2025', 1, 'Desarrollar prácticas de danza que consideren el consentimiento y el respeto de los límites en los vínculos con otras/os, y que cuestionen la generalización de roles tradicionales y su representación en diversas producciones y analizar cómo se ponen en juego estas relaciones en producciones apreciadas en diferentes soportes (video, imagen, función en vivo).', '["Reflexiona acerca de los estereotipos de género presentes en la danza y su influencia en la composición de movimientos.","Experimenta roles diversos en la práctica dancística, resignificando posibilidades expresivas.","Experimenta el movimiento desgenerizado, en composiciones individuales o grupales."]', 'PdA p. 201'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Análisis de videos, imágenes y obras, en vivo, y que contengan el lenguaje de la danza, reconociendo cómo se ponen en juego los roles en relación al género (ballet, tango, folklore, entre otras).', 'pda_2025', 1, 'Desarrollar prácticas de danza que consideren el consentimiento y el respeto de los límites en los vínculos con otras/os, y que cuestionen la generalización de roles tradicionales y su representación en diversas producciones y analizar cómo se ponen en juego estas relaciones en producciones apreciadas en diferentes soportes (video, imagen, función en vivo).', '["Describe los roles asociados al género en distintas manifestaciones de la danza (ballet, tango, folklore, entre otras).","Analiza cómo se articulan los roles en relación con el género, en videos, imágenes y obras en vivo.","Compara las diferencias y similitudes en la construcción de roles de género que se observan en diversas formas dancísticas."]', 'PdA p. 201'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Desarrollo de una práctica de danza consciente y reflexiva respecto del consentimiento,con incorporación de una perspectiva ética y crítica en los procesos creativos.', 'pda_2025', 1, 'Desarrollar prácticas de danza que consideren el consentimiento y el respeto de los límites en los vínculos con otras/os, y que cuestionen la generalización de roles tradicionales y su representación en diversas producciones y analizar cómo se ponen en juego estas relaciones en producciones apreciadas en diferentes soportes (video, imagen, función en vivo).', '["Reconoce el consentimiento como principio básico en la práctica de la danza.","Comunica los límites propios y respeta los ajenos, en propuestas compartidas de movimiento.","Reflexiona y analiza, críticamente, situaciones de la práctica de danza en las que aparecen relaciones de poder, roles o tensiones grupales."]', 'PdA p. 202'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Problematización de los estereotipos de género y exploración de las posibilidades diversas de los roles dentro de la práctica de la danza y la composición.', 'pda_2025', 1, 'Desarrollar prácticas de danza que consideren el consentimiento y el respeto de los límites en los vínculos con otras/os, y que cuestionen la generalización de roles tradicionales y su representación en diversas producciones y analizar cómo se ponen en juego estas relaciones en producciones apreciadas en diferentes soportes (video, imagen, función en vivo).', '["Reconoce estereotipos de género presentes en prácticas y representaciones de la danza.","Asume tanto la guía como el acompañamiento en danzas de pareja (alternancia del rol).","Explora y asume roles diversos en las danzas de pareja, priorizando el intercambio equitativo y la desjerarquización entre quienes bailan.","Participa en composiciones que distribuyen los roles de manera equitativa."]', 'PdA p. 202'),
(7, 'eje_contenido', 'Danza (por ciclo)', 'Investigación de movimientos relacionados con los roles en la experiencia de la danza (guía, partenaire, etc), desligados del género, y desmontando la asociación rol-género de sus elementos, (zapateos, levantadas, saltos, guías).', 'pda_2025', 1, 'Desarrollar prácticas de danza que consideren el consentimiento y el respeto de los límites en los vínculos con otras/os, y que cuestionen la generalización de roles tradicionales y su representación en diversas producciones y analizar cómo se ponen en juego estas relaciones en producciones apreciadas en diferentes soportes (video, imagen, función en vivo).', '["Investiga y reconoce los roles tradicionales en la danza y su asociación histórica al género.","Ejecuta movimientos correspondientes a distintos roles (guía, partenaire, zapateo, levantada, salto), sin vincularlos con identidades de género.","Reflexiona sobre la experiencia de habitar diferentes roles, desde una perspectiva de igualdad y diversidad."]', 'PdA p. 202'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Participación en experiencias sensoperceptivas para reconocer la multidimensionalidad del propio cuerpo y en relación a otras/os.', 'pda_2025', 1, 'Avanzar en la construcción del sujeto escénico, profundizando la conciencia corporal, vocal y espacial como instrumentos expresivos y comunicativos, en relación con el grupo, el espacio y la escena.', '["Reconoce, a partir de ejercicios y prácticas corporales, nociones de estructura ósea, tono muscular, postura, eje, apoyos, peso, entre otras.","Identifica la corporeidad como una construcción social y cultural, que integra aspectos físicos, afectivos, culturales, sociales, políticos.","Manifiesta una actitud de respeto en relación con la diversidad corporal.","Reconoce el cuerpo como caja de resonancia y explora diferentes posibilidades en el uso de la voz (tímbricas, de altura, intensidad, acentuación, pausas, rítmica de las palabras, proyección, articulación, entre otras).","Reconoce y respeta la diversidad corporal y expresiva del grupo, valorando la singularidad de cada participante en la creación escénica."]', 'PdA p. 276'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Utilización consciente del espacio escénico.', 'pda_2025', 1, 'Avanzar en la construcción del sujeto escénico, profundizando la conciencia corporal, vocal y espacial como instrumentos expresivos y comunicativos, en relación con el grupo, el espacio y la escena.', '["Diferencia tipos de espacios escénicos (italiano, isabelino, circular, caja negra, entre otros).","Reconoce los límites y los sectores que definen el espacio escénico (proscenio, bastidores, cuarta pared, entre otros).","Explora direcciones, niveles, distancias y trayectorias en relación con los otros y con los objetos.","Reconoce cómo las decisiones espaciales influyen en la comunicación teatral."]', 'PdA p. 276'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Acercamiento a la noción de presencia escénica, sosteniendo la atención y la energía durante la acción teatral.', 'pda_2025', 1, 'Avanzar en la construcción del sujeto escénico, profundizando la conciencia corporal, vocal y espacial como instrumentos expresivos y comunicativos, en relación con el grupo, el espacio y la escena.', '["Mantiene la atención y concentración durante las actividades escénicas, evitando dispersarse o abandonar la acción.","Sostiene la energía corporal y vocal durante el tiempo que dura la escena o improvisación.","Reconoce la importancia de la mirada, la postura y la disposición corporal para sostener la presencia escénica.","Adapta su nivel de energía y expresividad según la situación dramática o las consignas del grupo.","Participa activamente en la construcción del clima escénico, respondiendo de manera coherente a las acciones de los demás.","Identifica momentos de pérdida o quiebre de la atención, reflexionando sobre cómo recuperarla dentro del juego teatral."]', 'PdA p. 277'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Fortalecimiento de la autonomía interpretativa durante los ejercicios de representación.', 'pda_2025', 1, 'Avanzar en la construcción del sujeto escénico, profundizando la conciencia corporal, vocal y espacial como instrumentos expresivos y comunicativos, en relación con el grupo, el espacio y la escena.', '["Sostiene la atención y la presencia escénica durante el desarrollo de las acciones teatrales, sin depender permanentemente de la guía docente.","Toma decisiones interpretativas en relación con el personaje, la situación o el clima escénico, mostrando iniciativa y criterio propio.","Ajusta sus movimientos, gestos y tonos de voz en función del sentido de la escena o las indicaciones de sus pares y de la/el docente.","Participa activamente en la construcción colectiva de la puesta, asumiendo responsabilidades y compromisos con el proceso grupal."]', 'PdA p. 277'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Experimentación con partituras físicas y/o vocales para organizar secuencias de acciones que expresen intenciones, emociones o climas escénicos.', 'pda_2025', 1, 'Avanzar en la construcción del sujeto escénico, profundizando la conciencia corporal, vocal y espacial como instrumentos expresivos y comunicativos, en relación con el grupo, el espacio y la escena.', '["Diseña y ejecuta secuencias corporales y vocales coherentes con la intención expresiva de la escena o del personaje.","Identifica la relación entre las acciones físicas, la emoción y el espacio escénico, ajustando su interpretación según las necesidades dramáticas.","Explora variaciones de ritmo, intensidad, energía y pausa en su partitura física y vocal, reconociendo sus efectos en el espectador.","Participa en procesos de ensayo en los que analiza, ajusta y consolida su partitura en diálogo con el grupo y la dirección.","Integra los distintos planos expresivos (movimiento, voz, silencio, mirada, desplazamiento) de forma orgánica y con sentido comunicativo."]', 'PdA p. 277'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Reflexión sobre el propio proceso expresivo, reconociendo avances, dificultades y estrategias personales para el trabajo escénico y la comunicación teatral.', 'pda_2025', 1, 'Avanzar en la construcción del sujeto escénico, profundizando la conciencia corporal, vocal y espacial como instrumentos expresivos y comunicativos, en relación con el grupo, el espacio y la escena.', '["Describe y analiza su propio proceso de aprendizaje, identificando progresos en la expresión corporal, vocal y escénica.","Reconoce los desafíos o bloqueos personales que afectan su interpretación y propone estrategias para superarlos.","Escucha y valora las devoluciones de la/el docente y sus pares, integrándolas en su proceso de mejora.","Utiliza vocabulario específico del teatro (presencia, acción, partitura, ritmo, intención, clima, entre otros) para comunicar reflexiones sobre su trabajo.","Manifiesta una actitud crítica y constructiva hacia su producción y la de sus compañeras/os, comprendiendo el valor del proceso creativo colectivo."]', 'PdA p. 278'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Reconocimiento de la improvisación como práctica compleja, en la que se articulan ideas, acciones, materiales y estructura.', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Participa de prácticas de improvisación guiada, a partir de diferentes consignas y estímulos como objetos, imágenes, música, sonidos, palabras y textos breves.","Explora los elementos básicos del lenguaje teatral (acción, texto, cuerpo, espacio, objetos, sonido y luz), reconociendo su función expresiva dentro de la escena.","Participa activamente en improvisaciones teatrales, proponiendo ideas, acciones o personajes coherentes con la consigna.","Integra elementos corporales, vocales y materiales (objetos, sonidos, espacio) durante la improvisación, manteniendo una intención expresiva.","Reconoce, con guía docente, la importancia de la estructura en la improvisación (inicio, desarrollo, cierre).","Reflexiona sobre cómo las decisiones espontáneas generan sentido y organización dentro de la escena."]', 'PdA p. 279'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Reconocimiento del texto dramático como uno de los componentes del teatro.', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Identifica al texto dramático como un componente específico del hecho teatral, diferenciándolo de otros lenguajes artísticos (narrativo, poético, audiovisual).","Experimenta la dramaturgia desde la escritura o desde la composición escénica.","Relaciona el texto con la acción escénica, comprendiendo que las palabras cobran sentido en la representación y a través del cuerpo y la voz de los intérpretes.","Participa en lecturas dramatizadas, explorando cómo las intenciones, emociones y ritmos del texto se traducen en acciones teatrales.","Comenta de manera oral o escrita el vínculo entre lo escrito y lo actuado, expresando cómo el texto puede transformarse en escena.","Valora el texto dramático como punto de partida o material creativo dentro del proceso teatral, reconociendo que no es la única fuente de creación escénica."]', 'PdA p. 279'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Comprensión inicial de la relación entre texto y acción escénica, experimentando cómo las palabras, los gestos y los movimientos se integran en una situación teatral.', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Combina distintos recursos (voz, cuerpo, objetos, iluminación, música, etc.) para construir climas y significados escénicos.","Explora distintos modos de decir y actuar un texto, probando variaciones de tono, ritmo o intención.","Articula texto, cuerpo y desplazamiento en breves escenas o ejercicios teatrales.","Reconoce cómo los gestos, movimientos o silencios modifican el sentido de lo dicho.","Identifica la relación entre las palabras y las acciones dentro de la representación (qué se dice / qué se hace)."]', 'PdA p. 280'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Reflexión sobre las decisiones expresivas tomadas, reconociendo cómo los distintos elementos del lenguaje teatral contribuyen a construir sentido en la escena.', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Participa en instancias de diálogo y análisis grupal sobre las producciones realizadas.","Identifica los recursos utilizados (iluminación, espacio, vestuario, sonido, actuación) y su efecto expresivo.","Argumenta sus decisiones escénicas con vocabulario inicial del lenguaje teatral (personaje, acción, clima, espacio, ritmo).","Reconoce los aportes del grupo en la construcción colectiva del sentido teatral.","Muestra disposición para revisar y mejorar su trabajo a partir de observaciones propias o del grupo."]', 'PdA p. 280'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Integración consciente de los componentes del lenguaje teatral (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia) en la creación de escenas.', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Integra de manera coherente los distintos elementos del lenguaje teatral en una misma propuesta escénica.","Adapta recursos escénicos (espacio, luz, sonido, objetos, vestuario) a las necesidades expresivas del texto o la situación dramática.","Reconoce el valor expresivo y simbólico de cada componente del lenguaje teatral y su incidencia en la construcción de sentido.","Explica las decisiones tomadas respecto de los elementos utilizados en la creación escénica.","Evalúa críticamente la relación entre los recursos escénicos empleados y el efecto expresivo logrado en la escena."]', 'PdA p. 280'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Exploración de la relación entre dramaturgia, puesta en escena y espectador.', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Reconoce cómo las decisiones estéticas inciden en la comunicación del sentido teatral.","Experimenta con diversas estructuras dramatúrgicas y compositivas, incorporando variaciones en los modos de narrar, representar y construir personajes.","Identifica el propósito comunicativo de una escena y analiza cómo se construye el vínculo con el público.","Advierte cómo las elecciones dramatúrgicas y de puesta en escena condicionan la percepción del espectador.","Participa en instancias de reflexión grupal sobre la recepción de las producciones, proponiendo ajustes en función del impacto observado.","Comenta, con vocabulario específico, cómo el montaje escénico modifica el sentido del texto o la acción dramática."]', 'PdA p. 281'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Diseño de producciones teatrales colectivas, asumiendo diferentes roles (actuación, dirección, escenografía, iluminación, sonido, dramaturgia) y comprendiendo su interdependencia dentro del hecho teatral.', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Reflexiona oralmente sobre su experiencia y reconoce aprendizajes en relación con las dimensiones organizativas, comunicativas, afectivas, entre otras.","Participa activamente en el diseño y desarrollo de producciones colectivas, asumiendo responsabilidades específicas dentro del grupo.","Comprende y respeta los roles y funciones dentro del proceso de producción teatral.","Explica cómo las decisiones de cada rol inciden en el resultado de la puesta en escena.","Evalúa el trabajo grupal, reconociendo fortalezas, dificultades y aprendizajes surgidos del proceso colaborativo."]', 'PdA p. 281'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Diseño, producción y presentación de proyectos escénicos interdisciplinarios, integrando distintos lenguajes (audiovisual, literario, visual, corporal, musical).', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Reflexiona sobre los procesos de producción, circulación y recepción del hecho teatral.","Integra de manera coherente distintos lenguajes en la planificación y realización de una propuesta escénica.","Diferencia la especificidad del lenguaje teatral de otros lenguajes artísticos/expresivos.","Selecciona y combina recursos expresivos de diferentes disciplinas para construir una narrativa o atmósfera escénica unificada.","Evalúa críticamente el proceso de integración interdisciplinaria, identificando logros, tensiones y decisiones.","Reflexiona sobre el valor del trabajo interdisciplinario como forma contemporánea de creación teatral y como medio para representar problemáticas sociales, culturales o simbólicas."]', 'PdA p. 281'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Reconocimiento del teatro como proyecto que, como tal, se planifica, se ensaya, se revisa y se comunica a otras/os.', 'pda_2025', 1, 'Afianzar los procesos de creación colectiva, reconociendo el valor del trabajo grupal, construyendo criterios de análisis, apreciación y valoración estética fundamentada.', '["Participa activamente en la planificación de pequeñas producciones teatrales, aportando ideas para personajes, escenas o materiales.","Reconoce el ensayo como parte del proceso creativo, mostrando disposición a repetir, mejorar o ajustar su actuación.","Valora la importancia del trabajo grupal y de la preparación previa antes de mostrar una escena al público.","Identifica momentos del proceso teatral (ensayo, representación, intercambio con el público).","Reflexiona con guía docente sobre los pasos realizados y los aprendizajes alcanzados durante la experiencia teatral."]', 'PdA p. 282'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Experimentación colectiva de escritura dramatúrgica.', 'pda_2025', 1, 'Afianzar los procesos de creación colectiva, reconociendo el valor del trabajo grupal, construyendo criterios de análisis, apreciación y valoración estética fundamentada.', '["Reconoce diferentes posibilidades de abordar la escritura teatral, como dramaturgia de grupo, de actrices/ actores, de directoras/es, de autoras/es, entre otras.","Escribe nuevos textos teatrales a partir del registro de improvisaciones, ensayos, ejercicios de juego teatral, asumiendo decisiones en relación con la estructura y el contenido."]', 'PdA p. 282'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Construcción de poéticas propias en producciones grupales.', 'pda_2025', 1, 'Afianzar los procesos de creación colectiva, reconociendo el valor del trabajo grupal, construyendo criterios de análisis, apreciación y valoración estética fundamentada.', '["Produce, de manera grupal, una propuesta escénica singular en la que integra aprendizajes sobre la improvisación, juego teatral y la composición escénica con las nociones de poéticas y micropoéticas.","Recupera las características de las poéticas teatrales indagadas para incorporarlas en la propia producción.","Reflexiona acerca de posiciones éticas y políticas asumidas, por ejemplo, en el abordaje o tratamiento de la violencia, la discriminación, el poder, el género, entre otras."]', 'PdA p. 282'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Construcción de la convención y las reglas propias de ficción, representación y /o metáfora, en las producciones grupales.', 'pda_2025', 1, 'Afianzar los procesos de creación colectiva, reconociendo el valor del trabajo grupal, construyendo criterios de análisis, apreciación y valoración estética fundamentada.', '["Construye, de manera grupal, una micropoética a partir de la práctica y la producción.","Acuerda en relación con el uso del espacio y el tiempo, el registro de actuación, los criterios de ficción o no ficción, la manera en que se establece el vínculo con el público, los criterios de representación, la cercanía o distancia con la realidad contextual del grupo, entre otros.","Manifiesta las intenciones del grupo y explicita las concepciones que subyacen en las producciones teatrales creadas, tanto acerca de las maneras de hacer teatro, como sobre las temáticas que se proponen."]', 'PdA p. 283'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Sistematización del trabajo grupal mediante la planificación, el ensayo y la revisión crítica.', 'pda_2025', 1, 'Afianzar los procesos de creación colectiva, reconociendo el valor del trabajo grupal, construyendo criterios de análisis, apreciación y valoración estética fundamentada.', '["Reconoce la importancia de la organización, la cooperación y la autoevaluación en la práctica escénica.","Participa activamente en la planificación del proceso teatral, aportando ideas y acordando objetivos, tareas y cronogramas con el grupo.","Sostiene una actitud de compromiso y constancia durante los ensayos, demostrando disposición para mejorar su desempeño y el del grupo.","Participa en instancias de revisión crítica, identificando avances, dificultades y posibles mejoras en las producciones teatrales.","Escucha y valora las observaciones del docente y de sus pares, proponiendo modificaciones o ajustes en función de los acuerdos colectivos.","Expresa reflexiones fundamentadas sobre el proceso de creación, reconociendo el valor de la planificación, la cooperación y la evaluación compartida."]', 'PdA p. 283'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Valoración del teatro como espacio de encuentro y construcción colectiva de conocimiento.', 'pda_2025', 1, 'Afianzar los procesos de creación colectiva, reconociendo el valor del trabajo grupal, construyendo criterios de análisis, apreciación y valoración estética fundamentada.', '["Reconoce el valor del trabajo teatral colectivo como experiencia de aprendizaje compartido y de construcción conjunta de sentido.","Relaciona la práctica teatral con otras experiencias de conocimiento, identificando cómo el teatro favorece la reflexión sobre la realidad, la comunicación y la convivencia.","Expresa con argumentos personales cómo el teatro contribuye al desarrollo de habilidades sociales, expresivas y cognitivas.","Valora al teatro como una práctica que integra lo sensible, lo intelectual y lo social, reconociéndolo como un espacio para pensar, sentir y construir colectivamente."]', 'PdA p. 283'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Reconocimiento de las características del fenómeno teatral a lo largo de la historia.', 'pda_2025', 1, 'Pensar y analizar el teatro como un fenómeno social, político y cultural, reconociendo sus vínculos con los contextos históricos y con otras manifestaciones artísticas contemporáneas.', '["Identifica hitos o etapas relevantes en la historia del teatro (por ejemplo, teatro griego, clásico, contemporáneo,entre otros).","Reconoce transformaciones en las formas de representar y en la relación entre actores y público, según los distintos contextos históricos.","Compara representaciones teatrales de diferentes épocas, observando cambios en temas, estilos o espacios escénicos.","Expresa de forma oral o escrita ideas sobre cómo el teatro manifiesta los valores, conflictos o visiones del mundo de su tiempo."]', 'PdA p. 284'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Reconocimiento del teatro como práctica vinculada con las costumbres, creencias y modos de expresión de diferentes sociedades.', 'pda_2025', 1, 'Pensar y analizar el teatro como un fenómeno social, político y cultural, reconociendo sus vínculos con los contextos históricos y con otras manifestaciones artísticas contemporáneas.', '["Observa y describe manifestaciones teatrales o rituales presentes en su contexto o en otras culturas.","Reconoce el teatro como una práctica social que comunica ideas, emociones y valores colectivos.","Establece relaciones entre manifestaciones teatrales y costumbres, celebraciones o ritos juegode diferentes pueblos.","Identifica cómo las obras o escenas teatrales pueden representar modos de vida, creencias o problemáticas sociales."]', 'PdA p. 284'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Lectura grupal de textos teatrales como posibilidad de ingresar a la representación de la alteridad y acceder a concepciones de mundo, diversidad de personas, culturas, realidades.', 'pda_2025', 1, 'Pensar y analizar el teatro como un fenómeno social, político y cultural, reconociendo sus vínculos con los contextos históricos y con otras manifestaciones artísticas contemporáneas.', '["Se acerca a la lectura de textos teatrales de diferentes características.","Reconoce, en las escenas u obras leídas; temáticas, épocas y territorios de producción.","Valora la multiplicidad de sentidos singulares y situados que se desprenden de la lectura.","Reconoce la perspectiva de género en la historia de la dramaturgia, tanto en las representaciones sociales de las obras leídas.","Explora la lectura en voz alta y reconstruye, a través de escenas, las situaciones leídas."]', 'PdA p. 285'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Exploración de relaciones entre el teatro y otras artes.', 'pda_2025', 1, 'Pensar y analizar el teatro como un fenómeno social, político y cultural, reconociendo sus vínculos con los contextos históricos y con otras manifestaciones artísticas contemporáneas.', '["Identifica elementos compartidos entre el teatro y otras disciplinas artísticas (música, plástica, literatura, cine, danza).","Reconoce influencias visuales, sonoras o narrativas de otras artes en producciones teatrales observadas o realizadas en clase.","Participa en actividades donde se integran distintos lenguajes artísticos, mostrando disposición para experimentar combinaciones expresivas.","Explica de manera sencilla cómo la integración de distintos lenguajes enriquece la comunicación escénica."]', 'PdA p. 285'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Identificación de las relaciones entre poéticas teatrales y contextos históricos.', 'pda_2025', 1, 'Pensar y analizar el teatro como un fenómeno social, político y cultural, reconociendo sus vínculos con los contextos históricos y con otras manifestaciones artísticas contemporáneas.', '["Comprende cómo los estilos, temáticas y lenguajes responden a las transformaciones sociales, ideológicas y artísticas de su tiempo.","Reconoce características de distintas poéticas teatrales (realista, épica, absurda, performática, entre otras.) y las vincula con su contexto histórico, social y cultural de origen.","Establece relaciones entre los temas, personajes o conflictos representados y los acontecimientos o debates de la época.","Compara producciones teatrales de diferentes períodos, analizando cómo cada una expresa valores, visiones del mundo o problemáticas sociales.","Utiliza vocabulario específico para describir rasgos estilísticos, estéticos y contextuales de las obras analizadas."]', 'PdA p. 285'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Reconocimiento del teatro contemporáneo como espacio de diálogo interdisciplinario, explorando vínculos con otras artes y con los discursos sociales actuales.', 'pda_2025', 1, 'Pensar y analizar el teatro como un fenómeno social, político y cultural, reconociendo sus vínculos con los contextos históricos y con otras manifestaciones artísticas contemporáneas.', '["Identifica elementos de otras disciplinas artísticas (música, danza, artes visuales, cine, performance, producciones audiovisuales) en producciones teatrales contemporáneas.","Analiza cómo el teatro actual dialoga con problemáticas sociales (género, diversidad, ambiente, memoria, tecnología, identidad, entre otras).","Participa en experiencias de creación interdisciplinaria, integrando recursos de distintas artes para construir sentido escénico.","Explica cómo las producciones contemporáneas amplían el lenguaje teatral y la relación con el público."]', 'PdA p. 286'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Valoración del teatro como medio de expresión y participación ciudadana.', 'pda_2025', 1, 'Pensar y analizar el teatro como un fenómeno social, político y cultural, reconociendo sus vínculos con los contextos históricos y con otras manifestaciones artísticas contemporáneas.', '["Reconoce el valor del teatro como espacio de reflexión, denuncia o transformación social.","Participa en debates o puestas en común sobre el papel del arte en la construcción de ciudadanía y derechos culturales.","Analiza ejemplos de teatro comunitario, político o documental, identificando sus finalidades expresivas y sociales.","Expresa ideas personales sobre cómo el teatro puede intervenir en su contexto cercano, promoviendo actitudes de respeto, empatía y compromiso colectivo."]', 'PdA p. 286');
INSERT INTO `curriculum_contenidos` (`espacio_id`, `tipo`, `titulo`, `descripcion`, `fuente`, `vigente`, `meta`, `indicadores`, `pagina`) VALUES
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Elaboración de reflexiones y/o análisis, utilizando vocabulario específico del lenguaje teatral (personaje, escena, público, actuación, escenario, entre otros).', 'pda_2025', 1, 'Fortalecer la interpretación y análisis crítico de producciones teatrales, promoviendo la formulación de valoraciones argumentadas.', '["Utiliza palabras del campo teatral para describir lo que observa o realiza (por ejemplo, personaje, escena, público).","Comenta lo que le gustó o no de una representación, explicando las razones.","Reconoce elementos básicos de una obra o juego teatral y los menciona en sus apreciaciones.","Escucha las opiniones de sus compañeras/os, respetando diferentes puntos de vista.","Expresa emociones o sensaciones vinculadas con la experiencia teatral de manera oral o escrita."]', 'PdA p. 287'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Identificación de recursos teatrales que generan determinados efectos (por ejemplo, luces que crean climas, gestos que provocan risa, sonidos que acompañan emociones).', 'pda_2025', 1, 'Fortalecer la interpretación y análisis crítico de producciones teatrales, promoviendo la formulación de valoraciones argumentadas.', '["Observa y reconoce recursos expresivos que influyen en la escena (gestos, tonos, luces, sonidos).","Relaciona un recurso con su efecto, comentando cómo contribuye a provocar emoción, sorpresa o risa.","Explora de manera experimental la creación de climas escénicos mediante el uso de voz, movimiento, objetos o iluminación simple.","Participa en conversaciones grupales identificando qué elementos ayudan a comunicar mejor una idea o emoción.","Valora la intencionalidad artística tras las decisiones expresivas del grupo o de los artistas observados."]', 'PdA p. 287'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Identificación de intenciones expresivas, personajes, acciones, climas y uso de recursos del lenguaje teatral (luz, sonido, espacio, objetos, vestuario).', 'pda_2025', 1, 'Fortalecer la interpretación y análisis crítico de producciones teatrales, promoviendo la formulación de valoraciones argumentadas.', '["Reconoce y describe personajes, acciones principales y climas que se generan en una representación.","Identifica intenciones expresivas (divertir, emocionar, asustar, sorprender) en las producciones teatrales observadas o creadas.","Observa y comenta el uso de recursos escénicos (luz, sonido, vestuario, objetos) y su relación con el sentido de la escena.","Diferencia entre escenas realistas, simbólicas o imaginarias, mostrando comprensión de distintos modos expresivos.","Participa en intercambios grupales, aportando ideas personales sobre lo que percibe en las producciones."]', 'PdA p. 288'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Ampliación del vocabulario disciplinar del teatro en el análisis del hecho escénico.', 'pda_2025', 1, 'Fortalecer la interpretación y análisis crítico de producciones teatrales, promoviendo la formulación de valoraciones argumentadas.', '["Comprende y emplea el vocabulario disciplinar, en forma oral o escrita, para el análisis del hecho escénico y la relación con sus propias ideas.","Utiliza un vocabulario teatral más preciso al describir o analizar producciones.","Emplea términos teatrales para comunicar ideas propias o realizar comentarios sobre lo observado.","Reconoce palabras del lenguaje teatral en materiales o conversaciones del aula y las aplica correctamente en contextos nuevos.","Relaciona conceptos con experiencias teatrales concretas (por ejemplo, “esa escena tenía un conflicto”, “la música ayudaba a crear climas”)."]', 'PdA p. 288'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Reconocimiento del valor simbólico y expresivo de los recursos escénicos, comprendiendo cómo contribuyen a comunicar emociones, ideas o mensajes en una representación.', 'pda_2025', 1, 'Fortalecer la interpretación y análisis crítico de producciones teatrales, promoviendo la formulación de valoraciones argumentadas.', '["Identifica la intención comunicativa detrás del uso de ciertos recursos escénicos.","Explica con sus palabras cómo determinados elementos ayudan a transmitir una emoción o sentido.","Explora, en sus propias producciones, el uso expresivo de materiales, objetos, vestuarios o sonidos con sentido simbólico.","Reconoce el uso expresivo de los recursos teatrales.","Reflexiona sobre cómo los recursos escénicos enriquecen la escena y generan significados más complejos."]', 'PdA p. 288'),
(7, 'eje_contenido', 'Teatro (por ciclo)', 'Reflexión crítica y colaborativa sobre el proceso y el producto teatral, identificando logros, desafíos y posibles cambios o mejoras.', 'pda_2025', 1, 'Fortalecer la interpretación y análisis crítico de producciones teatrales, promoviendo la formulación de valoraciones argumentadas.', '["Participa activamente en instancias de revisión grupal, proponiendo mejoras y reconociendo avances del grupo.","Identifica logros personales y colectivos, valorando el trabajo conjunto.","Comenta con respeto las dificultades encontradas durante el proceso creativo.","Sugiere alternativas o nuevas ideas para resolver problemas o enriquecer la puesta.","Escucha las opiniones de los demás y ajusta su actuación o propuesta en función del intercambio grupal.","Reconoce la importancia del proceso de ensayo y revisión como parte esencial del trabajo teatral."]', 'PdA p. 289'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de sistemas sociotécnicos de diferentes épocas, culturas y lugares, reconociendo similitudes y diferencias de las relaciones que los conforman, materiales y medios técnicos.', 'pda_2025', 1, 'Problematizar y valorar las intervenciones tecnológicas, en el marco de la construcción de subjetividades y ciudadanías, identificando cómo estas interpelan y transforman las prácticas sociales, culturales, económicas y laborales.', '["Compara sistemas tecnológicos de distintas épocas, culturas y lugares, identificando los cambios y las transformaciones en relación con la producción, el trabajo y la vida cotidiana.","Reconoce los procesos de innovación presentes en la evolución de la tecnología.","Explica los cambios técnicos, sociotécnicos y la tecnificación, en el paso del control manual a los procesos de automatización.","Comprende posibles cadenas de efecto en la transformación de los sistemas tecnológicos (por ejemplo, la invención del automóvil impulsó áreas tecnológicas como la vial, la producción y refinamiento de combustibles).","Identifica cambios y continuidades del software y del hardware de las computadoras, a lo largo del tiempo (por ejemplo, advertir que la reducción del tamaño de algunos componentes incidió en el tamaño general de los dispositivos, se mantuvo la misma arquitectura general, es decir, unidad de procesamiento, memoria, componentes de entrada y de salida).","Identifica las relaciones entre los cambios del hardware y software, y los diferentes actores involucrados (en los ámbitos académico, empresarial, estatal, de usuarios y consumidores, entre otros)."]', 'PdA p. 104'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de los cambios socioculturales, a partir del acceso masivo a las tecnologías de la información y la comunicación.', 'pda_2025', 1, 'Problematizar y valorar las intervenciones tecnológicas, en el marco de la construcción de subjetividades y ciudadanías, identificando cómo estas interpelan y transforman las prácticas sociales, culturales, económicas y laborales.', '["Identifica las modificaciones de aspectos técnicos, sociales, culturales y económicos, producidas por las tecnologías de la información y la comunicación (imprenta, telégrafo, teléfono, Internet, entre otras), a lo largo del tiempo.","Relaciona el surgimiento de determinadas tecnologías de la información y la comunicación, con las necesidades de otros sistemas tecnológicos del momento histórico (por ejemplo, la relación del telégrafo y el ferrocarril o la telefonía e Internet).","Identifica particularidades del entorno digital (como el anonimato, la viralización de la información, la heterogeneidad de plataformas) que inciden en las prácticas sociales y culturales.","Reflexiona sobre la influencia de Internet, las redes sociales y plataformas digitales, en las formas de interacción, participación y organización de la vida cotidiana.","Distingue diversas formas de violencia digital, tales como el ciberacoso (ciberbullying y acoso digital), el cibercontrol (vigilancia o control de la actividad virtual), el doxing (difusión de datos personales con fines de acoso), la suplantación de identidad digital y las amenazas virtuales, reconociendo sus implicancias en los vínculos sociales y las prácticas culturales en entornos digitales."]', 'PdA p. 104'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento del vínculo entre tecnología, técnica y ciencia, identificando diferencias, interrelaciones y estímulos mutuos, en distintos contextos.', 'pda_2025', 1, 'Problematizar y valorar las intervenciones tecnológicas, en el marco de la construcción de subjetividades y ciudadanías, identificando cómo estas interpelan y transforman las prácticas sociales, culturales, económicas y laborales.', '["Diferencia técnica, ciencia y tecnología, para conceptualizar cada uno de los términos.","Analiza casos de interrelación de técnica, ciencia y tecnología, su influencia en el desarrollo social y en los avances en diversos campos.","Indaga sobre la relación entre ciencia y tecnología, a lo largo de la historia.","Explora producciones actuales en las que ciencia y tecnología se potencian mutuamente."]', 'PdA p. 105'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Valoración de las diferencias y similitudes, en relación con el rol que cumplen las personas en los procesos tecnológicos automatizados.', 'pda_2025', 1, 'Problematizar y valorar las intervenciones tecnológicas, en el marco de la construcción de subjetividades y ciudadanías, identificando cómo estas interpelan y transforman las prácticas sociales, culturales, económicas y laborales.', '["Identifica tareas, roles y saberes técnicos que aplican las personas en procesos manuales y automatizados, en diferentes contextos de producción.","Compara artefactos, con mayor o menor automatización, identificando la delegación del plan de acciones humanas.","Identifica las operaciones para realizar una tarea y reconoce aquellas que pueden ser realizadas por personas, de aquellas que pueden ser delegadas a alguna máquina o dispositivo (en lo referido a control, toma de decisiones y/o actuación).","Valora las ventajas y desventajas de la automatización en diferentes áreas de trabajo, profesiones y oficios, considerando aspectos como seguridad, productividad, originalidad, eficiencia y calidad, entre otros.","Reconoce la presencia de sesgos de género en el diseño y uso de artefactos y sistemas automatizados, reflexionando sobre cómo estos pueden impactar en la participación y en la construcción de estereotipos en diferentes profesiones y oficios."]', 'PdA p. 105'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de las modificaciones (técnicas, sociales y económicas), provocadas por la utilización de diversas fuentes de energía.', 'pda_2025', 1, 'Problematizar y valorar las intervenciones tecnológicas, en el marco de la construcción de subjetividades y ciudadanías, identificando cómo estas interpelan y transforman las prácticas sociales, culturales, económicas y laborales.', '["Describe cómo la incorporación de nuevas fuentes energéticas modificó las condiciones de vida de las personas en distintos contextos (por ejemplo, el uso de fuego, la electricidad, entre otras).","Identifica cambios en las formas de producción, transporte y distribución, vinculados con el uso de diferentes fuentes de energía, a lo largo del tiempo.","Reflexiona acerca del vínculo entre los procesos energéticos, la economía y el desarrollo productivo de una sociedad (por ejemplo, la relación directa entre la industria computacional y el aumento de las emisiones de carbono)."]', 'PdA p. 105'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Relación entre el accionar tecnológico y sus implicancias ambientales, en especial, en las etapas de extracción de elementos naturales que se transforman en insumos, los procesos productivos, las actividades de servicio y la gestión de residuos.', 'pda_2025', 1, 'Problematizar y valorar las intervenciones tecnológicas, en el marco de la construcción de subjetividades y ciudadanías, identificando cómo estas interpelan y transforman las prácticas sociales, culturales, económicas y laborales.', '["Reconoce los impactos ambientales generados por los procesos tecnológicos, como las emisiones de carbono que contribuyen al cambio climático, la acumulación de residuos en mares y océanos,la generación de residuos eléctricos y electrónicos, el uso de agua potable y su contaminación, entre otros.","Contrasta tecnologías orientadas a prevenir la contaminación con aquellas diseñadas para reparar el daño ambiental, por ejemplo, la producción de bioplásticos frente al reciclaje de plásticos convencionales.","Evalúa tecnologías según los impactos ambientales locales o regionales, identificando aquellas que son técnicamente viables, socialmente equitativas y ambientalmente sostenibles.","Reconoce los costos ambientales asociados con la fabricación, uso y desecho de dispositivos tecnológicos, y los evalúa desde la perspectiva de la economía circular, promoviendo la reutilización, prolongación de su vida útil o incorporación a nuevos procesos productivos."]', 'PdA p. 106'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de procesos tecnológicos del entorno, enfatizando en el reconocimiento de sus etapas y su interrelación.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Analiza procesos tecnológicos de producción diversos, reconociendo las operaciones técnicas y diferenciando las de transformación, respecto de las de organización espacio-temporal.","Utiliza diagramas y gráficos para la representación de secuencias de operaciones en un proceso.","Identifica en cada operación técnica el tipo de energía que se utiliza y la información que interviene, como insumo o como salida del proceso.","Distingue, en los procesos, el producto final de los residuos generados, analizando la eficiencia y sostenibilidad.","Valora procesos tecnológicos que atienden las necesidades locales, reconociendo la importancia de los saberes regionales."]', 'PdA p. 114'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento y clasificación de diferentes tipos de procesos de producción.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Distingue las tareas que realizan las personas y cómo se organizan diferentes procesos de producción (flexible y en línea).","Vincula tipos de procesos industriales (intermitentes, por lotes, continuos, por proyecto), con la cantidad y variedad de productos.","Identifica las tareas y el modo en que se organizan (redes de precedencias) y los procesos de producción por proyecto, analizando casos reales (fabricación de aviones, satélites, entre otros).","Describe los medios técnicos utilizados según el tipo de proceso de producción."]', 'PdA p. 114'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de productos tecnológicos, reconociendo que son el resultado de un proceso.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Identifica que la acción tecnológica excede los objetos materiales e incluye procesos, organizaciones, servicios, programas, métodos, entre otros.","Utiliza el análisis de productos para reconstruir los procesos de diseño y creación de distintos productos tecnológicos.","Reconoce que los productos tecnológicos son la respuesta a necesidades, deseos , demandas con diversos intereses (poder, lucro, valor del mercado, publicidad y propaganda) de distintos grupos sociales que disputan diseños tecnológicos."]', 'PdA p. 115'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Relación entre propiedades de materiales, operaciones técnicas y características del producto, analizando procesos de transformación de materiales.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Relaciona operaciones técnicas (como extrusión, termoformado, torneado, molienda) con los materiales sobre los que se aplican, y con las propiedades que modifican o aprovechan.","Analiza cómo las operaciones técnicas afectan las propiedades de los materiales y, en consecuencia, las características del producto final.","Identifica propiedades de los materiales (tales como flexibilidad, tenacidad, conductividad, entre otras) y las relaciona con su utilización para elaborar productos tecnológicos.","Compara productos según el tipo de material utilizado y las operaciones realizadas, reconociendo diferencias en funcionalidad, durabilidad o estética."]', 'PdA p. 115'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de los procesos de extracción de materiales y producción de materia prima.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Identifica las etapas y herramientas involucradas en procesos de extracción de materiales (por ejemplo, minería, tala, extracción de petróleo, entre otros).","Reconoce los recursos naturales utilizados y distingue su capacidad de regeneración, evaluando su sostenibilidad.","Compara distintos métodos de extracción de un mismo material, valorando el impacto ambiental y las condiciones de trabajo de las personas.","Analiza críticamente el modelo económico extractivista, comparando sus métodos de extracción (minería, hidrocarburos, agroindustria) con alternativas sostenibles, y evaluando su impacto integral (ambiental, social y de desarrollo económico) en los territorios."]', 'PdA p. 115'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de artefactos y sistemas tecnológicos, reconociendo los componentes, las interrelaciones, sus funciones y funcionamientos.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Comprende que un sistema es un conjunto de elementos interrelacionados que cumplen una función específica.","Describe las funciones y funcionamiento de distintos medios técnicos en un proceso.","Representa, por medio del dibujo técnico, artefactos en 2 y 3 dimensiones, especificando cada uno de sus componentes.","Analiza sistemas tecnológicos (eléctricos, mecánicos, hidráulicos, entre otros), identificando los subsistemas, componentes y flujo principal (electricidad, líquido, fuerzas, gases, entre otros).","Identifica componentes de control, transporte, almacenamiento y transformación, en distintos sistemas tecnológicos y/o artefactos."]', 'PdA p. 116'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis del funcionamiento de los artefactos que realizan transformaciones de energía en los procesos.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Identifica la energía útil y las energías residuales en un artefacto.","Reconoce los componentes de un artefacto, que permiten reducir el efecto de la energía residual (por ejemplo, cooler de una computadora, bandeja evaporadora del motor de una heladera).","Asocia operaciones técnicas específicas (como calentar, mover, iluminar, con las transformaciones de energía que las hacen posibles.","Reconoce transformaciones energéticas en artefactos cotidianos (como eléctrica a mecánica en un ventilador o a térmica en una estufa) y las representa por medio de diagramas de bloque."]', 'PdA p. 116'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Utilización, análisis, selección de instrumentos de medición.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Identifica diferentes tipos de instrumentos de medición (como termómetros, manómetros, multímetros) y sus aplicaciones.","Utiliza correctamente instrumentos de medición para obtener datos sobre las propiedades físicas de materiales o procesos.","Compara los resultados obtenidos con diferentes instrumentos de medición, para verificar su precisión y fiabilidad.","Selecciona el instrumento adecuado, según las características del proceso o material a medir."]', 'PdA p. 116'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Diferenciación entre software libre y privativo, reconociendo particularidades, similitudes, ventajas y desventajas.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Reconoce que el software es una producción intelectual (de personas, organizaciones o empresas) y, por lo tanto, está sujeta a las nociones de derecho de autoría y de responsabilidad social.","Considera que el desarrollo de software dispone de ciertos instrumentos legales, que habilitan o restringen modos de producción y de distribución (por ejemplo, las licencias Creative Commons o de dominio público vs. las patentes o licencias privativas).","Identifica ventajas y desventajas de los distintos tipos de licenciamiento del software (nivel de dependencia, posibilidad de análisis y apropiación para modificar y crear artefactos computacionales, relación entre las motivaciones y los intereses de quienes producen y usan software y hardware, con los modos de producirlos o distribuirlos).","Ejemplifica las nociones de software libre y privativo.","Identifica la presencia de software libre en los dispositivos computacionales que usa cotidianamente (por ejemplo, el sistema operativo Android, de teléfonos móviles, está basado en el núcleo Linux o el navegador web Mozilla Firefox)."]', 'PdA p. 117'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión del modelo de Von Neumann, como una forma general de organizar una máquina programable.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Reconoce el rol de los componentes fundamentales de este modelo en la ejecución de un programa.","Reconoce el modelo en los dispositivos de distintos momentos históricos, incluído el actual.","Relaciona los elementos de la arquitectura Von Neumann con aquellos componentes de hardware de los dispositivos computacionales que corresponden.","Identifica el rol que tiene el software en el modelo de Von Neumann, como instrucciones de programa que se almacenan en la misma memoria que los datos, y que la CPU ejecuta secuencialmente."]', 'PdA p. 117'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de procesos de comunicación a distancia, reconociendo operaciones como emisión, codificación, transmisión, recepción y decodificación, en sistemas que emplean señales sonoras o visuales.', 'pda_2025', 1, 'Comprender sistemas de información y comunicación a partir de las operaciones claves de recolección, representación, almacenamiento, transformación y transmisión de datos e información, así como también de los protocolos y artefactos involucrados en su funcionamiento.', '["Describe las etapas del proceso de comunicación, identificando operaciones como emitir, codificar, transmitir, recepcionar y decodificar, en sistemas, por ejemplo, un mensaje con tambores o una señal de humo o telégrafo de Chappe.","Analiza distintos sistemas de comunicación a distancia, reconociendo las operaciones de codificación (transformar la información en señales) y decodificación (interpretar esas señales).","Distingue los componentes físicos de un sistema de comunicación, como terminales (por ejemplo, micrófono y parlante en un teléfono) y medios de transmisión.","Diferencia medios de transmisión de señales (cables conductores, transmisión inalámbrica).","Reconoce las tareas y roles de las personas en los procesos de transmisión de información a distancia."]', 'PdA p. 127'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de la “digitalización” en los procesos de transmisión de información.', 'pda_2025', 1, 'Comprender sistemas de información y comunicación a partir de las operaciones claves de recolección, representación, almacenamiento, transformación y transmisión de datos e información, así como también de los protocolos y artefactos involucrados en su funcionamiento.', '["Distingue entre señal analógica y señal digital, reconociendo que la primera varía de forma continua (como el sonido en una radio antigua), y la segunda, usa valores discretos (como los datos transmitidos por computadoras o celulares).","Comprende que el proceso de digitalización consiste en convertir la señal analógica en señal discreta, para que pueda ser procesada, almacenada y transmitida por los dispositivos.","Analiza artefactos tecnológicos que representan la información de forma digital, como el telégrafo, el fax o sistemas computacionales.","Reconoce situaciones en que la digitalización presenta ventajas en la transmisión y almacenamiento de información, como la precisión, eficiencia y mayor durabilidad, comparando ejemplos como TV digital vs. analógica, o MP3 vs. casete."]', 'PdA p. 127'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de la estructura básica y funcionamiento de una red informática.', 'pda_2025', 1, 'Comprender sistemas de información y comunicación a partir de las operaciones claves de recolección, representación, almacenamiento, transformación y transmisión de datos e información, así como también de los protocolos y artefactos involucrados en su funcionamiento.', '["Comprende las funciones del hardware utilizado en redes (enrutador, puntos de acceso WI-Fi, conmutador o switch, repetidor, puente, entre otros).","Reconoce, en el análisis de redes cercanas, diferentes configuraciones de red (por ejemplo, redes locales, redes centralizadas y redes distribuídas).","Diferencia redes simples (la hogareña o escolar) y complejas (la del proveedor de servicios de Internet), en función de sus componentes y organización.","Identifica que, a partir de modificaciones de hardware y equipamiento, se pueden lograr mejoras en el funcionamiento de una red (por ejemplo, ubicación del router, uso de repetidores, cableado más adecuado).","Reconoce que cada dispositivo tiene asignada una dirección que lo identifica de manera única en la red , la IP (manejada por routers) y la MAC (para identificación física, manejada por switches), distinguiendo la unidad de datos (paquete o trama).","Reconoce que el router utiliza las direcciones IP para poder direccionar paquetes entre redes y switches, y las direcciones MAC, para dirigir tramas (frames) dentro de una red local."]', 'PdA p. 128'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso y análisis de protocolos para ejercer el control sobre la transmisión de información a distancia.', 'pda_2025', 1, 'Comprender sistemas de información y comunicación a partir de las operaciones claves de recolección, representación, almacenamiento, transformación y transmisión de datos e información, así como también de los protocolos y artefactos involucrados en su funcionamiento.', '["Reconoce protocolos utilizados para la transmisión de mensajes, como el uso de señales luminosas (linternas o faroles), banderas, tambores o sonidos codificados, identificando que la norma acordada permite organizar la comunicación.","Compara distintos protocolos según el tipo de señal que utilizan, analizando las ventajas y limitaciones de cada uno en distintas situaciones.","Describe cómo los protocolos aseguran el orden, la sincronización y la corrección de errores.","Analiza qué pasa cuando no se respetan las normas acordadas (errores, interferencias, confusión).","Distingue entre código y protocolo, al comprender que el código define el significado de cada señal, mientras que el protocolo establece cómo y cuándo se envían o reciben esas señales (por ejemplo, en qué orden, a qué ritmo, con qué pausas, entre otros).","Reconoce Internet como una red informática e identifica la existencia de protocolos de comunicación (por ejemplo, IP)."]', 'PdA p. 128'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Construcción de alternativas de solución para problemas de diseño de procesos tecnológicos, que respondan a problemáticas del entorno.', 'pda_2025', 1, 'Complejizar alternativas de solución que impliquen procesos de diseño y de desarrollo de productos tecnológicos en respuesta a problemas de la comunidad cercana, teniendo en cuenta la viabilidad, la incidencia en el contexto social y la sostenibilidad.', '["Distingue los diferentes momentos o fases en la resolución de problemas de diseño, por ejemplo, identificación y análisis del problema, búsqueda de alternativas, evaluación y selección de soluciones técnicas.","Planifica, de manera individual o colectiva, procesos de fabricación, tomando decisiones sobre la secuencia de armado, la cantidad de personas necesarias en cada etapa, la posibilidad de realizar operaciones simultáneas, entre otras.","Diseña y construye prototipos funcionales que responden a la problemática planteada, evaluando su funcionamiento y proponiendo mejoras.","Utiliza medios de representación para comunicar la información necesaria en cada etapa del proyecto.","Evalúa la solución diseñada, identificando posibles mejoras y su impacto en el entorno."]', 'PdA p. 135'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Participación en experiencias de diseño y construcción de artefactos sencillos para transportar materia, energía y/o información.', 'pda_2025', 1, 'Complejizar alternativas de solución que impliquen procesos de diseño y de desarrollo de productos tecnológicos en respuesta a problemas de la comunidad cercana, teniendo en cuenta la viabilidad, la incidencia en el contexto social y la sostenibilidad.', '["Diseña y construye artefactos sencillos que cumplan con la función de transportar materia, energía o información, utilizando materiales accesibles.","Identifica los componentes principales para que un artefacto cumpla su función, y describe su interacción.","Aplica conceptos de resistencia de materiales y estabilidad en el diseño de la estructura de un artefacto.","Reflexiona sobre las decisiones tomadas durante el diseño y construcción, por ejemplo, evalúa su eficacia y propone ajustes para mejorarlo.","Relaciona el diseño de un artefacto con situaciones problemáticas reales."]', 'PdA p. 135'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Resolución de problemas de diseño de transmisión de señales visuales o sonoras a distancia, estableciendo códigos y protocolos.', 'pda_2025', 1, 'Complejizar alternativas de solución que impliquen procesos de diseño y de desarrollo de productos tecnológicos en respuesta a problemas de la comunidad cercana, teniendo en cuenta la viabilidad, la incidencia en el contexto social y la sostenibilidad.', '["Identifica situaciones problemáticas en las que es necesario establecer comunicación a distancia.","Delimita el problema de comunicación, considerando condiciones del entorno y medios disponibles.","Indaga sobre sistemas de comunicación a distancia a lo largo del tiempo (telégrafo de Chappe, señales de humo, sistemas de tambores, telégrafo hidráulico, entre otros).","Diseña soluciones tecnológicas para comunicarse a distancia mediante señales visuales o sonoras, como sistemas de luces intermitentes, códigos de sonido, banderas o dispositivos simples.","Establece y aplica códigos y protocolos, adecuados para una comunicación clara y efectiva.","Evalúa la eficacia del sistema de comunicación propuesto, identificando posibles mejoras."]', 'PdA p. 136'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Participación en experiencias colaborativas de diseño de programas, para la resolución de problemas con elementos básicos de un lenguaje de programación.', 'pda_2025', 1, 'Complejizar alternativas de solución que impliquen procesos de diseño y de desarrollo de productos tecnológicos en respuesta a problemas de la comunidad cercana, teniendo en cuenta la viabilidad, la incidencia en el contexto social y la sostenibilidad.', '["Participa activamente en la distribución de las tareas de diseño y codificación, dentro de un equipo de trabajo.","Aplica manejo de eventos (controlados o por interacciones con la/el usuaria/o) en el diseño y construcción de programas.","Utiliza y crea procedimientos que integra al proceso de desarrollo de programas.","Diseña y construye, colaborativamente, programas para resolver problemas, utilizando lenguajes de programación (de bloques o textual) en los que se emplean, de manera combinada, diferentes estructuras de control y manipulando variables numéricas, eventos y procedimientos."]', 'PdA p. 136'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Iniciación en la codificación de programas, en un lenguaje de programación textual como python o javascript, entre otros.', 'pda_2025', 1, 'Desarrollar programas que utilicen la modularidad, manejo de eventos, estructuras de control y de datos, y que consideren criterios de legibilidad y eficacia en relación con sus objetivos, aplicando las habilidades de testeo, depuración y corrección.', '["Distingue los elementos y estructuras fundamentales de la programación, que son generales a todo lenguaje de programación (textual o de bloques).","Representa algoritmos con pseudocódigo, de manera optativa, y como paso intermedio entre el uso de bloques y la codificación en un lenguaje textual.","Identifica la sintaxis como reglas de combinación de comandos y expresiones de un lenguaje de programación.","Distingue entre la sintaxis, en lenguajes de bloques (dada por la forma predeterminada de los mismos), y la sintaxis de un lenguaje de programación textual.","Reconoce errores asociados con la sintaxis de los lenguajes textuales.","Utiliza adecuadamente los símbolos, según la sintaxis del lenguaje textual, para construir programas simples (que puedan incluir secuenciales, ciclos, alternativas condicionales y ciclos condicionales, variables numéricas, manejo de eventos, procedimientos)."]', 'PdA p. 141'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento del uso de variables para el almacenamiento de datos, en el desarrollo de los programas.', 'pda_2025', 1, 'Desarrollar programas que utilicen la modularidad, manejo de eventos, estructuras de control y de datos, y que consideren criterios de legibilidad y eficacia en relación con sus objetivos, aplicando las habilidades de testeo, depuración y corrección.', '["Identifica situaciones en las que se necesita almacenar datos en un determinado programa (por ejemplo, el puntaje en un juego, el nombre de la/del usuaria/o, entre otras).","Explora programas dados en los que se utilizan variables, reconociendo la función que cumplen.","Identifica que una variable almacena un dato, mientras que un comando representa una acción que ejecutará el dispositivo.","Comprueba que, al asignarle un nuevo valor a la variable, el valor anterior se pierde."]', 'PdA p. 141'),
(8, 'eje_contenido', 'Progresiones de Aprendizaje', 'Introducción al modelado de datos, identificando atributos relevantes de entidades.', 'pda_2025', 1, 'Desarrollar programas que utilicen la modularidad, manejo de eventos, estructuras de control y de datos, y que consideren criterios de legibilidad y eficacia en relación con sus objetivos, aplicando las habilidades de testeo, depuración y corrección.', '["Identifica qué entidades están involucradas en el contexto de un problema que requiera la organización y procesamiento de datos (por ejemplo, estudiante, institución, cliente, producto).","Reconoce una entidad, sus atributos, es decir el conjunto de características que las identifican y diferencian de otras entidades (por ejemplo, nombre, apellido, DNI, son atributos de la entidad persona).","Identifica atributos relevantes de las entidades, según el problema de modelado que se esté abordando.","Reconoce los registros de datos como una estrategia de representación de entidades.","Opera con registros de datos en programas de planillas de cálculo, manipulando sus campos para acceder, modificar o utilizar la información que representan."]', 'PdA p. 142'),
(8, 'objetivo', 'Objetivo', 'Identificar y analizar procesos tecnológicos de su entorno y los productos que de ellos resultan y relacionarlos con las prácticas concretas de producción y uso de los mismos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'objetivo', 'Objetivo', 'Resolver situaciones problemáticas, considerando los procesos tecnológicos que intervienen en su planteo y resolución.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'objetivo', 'Objetivo', 'Planificar, ejecutar y evaluar procesos tecnológicos utilizando insumos y medios técnicos, con las medidas adecuadas para la seguridad de las personas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'objetivo', 'Objetivo', 'Comprender -a partir de su utilización y valoración- los modos de representación y comunicación que participan en la construcción del conocimiento tecnológico y que permiten otorgarle especificidad.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'objetivo', 'Objetivo', 'Incorporar crítica y progresivamente criterios para actuar en los procesos tecnológicos, garantizando la seguridad social, la salud de las personas y la sustentabilidad ambiental.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'objetivo', 'Objetivo', 'Valorar el desarrollo histórico de la tecnología, identificando los cambios producidos, aquéllos inventos que impactaron en la sociedad y el rol creativo de hombres y mujeres en estos procesos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'objetivo', 'Objetivo', 'Incrementar la curiosidad y el interés por los procesos tecnológicos, los medios técnicos que participan, sus productos resultantes y la disposición final de los residuos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'objetivo', 'Objetivo', 'Analizar artefactos identificando las funciones de las partes que los forman, sus relaciones y el modo como se energizan y controlan.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'eje_contenido', 'Procesos tecnológicos', 'Análisis de productos y procesos tecnológicos del entorno poniendo énfasis en el reconocimiento de sus partes y como se interrelacionan.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'eje_contenido', 'Procesos tecnológicos', 'Reconocimiento de las interacciones entre materia, energía e información que están presentes en los diversos procesos tecnológicos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'eje_contenido', 'Procesos tecnológicos', 'Resolución de problemas de diseño de procesos tecnológicos que respondan a problemáticas del entorno planteadas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'eje_contenido', 'Medios técnicos', 'Análisis e identificación del funcionamiento de los artefactos que realizan transformaciones de energía en los procesos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'eje_contenido', 'Medios técnicos', 'Identificación de las relaciones entre las partes de los artefactos, las formas que poseen y la función que cumplen.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'eje_contenido', 'Medios técnicos', 'Utilización, análisis, selección de los instrumentos de medición.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'eje_contenido', 'La tecnología como proceso sociocultural', 'Identificación, diferenciación, análisis de las tareas que realizan las personas en los procesos tecnológicos y sus implicancias sociales, laborales, económicas, políticas, culturales, etc.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'eje_contenido', 'La tecnología como proceso sociocultural', 'Utilización y análisis de diferentes maneras de comunicar la información técnica correspondiente a un proceso, identificando la finalidad y los destinatarios para su selección y desarrollo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(8, 'eje_contenido', 'La tecnología como proceso sociocultural', 'Uso de las TIC como herramienta para elaborar, producir y comunicar la información técnica comparándolas con diversos soportes y sistemas de representación.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis crítico de situaciones problemáticas que involucren derechos y responsabilidades de las/os jóvenes, en diferentes entornos, identificando organizaciones sociales y procedimientos institucionales locales y provinciales para su exigibilidad.', 'pda_2025', 1, 'Reconocerse a sí misma/o y a las/os otras/os como sujetos de derechos y obligaciones, comprendiendo los derechos humanos establecidos transnacionalmente, así como algunos derechos civiles, políticos y sociales de las/os jóvenes como ciudadanas/os, conquistados en la historia argentina, junto a los procedimientos e instituciones que garantizan su protección y promoción.', '["Examina derechos contemplados en diferentes normativas, por ejemplo, el nuevo Código Civil, la Ley de Protección Integral de NNA y la Ley del Voto Joven, entre otras.","Identifica procedimientos para resolver situaciones problemáticas en el ámbito familiar, el mundo del trabajo y la participación política, entre otros.","Contrasta situaciones de vigencia y vulneración de derechos de NNA, reconociendo discursos sociales que estigmatizan y criminalizan a las/os jóvenes de diferentes sectores sociales y consumos culturales.","Propone acciones para la promoción y defensa de los Derechos de NNA.","Reconoce e indaga acerca de instituciones locales/provinciales que protegen y promocionan derechos de NNA, a las que puede acudir ante situaciones concretas (por ejemplo, la identidad de género en la escuela o el hospital)."]', 'PdA p. 108'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación de principios, garantías, deberes y derechos constitucionales fundamentales, y reflexión sobre su importancia para la democracia, así como su vigencia en la historia reciente argentina y en la actualidad.', 'pda_2025', 1, 'Reconocerse a sí misma/o y a las/os otras/os como sujetos de derechos y obligaciones, comprendiendo los derechos humanos establecidos transnacionalmente, así como algunos derechos civiles, políticos y sociales de las/os jóvenes como ciudadanas/os, conquistados en la historia argentina, junto a los procedimientos e instituciones que garantizan su protección y promoción.', '["Diferencia principios, garantías, deberes y derechos constitucionales, explicando los valores que representan, algunas de sus funciones, y su valor en la vida democrática.","Define qué es una garantía constitucional y reconoce su importancia para la protección de derechos.","Explica la vinculación entre derechos y deberes fundamentales, ofreciendo ejemplos.","Comprende nociones como igualdad ante la ley, debido proceso, defensa en juicio, presunción de inocencia, libertad de expresión y de culto, acceso a la justicia e información veraz, derecho a peticionar ante las autoridades, condiciones dignas y equitativas de labor, derecho a huelga, derecho a la seguridad, entre otros.","Compara la vigencia o vulneración de principios, derechos y garantías, en gobiernos dictatoriales y democráticos, y debate sobre casos (de trascendencia pública/ mediática en la actualidad y la historia reciente).","Valora críticamente algunos principios, derechos y garantías constitucionales, fundamentando (de manera escrita u oral) su relevancia para la vida democrática.","Selecciona un principio, garantía y/o derecho constitucional vinculada con la prevención integral y gestión de riesgo socioambientales, y fundamenta (de manera escrita u oral) su importancia para la vida democrática."]', 'PdA p. 109'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento y puesta en valor de la democracia como cultura y estilo de vida, comprendiendo la participación como un derecho de NNA y una responsabilidad para con la comunidad y el entorno.', 'pda_2025', 1, 'Participar democráticamente en acciones de ciudadanía local comprometidas con el desarrollo sostenible, que sean significativas para las juventudes y se aproximen a experiencias de ciudadanía global, a través de la apropiación (o no) de tecnologías digitales.', '["Ejerce el derecho a expresarse libremente y a ser escuchada/o en temas que afectan a las adolescencias, utilizando distintos espacios de participación —incluidos los digitales—, ante autoridades institucionales, barriales o representantes locales electas/os.","Asume actitudes y valores democráticos, tales como la igualdad de derechos, la participación colectiva en temáticas que afectan a todas/os las/os involucradas/os, la aceptación de las reglas consensuadas grupalmente, la deliberación como mecanismo para tomar decisiones sobre problemáticas comunes, entre otros.","Analiza casos y participa de debates grupales sobre la vulneración de derechos en democracia, y reflexiona acerca de los mecanismos para la exigencia de su cumplimiento.","Valora el compromiso y la solidaridad con la comunidad como parte constitutiva de la ciudadanía, a través del reconocimiento de experiencias escolares y locales que promueven el cuidado y la sostenibilidad."]', 'PdA p. 111'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Participación progresiva y efectiva en el gobierno escolar, como ejercicio de derechos y responsabilidades de las/os jóvenes, a partir de problemáticas vinculadas con la convivencia entre pares y personas adultas, en ámbitos físicos y entornos digitales.', 'pda_2025', 1, 'Participar democráticamente en acciones de ciudadanía local comprometidas con el desarrollo sostenible, que sean significativas para las juventudes y se aproximen a experiencias de ciudadanía global, a través de la apropiación (o no) de tecnologías digitales.', '["Se involucra, con voz y voto, en diversos espacios de participación estudiantil, por ejemplo, centro de estudiantes, consejos institucionales, mediaciones, proyectos escolares, salidas educativas, entre otros.","Analiza acuerdos de convivencia y realiza propuestas/revisiones/modificaciones sobre problemáticas de la convivencia atravesadas por las tecnologías digitales.","Reflexiona sobre su propio modo de participación en estos espacios, reconociendo fortalezas y aspectos a revisar, para un ejercicio más responsable y democrático."]', 'PdA p. 111'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de las formas en que la ciudadanía se apropia de las tecnologías digitales dedicadas a la creación de herramientas tecnológicas para el bienestar.', 'pda_2025', 1, 'Participar democráticamente en acciones de ciudadanía local comprometidas con el desarrollo sostenible, que sean significativas para las juventudes y se aproximen a experiencias de ciudadanía global, a través de la apropiación (o no) de tecnologías digitales.', '["Identifica, en casos de actualidad, actores, acciones y tecnologías digitales vinculadas con el ciberactivismo (ONG, influencers, youtubers, entre otros).","Elabora textos argumentativos (ensayo breve, presentación) en los que plantea beneficios (accesibilidad, rapidez, alcance) y desafíos (brecha digital, desinformación, privacidad) de las tecnologías digitales involucradas en situaciones de participación ciudadana (reclamo de derechos, causas solidarias, campañas de opinión pública, entre otros)."]', 'PdA p. 112'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de diferentes concepciones de justicia, y de su vinculación con la igualdad y la solidaridad, presentes en diferentes leyes nacionales, provinciales y/o locales.', 'pda_2025', 1, 'Analizar críticamente los orígenes y sentidos de las normas sociales para la convivencia, indagar sobre los fundamentos éticos y democráticos de las leyes, —comprendiéndolas como construcciones históricas que resultan de negociaciones y consensos entre diferentes actores sociales— y asumir, de manera progresiva, el compromiso de respetarlas y hacerlas respetar.', '["Comprende diferentes perspectivas sobre la justicia (igualitaria, distributiva, restaurativa) y examina su relación con otros valores, como la igualdad de oportunidades y la solidaridad, en casos de actualidad o de su contexto cercano.","Reconoce las nociones de justicia presentes en normativas locales, provinciales y/o nacionales (por ejemplo, leyes antidiscriminación, laborales, de atención a la salud, de discapacidad, entre otras).","Reflexiona acerca de sus propias ideas de justicia y compara cómo se transforman, ante distintos casos y perspectivas."]', 'PdA p. 114'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reflexión y análisis crítico sobre el origen histórico, el sentido y fundamento ético de normas e instituciones sociales, reconociendo su importancia para la convivencia democrática.', 'pda_2025', 1, 'Analizar críticamente los orígenes y sentidos de las normas sociales para la convivencia, indagar sobre los fundamentos éticos y democráticos de las leyes, —comprendiéndolas como construcciones históricas que resultan de negociaciones y consensos entre diferentes actores sociales— y asumir, de manera progresiva, el compromiso de respetarlas y hacerlas respetar.', '["Reconoce las normas sociales como reglas de conductas históricas y cambiantes, producidas en diferentes contextos, que organizan la convivencia entre individuos y grupos.","Comprende los valores y principios compartidos que las normas buscan proteger y promover, contrastando con valores controversiales y no compartidos.","Analiza críticamente la vinculación de ciertas normas con relaciones de poder y sistemas de desigualdades (patriarcales, coloniales, económicos, políticos, entre otros).","Indaga en los cambios y permanencias de las normas escolares a lo largo de la historia, relacionándolos con transformaciones sociales más amplias (como cambios de paradigmas respecto a la niñez y adolescencia)."]', 'PdA p. 114'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión de los grados de responsabilidad personal y social en diversas problemáticas vinculadas con el tránsito, reflexionando sobre los factores que influyen en la seguridad vial.', 'pda_2025', 1, 'Analizar críticamente los orígenes y sentidos de las normas sociales para la convivencia, indagar sobre los fundamentos éticos y democráticos de las leyes, —comprendiéndolas como construcciones históricas que resultan de negociaciones y consensos entre diferentes actores sociales— y asumir, de manera progresiva, el compromiso de respetarlas y hacerlas respetar.', '["Analiza el entorno vial local a partir de diferentes fuentes de información, identificando actores y dinámicas que inciden en la seguridad vial.","Advierte las consecuencias, para sí misma/o, para otras/ os, de las propias prácticas y de las prácticas ajenas en espacios públicos, reflexionando sobre las responsabilidades como peatona/ón, pasajera/o y/o conductora/or.","Reflexiona sobre prácticas viales seguras (uso de cinturón, casco, celular, consumo de sustancias, entre otros)."]', 'PdA p. 115'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Problematización de las diferencias entre lo público/privado/íntimo y reflexión crítica sobre sus transformaciones, en las interacciones en Internet y en entornos digitales.', 'pda_2025', 1, 'Asumir una posición personal argumentada en debates sobre situaciones conflictivas, casos dilemáticos o temáticas controversiales (ambiente, género y sexualidad, tecnologías digitales,trabajo, salud y adicciones, desarrollo sostenible, seguridad, entre otras) vinculadas con las juventudes, identificando actores y grupos sociales involucrados, y reflexionando sobre valores y derechos respetados o vulnerados.', '["Observa y comenta intercambios comunicativos en grupos de pares, redes sociales o medios masivos de comunicación, analizando si son respetuosos o no de la privacidad, la intimidad y la confidencialidad de las personas.","Reconoce situaciones comunicativas en las que lo privado se hace público, y formula preguntas sobre los motivos por los cuales las personas comparten aspectos de su vida cotidiana en Internet y redes sociales.","Expone sus razones, e intercambia posiciones con sus compañeras/os, acerca de las consecuencias positivas y negativas que las prácticas digitales pueden tener para la construcción de identidades y vínculos con otras/os."]', 'PdA p. 117'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis crítico sobre hábitos y prácticas de consumo, a partir de la noción de consumo responsable, reflexionando éticamente sobre los desafíos actuales, y proponiendo acciones que favorezcan un estilo de vida sostenible.', 'pda_2025', 1, 'Asumir una posición personal argumentada en debates sobre situaciones conflictivas, casos dilemáticos o temáticas controversiales (ambiente, género y sexualidad, tecnologías digitales,trabajo, salud y adicciones, desarrollo sostenible, seguridad, entre otras) vinculadas con las juventudes, identificando actores y grupos sociales involucrados, y reflexionando sobre valores y derechos respetados o vulnerados.', '["Identifica hábitos y prácticas de consumo (alimentos, vestimenta, tecnologías, energías, agua, entre otros), propios y ajenos, reflexionando sobre las consecuencias ambientales.","Examina el recorrido de los productos y servicios que consume, debatiendo éticamente sobre las formas de producción y comercialización (justas, igualitarias, solidarias, sostenibles, respetuosas de derechos de NNA, entre otros).","Indaga sobre el grado de compromiso de empresas locales, de productos y servicios, con la sostenibilidad, y elabora recomendaciones a través de tecnologías digitales.","Propone acciones cotidianas acordes con un estilo de vida sostenible, como reducir el consumo, elegir productos con menor impacto ambiental, disminuir la huella de carbono, realizar prácticas de reutilización, reacondicionamiento y reciclaje en su comunidad."]', 'PdA p. 117'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Indagación crítica acerca de la neutralidad de los contenidos que circulan en entornos digitales, así como sobre las fuentes y motores de búsqueda de información en Internet, reflexionando sobre la libertad y los condicionamientos que implican en las prácticas ciudadanas.', 'pda_2025', 1, 'Asumir una posición personal argumentada en debates sobre situaciones conflictivas, casos dilemáticos o temáticas controversiales (ambiente, género y sexualidad, tecnologías digitales,trabajo, salud y adicciones, desarrollo sostenible, seguridad, entre otras) vinculadas con las juventudes, identificando actores y grupos sociales involucrados, y reflexionando sobre valores y derechos respetados o vulnerados.', '["Problematiza la representación de Internet como espacio completamente libre y democrático, reconociendo actores formadoras/es de opinión pública, por ejemplo, influencers, trolls, bots, hackers, entre otros.","Identifica y debate los intereses económicos, políticos y empresariales presentes en motores de búsqueda, aplicaciones de IA, dispositivos y tecnologías digitales.","Expone sus ideas acerca de los condicionamientos a la libertad de expresión, la diversidad de voces y la participación ciudadana digital."]', 'PdA p. 118'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reflexión ética de discursos y prácticas presentes en Internet y entornos digitales, que representan riesgos, vulneran valores y derechos de NNA, a partir del análisis de casos.', 'pda_2025', 1, 'Asumir una posición personal argumentada en debates sobre situaciones conflictivas, casos dilemáticos o temáticas controversiales (ambiente, género y sexualidad, tecnologías digitales,trabajo, salud y adicciones, desarrollo sostenible, seguridad, entre otras) vinculadas con las juventudes, identificando actores y grupos sociales involucrados, y reflexionando sobre valores y derechos respetados o vulnerados.', '["Analiza críticamente la presencia o ausencia de valores (como el respeto de la diversidad, la responsabilidad, la privacidad, entre otros), en intercambios digitales propios y ajenos.","Reconoce, en situaciones cotidianas, experiencias y casos riesgosos, tales como el ciberacoso, bullying digital, sexting, sextorsión, grooming, phishing, malware, la exposición no consentida a contenidos violentos o sexualmente explícitos.","Participa en conversaciones grupales sobre las consecuencias de estas prácticas en el bienestar emocional de las/os estudiantes y la convivencia escolar."]', 'PdA p. 118'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Distinción entre acciones libres y no libres, y su vinculación con el problema de la responsabilidad, a partir del trabajo con dilemas morales vinculados a prácticas sociales cercanas a las/os jóvenes.', 'pda_2025', 1, 'Asumir una posición personal argumentada en debates sobre situaciones conflictivas, casos dilemáticos o temáticas controversiales (ambiente, género y sexualidad, tecnologías digitales,trabajo, salud y adicciones, desarrollo sostenible, seguridad, entre otras) vinculadas con las juventudes, identificando actores y grupos sociales involucrados, y reflexionando sobre valores y derechos respetados o vulnerados.', '["Comprende la noción de libertad y responsabilidad, comparando diferentes grados de condicionamiento en las acciones propias o ajenas.","Debate y argumenta acerca de sus decisiones personales respecto de las situaciones dilemáticas analizadas (por ejemplo, estudiar o trabajar, consumo de sustancias, prácticas en Internet y salud digital, delitos y contravenciones, presiones del grupo y consumos culturales —moda, estéticas, música— entre otros).","Propone alternativas personales y colectivas orientadas a un ejercicio más responsable y autónomo de la libertad."]', 'PdA p. 118'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Respeto y valoración de la diversidad sexual y de proyectos de vida que coexisten en la comunidad escolar y local, a través de prácticas comunicativas y experiencias compartidas.', 'pda_2025', 1, 'Reconocer la diversidad como aquello que enriquece la convivencia en ámbitos escolares, sociales y espacios virtuales, a través de la puesta en valor de experiencias colectivas, normativas e identidades (de género, étnicas, socioculturales, políticas), para revertir representaciones estereotipadas, prejuiciosas y discriminatorias.', '["Desarrolla prácticas comunicativas (entrevistas, encuentros, producciones artísticas) que expresan respeto por la diversidad sexual, en entornos físicos y digitales, y las valora como factor de enriquecimiento de la convivencia democrática.","Reconoce el derecho de las personas a vivir su sexualidad y a desarrollar sus elecciones y proyectos personales, de acuerdo con sus convicciones y preferencias, vigentes en diferentes normativas comprometidas con la equidad de género (por ejemplo, Ley 26.618 de Matrimonio Igualitario, Ley 26.743 de Identidad de Género, Ley 27.234 de Educar en Igualdad).","Reflexiona sobre nuevas formas de femineidad y masculinidad, problematizando estereotipos y prejuicios de género presentes, en sí misma/o y en otras/os."]', 'PdA p. 121'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Lectura crítica de la pluralidad de expresiones culturales, cosmovisiones y sistemas valorativos, generando espacios de encuentro y participación para la difusión y defensa de derechos identitarios.', 'pda_2025', 1, 'Reconocer la diversidad como aquello que enriquece la convivencia en ámbitos escolares, sociales y espacios virtuales, a través de la puesta en valor de experiencias colectivas, normativas e identidades (de género, étnicas, socioculturales, políticas), para revertir representaciones estereotipadas, prejuiciosas y discriminatorias.', '["Asume una posición crítica en relación con los estereotipos y formas de discriminación asociados con diversidades étnico-culturales, lingüísticas y de creencias, a partir de intercambios culturales y de acciones ciudadanas de concientización sobre derechos.","Conoce las luchas sociales e históricas llevadas a cabo por grupos subalternos (pueblos originarios, afrodescendientes, migrantes), por el reconocimiento del derecho a la identidad (reivindicación de la lengua, tradiciones y ceremonias, entre otros) y a derechos políticos, sociales y económicos.","Participa activamente en espacios de acción y reflexión sobre estas experiencias, valorando cómo su comprensión y acciones influyen en la promoción del respeto hacia la diversidad cultural."]', 'PdA p. 121'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis crítico de las nociones de usuaria/o, perfil y huella digital, reflexionando sobre sus vinculaciones con las identidades que se construyen en entornos digitales y sus repercusiones en la convivencia y el respeto por la diversidad.', 'pda_2025', 1, 'Reconocer la diversidad como aquello que enriquece la convivencia en ámbitos escolares, sociales y espacios virtuales, a través de la puesta en valor de experiencias colectivas, normativas e identidades (de género, étnicas, socioculturales, políticas), para revertir representaciones estereotipadas, prejuiciosas y discriminatorias.', '["Comprende las nociones de usuaria/o, perfil y huella digital, como formas de mostrarse e interactuar en espacios digitales.","Construye y/o reconstruye la propia huella digital, a través de ejercicios de navegación con dispositivos móviles y tecnologías digitales, identificando posibles riesgos (usurpación de identidad, robo de información financiera, estafas y fraudes digitales, entre otros).","Reflexiona sobre la imagen personal digital, propia y ajena, asumiendo actitudes de respeto, inclusión y valoración de la diversidad (corporal, sexual, estética, étnica, entre otras) .","Escribe reflexiones personales sobre su experiencia en redes sociales y cómo influye en su percepción de sí misma/o y en las relaciones con las demás personas."]', 'PdA p. 122'),
(9, 'eje_contenido', 'Progresiones de Aprendizaje', 'Conocimiento del sistema político institucional argentino, a través de conceptos como Nación y Estado, forma republicana de gobierno, federalismo, representación democrática y soberanía popular.', 'pda_2025', 1, 'Comprender la configuración del sistema político argentino, provincial y municipal, a partir de los marcos constitucionales que los sustentan —reconociéndolos como contratos sociales e históricos— distinguiendo las competencias básicas de los poderes del Estado y sus principales órganos, reflexionando sobre su importancia para la participación ciudadana y los derechos humanos, en situaciones del presente y de la historia reciente.', '["Comprende las características distintivas del Estado como organización jurídico-política-territorial, diferenciándolas de las que corresponden a la Nación.","Identifica los poderes del Estado (ejecutivo, legislativo y judicial), así como sus vinculaciones y competencias específicas.","Comprende la relación política entre provincias y estado nacional.","Explica la articulación entre los diferentes niveles de gobierno (nacional, provincial, municipal), y ofrece ejemplos de la autonomía de las provincias, a través de algunas de sus competencias.","Reconoce los mecanismos y actores principales en la representación democrática, y la delegación de la soberanía a través del sufragio."]', 'PdA p. 124'),
(9, 'objetivo', 'Objetivo', 'Reconocer los aspectos comunes y diversos en las identidades personales, grupales y comunitarias, desde una perspectiva de valoración de la convivencia multicultural.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'objetivo', 'Objetivo', 'Asumir una posición personal sobre conflictos sociales, dilemas o conflictos de valor real o hipotético, dando razones crecientemente autónomas, creativas y solidarias.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'objetivo', 'Objetivo', 'Conocer y practicar formas democráticas de participación en la vida ciudadana, valorando la práctica del diálogo argumentativo como herramienta para afrontar conflictos en diversos ámbitos y debatir temas relacionados con normas y valores.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'objetivo', 'Objetivo', 'Reflexionar sobre derechos y responsabilidades en la convivencia cotidiana, identificando aquéllos que corresponden a los ciudadanos en Argentina y los Derechos Humanos establecidos transnacionalmente.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'objetivo', 'Objetivo', 'Desarrollar la reflexión crítica y la deliberación argumentativa en torno a temas relevantes de la realidad social: Ambiente, Convivencia, Salud, Alimentación y Adicciones.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'objetivo', 'Objetivo', 'Identificar diferentes formas de ejercicio de la violencia y la discriminación, ejercitando respuestas alternativas, sensibles y creativas a los conflictos interpersonales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'objetivo', 'Objetivo', 'Desarrollar prácticas que contribuyan a analizar patrones de consumo y modos de producción que impactan en la conservación del ambiente.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'objetivo', 'Objetivo', 'Promover y desarrollar conductas saludables en los planos individual y colectivo a partir de la reflexión crítica y el aprendizaje.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'eje_contenido', 'Reflexión ética', 'Análisis ético intersubjetivo de situaciones conflictivas de la vida escolar y conflictos morales presentes en el tratamiento de contenidos de otras áreas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'eje_contenido', 'Reflexión ética', 'Distinción entre las acciones libres y no libres y su vinculación con el problema de la responsabilidad, a través del análisis de casos y dilemas reales e hipotéticos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'eje_contenido', 'Reflexión ética', 'Ejercicio del diálogo argumentativo y su valoración como herramienta para la explicitación de desacuerdos, la construcción de acuerdos, la resolución de conflictos, la apertura a puntos de vista diversos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'eje_contenido', 'Construcción histórica de las identidades', 'Reconocimiento, respeto y valoración de la diversidad de identidades personales y proyectos de vida, individuales y/o colectivos, que coexisten en diferentes contextos sociales, históricos y culturales a partir de entrevistas con adultos, jóvenes y otros actores sociales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'eje_contenido', 'Construcción histórica de las identidades', 'Reconocimiento de la preexistencia de los pueblos originarios americanos y los procesos históricos de mestización e hibridación cultural.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'eje_contenido', 'Construcción histórica de las identidades', 'Conocimiento y reflexión acerca de modelos corporales presentes en los medios de comunicación, en la publicidad, y en las representaciones artísticas identificando estereotipos y su incidencia en la construcción de la propia identidad y de identidades juveniles.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'eje_contenido', 'Derechos y participación', 'Reconocimiento de sí mismo y de los otros como sujetos de derechos capaces de resignificar los derechos vigentes, reconocer los procedimientos para su exigibilidad y participar en su promoción y defensa.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'eje_contenido', 'Derechos y participación', 'Reconocimiento y valoración de la democracia como sistema de vida.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'eje_contenido', 'Derechos y participación', 'Conocimiento de derechos, deberes y garantías constitucionales, en relación con la responsabilidad ciudadana.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'eje_contenido', 'Derechos y participación', 'Comprensión crítica de normas y criterios de tránsito para la circulación autónoma y segura por la vía pública como peatones, usuarios y conductores de medios de transporte.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(9, 'eje_contenido', 'Intervención sociocomunitaria', 'Análisis y valoración de experiencias escolares de intervención sociocomunitarias (aprendizaje-servicio, acción solidaria, etc.).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento del propio cuerpo, sus cambios, continuidades, posibilidades y capacidades diversas, en prácticas corporales y motrices variadas, que posibiliten la construcción de su corporeidad.', 'pda_2025', 1, 'Construir una corporeidad consciente, mediante la aplicación combinada de habilidades y capacidades físicas, en un amplio repertorio de prácticas motrices, para resolver desafíos con autonomía y creatividad, transferir soluciones a diversas situaciones y habilitar la comunicación corporal en el marco de la inclusión y valoración de la diversidad, en todas sus expresiones.', '["Reconoce los cambios y continuidades corporales propios de la adolescencia y su implicancia en la motricidad.","Reorganiza su imagen y esquema corporal, reconociendo sus posibilidades y realiza ajustes en su posición y acción, para resolver tareas motrices individuales y/o grupales.","Identifica la interrelación de las diversas dimensiones del cuerpo (físicas, psicológicas, emocionales, culturales, sociales) y cómo estas influyen en sus prácticas motrices.","Analiza los modelos dominantes del “cuerpo bello”, su impacto diferencial, según el género, y relata experiencias relacionadas a ello.","Reconoce y valora las capacidades de cada persona, promueve la inclusión y la diversidad de cuerpos e identidades, y construye relaciones igualitarias, respetuosas y responsables.","Reconoce y comunica sus emociones, valorando la empatía y el respeto como bases para una convivencia armónica en las diversas prácticas motrices.","Identifica y describe los mitos y tabúes asociados con el ciclo menstrual y reconoce que estos no limitan la participación en las prácticas corporales."]', 'PdA p. 81'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de capacidades condicionales en prácticas corporales y motrices que desafíen y amplíen la disponibilidad motriz.', 'pda_2025', 1, 'Construir una corporeidad consciente, mediante la aplicación combinada de habilidades y capacidades físicas, en un amplio repertorio de prácticas motrices, para resolver desafíos con autonomía y creatividad, transferir soluciones a diversas situaciones y habilitar la comunicación corporal en el marco de la inclusión y valoración de la diversidad, en todas sus expresiones.', '["Identifica y nombra las capacidades condicionales (fuerza, resistencia, velocidad, flexibilidad) presentes en distintas prácticas corporales, y valora su desarrollo para el bienestar de las personas.","Realiza tareas que permiten el desarrollo de distintas capacidades condicionales y las ajusta/adapta según su edad, nivel y posibilidades individuales.","Ajusta su accionar motor (ritmo, intensidad, tiempo de ejecución) según el tipo de tarea o desafío propuesto.","Analiza cómo la práctica de actividades físicas puede mejorar sus capacidades condicionales, y cómo esto amplía sus posibilidades de movimiento.","Utiliza la información de su cuerpo en actividad y en reposo (frecuencia cardíaca, fatiga, recuperación, entre otras) para reconocer la exigencia de una actividad física.","Reflexiona sobre sus propias posibilidades y límites en relación con estas capacidades, y describe progresos o dificultades.","Identifica diferentes tipos de respiración, en situaciones de reposo, esfuerzo y recuperación, estableciendo relaciones con la capacidad condicional trabajada."]', 'PdA p. 82'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Desarrollo de capacidades coordinativas, a partir de la resolución de problemas motores y de la adecuación de los movimientos a sus posibilidades y al contexto.', 'pda_2025', 1, 'Construir una corporeidad consciente, mediante la aplicación combinada de habilidades y capacidades físicas, en un amplio repertorio de prácticas motrices, para resolver desafíos con autonomía y creatividad, transferir soluciones a diversas situaciones y habilitar la comunicación corporal en el marco de la inclusión y valoración de la diversidad, en todas sus expresiones.', '["Reconoce y describe las capacidades coordinativas presentes en sus propios movimientos y en los de las/os demás, y explica cómo estas influyen en la eficacia y adaptabilidad del cuerpo.","Ejecuta acciones motrices que requieren la disociación segmentaria y el control postural estable, en situaciones tanto estáticas como dinámicas.","Ajusta la velocidad y el ritmo de sus movimientos, al sincronizarse con estímulos externos e internos.","Realiza ajustes coordinativos de sus movimientos, al anticipar trayectorias de objetos y desplazamientos de compañeras/os o adversarias/os, en juegos o tareas motrices.","Crea y aplica estrategias motoras que contemplen las necesidades de personas con discapacidad, al reconocer y valorar sus capacidades diferentes.","Analiza sus desempeños en tareas coordinativas y diseña con sus compañeras/os nuevas propuestas de acción."]', 'PdA p. 82'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Práctica y aplicación de habilidades motoras específicas y compuestas, transferibles a diversos contextos, a lo largo de la vida.', 'pda_2025', 1, 'Construir una corporeidad consciente, mediante la aplicación combinada de habilidades y capacidades físicas, en un amplio repertorio de prácticas motrices, para resolver desafíos con autonomía y creatividad, transferir soluciones a diversas situaciones y habilitar la comunicación corporal en el marco de la inclusión y valoración de la diversidad, en todas sus expresiones.', '["Identifica y aplica modos variados de ejecución de habilidades motrices, adecuados a las demandas de juegos y tareas.","Combina habilidades motrices simultáneas y/o sucesivas, para resolver una tarea motriz en situaciones de juego cambiantes.","Domina elementos variados (convencionales, alternativos, autoconstruidos, entre otros),y adapta sus acciones al entorno y a las condiciones cambiantes del juego o actividad.","Selecciona y justifica la habilidad motriz específica que resulta más efectiva para resolver un problema o desafío, presentado en una tarea motriz o situación de juego.","Trabaja colaborativamente con las/os demás, combina habilidades motoras y realiza ajustes, según la situación problemática a resolver.","Identifica y verbaliza las emociones de frustración o enojo que surgen al enfrentar dificultades o errores en la práctica motriz, y aplica estrategias como la pausa, empleándolas para mantener la calma."]', 'PdA p. 83'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación de prácticas corporales frecuentes y seguras, que permitan proyectar un estilo de vida saludable.', 'pda_2025', 1, 'Valorar la importancia de incorporar prácticas corporales sistemáticas y sostenibles como parte de un proyecto de vida saludable, con análisis de hábitos diversos y de los efectos anatómicos, fisiológicos, socio-afectivos propios de estas prácticas.', '["Identifica y describe la importancia de la actividad física, como parte de un proyecto de estilo de vida saludable.","Registra ritmos cardíacos y respiratorios, según los diferentes tipos de prácticas y los procedimientos para su regulación.","Aplica técnicas de respiración diafragmática de manera consciente, para regular su estado fisiológico y emocional, en diferentes momentos de la práctica.","Ajusta su postura corporal y la integra en actividades frecuentes que favorezcan un estilo de vida saludable.","Comprende la importancia de iniciar cada práctica con ejercicios dinámicos, movilidad articular, activación neuromuscular y elementos específicos, como requisito para optimizar la participación y el desempeño en la práctica motriz.","Identifica cómo la práctica regular de actividad física contribuye a mejorar su condición corporal y motriz, y mantener un estilo de vida saludable.","Valora el conocimiento y percepción de su propio cuerpo, como base para el autocuidado y el bienestar integral."]', 'PdA p. 88'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento y comprensión de la función biomecánica del sistema locomotor y su participación en el movimiento, para adoptar prácticas corporales que contribuyan al bienestar y al sostenimiento de una vida activa.', 'pda_2025', 1, 'Valorar la importancia de incorporar prácticas corporales sistemáticas y sostenibles como parte de un proyecto de vida saludable, con análisis de hábitos diversos y de los efectos anatómicos, fisiológicos, socio-afectivos propios de estas prácticas.', '["Identifica y nombra las partes y segmentos corporales y localiza las referencias de orientación espacial (derecha/izquierda, arriba/abajo, adelante/atrás) en su propio cuerpo, tanto en situaciones de reposo como de movimiento simple.","Explica y diferencia la función principal de las articulaciones (movimiento) y los huesos (soporte y protección), en acciones motrices.","Localiza las estructuras óseas en su propio cuerpo, explicando cómo su función de palanca y soporte resulta fundamental para ejecutar y optimizar los movimientos.","Reconoce y explica cómo el ejercicio físico sistemático y regular, junto con los hábitos de una vida activa, contribuyen a la prevención de lesiones y el mantenimiento del bienestar integral.","Ejecuta y modifica intencionalmente acciones motrices simples (por ejemplo, girar, desplazarse, equilibrarse) , al considerar los ejes corporales y la función de los segmentos que intervienen en el movimiento."]', 'PdA p. 88'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Vivencia de prácticas ludomotrices creativas y expresivas a partir de la biografía corporal y motriz: Danzas, Expresión corporal, Expresión artística de movimiento, otros.', 'pda_2025', 1, 'Resolver situaciones problemáticas en prácticas corporales ludomotrices, recreativas, expresivas, y de iniciación deportiva escolar, y consolidando su autonomía en la toma de decisiones, mediante el diseño y aplicación de estrategias y tácticas en el marco del juego limpio, la inclusión y la equidad de género.', '["Diseña secuencias de movimiento (danzas, expresión corporal) con elementos de su biografía motriz (recuerdos, juegos o gestos significativos), expresando autenticidad y creatividad en la expresión.","Aplica principios de la expresión corporal y el movimiento (por ejemplo, espacio, tiempo, fluidez, energía), para comunicar una emoción, una idea o un relato personal.","Reconoce las limitaciones que iponen los estereotipos de género en la posibilidad de desarrollar prácticas expresivas.","Distingue diferentes ritmos, bailes típicos y danzas populares, de la cultura local y de pueblos originarios.","Crea y recrea producciones coreográficas individuales y/o grupales, expresándose mediante diferentes lenguajes comunicativos.","Establece y sostiene acuerdos que permiten el trabajo colaborativo y valora la diversidad y la diferencia como potencialidades."]', 'PdA p. 91'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Valoración de las prácticas recreativas como un derecho humano fundamental y una herramienta esencial para el bienestar integral.', 'pda_2025', 1, 'Resolver situaciones problemáticas en prácticas corporales ludomotrices, recreativas, expresivas, y de iniciación deportiva escolar, y consolidando su autonomía en la toma de decisiones, mediante el diseño y aplicación de estrategias y tácticas en el marco del juego limpio, la inclusión y la equidad de género.', '["Explica y argumenta por qué el juego y la recreación constituyen un derecho para todas las personas, independientemente de su edad, género o capacidad, e identifica cómo este derecho se expresa en su contexto escolar.","Crea y propone prácticas recreativas diversas durante el recreo, en clases o en otros espacios escolares, como estrategias para reconocer emociones, relajarse y favorecer el bienestar personal y grupal.","Transfiere y aplica propuestas de juego y recreación en su vida diaria, para disminuir el estrés, fomentar lazos sociales y contribuir activamente a su propio bienestar físico y emocional.","Diseña y propone actividades recreativas, explicando sus elecciones en función del equilibrio entre el disfrute, el desarrollo corporal y el cuidado de la salud."]', 'PdA p. 91'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Resolución de desafíos motrices propios de la iniciación deportiva de prácticas centradas en la ejecución en entornos estables, como las prácticas atléticas, gimnásticas, acuáticas, entre otras.', 'pda_2025', 1, 'Resolver situaciones problemáticas en prácticas corporales ludomotrices, recreativas, expresivas, y de iniciación deportiva escolar, y consolidando su autonomía en la toma de decisiones, mediante el diseño y aplicación de estrategias y tácticas en el marco del juego limpio, la inclusión y la equidad de género.', '["Conoce y aplica habilidades específicas básicas de carrera, salto y lanzamiento, en diferentes pruebas atléticas adaptadas, con el propósito de mejorar su desempeño individual.","Mide y registra los resultados obtenidos en pruebas atléticas, y utiliza esa información para planificar estrategias de mejora, según sus posibilidades.","Reconoce y ejecuta destrezas básicas de la gimnasia, como giros a un pie, saltos en extensión y agrupados, equilibraciones, roles con variantes, rol atrás, vertical balanza, medialuna, entre otros.","Diseña y practica secuencias de movimientos gimnásticos que combinan equilibrio, giros y apoyos, demostrando control corporal.","Realiza diversas prácticas deportivas en contextos estables que representan desafíos personales o grupales, y propone diferentes formas de resolverlos.","Ejecuta diversas formas de entrada y salida del medio acuático, consolida la flotación estática y dinámica, el desplazamiento coordinado de brazos y piernas en posición ventral y dorsal, e incorpora inmersiones y rolidos (giros), de acuerdo con las posibilidades de implementación de cada institución.","Reconoce técnicas de concentración y relajación (por ejemplo, respiración consciente, visualización) e identifica emociones como la ansiedad o el miedo al error, en desafíos motrices."]', 'PdA p. 92'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento y análisis de los elementos constitutivos de los juegos de iniciación deportiva de situación, que permitan comprender la lógica interna del juego y adaptar las acciones al entorno cambiante.', 'pda_2025', 1, 'Resolver situaciones problemáticas en prácticas corporales ludomotrices, recreativas, expresivas, y de iniciación deportiva escolar, y consolidando su autonomía en la toma de decisiones, mediante el diseño y aplicación de estrategias y tácticas en el marco del juego limpio, la inclusión y la equidad de género.', '["Identifica y analiza los elementos de un juego de iniciación deportiva de situación (objetivo, reglas básicas, roles, espacio, móvil, interacciones motrices), y su función principal en la dinámica del juego.","Diferencia la lógica interna de diferentes tipos de juegos de situación y explica cómo los roles y las interacciones motrices cambian en cada uno.","Analiza situaciones de juego y anticipa las acciones posibles, basándose en la comprensión de los roles y las reglas del juego.","Comprende el sentido de las reglas como acuerdos necesarios para jugar, y construye, junto a otros/as, normas que favorecen la resolución de conflictos mediante el diálogo, la negociación y el consenso.","Propone y explica modificaciones en las reglas, los espacios o los roles de un juego conocido, con el propósito de generar determinados efectos en la dinámica o en las acciones de los participantes."]', 'PdA p. 92'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Selección y ajuste de acciones motrices en juegos motores de situación, para resolver problemas tácticos que surgen ante la incertidumbre del entorno.', 'pda_2025', 1, 'Resolver situaciones problemáticas en prácticas corporales ludomotrices, recreativas, expresivas, y de iniciación deportiva escolar, y consolidando su autonomía en la toma de decisiones, mediante el diseño y aplicación de estrategias y tácticas en el marco del juego limpio, la inclusión y la equidad de género.', '["Aplica y ajusta decisiones tácticas individuales, para anticipar las intenciones de su oponente, y optimizar el rendimiento propio en juegos modificados con lógicas de oposición sin cooperación (tenis 1 vs. 1 o golf)","Reconoce y aplica estrategias individuales para identificar, neutralizar y aprovechar las ventajas y desventajas de su oponente, en prácticas de oposición codificada (lucha y combate), ajustando sus acciones según la dinámica del enfrentamiento y el reglamento.","Diferencia juegos modificados de cooperación y oposición de diferentes lógicas internas. como de blanco y diana, de cancha dividida o muro, de invasión, de campo y bate, y reconoce características distintivas de su estructura y lógica interna.","Reconoce diversos juegos motores acuáticos que le permiten explorar y adaptar sus movimientos a los de sus compañeras/os y el entorno, respetando las normas de seguridad establecidas, según las posibilidades de implementación de cada institución.","Identifica situaciones de ataque y defensa, y aplica movimientos de desmarque, cobertura de espacios, anticipación y ajuste del propio accionar.","Selecciona la acción motriz más pertinente (pasar, driblar, tirar, defender) en función de la información percibida en tiempo real.","Respeta y establece acuerdos colectivos para resolver situaciones tácticas grupales."]', 'PdA p. 93'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Vivencia y puesta en valor de prácticas corporales motrices alternativas y emergentes.', 'pda_2025', 1, 'Resolver situaciones problemáticas en prácticas corporales ludomotrices, recreativas, expresivas, y de iniciación deportiva escolar, y consolidando su autonomía en la toma de decisiones, mediante el diseño y aplicación de estrategias y tácticas en el marco del juego limpio, la inclusión y la equidad de género.', '["Identifica y valora prácticas corporales y motrices poco habituales en su entorno, reconociendo su aporte a la diversidad cultural del cuerpo y el movimiento.","Diseña y practica secuencias creativas de movimientos propias de prácticas circenses, como murga, malabares, entre otras.","Reconoce los elementos constitutivos de diversos deportes alternativos, sin elementos o con material autoconstruido, como ringo sport, peteca, lagory, khokho, entre otros.","Analiza y ejecuta juegos tradicionales y autóctonos de la cultura local, y comprende su relación con las costumbres, los valores y la historia de la comunidad."]', 'PdA p. 93'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación y análisis de los valores del deporte en distintos momentos históricos y contextos culturales, y su vinculación con las formas en que se viven y transmiten, en la escuela y su comunidad.', 'pda_2025', 1, 'Resolver situaciones problemáticas en prácticas corporales ludomotrices, recreativas, expresivas, y de iniciación deportiva escolar, y consolidando su autonomía en la toma de decisiones, mediante el diseño y aplicación de estrategias y tácticas en el marco del juego limpio, la inclusión y la equidad de género.', '["Identifica valores como el respeto, la cooperación y el “juego limpio”, en diferentes juegos y deportes, tanto de la actualidad como de épocas pasadas.","Compara la manifestación de ciertos valores en prácticas corporales históricas (olimpismo antiguo) con su aplicación en el deporte escolar actual.","Reconoce que los valores asociados al deporte varían y evolucionan, según las culturas y los momentos históricos.","Reconoce distintas formas de vivir la competencia en el juego, el deporte y la vida escolar, y valora aquellas que promueven el respeto y la cooperación."]', 'PdA p. 93'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento y aplicación de normas de seguridad, acuerdos de convivencia y principios de cuidado del ambiente, para una interacción respetuosa con las/os otras/os y con el entorno, en prácticas corporales y motrices.', 'pda_2025', 1, 'Adaptar su disponibilidad motriz a diversos ambientes e identificar los desafíos y oportunidades que estos ofrecen, para ejercer conciencia ambiental en el diseño e implementación de prácticas motrices seguras, sostenibles y responsables con el entorno.', '["Reconoce y aplica las normas de seguridad personales y del entorno en las prácticas corporales, e identifica posibles riesgos para sí misma/o y para sus compañeras/os.","Propone y acuerda normas de convivencia para la realización de prácticas motrices seguras en ambientes no habituales, y reconoce su importancia para el disfrute compartido y la inclusión de todos las/os participantes.","Identifica y clasifica los desechos generados y reconoce los lugares adecuados para su disposición y gestión sostenible.","Reconoce las posibles consecuencias ambientales (como erosión del suelo, alteración de la fauna, generación de residuos) derivadas de una práctica motriz específica.","Propone modificaciones sostenibles a las prácticas motrices convencionales (como el uso de materiales reciclados, adaptación al terreno), y explica cómo estas acciones promueven el cuidado del ambiente."]', 'PdA p. 101'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Vivencia de prácticas corporales vinculadas con la vida en la naturaleza y el conocimiento y aplicación de habilidades específicas, como la orientación y las construcciones rústicas, en un marco de reflexión crítica sobre la interacción con el ambiente.', 'pda_2025', 1, 'Adaptar su disponibilidad motriz a diversos ambientes e identificar los desafíos y oportunidades que estos ofrecen, para ejercer conciencia ambiental en el diseño e implementación de prácticas motrices seguras, sostenibles y responsables con el entorno.', '["Identifica riesgos y problemáticas ambientales a partir de la participación en salidas, de corta duración, a diferentes lugares.","Utiliza los puntos cardinales, y la referencia de la salida y puesta del sol, para orientarse y ubicarse eficazmente en diferentes espacios.","Diseña y realiza construcciones rústicas funcionales con elementos del ambiente, en pequeños grupos y con cuidado del entorno.","Analiza críticamente la interacción entre la práctica corporal y el ambiente natural, y explica las responsabilidades éticas y las acciones sostenibles necesarias para reducir el impacto ambiental."]', 'PdA p. 101'),
(10, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación de situaciones de emergencia en diversos ambientes y aplicación de procedimientos que favorezcan la respuesta rápida, el autocuidado y la seguridad colectiva en la práctica motriz.', 'pda_2025', 1, 'Adaptar su disponibilidad motriz a diversos ambientes e identificar los desafíos y oportunidades que estos ofrecen, para ejercer conciencia ambiental en el diseño e implementación de prácticas motrices seguras, sostenibles y responsables con el entorno.', '["Conoce el protocolo de actuación convenido institucionalmente ante situaciones de emergencias.","Identifica y clasifica las situaciones de emergencia más comunes en distintos ambientes (como lesiones musculares, insolación o desorientación) y aplica el protocolo básico de actuación correspondiente.","Aplica procedimientos de autocuidado y prevención, para minimizar el riesgo de accidentes y lesiones, reconociendo la relación entre prevención y seguridad personal.","Ejecuta el protocolo de respuesta rápida ante una situación de emergencia simulada, actúa con seguridad para activar el sistema de ayuda (pedir auxilio, contactar a un adulto responsable) y brindar apoyo a una/un compañera/o."]', 'PdA p. 102'),
(10, 'objetivo', 'Objetivo', 'Explorar y comprender el cuerpo sexuado y el movimiento propio en la unidad y diversidad de sus múltiples dimensiones.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'objetivo', 'Objetivo', 'Aceptar las posibilidades de acción, comunicación y expresión y los límites posibles en la manifestación singular de la producción corporal y motriz.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'objetivo', 'Objetivo', 'Adquirir las herramientas y procedimientos necesarios para la construcción autónoma y responsable de su proyecto de vida saludable, apropiándose del conocimiento, práctica y disfrute de actividades físicas lúdicas, deportivas y expresivas, tomando conciencia de las acciones que favorecen y perjudican el cuidado de la salud.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'objetivo', 'Objetivo', 'Aprender a jugar y competir en distintos ámbitos, en el marco de los diversos tipos de juegos, apropiándose progresivamente de su lógica, organización y sentido, construyendo e internalizando normas y reglas de trabajo en equipo, a partir del acuerdo colectivo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'objetivo', 'Objetivo', 'Reconocer en la práctica lúdica y deportiva el valor del juego cooperativo, el esfuerzo compartido y la resolución colectiva de problemas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'objetivo', 'Objetivo', 'Adoptar medidas necesarias para la propia seguridad y la de los demás en la práctica de actividades de la vida en la naturaleza.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'objetivo', 'Objetivo', 'Reflexionar críticamente sobre el ambiente y sus problemáticas favoreciendo el uso responsable para un desarrollo sustentable.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'objetivo', 'Objetivo', 'Valorar la experiencia estética de moverse, manifestando el lenguaje y el movimiento corporal expresivo en comunicación con otros y de modo creativo, despojándose de prejuicios culturales y sociales de género.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices referidas a la disponibilidad de sí mismo', 'Reconocimiento de los accidentes más frecuentes como producto de la participación en prácticas corporales y motrices y los procedimientos adecuados para la aplicación de los primeros auxilios.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices referidas a la disponibilidad de sí mismo', 'Exploración y valoración de prácticas corporales y motrices que promueven el desarrollo de capacidades condicionales e intermedias.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices referidas a la disponibilidad de sí mismo', 'Conocimiento y reflexión acerca de las prácticas corporales y motrices realizadas y análisis crítico del mensaje hegemónico que los medios de comunicación divulgan al respecto.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices en interacción con otros', 'Iniciación al deporte escolar.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices en interacción con otros', 'Exploración lúdica y establecimiento de acuerdos colectivos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices en interacción con otros', 'Conocimiento y experimentación de juegos de lógica cooperativa.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices en el ambiente', 'Acuerdo y aceptación de normas de interacción, higiene y seguridad para promover el disfrute de todos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices en interacción con otros', 'Fortalecimiento de aptitudes para el juego y la práctica deportiva, recuperando actitudes lúdicas en la interacción con otros.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(10, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices en el ambiente', 'Participación en actividades ludomotrices, individuales y grupales, para el desempeño eficaz, placentero y equilibrado en el ambiente.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(11, 'eje_contenido', 'Progresiones de Aprendizaje', 'Puesta en juego del registro formal en diferentes géneros textuales implicados en la gestión de actividades intra y extracurriculares.', 'pda_2025', 1, 'Poner en juego convenciones genéricas y estrategias de cortesía en intercambios orales sobre problemáticas cotidianas.', '["Escucha y expresa sugerencias en la toma de decisiones relativas a la organización de actividades intra o extraescolares.","Analiza recursos propios del registro formal, como estrategias de persuasión para lograr el propósito, en solicitudes y petitorios en diversos soportes.","Elige, entre las variedades lingüísticas que se hablan en el aula, las opciones correspondientes al registro formal: fórmulas de apertura y despedida, elección del vocabulario adecuado al registro y la segunda persona en pronombres y verbos.","Incrementa el repertorio de recursos del registro formal, a partir de la escucha y de la lectura de textos pertenecientes a diferentes géneros, como petitorios, aperturas de eventos, cartas de solicitud, correos electrónicos."]', 'PdA p. 83'),
(11, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reflexión sobre recursos verbales de cortesía propios del registro formal oral.', 'pda_2025', 1, 'Poner en juego convenciones genéricas y estrategias de cortesía en intercambios orales sobre problemáticas cotidianas.', '["Reconoce, en enunciados ajenos, el uso del registro formal como una estrategia de cortesía condicionada por la situación y la relación entre las/os interlocutoras/es.","Distingue el registro formal en la oralidad y en la escritura respecto de las opciones para referir a la/al destinataria/o, y el uso de fórmulas de apertura y de cierre, petición y agradecimiento."]', 'PdA p. 83'),
(11, 'eje_contenido', 'Progresiones de Aprendizaje', 'Fundamentación de interpretaciones a partir de la relación de conocimientos sobre subgéneros, organizados a partir del eje de lo real (por ejemplo, ciencia ficción, realista, fantástico, entre otros), con características inherentes a la voz narrativa y a la espacialidad.', 'pda_2025', 1, 'Leer obras literarias de diversos subgéneros, seleccionados a partir del eje de lo real, y poner en juego conocimientos sobre procedimientos literarios, en la definición de preferencias y el establecimiento de relaciones con otros lenguajes artísticos.', '["Usa las categorías de voz narrativa y espacialidad en la fundamentación de sus hipótesis de sentido.","Explicita la relación entre la voz narrativa y la construcción de efectos de sentido.","Ejemplifica la relación entre categorías ligadas a la espacialidad con la construcción de sentidos en subgéneros narrativos (como la distopía del espacio en relatos de ciencia ficción de corte catastrófico o los escenarios urbanos y sórdidos en el policial negro).","Analiza la descripción de escenas en obras de teatro y relaciona el aporte de la espacialidad en la construcción de sentido."]', 'PdA p. 86'),
(11, 'eje_contenido', 'Progresiones de Aprendizaje', 'Exploración de recursos retóricos en textos poéticos para dar cuenta de sus posibilidades estéticas y efectos de sentido.', 'pda_2025', 1, 'Leer obras literarias de diversos subgéneros, seleccionados a partir del eje de lo real, y poner en juego conocimientos sobre procedimientos literarios, en la definición de preferencias y el establecimiento de relaciones con otros lenguajes artísticos.', '["Reconoce el uso de recursos centrados en el plano léxico y sintáctico (metáfora, metonimia, oxímoron, quiasmo, hipérbaton, hipérbole, repetición de palabras, paralelismo, entre otros) en textos poéticos seleccionados por la/el docente.","Comparte sus impresiones y valoraciones sobre los efectos estéticos de la palabra poética en el marco de conversaciones literarias.","Sistematiza conocimientos sobre los recursos identificados en la poesía para comparar su uso en otros géneros, particularmente, en la publicidad.","Gestiona itinerarios de lectura centrados en sus preferencias poéticas."]', 'PdA p. 86'),
(11, 'eje_contenido', 'Progresiones de Aprendizaje', 'Establecimiento de relaciones intertextuales a partir de la construcción de la espacialidad entre textos leídos y obras de imagen fija (fotografía, ilustración, pintura, entre otras).', 'pda_2025', 1, 'Leer obras literarias de diversos subgéneros, seleccionados a partir del eje de lo real, y poner en juego conocimientos sobre procedimientos literarios, en la definición de preferencias y el establecimiento de relaciones con otros lenguajes artísticos.', '["Compara obras literarias y artísticas de imagen fija que apelan a un mismo recurso retórico, en función de las características de cada lenguaje.","Identifica similitudes entre las posibilidades enunciativas de la imagen fija y de la palabra, como la convergencia entre la pantalla en abismo y el relato enmarcado.","Explora las posibilidades de descripción de la espacialidad a través de la palabra y, en la imagen fija, de categorías como plano, ángulo, inclinación, cromatismo."]', 'PdA p. 87'),
(11, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de recursos paraverbales en la lectura expresiva de textos narrativos literarios.', 'pda_2025', 1, 'Leer con expresividad en situaciones de lectura para otras/os, con empleo de recursos no verbales. 1.er año', '["Identifica, durante la oralización de un texto y a través de la toma de notas, cambios en distintos aspectos paraverbales respecto del contenido (entonación en actos de habla —como consejo, ruego, invitación, orden—, mayor velocidad de lectura en la sucesión de eventos y disminución en descripciones, pausas marcadas por signos de puntuación) en el discurso referido, directo e indirecto.","Comparte notas de los recursos relevados."]', 'PdA p. 90'),
(11, 'eje_contenido', 'Progresiones de Aprendizaje', 'Incorporación de recursos paraverbales en la lectura en voz alta de textos narrativos breves, en escenarios presenciales.', 'pda_2025', 1, 'Leer con expresividad en situaciones de lectura para otras/os, con empleo de recursos no verbales. 1.er año', '["Colabora con sugerencias para la mejora de dificultades de la lectura en voz alta de sus compañeras/os.","Monitorea, en situaciones de autoevauación, la expresividad de su propia lectura."]', 'PdA p. 90'),
(11, 'eje_contenido', 'Progresiones de Aprendizaje', 'Exploración de las posibilidades lúdicas y estéticas del plano léxico del lenguaje en la escritura de invención.', 'pda_2025', 1, 'Producir textos ficcionales que pongan en juego rasgos textuales acordes al género y rasgos lingüísticos, y que desplieguen la potencialidad expresiva y estética del lenguaje.', '["Lee textos que juegan con el plano léxico del lenguaje e identifica en qué consiste la condición lúdica de homonimia, polisemia, repetición de palabras, sucesión de sinónimos, oxímoron, entre otros.","Reconoce la restricción que plantea la consigna en el plano léxico y colabora con ejemplos.","Ensaya posibilidades léxicas en la escritura colectiva y grupal de textos."]', 'PdA p. 94'),
(11, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reformulación de elementos de la trama y de voces narrativas en la escritura de relatos.', 'pda_2025', 1, 'Producir textos ficcionales que pongan en juego rasgos textuales acordes al género y rasgos lingüísticos, y que desplieguen la potencialidad expresiva y estética del lenguaje.', '["Resuelve problemas de reflexión y reformulación (ampliación, sustitución, recolocación y supresión) de elementos de la trama, como núcleos narrativos por acciones secundarias vinculadas con pretéritos del modo indicativo y su ortografía; por diálogos que emplean verbos y modificadores verbales, expresando variados modos del decir; de sustantivos/construcciones sustantivas, evidenciando cómo se nombran los personajes entre sí y qué relación tienen.","Resuelve problemas de reflexión y reformulación (ampliación, sustitución, recolocación y supresión) de elementos de la voz narrativa, en función del sistema de pronombres personales.","Recrea formulaciones propias, desarrolladas por otras/ os, o por aplicaciones de inteligencia artificial, para explorar otros modos de expresarlas y afianzar estrategias de reformulación.","Resuelve problemas orientados a reflexionar sobre el uso de la elipsis de verbo y de determinantes posesivos, los cambios de los tiempos verbales en los diálogos, casos especiales de tildación (como porque/por qué/porqué).","Emplea los recursos relevados en la reformulación de la voz narrativa de un texto dado o en la producción de nuevas versiones que alteren algún elemento de la trama."]', 'PdA p. 94'),
(11, 'eje_contenido', 'Progresiones de Aprendizaje', 'Descripción de lugares con empleo de diversos recursos lingüísticos vinculados con la espacialidad.', 'pda_2025', 1, 'Producir textos ficcionales que pongan en juego rasgos textuales acordes al género y rasgos lingüísticos, y que desplieguen la potencialidad expresiva y estética del lenguaje.', '["Analiza qué aspectos se elige describir, desde qué ángulo del espacio, a través de qué recursos se los caracteriza, y cuál es el orden en que se organiza esa descripción, en relación con el propósito del texto.","Explora y compara alternativas para nombrar segmentos del espacio, variedad de clases de palabras y de construcciones para caracterizarlas, adverbios y construcciones preposicionales para indicar relaciones espaciales.","Resuelve problemas orientados a reflexionar sobre casos especiales de concordancia entre sustantivo y adjetivo, el uso de punto y coma en las enumeraciones en los casos de elipsis verbal, la ortografía del nuevo vocabulario.","Recrea las alternativas analizadas para explorar otros modos de describir lugares y afianzar estrategias de reformulación.","Sistematiza los recursos lingüísticos analizados en presentaciones a través de organizadores gráficos o breves textos expositivos, y los emplea en la producción de descripciones de lugares."]', 'PdA p. 95'),
(11, 'eje_contenido', 'Progresiones de Aprendizaje', 'Apropiación de la información que transmiten los textos expositivos, con el propósito de comunicar oralmente, o por escrito, conocimientos sobre un tema.', 'pda_2025', 1, 'Producir exposiciones orales y escritas con diversos propósitos, que pongan en juego recursos lingüísticos y textuales adecuados al género.', '["Participa de la lectura de textos expositivos de diferentes géneros referidos a temas de la lengua y la literatura, por ejemplo, la relevancia de la ortografía, la relación entre creación y posibilidades tecnológicas, neologismos con el prefijo bio-, el empleo de seudónimos en la literatura, entre otros temas.","Implementa estrategias de relectura y de reformulación, para revisar interpretaciones y ajustarlas al propósito de lectura.","Resuelve problemas orientados a reflexionar sobre el uso de la tercera persona y expresiones propias del registro formal académico (en función de, respecto de, no obstante, entre otros) para seguir ajustando interpretaciones.","Selecciona la información relevante según el propósito y la resume.","Participa en la reflexión colectiva sobre el papel de la escritura para el estudio."]', 'PdA p. 98'),
(11, 'eje_contenido', 'Progresiones de Aprendizaje', 'Escritura de respuestas a consignas de evaluación que impliquen el desarrollo de un tema.', 'pda_2025', 1, 'Producir exposiciones orales y escritas con diversos propósitos, que pongan en juego recursos lingüísticos y textuales adecuados al género.', '["Diferencia consignas de evaluación de respuesta cerrada, con las que implican el desarrollo de un tema.","Identifica, en las consignas de desarrollo, el tema a tratar, el verbo que orienta sobre cómo abordar el tema y el material implicado.","Explora estrategias para planificar un desarrollo ordenado del tema, mediante la construcción de listado de palabras o ideas clave, esquema, entre otros.","Selecciona, del universo de opciones disponibles (buscadores web, aplicaciones de inteligencia artificial, entre otras), el gráfico adecuado en función de la acción requerida por la consigna.","Participa en la redacción grupal de la respuesta y en su revisión, teniendo en cuenta el ajuste a la consigna y los aspectos formales estudiados, la organización de la información, el registro formal propio de los textos expositivos, el uso de conectores y ordenadores textuales, la puntuación y la ortografía."]', 'PdA p. 99'),
(11, 'objetivo', 'Objetivo', 'Apropiarse de prácticas de lenguaje diversas que le permitan una participación cada vez más plena en el contexto, tanto escolar como extraescolar.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'objetivo', 'Objetivo', 'Apropiarse de las formas de expresión que caracterizan los diferentes tipos de textos e intercambios formales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'objetivo', 'Objetivo', 'Ampliar y fortalecer su capacidad de expresar y compartir emociones, ideas, conocimientos y opiniones por medio de la lengua oral y escrita.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'objetivo', 'Objetivo', 'Utilizar el lenguaje de manera cada vez más libre, personal y autónoma para reconstruir y comunicar la experiencia propia y crear mundos de ficción.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'objetivo', 'Objetivo', 'Desarrollar su capacidad para interactuar, narrar, exponer y debatir utilizando cada vez con mayor fluidez y adecuación la lengua oral.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'objetivo', 'Objetivo', 'Fortalecer y ampliar habilidades estratégicas para leer diversidad de textos, con diferentes propósitos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'objetivo', 'Objetivo', 'Fortalecer su interés por saber más acerca de la lengua y de la literatura para conocer y comprender mejor el mundo y a sí mismos e imaginar mundos posibles.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'objetivo', 'Objetivo', 'Apropiarse reflexivamente de los aspectos normativos, gramaticales y textuales inherentes a las demandas de la acción e interacción lingüística.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'eje_contenido', 'Comprensión y producción oral', 'Desempeño participativo en situaciones de intercambio dialógico: conversaciones y discusiones sobre temas propios del área, del mundo de la cultura y de la ciudadanía.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'eje_contenido', 'Comprensión y producción oral', 'Selección, confrontación y registro de información y opiniones provenientes de diversas fuentes como soporte de la conversación y la discusión.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'eje_contenido', 'Comprensión y producción oral', 'Incorporación de recursos específicos (definiciones, ejemplos, comparaciones, analogías, reformulaciones) en las exposiciones orales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'eje_contenido', 'Lectura y producción escrita', 'Profundización de saberes específicos en relación con géneros discursivos propios del ámbito personal (cartas, mensajes en soporte papel y electrónico, notas personales, anécdotas, autobiografías) y social (crónicas de viajes, noticias, cartas de lectores, géneros publicitarios).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'eje_contenido', 'Lectura y producción escrita', 'Producción de textos narrativos (relatos de experiencias y viajes, anécdotas, autobiografías, biografías, noticias, reseñas históricas) atendiendo a la elección de la voz narrativa, la caracterización de personas y personajes, épocas y ambientes, la organización (episodios y sucesos, marco espacio temporal; secuencia lógica y cronológica lineal y no lineal).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'eje_contenido', 'Literatura', 'Escucha, lectura e interpretación de cuentos y novelas (realistas, maravillosos, de misterio, policiales).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'eje_contenido', 'Literatura', 'Escucha, lectura e interpretación de poesía de tradición oral (coplas, romances) y de autores regionales, nacionales y universales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'eje_contenido', 'Reflexión sobre el lenguaje, la lengua (sistema, norma y uso) y los textos', 'Contrastación de usos lingüísticos (orales y escritos) propios de distintos registros y dialectos (geográficos y sociales).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(11, 'eje_contenido', 'Reflexión sobre el lenguaje, la lengua (sistema, norma y uso) y los textos', 'Conocimiento de la ortografía correspondiente al vocabulario cotidiano y escolar.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Producción de fórmulas para representar regularidades con números naturales, incluidas las representadas geométricamente.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Interpreta fórmulas para la escritura de los primeros términos de regularidades numéricas.","Compara y explica fórmulas elaboradas por ella/él misma/o, y por otras/os, que permiten calcular el término n de regularidades numéricas.","Justifica la equivalencia entre fórmulas que representan una misma regularidad numérica, acudiendo a las propiedades de las operaciones."]', 'PdA p. 54'),
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de números enteros en situaciones de interpretación, comparación y de suma y resta.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Reconoce que los números enteros expresan la relación de una cantidad con respecto a una referencia que se toma como cero, en situaciones extramatemáticas.","Reconoce y explica características de dos números enteros opuestos.","Explica semejanzas y diferencias entre los criterios de comparación de números naturales y los elaborados para números enteros.","Ordena números enteros recurriendo a su representación en la recta numérica cuando sea necesario. Elabora, compara y explica diferentes procedimientos de cálculo, propios y de otras/os, para la suma y la resta con números enteros."]', 'PdA p. 54');
INSERT INTO `curriculum_contenidos` (`espacio_id`, `tipo`, `titulo`, `descripcion`, `fuente`, `vigente`, `meta`, `indicadores`, `pagina`) VALUES
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de la multiplicación y la división entera con números enteros.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Justifica el signo del producto de un entero positivo por otro negativo, a partir del significado de la multiplicación como suma reiterada.","Justifica el signo del producto dos enteros negativos, a partir del concepto de opuesto y del producto de enteros de distinto signo.","Elabora y justifica la regla de los signos de la división entera a partir de la relación entre dividendo, divisor y cociente.","Anticipa productos y cocientes de números enteros a partir de la comparación e interpretación de los números involucrados."]', 'PdA p. 55'),
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis y escritura algebraica de las propiedades de la suma y la multiplicación con números enteros.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Justifica la validez de las propiedades asociativa, conmutativa de la suma y la multiplicación, la distributiva de la multiplicación con respecto a la suma y resta, con números enteros, a partir de las elaboradas con números naturales","Elabora y explica, a partir de ejemplos, la propiedad del elemento neutro para la suma y la multiplicación, y del elemento absorbente para la multiplicación.","Comunica mediante expresiones algebraicas las propiedades de la suma y la multiplicación con números enteros."]', 'PdA p. 55'),
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de la potenciación de números enteros con exponente natural.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Justifica el signo de la potencia, a partir del significado de potenciación y el signo del producto de enteros.","Emplea potencias de números enteros con exponente natural en situaciones intramatemáticas."]', 'PdA p. 55'),
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de números racionales (positivos, negativos y cero) en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Reconoce el número racional como cociente entre números enteros.","Reconoce y explica características de las expresiones fraccionarias que se corresponden con expresiones decimales finitas.","Reconoce y explica características de las expresiones fraccionarias que se corresponden con expresiones decimales infinitas periódicas.","Selecciona y justifica la forma de representar los números racionales (expresión fraccionaria, decimal finita, decimal periódica, porcentaje y punto de la recta numérica), en función del contexto de uso y al ordenarlos.","Compara y explica las propiedades del conjunto de los números racionales, con las del conjunto de los números enteros."]', 'PdA p. 55'),
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de la suma, la resta, la multiplicación y la división con números racionales (positivos, negativos y cero) en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Fundamenta la validez de las propiedades de la suma y la multiplicación con números racionales, a partir de las elaboradas con números enteros.","Reconoce y explica las ventajas y desventajas de las distintas representaciones de los números racionales, para operar de acuerdo con los números involucrados.","Lee una situación, selecciona la información relevante y busca, en distintas fuentes, la información que falta para resolverla.","Selecciona y justifica la operación (suma, resta, multiplicación, división) que permite resolver las situaciones leídas, incluidas las de interés y descuento porcentual.","Selecciona un tipo de cálculo —no algorítmico o algorítmico— que resulta más adecuado según los números racionales involucrados y el contexto de uso, al sumar, restar, multiplicar y dividir, y justifica la elección realizada.","Anticipa el resultado de un cálculo evaluando su razonabilidad de acuerdo a los números racionales involucrados y al contexto de uso."]', 'PdA p. 56'),
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de relaciones de proporcionalidad directa e inversa, presentadas en textos, tablas, gráficos y fórmulas, en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Modelizar situaciones vinculadas a las relaciones de proporcionalidad directa e inversa y variaciones lineales.', '["Lee una situación (en textos, tablas y gráficos), selecciona la información relevante y/o busca, en distintas fuentes, la información que falta para resolver la situación.","Reconoce y explica variables independientes y dependientes, en relaciones de proporcionalidad directa e inversa, presentadas en textos, tablas y gráficos.","Interpreta y justifica fórmulas de relaciones de proporcionalidad directa e inversa.","Explica la relación entre las distintas representaciones (tablas, gráficos y fórmulas) de una relación de proporcionalidad directa o inversa.","Produce y justifica la validez de fórmulas que representan relaciones de proporcionalidad directa o inversa, presentadas en textos, tablas y gráficos."]', 'PdA p. 59'),
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de ecuaciones lineales con una incógnita del tipo ax + b = c x + d, en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Modelizar situaciones vinculadas a las relaciones de proporcionalidad directa e inversa y variaciones lineales.', '["Justifica la selección de las propiedades de las operaciones (uniforme, distributiva de la multiplicación con respecto a la suma y la resta) empleadas para transformar expresiones algebraicas del tipo mx + nx en otras equivalentes.","Fundamenta la validez de expresiones algebraicas equivalentes a través de las propiedades de las operaciones.","Explica las propiedades de las operaciones utilizadas al transformar ecuaciones lineales del tipo ax + b = cx + d en otras equivalentes para hallar el valor de x.","Justifica la validez de la solución de una ecuación al sustituir la incógnita por un número que verifica la igualdad."]', 'PdA p. 59'),
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de relaciones multiplicativas y aditivas —sin la utilización de fórmulas— en situaciones de permutación, variación y combinación.', 'pda_2025', 1, 'Cuantificar la incertidumbre recurriendo a las nociones de probabilidad clásica y comunicar información estadística.', '["Selecciona y compara con otros/as la estrategia más adecuada para determinar el número total de casos a partir de la situación leída.","Justifica la elección de cálculos multiplicativos y aditivos (sin utilización de fórmulas) para determinar el número total de casos."]', 'PdA p. 62'),
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Cuantificación de la probabilidad clásica de eventos aleatorios para espacios muestrales finitos.', 'pda_2025', 1, 'Cuantificar la incertidumbre recurriendo a las nociones de probabilidad clásica y comunicar información estadística.', '["Lee una situación extramatemática y determina el espacio muestral de un experimento aleatorio, recurriendo a estrategias de conteo de casos (sin el uso de fórmulas) cuando sea necesario.","Reconoce y explica eventos aleatorios, como subconjuntos del espacio muestral.","Interpreta la fracción que expresa la probabilidad clásica de un evento aleatorio.","Diferencia la probabilidad clásica de un evento aleatorio de su estimación a partir de la probabilidad frecuencial (frecuencia relativa en un experimento)."]', 'PdA p. 62'),
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Representación de datos recolectados de variables cualitativas (nominales y ordinales) y cuantitativas discretas en tablas de distribución de frecuencias y gráficos de barras, circulares y bastones.', 'pda_2025', 1, 'Cuantificar la incertidumbre recurriendo a las nociones de probabilidad clásica y comunicar información estadística.', '["Lee una situación extramatemática y diferencia variables cualitativas nominales de las ordinales.","Organiza datos en tablas de distribución de frecuencias absoluta, relativa y acumulada para variables cualitativas ordinales y cuantitativas discretas, apelando al uso de software cuando sea posible.","Justifica la elección del gráfico estadístico más apropiado para representar las variables que contienen los datos.","Elabora textos que integran la información estadística presentada en tablas de distribución de frecuencia, gráficos y medidas estadísticas (moda y mediana)."]', 'PdA p. 62'),
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Formulación de argumentaciones sobre propiedades de ángulos y diagonales de polígonos convexos de más de cuatro lados, en situaciones de construcción y comunicación.', 'pda_2025', 1, 'Usar propiedades de polígonos convexos, criterios de congruencia y semejanza de triángulos, en situaciones de construcción de figuras geométricas y cálculo de áreas y volúmenes.', '["Elabora y justifica propiedades de ángulos y diagonales de polígonos convexos de más de cuatro lados, a partir de propiedades de lados y ángulos de triángulos y cuadriláteros, con empleo de software cuando sea necesario.","Explica la construcción de polígonos convexos regulares e irregulares a partir de sus ángulos y diagonales, y la justifica desde la propiedades."]', 'PdA p. 66'),
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Formulación de argumentaciones sobre las condiciones de congruencia de triángulos, en situaciones de construcción y comunicación.', 'pda_2025', 1, 'Usar propiedades de polígonos convexos, criterios de congruencia y semejanza de triángulos, en situaciones de construcción de figuras geométricas y cálculo de áreas y volúmenes.', '["Reconoce la información mínima necesaria sobre lados y ángulos de un triángulo para que su construcción sea única.","Explicita los criterios de congruencia de triángulos.","Justifica la congruencia de triángulos a partir de propiedades de lados y ángulos, y criterios de congruencia."]', 'PdA p. 66'),
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de fórmulas para el cálculo de áreas de polígonos convexos de más de cuatro lados y sectores circulares, en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Usar propiedades de polígonos convexos, criterios de congruencia y semejanza de triángulos, en situaciones de construcción de figuras geométricas y cálculo de áreas y volúmenes.', '["Elabora, explica y compara fórmulas propias y de otras/ os, que permiten calcular el área de polígonos regulares.","Selecciona las fórmulas de acuerdo con la información disponible en la situación leída, para el cálculo del área de polígonos convexos irregulares, y justifica su elección.","Deduce y justifica la fórmula de área del sector circular."]', 'PdA p. 67'),
(12, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de fórmulas para el cálculo de volúmenes de prismas, pirámides y cuerpos redondos, en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Usar propiedades de polígonos convexos, criterios de congruencia y semejanza de triángulos, en situaciones de construcción de figuras geométricas y cálculo de áreas y volúmenes.', '["Elabora, explica y compara fórmulas propias y de otras/ os, que permiten calcular el volumen de pirámides y conos, a partir de la relación con el volumen de prismas y cilindros, respectivamente.","Emplea la fórmula de volumen de una esfera.","Selecciona las fórmulas de acuerdo con la información disponible en la situación leída, para el cálculo del volumen de cuerpos compuestos por prismas, pirámides y/o cuerpos redondos, y justifica la elección realizada."]', 'PdA p. 67'),
(12, 'objetivo', 'Objetivo', 'Utilizar números racionales, sus propiedades y sus representaciones de acuerdo a la necesidad que impone el problema.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'objetivo', 'Objetivo', 'Usar números enteros y racionales para resolver problemas extramatemáticos e intramatemáticos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'objetivo', 'Objetivo', 'Usar y explicitar las operaciones en los distintos campos numéricos (N, Z, Q) en la resolución de problemas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'objetivo', 'Objetivo', 'Emplear y explicitar las propiedades de las operaciones en los distintos campos numéricos (N, Z, Q) en la resolución de problemas de cálculo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'objetivo', 'Objetivo', 'Recurrir al uso del lenguaje algebraico para generalizar propiedades aritméticas y geométricas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'objetivo', 'Objetivo', 'Producir y analizar construcciones geométricas - utilizando cuando sea posible software geométrico- acudiendo a argumentos deductivos, según ciertas condiciones y propiedades puestas en juego, reconociendo el límite de las pruebas empíricas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'objetivo', 'Objetivo', 'Usar expresiones algebraicas y analizar su equivalencia para resolver problemas extramatemáticos e intramatemáticos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'objetivo', 'Objetivo', 'Organizar e interpretar datos estadísticos mediante tablas (de frecuencia, por intervalos) y gráficos, eligiendo la forma más adecuada.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'eje_contenido', 'Número y operaciones', 'Interpretación, registro, comunicación y comparación de números enteros.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'eje_contenido', 'Número y operaciones', 'Uso de diferentes representaciones de un número racional (expresiones fraccionarias decimales, notación científica, punto de la recta, etc.), eligiendo la representación más adecuada de acuerdo al problema.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'eje_contenido', 'Número y operaciones', 'Explicitación y análisis de las operaciones en Z y sus propiedades como extensión de las elaboradas en N.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'eje_contenido', 'Álgebra y funciones', 'Explicitación y análisis de propiedades de funciones de proporcionalidad directa (variación uniforme, origen al cero).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'eje_contenido', 'Álgebra y funciones', 'Interpretación de relaciones entre variables en tablas, gráficos y fórmulas para resolver problemas en diversos contextos, tales como regularidades numéricas, proporcionalidad directa e inversa.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'eje_contenido', 'Álgebra y funciones', 'Obtención de expresiones algebraicas equivalentes acudiendo a propiedades para resolver ecuaciones de primer grado.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'eje_contenido', 'Álgebra y funciones', 'Elaboración y análisis de expresiones simbólicas para expresar y validar afirmaciones sobre propiedades de operaciones o criterios de divisibilidad.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'eje_contenido', 'Geometría y medida', 'Elaboración de argumentaciones acerca de la validez de las propiedades de las figuras bidimensionales (triángulos, cuadriláteros y círculos) para analizar afirmaciones, reconociendo los límites de las pruebas empíricas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'eje_contenido', 'Estadística y probabilidad', 'Identificación de variables cuantitativas (discretas y continuas) y cualitativas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'eje_contenido', 'Estadística y probabilidad', 'Construcción de gráficos estadísticos que involucren variables cuantitativas y cualitativas adecuados de acuerdo a la información a describir.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'eje_contenido', 'Estadística y probabilidad', 'Interpretación de significado de parámetros de posición (media aritmética y modo) para describir datos en estudio.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(12, 'eje_contenido', 'Estadística y probabilidad', 'Comparación de la probabilidad frecuencial de un suceso, obtenida a partir de la exploración real o simulada con la probabilidad clásica.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(13, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión de la estructura discontinua de la materia utilizando el modelo cinético corpuscular e identificación de sus componentes submicroscópicos: átomos y moléculas.', 'pda_2025', 1, 'Explicar, a través de la modelización, que la materia está formada por partículas, y establecer relaciones entre los niveles de representación macroscópico, submicroscópico y simbólico.', '["Interpreta las diferencias estructurales entre los estados de la materia (sólido, líquido, gaseoso y plasma) utilizando el modelo cinético corpuscular.","Realiza inferencias/anticipaciones sobre el comportamiento (movimientos, fuerzas de atracción, ordenamiento) de las partículas en los diferentes estados de agregación, por ejemplo, a través de la interacción con simuladores.","Establece relaciones entre la temperatura de un cuerpo y el movimiento de sus partículas, a partir de la experimentación y/o de la interacción con simuladores.","Reconoce que, a nivel submicroscópico, las partículas de la materia pueden ser átomos, iones y moléculas, y describe diferencias entre ellas.","Elabora explicaciones sobre situaciones cotidianas utilizando el modelo cinético corpuscular (por ejemplo, controlar la presión de los neumáticos del auto en frío)."]', 'PdA p. 125'),
(13, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interpretación y comparación de algunas propiedades de la materia, en sus diferentes estados de agregación, a nivel macroscópico y submicroscópico.', 'pda_2025', 1, 'Explicar, a través de la modelización, que la materia está formada por partículas, y establecer relaciones entre los niveles de representación macroscópico, submicroscópico y simbólico.', '["Compara algunas propiedades macroscópicas de la materia (forma y volumen) entre sólidos, líquidos, gases y plasma, y las relaciona con la estructura submicroscópica, empleando modelizaciones (maquetas, esquemas, materiales concretos, laboratorios virtuales, entre otros).","Describe algunas propiedades particulares de la materia (por ejemplo, expansibilidad, compresibilidad, dilatación, fluidez, entre otras) e interpreta el comportamiento de sus partículas, utilizando el modelo cinético corpuscular.","Compara las propiedades físicas de rocas y minerales, y las clasifica, según su origen, en ígneas, metamórficas y sedimentarias.","Explora a través de experiencias sencillas, y explica, utilizando esquemas, los cambios físicos de los materiales (estado de agregación) del entorno cotidiano.","Reconoce, a partir de la experimentación, que la variación de temperatura produce cambios en el estado de agregación de los materiales.","Identifica, a través del análisis de fenómenos del entorno cotidiano y de la interacción con simuladores, los procesos involucrados en los cambios de estado, como fusión, sublimación, solidificación, sublimación inversa, vaporización (evaporación vs ebullición) y condensación."]', 'PdA p. 126'),
(13, 'eje_contenido', 'Progresiones de Aprendizaje', 'Diferenciación entre las sustancias puras y las mezclas, teniendo en cuenta su composición y algunas de sus propiedades.', 'pda_2025', 1, 'Explicar, a través de la modelización, que la materia está formada por partículas, y establecer relaciones entre los niveles de representación macroscópico, submicroscópico y simbólico.', '["Reconoce, a partir del análisis de ejemplos presentes en el entorno cotidiano, que las sustancias puras tienen composición fija e idénticas propiedades en toda su extensión, mientras que las mezclas están formadas por combinaciones de dos o más sustancias y presentan cambios en sus propiedades.","Clasifica mezclas homogéneas y heterogéneas, a partir de la indagación y diferenciación de sus fases y componentes.","Utiliza el modelo cinético corpuscular para representar y diferenciar, a nivel submicroscópico, las sustancias puras de las mezclas (homogéneas y heterogéneas) presentes en la vida cotidiana.","Interpreta el concepto de sistema material y su clasificación, a través de la experimentación con diferentes sustancias (y/o materiales) y sus combinaciones para la formación de mezclas.","Reflexiona acerca de la presencia de las mezclas y sus usos, en diferentes ámbitos y situaciones de la vida cotidiana.","Identifica mezclas que pueden presentar riesgos para la salud y el ambiente."]', 'PdA p. 126'),
(13, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de los métodos de separación y fraccionamiento de sistemas materiales homogéneos y heterogéneos, según las propiedades de sus componentes.', 'pda_2025', 1, 'Explicar, a través de la modelización, que la materia está formada por partículas, y establecer relaciones entre los niveles de representación macroscópico, submicroscópico y simbólico.', '["Reconoce y utiliza procedimientos físicos para separar y/o fraccionar los componentes de las mezclas.","Realiza anticipaciones y propone métodos de fraccionamiento y separación basados en las propiedades de los componentes de las mezclas (densidad, tamaño, punto de ebullición, entre otras).","Resuelve situaciones problemáticas basadas en la formación y/o separación de las mezclas utilizadas, en actividades cotidianas.","Reconoce y fundamenta los pasos realizados para resolver situaciones problemáticas relacionadas con la formación y/o separación de las mezclas.","Reconoce y describe procedimientos que se utilizan para separar las mezclas del entorno cotidiano.","Identifica y utiliza correctamente el material de laboratorio químico para separar y/o fraccionar las mezclas —probetas, embudos, filtros, tría, ampolla de decantación, destilador, entre otros—, considerando las recomendaciones de bioseguridad e higiene."]', 'PdA p. 127'),
(13, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación de los componentes de una solución y descripción de algunas de sus propiedades macroscópicas, de acuerdo con las proporciones entre soluto y solvente.', 'pda_2025', 1, 'Explicar, a través de la modelización, que la materia está formada por partículas, y establecer relaciones entre los niveles de representación macroscópico, submicroscópico y simbólico.', '["Reconoce soluciones de uso cotidiano, describe sus componentes e interpreta etiquetas en soluciones comerciales, identificando la presencia de solutos y solventes.","Identifica el soluto y el solvente en ejemplos de disoluciones, de acuerdo con las proporciones que guardan entre sí y su estado físico.","Prepara soluciones con diferentes solutos (por ejemplo, sulfato de cobre, cloruro de sodio y otras sales, anilinas, sacarosa, glicerina, entre otros) y solventes (agua, aceites, etanol); registra y compara algunas de sus propiedades macroscópicas (color, densidad, conductividad eléctrica, afinidad).","Reconoce al agua como disolvente universal y analiza su importancia, disponibilidad y consumo responsable."]', 'PdA p. 127'),
(13, 'eje_contenido', 'Progresiones de Aprendizaje', 'Descripción del proceso de disolución, a nivel macroscópico, y su interpretación a nivel submicroscópico, utilizando el modelo cinético-corpuscular.', 'pda_2025', 1, 'Explicar, a través de la modelización, que la materia está formada por partículas, y establecer relaciones entre los niveles de representación macroscópico, submicroscópico y simbólico.', '["Explica el proceso de disolución, a partir de la observación de los cambios que se producen a nivel macroscópico.","Relaciona los cambios del proceso de disolución, observables macroscópicamente, con el comportamiento de la partículas a nivel submicroscópico, utilizando el modelo cinético corpuscular y la interacción con simuladores y animaciones.","Experimenta, registra y elabora explicaciones sobre el efecto de las condiciones físicas (temperatura, tamaño de partículas y la agitación) en el proceso de disolución.","Compara el diseño experimental, los resultados y las conclusiones con sus compañeras/os, identificando las diferentes estrategias utilizadas en la preparación de soluciones o el fraccionamiento de sus componentes."]', 'PdA p. 128'),
(13, 'eje_contenido', 'Progresiones de Aprendizaje', 'Clasificación de soluciones según diferentes criterios, por ejemplo, de acuerdo con su concentración (diluidas, concentradas, saturadas, sobresaturadas), y estado físico (sólidas, líquidas y gaseosas).', 'pda_2025', 1, 'Explicar, a través de la modelización, que la materia está formada por partículas, y establecer relaciones entre los niveles de representación macroscópico, submicroscópico y simbólico.', '["Describe las características de soluciones diluídas, concentradas y saturadas, a partir de ejemplos cotidianos.","Compara, a través de la experimentación y el registro de datos observables en tablas, las propiedades macroscópicas (por ejemplo, densidad, color, conductividad eléctrica, entre otras) de las soluciones preparadas con cantidades diferentes de un mismo soluto, en un volumen determinado de solvente.","Analiza situaciones cotidianas en las que se emplean soluciones de concentraciones diferentes.","Reconoce la presencia de soluciones en diferentes estados de agregación e identifica el/los soluto/s y el solvente."]', 'PdA p. 128'),
(13, 'eje_contenido', 'Progresiones de Aprendizaje', 'Diferenciación entre los cambios físicos y químicos que experimenta la materia en el entorno cotidiano.', 'pda_2025', 1, 'Describir las transformaciones de la materia que ocurren en los cambios químicos, comprendiendo que se modifica la composición de las sustancias iniciales y que implica la ruptura y formación de nuevos enlaces.', '["Diferencia cambios químicos de cambios físicos y propone ejemplos de la vida cotidiana.","Clasifica los cambios físicos y químicos que experimentan distintos objetos y sustancias, a partir de la realización de experiencias sencillas y el análisis de evidencias observadas.","Realiza observaciones y describe cambios químicos en materiales y sustancias observables macroscópicamente, tales como desprendimiento de gases, cambios de color, liberacion de energía y formación de precipitados.","Reflexiona sobre cómo los cambios químicos y físicos producen efectos en el entorno, por ejemplo el reciclado de materiales, la contaminación ambiental, entre otros."]', 'PdA p. 131'),
(13, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento e interpretación de los cambios químicos que ocurren en el entorno (oxidación, combustión, corrosión), a partir de la observación macroscópica y su representación a nivel submicroscópico.', 'pda_2025', 1, 'Describir las transformaciones de la materia que ocurren en los cambios químicos, comprendiendo que se modifica la composición de las sustancias iniciales y que implica la ruptura y formación de nuevos enlaces.', '["Interpreta los cambios químicos a nivel submicroscópico, a través de la modelización (con simuladores, animaciones o esquemas), y explica cómo las partículas interactúan para formar nuevas sustancias con propiedades diferentes.","Establece relaciones entre las evidencias del cambio químico (combustión, oxidación y corrosión), observables macroscópicamente, y su representación a nivel submicroscópico, a partir de la modelización con esquemas.","Identifica situaciones cotidianas en las que ocurre una combustión incompleta (por ejemplo, la emisión de humo negro del escape de vehículos y de estufas a gas, entre otros) y explica sus efectos sobre el ambiente y la salud.","Interpreta el proceso de corrosión del hierro desde una perspectiva macroscópica (cambio de color, fragilidad) y submicroscópica (formación de óxido de hierro).","Reconoce ejemplos de corrosión en estructuras metálicas (puentes, barandas, monumentos) y describe las condiciones que favorecen su aparición.","Indaga, en diferentes fuentes de información, acerca de las estrategias para evitar la corrosión y la combustión incompleta, y justifica las más efectivas, según la situación."]', 'PdA p. 131'),
(13, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión del principio de conservación de la masa en cambios químicos que ocurren en el entorno cotidiano, a través de la experimentación y la explicación desde el modelo cinético corpuscular.', 'pda_2025', 1, 'Describir las transformaciones de la materia que ocurren en los cambios químicos, comprendiendo que se modifica la composición de las sustancias iniciales y que implica la ruptura y formación de nuevos enlaces.', '["Registra, en situaciones experimentales, y/o analiza (en videos, imágenes o tablas/textos de experiencias desarrolladas por otras/os) mediciones de la masa de reactivos y productos, confeccionando tablas de datos.","Explica el principio de conservación de la masa, relacionándolo con la igualdad entre las cantidades de reactivos y productos en los cambios químicos.","Analiza y compara datos experimentales sobre la conservación de la masa en el cambio químico, elaborando conclusiones.","Realiza actividades experimentales, tomando decisiones adecuadas en torno al uso del material e instrumental de laboratorio, y la manipulación de sustancias químicas, considerando las recomendaciones de bioseguridad e higiene.","Describe cómo las actividades experimentales le permiten comprender el principio de conservación de la masa."]', 'PdA p. 132'),
(13, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión de los efectos que produce la presencia de los gases efecto invernadero (GEI) en la atmósfera, como por ejemplo el dióxido de carbono (CO2), el metano (CH4) y los óxidos del nitrógeno (NOx).', 'pda_2025', 1, 'Establecer relaciones causa-efecto en torno al cambio climático, reconociendo medidas de adaptación climática y otras alternativas viables para la sostenibilidad.', '["Reconoce los principales GEI y su origen (cambios químicos del entorno cotidiano), natural o antropogénico.","Explica, de manera sencilla, los procesos más importantes del cambio climático en relación a los gases de efecto invernadero (GEI).","Identifica efectos del cambio climático a nivel local, regional y global, derivados del aumento de los GEI en la atmósfera.","Identifica distintas dimensiones de análisis que reflejan los impactos del cambio climático (económicas, sociales, ambientales).","Propone y valora acciones concretas para disminuir su propia huella de carbono y la de su comunidad."]', 'PdA p. 134'),
(13, 'objetivo', 'Objetivo', 'Reconocer y valorar los aportes de las Ciencias Naturales a la sociedad a lo largo de la historia.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(13, 'objetivo', 'Objetivo', 'Interpretar el conocimiento científico y sus procesos de producción como una construcción histórico-social de carácter provisorio.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(13, 'objetivo', 'Objetivo', 'Reconocer e interpretar a los modelos como representaciones que se elaboran para explicar y predecir hechos y fenómenos de la naturaleza.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(13, 'objetivo', 'Objetivo', 'Reconocer las principales propiedades de los materiales identificando familias de materiales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(13, 'objetivo', 'Objetivo', 'Comprender la estructura de la materia como discontinua identificando sus componentes submicroscópicos: átomos, moléculas e iones.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(13, 'objetivo', 'Objetivo', 'Emplear el modelo cinético-corpuscular para interpretar las propiedades de los materiales, los estados de agregación y sus cambios y también el proceso de disolución reconociendo las variables que influyen en el mismo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(13, 'objetivo', 'Objetivo', 'Reconocer a la Tabla Periódica como una fuente de datos sistematizados sobre los elementos químicos y emplearlas para extraer algunos datos relevantes de los elementos químicos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(13, 'objetivo', 'Objetivo', 'Valorar el cuidado del ambiente desarrollando una actitud crítica frente a la utilización de los recursos naturales y al deterioro del medio.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(13, 'eje_contenido', 'Los materiales: estructura, propiedades e interacciones', 'Reconocimiento de familias de materiales por sus propiedades comunes como, por ejemplo, materiales metálicos, plásticos, combustibles.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(13, 'eje_contenido', 'Los materiales: estructura, propiedades e interacciones', 'Interpretación de la discontinuidad de la materia a partir del modelo cinético-corpuscular.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(13, 'eje_contenido', 'Los materiales: estructura, propiedades e interacciones', 'Identificación de los componentes submicroscópicos de los materiales presentes en el ambiente y los seres vivos (iones, átomos, moléculas, agregados moleculares).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(13, 'eje_contenido', 'Los materiales: estructura, propiedades e interacciones', 'Identificación y descripción del modelo atómico actual simplificado: electroneutralidad, núcleo y nube electrónica.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(13, 'eje_contenido', 'Los materiales: estructura, propiedades e interacciones', 'Interpretación de los estados de agregación de la materia y sus cambios, en particular los del agua, desde el modelo cinético corpuscular.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(13, 'eje_contenido', 'Los materiales: estructura, propiedades e interacciones', 'Interpretación del proceso de disolución desde el modelo cinético-corpuscular (incluyendo las variables), en particular el estudio del agua como disolvente universal.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(13, 'eje_contenido', 'Los materiales: estructura, propiedades e interacciones', 'Diferenciación y caracterización de sustancias puras y mezclas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(13, 'eje_contenido', 'Los materiales: estructura, propiedades e interacciones', 'Reconocimiento de la Tabla Periódica como una forma de organización y fuente de datos acerca de los elementos químicos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'eje_contenido', 'Progresiones de Aprendizaje', 'Caracterización de los métodos anticonceptivos según su forma de acción (mecánicos o de barrera, químicos, quirúrgicos y naturales), para poder elegir desde una perspectiva de derecho.', 'pda_2025', 1, 'Tomar decisiones, responsables y fundamentadas, en torno al cuidado del propio cuerpo y el de las demás personas, desde una visión integral de salud.', '["Dialoga sobre el cuidado del cuerpo propio y de las/os otras/os, en relación con las relaciones sexuales.","Comprende que el ejercicio pleno de la sexualidad debe estar acompañado de la toma de decisiones fundamentadas.","Selecciona métodos anticonceptivos, considerando fundamentos y sitios de acción, en relación con distintas situaciones hipotéticas.","Reconoce que la anticoncepción es una responsabilidad compartida, participando en charlas reflexivas en torno a la importancia de la procreación responsable.","Interpreta que no existe un método anticonceptivo ideal, sino que deben evaluarse en contexto y en función de objetivos, características biológicas, planeación familiar, entre otras variables.","Analiza las principales leyes argentinas en relación con la salud sexual y reproductiva, y las relaciona con el ejercicio de derechos.","Reconoce el acceso a anticonceptivos gratuitos y de calidad como un derecho."]', 'PdA p. 98'),
(14, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de las características, modos de transmisión, prevención y tratamiento de las infecciones de transmisión sexual (ITS).', 'pda_2025', 1, 'Tomar decisiones, responsables y fundamentadas, en torno al cuidado del propio cuerpo y el de las demás personas, desde una visión integral de salud.', '["Explica algunas situaciones relacionadas con la salud sexual y reproductiva como prevención de riesgos y daños, el embarazo en la adolescencia, y las infecciones de transmisión sexual (ITS).","Diferencia entre ETS e ITS, reconociendo la importancia y las implicancias médica y social de renombrar las primeras.","Compara a las ITS según su agente causal (virus, bacteria, hongo, protozoo), síntomas y modos de contagio, considerando el tipo de tratamiento idóneo para cada una.","Reconoce que la mayoría de las ITS poseen tratamiento y requieren de la consulta médica para su detección temprana y tratamiento oportuno.","Comunica, en distintos soportes y lenguajes, la importancia de utilizar preservativo como único método que previene ITS y embarazo no intencional.","Manipula correctamente el preservativo y el campo de látex, en simulaciones sobre su uso como métodos de prevención de ITS."]', 'PdA p. 98'),
(14, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de actitudes que contribuyen con el cuidado del cuerpo y con la toma de decisiones responsables en relación a los vínculos sexoafectivos.', 'pda_2025', 1, 'Tomar decisiones, responsables y fundamentadas, en torno al cuidado del propio cuerpo y el de las demás personas, desde una visión integral de salud.', '["Plantea dudas e inquietudes relacionadas con el ejercicio de la sexualidad, en relación con los vínculos socioafectivos y los derechos sexuales y reproductivos.","Reconoce al consentimiento como condición necesaria para la construcción de relaciones sexoafectivas saludables, y el ejercicio de una sexualidad plena.","Identifica algunas herramientas institucionales (leyes, redes, normativas) que colaboran con la toma de decisiones sobre la salud sexual y reproductiva, en relación con los proyectos de vida.","Reconoce los derechos sexuales y reproductivos desde la autonomía progresiva.","Identifica situaciones reales o hipotéticas de vulneración de derechos en noviazgos, amistades, vínculos sexoafectivos, a partir de análisis de casos, juegos de rol, entre otros.","Reconoce información clave de la Ley de Salud Sexual y Procreación Responsable."]', 'PdA p. 99'),
(14, 'eje_contenido', 'Progresiones de Aprendizaje', 'Explicación de algunos procesos de las personas vinculados con el crecimiento, desarrollo y maduración, con foco en la procreación.', 'pda_2025', 1, 'Tomar decisiones, responsables y fundamentadas, en torno al cuidado del propio cuerpo y el de las demás personas, desde una visión integral de salud.', '["Reflexiona en torno a la procreación responsable y a la planificación familiar, retomando la normativa vigente en el país.","Identifica las condiciones en las que puede ocurrir un embarazo y las relaciona con el ciclo menstrual.","Conoce, de manera general, los principales procesos biológicos involucrados durante el embarazo y la gestación (por ejemplo, rol de la placenta).","Reconoce al parto respetado como un derecho de todas y todos.","Reflexiona en torno a la maternidad y paternidad desde una perspectiva de género, identificando roles y estereotipos de género, reconociendo que el cuidado parental debe ser equitativo y compartido.","Comprende que existen muchos tipos de familias y respeta las diferentes conformaciones familiares.","Reconoce la importancia de los hábitos de cuidados durante el embarazo. y la lactancia.","Valora la importancia de la lactancia materna como un acto de nutrición, cuidado y vínculo."]', 'PdA p. 99'),
(14, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interpretación del proceso de nutrición, desde una visión sistémica en organismos autótrofos y heterótrofos.', 'pda_2025', 1, 'Reconocer lo común, presente en la diversidad de formas de vida, comparando distintos niveles de organización biológica (célula, tejidos, organismo, comunidad, entre otros).', '["Identifica las estructuras implicadas en los procesos de nutrición en diferentes seres vivos.","Distingue que los animales, los hongos y algunas bacterias incorporan alimentos del entorno (son heterótrofos), mientras que las plantas, las algas y las cianobacterias son autótrofos.","Explora, registra y sistematiza la diversidad de los seres vivos autótrofos, en salidas educativas de reconocimiento o a través de recursos audiovisuales.","Participa de experiencias de laboratorio sencillas en relación con la nutrición (por ejemplo, con levaduras y con algas), identificando variables implicadas.","Reconoce la importancia de los seres vivos autótrofos como principales productores de materia y energía en el planeta, y que dan sustento al resto de los seres vivos."]', 'PdA p. 102'),
(14, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interpretación de las relaciones tróficas de los sistemas ecológicos, identificando el papel de los grandes grupos de seres vivos (productores, consumidores, descomponedores).', 'pda_2025', 1, 'Reconocer lo común, presente en la diversidad de formas de vida, comparando distintos niveles de organización biológica (célula, tejidos, organismo, comunidad, entre otros).', '["Identifica la diversidad de modos de alimentación (herbívoros, por ejemplo folívoros, nectívoros, frugívoros, granívoros, entre otros; carnívoros depredadores, por ejemplo, carnívoros estrictos, piscívoros, Insectívoros y carnívoros carroñeros) de los seres vivos.","Clasifica a los seres vivos en función de su papel ecosistémico.","Construye redes tróficas de diferentes ambientes, considerando los seres vivos que los habitan.","Esquematiza los intercambios de materiales y energía en los sistemas ecológicos, mediante flechas u otra simbología equivalente, reconociendo el ciclado de materia y el flujo de energía.","Comprende la importancia de los diferentes niveles tróficos para el sostenimiento y equilibrio de los sistemas ecológicos.","Identifica la importancia de los descomponedores en relación con el ciclado natural de nutrientes/materia.","Comprende la importancia de la conservación de la biodiversidad de los suelos en los sistemas ecológicos.","Reconoce y valora la diversidad de descomponedores, consumidores y productores, con énfasis en la biodiversidad autóctona."]', 'PdA p. 102'),
(14, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión de la importancia de la preservación de la biodiversidad, desde los puntos de vista ecológicos y evolutivos.', 'pda_2025', 1, 'Reconocer lo común, presente en la diversidad de formas de vida, comparando distintos niveles de organización biológica (célula, tejidos, organismo, comunidad, entre otros).', '["Esboza explicaciones en relación a la importancia de preservar la biodiversidad, retomando como argumento las contribuciones de la naturaleza.","Interpreta criterios de los distintos sistemas de clasificación que sistematizan la biodiversidad.","Explica la interrelación ecológica y la continuidad evolutiva, a través de la clasificación de la biodiversidad.","Reconoce la necesidad de crear y mantener áreas naturales protegidas, para conservar y proteger la biodiversidad, en todos sus niveles.","Comunica acciones o actitudes que promueven el cuidado de las áreas naturales protegidas, a través de diferentes lenguajes/formas de representación."]', 'PdA p. 103'),
(14, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación de los aportes de la paleontología y la geología a la comprensión del proceso evolutivo y la clasificación de la biodiversidad.', 'pda_2025', 1, 'Reconocer lo común, presente en la diversidad de formas de vida, comparando distintos niveles de organización biológica (célula, tejidos, organismo, comunidad, entre otros).', '["Utiliza la escala de tiempo profundo, para identificar grandes eventos evolutivos sucedidos en la historia de la vida de la Tierra.","Selecciona y sistematiza información sobre yacimientos fósiles en Argentina.","Reflexiona sobre eventos de extinción del pasado geológico, y los relaciona con los sucesos de diversificación (por ejemplo, surgimiento de planes corporales, tipos celulares, entre otros).","Diferencia distintos tipos de fosilización y establece su relación con la estratigrafía.","Reconoce los cambios generales en la distribución de los continentes en el tiempo profundo.","Modeliza, usando simuladores, maquetas u otros materiales, los cambios geológicos de las placas continentales (tectónica de placas)."]', 'PdA p. 103'),
(14, 'eje_contenido', 'Progresiones de Aprendizaje', 'Conocimiento del origen evolutivo de la célula eucariota y de algunas organelas (como mitocondria, cloroplasto, amiloplasto y núcleo) diferenciando entre células animales, vegetales y fúngicas a partir de la teoría de la endosimbiosis.', 'pda_2025', 1, 'Reconoce los aportes del enfoque evolutivo para explicar cambios y permanencias, así como también características, funciones y estructuras celulares en relación con la biodiversidad.', '["Plantea sus ideas sobre el cambio en los seres vivos en el tiempo geológico.","Describe y contrasta ideas sobre el cambio en los seres vivos (Creacionismo, Transformismo y Evolucionismo por selección natural), fundamentando cuáles pueden considerarse científicas.","Identifica, en esquemas, imágenes o modelos, los tipos celulares principales, eucariota y procariota, reconociendo su temporalidad evolutiva, en relación con el origen de la vida.","Observa y compara distintos preparados microscópicos o fotografías y fotomicrografía de células de distintos tipos, diferenciando células eucariotas vegetales, fúngicas y animales, a partir de sus organelas características.","Indaga acerca de las funciones de las principales organelas celulares (mitocondrias, plástidos, retículos endoplasmáticos, lisosomas, entre otros), y las vincula los distintos tipos de células eucariotas (vegetal, animal, fungi).","Explica los impactos evolutivos de los diferentes eventos endosimbióticos, que dieron origen a los distintos tipos celulares eucariotas y los ubica temporalmente en la historia de la vida de la Tierra.","Se aproxima a explicar la Teoría de la endosimbiosis y sus aportes para comprender la historia evolutiva de los seres vivos."]', 'PdA p. 107'),
(14, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interpretación de criterios para clasificar la biodiversidad (celular, morfológico, nutricional, reproductivo, evolutivo) y reconocimiento de los grupos de seres vivos.', 'pda_2025', 1, 'Reconoce los aportes del enfoque evolutivo para explicar cambios y permanencias, así como también características, funciones y estructuras celulares en relación con la biodiversidad.', '["Realiza clasificaciones de seres vivos, utilizando distintos instrumentos de análisis (por ejemplo, claves dicotómicas, diagramas, dibujos, cladogramas, entre otros).","Reflexiona sobre los instrumentos utilizados para la clasificación de los seres vivos, reconociendo sus ventajas y limitaciones.","Esboza explicaciones para la inclusión o exclusión en una categoría, a partir de las características comunes entre seres vivos de un mismo grupo.","Propone, identifica o utiliza criterios para agrupar a los seres vivos, en diferentes situaciones y contexto de estudio.","Problematiza el sistema de clasificación escolar (de Whittaker) al considerar el registro fósil de vertebrados.","Reconoce los cambios históricos y los aportes científicos, en relación con la clasificación de la biodiversidad (por ejemplo, exclusión de los hongos del grupo de las plantas, aproximación a la comprensión de Protista y Monera como grupos polifiléticos)."]', 'PdA p. 107'),
(14, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión de la mitosis como mecanismo de reproducción de organismos y producción o renovación de tejidos, y de la meiosis, como mecanismo de producción de gametos.', 'pda_2025', 1, 'Reconoce los aportes del enfoque evolutivo para explicar cambios y permanencias, así como también características, funciones y estructuras celulares en relación con la biodiversidad.', '["Dialoga en torno a la reproducción de los seres vivos , reconociendo que existen diversas formas de asegurar la continuidad de la especie.","Relaciona el proceso de meiosis con la reproducción sexual, y el de mitosis, con la reproducción asexual.","Esboza explicaciones en relación con las ventajas y desventajas adaptativas de la reproducción sexual y asexual.","Indica que la mitosis, en organismos pluricelulares, ocurre en tejidos somáticos, mientras que la meiosis ocurre en tejidos germinales (esporogénicos o gametogénicos).","Reconoce en plantas, hongos y animales, los tejidos donde suceden la mitosis y la meiosis.","Reconoce las fases del ciclo celular mediante observaciones en el microscopio o fotomicrografías y esquematiza mediante dibujos y/o esquemas.","Comunica,mediante textos breves o explicaciones orales, las diferencias y similitudes entre mitosis y meiosis."]', 'PdA p. 108'),
(14, 'eje_contenido', 'Progresiones de Aprendizaje', 'Aproximación al proceso de fotosíntesis, desde las características propias de la célula vegetal (amiloplasto, cloroplastos, vacuola, pared celular) y su relación con la fotoautotrofia.', 'pda_2025', 1, 'Reconoce los aportes del enfoque evolutivo para explicar cambios y permanencias, así como también características, funciones y estructuras celulares en relación con la biodiversidad.', '["Plantea sus ideas sobre la forma de alimentación en las plantas (autotrofia).","Esboza la ecuación simplificada de la fotosíntesis (sin descripción molecular, solo los componentes como agua, luz, clorofila, azúcar) identificando qué se requieren (reactivos) y qué se forma (productos).","Diseña o participa de experimentaciones sencillas en torno a la fotosíntesis, identificando variables intervinientes como luz, presencia de carbono, oxígeno, temperatura.","Contrasta los resultados obtenidos en experimentaciones sobre fotosíntesis con los obtenidos por sus compañeras/os y analiza las diferencias en relación con las hipótesis previas.","Formula explicaciones sobre la presencia de almidón en diferentes partes de la planta, retomando nociones de biología celular, del proceso de fotosíntesis y de transporte.","Distingue las partes del cuerpo de las plantas donde se realiza el proceso de fotosíntesis.","Relaciona la presencia de pigmentos con el proceso de fotosíntesis y reconoce su ubicación en los cloroplastos.","Reflexiona sobre el sentido del proceso fotosintético para las plantas, en relación con la producción de oxígeno como residuo, y de azúcar, como insumo nutricional."]', 'PdA p. 108'),
(14, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación de los atributos emergentes de niveles de organización en poblaciones, ecosistemas y ecorregiones, según diferentes criterios.', 'pda_2025', 1, 'Reconoce los aportes del enfoque evolutivo para explicar cambios y permanencias, así como también características, funciones y estructuras celulares en relación con la biodiversidad.', '["Reconoce algunas de las propiedades emergentes (por ejemplo, tasa de natalidad, tasa de supervivencia, entre otras) de las poblaciones de seres vivos.","Utiliza el pensamiento poblacional para explicar los cambios adaptativos que se observan entre generaciones.","Analiza gráficos donde se representan las tasas de supervivencia, mortandad, entre otras, para comprender la dinámica poblacional y relacionar sus variaciones con cambios en los ecosistemas.","Identifica distintos tipos de relaciones entre especies (simbiosis, mutualismo, amensalismo, parasitismo, depredación, competencia) y ejemplifica considerando la diversidad nativa presente en las diferentes ecorregiones del territorio de Córdoba."]', 'PdA p. 109'),
(14, 'eje_contenido', 'Progresiones de Aprendizaje', 'Valoración de alternativas y conductas (individuales y colectivas) en relación con la biodiversidad, que permitan la adaptación y mitigación de las consecuencias del cambio climático.', 'pda_2025', 1, 'Establecer relaciones causa-efecto en torno al cambio climático, reconociendo medidas de adaptación climática y otras alternativas viables para la sostenibilidad.', '["Distingue entre propuestas de adaptación y mitigación del cambio climático.","Analiza acuerdos o tratados internacionales, legislación (nacional o provincial), políticas y acciones a distintos niveles (internacional, nacional, provincial, local) relacionados con el cambio climático, valorando sus impactos y alcances.","Evalúa la información de medios de comunicación y redes sociales que muestran estrategias de adaptación y mitigación del cambio climático, para diferenciar opiniones de argumentos basados en evidencias científicas.","Explica el papel de las plantas en la mitigación de los efectos del cambio climático, incorporando nociones como fotosíntesis, gases, temperatura, entre otras, y valorando los ecosistemas naturales.","Relaciona la biodiversidad y los ecosistemas saludables con la regulación climática (por ejemplo, bosques y humedales como sumideros de carbono y protectores de cuencas hídricas).","Busca información sobre propuestas de restauración ecosistémica locales y regionales y las analiza en cuanto a sus aportes para la biodiversidad, y la adaptación y mitigación del cambio climático (por ejemplo, la reforestación de los bosques de tabaquillo).","Participa de mapeos colectivos donde se relevan problemáticas ambientales vinculadas con las causas y las consecuencias del cambio climático.","Participa de acciones comunitarias que aporten al empoderamiento de acción climática (por ejemplo, participación en asambleas, reforestación con especies nativas, control de especies vegetales exóticas, charlas, entre otras) en su territorio."]', 'PdA p. 111'),
(14, 'objetivo', 'Objetivo', 'Reconocer y valorar los aportes de las Ciencias Naturales a la sociedad a lo largo de la historia.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'objetivo', 'Objetivo', 'Interpretar el conocimiento científico y sus procesos de producción como una construcción histórico-social de carácter provisorio.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'objetivo', 'Objetivo', 'Interpretar e inferir la diversidad de las consecuencias que implican las decisiones y acciones humanas sobre el ambiente y la salud.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'objetivo', 'Objetivo', 'Reconocer a la diversidad como consecuencia de la evolución de los seres vivos a través del tiempo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'objetivo', 'Objetivo', 'Comprender que todo ser vivo es capaz de mantener estables y constantes todas las condiciones internas de su organismo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'objetivo', 'Objetivo', 'Reconocer a las funciones de reproducción, relación y control como características principales de todo ser vivo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'objetivo', 'Objetivo', 'Comprender al organismo humano como sistema abierto, complejo, coordinado y que se reproduce.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'objetivo', 'Objetivo', 'Identificar e interpretar criterios de clasificación para agrupar a los seres vivos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'eje_contenido', 'Los seres vivos: diversidad, unidad, interrelaciones, continuidad y cambio', 'Aproximación al conocimiento de las teorías que explican el origen de la vida y su relación con las funciones vitales, como expresión de la unidad de los seres vivos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'eje_contenido', 'Los seres vivos: diversidad, unidad, interrelaciones, continuidad y cambio', 'Identificación y reconocimiento de los componentes de la célula Procariota y Eucariota.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'eje_contenido', 'Los seres vivos: diversidad, unidad, interrelaciones, continuidad y cambio', 'Reconocimiento y análisis de la biodiversidad como resultado de cambios producidos en los seres vivos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'eje_contenido', 'Los seres vivos: diversidad, unidad, interrelaciones, continuidad y cambio', 'Reconocimiento de la diversidad animal y vegetal y de los mecanismos que a lo largo del tiempo han desarrollado para adaptarse a diferentes ambientes.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'eje_contenido', 'Los seres vivos: diversidad, unidad, interrelaciones, continuidad y cambio', 'Identificación e interpretación de algunos criterios para clasificar a los seres vivos en reinos con ayuda de claves, dibujos, pirámides, y/o fotografías.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'eje_contenido', 'Los seres vivos: diversidad, unidad, interrelaciones, continuidad y cambio', 'Reconocimiento de las ventajas y desventajas adaptativas de la reproducción sexual y asexual.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'eje_contenido', 'El organismo humano desde una visión integral', 'Reconocimiento y caracterización de las funciones de relación y control en los seres vivos, asociadas con los cambios en el medio interno y externo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'eje_contenido', 'El organismo humano desde una visión integral', 'Comprensión del mecanismo de homeostasis: equilibrio hídrico, térmico.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'eje_contenido', 'El organismo humano desde una visión integral', 'Reconocimiento y caracterización de las estructuras y procesos relacionados con la reproducción humana.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'eje_contenido', 'El organismo humano desde una visión integral', 'Comprensión de la mitosis como mecanismo de reproducción de organismos y producción o renovación de tejidos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(14, 'eje_contenido', 'El organismo humano desde una visión integral', 'Comprensión de la meiosis como mecanismo de producción de gametos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 59-62'),
(15, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión de los cambios que se producen en el espacio y en las primeras sociedades, por el paso de un modo de subsistencia a un modo de producción.', 'pda_2025', 1, 'Analizar las sociedades y sus transformaciones, considerando cambios y continuidades y la interrelación entre sociedad-espacio-tiempo, a partir de procesos vinculados a identidades, diversidad y alteridad, desigualdad y multiplicidad de voces y saberes.', '["Explica la interrelación e influencia recíproca entre los procesos de hominización (desarrollo biológico) y de humanización (desarrollo cultural).","Compara y explica los cambios que se producen en el espacio, por el paso de un modo de subsistencia a un modo de producción.","Relaciona la forma de subsistencia y producción, y los modos de organización social, a partir de diversos vestigios arqueológicos y otras fuentes históricas, en el actual territorio cordobés.","Localiza, cronológica y espacialmente, procesos históricos, a través del uso y construcción de herramientas, analógicas y/o digitales, tales como mapas históricos y líneas de tiempo, entre otros recursos."]', 'PdA p. 106'),
(15, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis del conflicto en la expansión territorial de sociedades esclavistas y del control sobre otras sociedades, y en la construcción de organizaciones imperiales en Mesoamérica/el Mundo Mediterráneo.', 'pda_2025', 1, 'Interpretar y construir, de manera individual y colaborativa, diversos dispositivos y representaciones gráficas, cartográficas, audiovisuales y multimediales para la problematización y/o comunicación de procesos y problemáticas históricas y socio-territoriales.', '["Compara casos de construcción de organizaciones imperiales, en distintos espacios y tiempos históricos, y explica sus diferencias y similitudes.","Explica y relaciona las múltiples causas involucradas en la expansión, el alcance territorial, y la hegemonía cultural de las organizaciones imperiales.","Identifica la expansión territorial y las estrategias de dominación ejercidas por los imperios, como causa de los conflictos en diferentes sociedades en Occidente y Mesoamérica, y los representa a través de diversas cartografías.","Compara la situación de las mujeres en las diferentes sociedades,y analiza las desigualdades de género existentes.","Interpreta la esclavitud como una nueva forma de organización del trabajo, a partir de la crisis de las sociedades tributarias y de los estados teocráticos.","Debate y argumenta acerca de las formas que adquiere la esclavitud en la actualidad."]', 'PdA p. 107'),
(15, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión de las transformaciones, a partir de la producción de excedentes, la organización y división del trabajo, la jerarquización social y el surgimiento de los primeros estados teocráticos tributarios.', 'pda_2025', 1, 'Comprender la complejidad y dinamismo de los procesos sociales, con énfasis en los actores individuales y colectivos involucrados, y su capacidad de acción, decisión e intención, reflexionando en torno al conflicto y las posibilidades de consensos como formas de organización e integración de las sociedades en diferentes escalas', '["Establece relaciones de causalidad entre el surgimiento de la agricultura, la división social y sexual del trabajo, la complejización y jerarquización social, en las sociedades agrarias tributarias.","Interpreta la apropiación de tierras fértiles como causa de los conflictos en distintas sociedades en Oriente, Mesoamérica y la Región Andina.","Argumenta y compara conflictos actuales por los bienes comunes.","Diferencia diversos sistemas políticos (de las comunidades no jerarquizadas a las ciudades-estado teocráticas) y sus estrategias de legitimación de poder, a través del culto y la violencia legal.","Analiza el modo en que la estructura social, política y religiosa se evidencia en la diferenciación del espacio en las ciudades-Estado.","Explora la diversidad de expresiones culturales en los concretos sociohistóricos estudiados y crea presentaciones utilizando dispositivos digitales.","Identifica, espacial y temporalmente, las sociedades estudiadas."]', 'PdA p. 108'),
(15, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación de diversas culturas, en relación con sus desarrollos tecnológicos, económicos, artísticos y sociopolíticos, antes de la llegada de los conquistadores al Abya Yala, con especial atención a la Región Andina y al territorio cordobés.', 'pda_2025', 1, 'Comprender la complejidad y dinamismo de los procesos sociales, con énfasis en los actores individuales y colectivos involucrados, y su capacidad de acción, decisión e intención, reflexionando en torno al conflicto y las posibilidades de consensos como formas de organización e integración de las sociedades en diferentes escalas', '["Describe y compara los modos de vida de las diversas culturas, en relación con sus desarrollos tecnológicos, económicos, artísticos y sociopolíticos, antes de la llegada de los conquistadores al Abya Yala.","Reconoce distintas formas de prejuicio y discriminación entre diferentes sociedades y dentro de estas, comparando pasado-presente, y elaborando hipótesis de futuros posibles, en relación con las reivindicaciones culturales y territoriales.","Identifica, en representaciones cartográficas, las distintas sociedades, y crea iconografía de manera individual y/o con otros, para dar cuenta de las estrategias de dominación política, religiosa, económica y social."]', 'PdA p. 108'),
(15, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de la fragmentación del mundo mediterráneo, que dio lugar al surgimiento de diversas sociedades, como Europa occidental feudal católica, Europa oriental cristiana ortodoxa e Islam.', 'pda_2025', 1, 'Comprender la complejidad y dinamismo de los procesos sociales, con énfasis en los actores individuales y colectivos involucrados, y su capacidad de acción, decisión e intención, reflexionando en torno al conflicto y las posibilidades de consensos como formas de organización e integración de las sociedades en diferentes escalas', '["Identifica el Imperio Romano como unidad homogénea impuesta, y su posterior fragmentación y diversidad cultural.","Elabora representaciones gráficas y explicaciones escritas del proceso de fragmentación y transformación del mundo mediterráneo.","Aplica el binomio unidad-fragmentación, de este proceso histórico a otros, en distintos espacios y tiempos.","Compara la forma de organización de la sociedad, la economía, la política, y los sistemas de creencias, valores y costumbres, en las sociedades hebrea, bizantina, musulmana y cristiana, así como su proyección en el tiempo y en el espacio, hasta la actualidad."]', 'PdA p. 109'),
(15, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación de las transformaciones que se producen, desde finales del siglo XV, en las sociedades europeas, por la concentración del poder monárquico, la reorganización espacial y la expansión ultramarina.', 'pda_2025', 1, 'Comprender la complejidad y dinamismo de los procesos sociales, con énfasis en los actores individuales y colectivos involucrados, y su capacidad de acción, decisión e intención, reflexionando en torno al conflicto y las posibilidades de consensos como formas de organización e integración de las sociedades en diferentes escalas', '["Distingue, a partir del siglo XI, las características del mundo rural feudal respecto del mundo urbano, con el surgimiento de las ciudades en Europa y analiza diferencias y similitudes.","Representa (a través de gráficos, esquemas, mapas conceptuales y cartografías) la reorganización espacial del mundo europeo a partir de la concentración del poder monárquico.","Explica las razones de la importancia de los conflictos serviles, campesinos, heréticos y de mujeres, contra el clero, la nobleza y la burguesía hacia el siglo XV.","Estudia los casos de España y Portugal para identificar y explicar las causas de la expansión comercial y territorial europea, los elementos que la hicieron posible, los móviles o intereses particulares que la impulsaron y las rutas que siguieron."]', 'PdA p. 109'),
(15, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de la economía-mundo y de las nuevas relaciones de colonialidad, a instancias de la invasión y conquista de los territorios del Abya Yala.', 'pda_2025', 1, 'Asumir una participación crítica y activa, como sujetos de derechos con responsabilidades, ante problemas socialmente relevantes en debates vinculados a los principios de justicia social y ambiental, igualdad socioeconómica, diversidad socio-cultural y derechos humanos.', '["Interpreta y se apropia del concepto de economía-mundo, que surge de la declinación del feudalismo en la Europa Occidental de los siglos XV y XVI, y de la proyección territorial y el desplazamiento cultural hacia América, a instancias de la expansión geográfica.","Identifica la desigualdad entre distintas regiones (periferia, semiperiferia, estados centrales) en el acceso a los bienes y productos en los inicios de la modernidad occidental, y compara con la actualidad.","Se aproxima a los conceptos de colonialidad, racismo y patriarcado, como elementos constituyentes de la modernidad occidental."]', 'PdA p. 111'),
(15, 'objetivo', 'Objetivo', 'Recuperar los aportes teóricos de las Ciencias Sociales y sus interpretaciones de la realidad socio-histórica.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'objetivo', 'Objetivo', 'Comprender las distintas problemáticas socio-históricas desde la multicausalidad y la multiperspectividad, asumiendo la complejidad de las categorías temporales de simultaneidad, cambio y continuidad, cronología, periodización y duración, sobre los períodos históricos estudiados, desde interpretaciones controversiales y diversas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'objetivo', 'Objetivo', 'Organizar la información a través de diversos procedimientos que incluyan el análisis crítico de distintas fuentes y diferentes modos de comunicación (orales, escritos, icónicos, entre otros).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'objetivo', 'Objetivo', 'Reconocer los cambios producidos por el paso de la vida nómade a la sedentaria en distintos contextos históricos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'objetivo', 'Objetivo', 'Identificar las formaciones de sistemas de poder como producto de procesos sociales conflictivos en diversos contextos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'objetivo', 'Objetivo', 'Reconocer los procesos históricos desarrollados en la configuración de la matriz de la cultura occidental.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'objetivo', 'Objetivo', 'Valorar los desarrollos culturales originarios en América en su riqueza y diversidad.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'objetivo', 'Objetivo', 'Identificar el orden colonial impuesto por Europa en América como la apropiación del espacio y la organización de la vida social y política en función de las economías extractivas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'eje_contenido', 'La organización de la subsistencia y de los sistemas políticos', 'Conocimiento del origen común de la humanidad hace más de 250.000 años en África, y su posterior distribución territorial en el resto del mundo vinculada con la apropiación de diversos recursos y la transformación de la naturaleza en procura de su subsistencia.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'eje_contenido', 'La organización de la subsistencia y de los sistemas políticos', 'Explicación de los cambios que se producen en el paisaje por el paso de la forma de vida nómade a la vida sedentaria como modos de satisfacción de las necesidades humanas en Occidente y en América.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'eje_contenido', 'La organización de la subsistencia y de los sistemas políticos', 'Comprensión de las transformaciones en la división del trabajo, la organización social y las distintas formas de autoridad: tribus, jefaturas, cacicazgos y estados.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'eje_contenido', 'La organización de la subsistencia y de los sistemas políticos', 'Comparación de los procesos de organización de los estados en Oriente Próximo, en el Mediterráneo y en América.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'eje_contenido', 'Las organizaciones imperiales en Europa y América: proyección territorial y desplazamiento cultural', 'Análisis del proceso de construcción del Imperio Romano y su alcance territorial, su predominio económico, político y cultural, la crisis del Imperio Romano y la fragmentación de Occidente.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'eje_contenido', 'Las organizaciones imperiales en Europa y América: proyección territorial y desplazamiento cultural', 'Conocimiento del proceso de construcción de organizaciones imperiales en América, su alcance territorial, su predominio cultural', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'eje_contenido', 'Diversidad cultural a partir de la fragmentación del Mundo Mediterráneo', 'Análisis de la fragmentación del mundo mediterráneo y el surgimiento de nuevas formas de relación social, económicas y de poder en la configuración del feudalismo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'eje_contenido', 'Diversidad cultural a partir de la fragmentación del Mundo Mediterráneo', 'Reconocimiento de las principales similitudes y diferencias en la forma de organización de la economía, la sociedad, la política y los sistemas de creencias, valores y costumbres en las sociedades hebrea, bizantina, musulmana y cristiana y su proyección en el tiempo y en el espacio.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'eje_contenido', 'Diversidad cultural a partir de la fragmentación del Mundo Mediterráneo', 'Explicación del proceso de surgimiento de las ciudades en Europa a partir del Siglo XI: las actividades económicas, grupos sociales, distribución del poder y conflictos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'eje_contenido', 'El impacto de Occidente sobre las sociedades americanas', 'Explicación del proceso de conquista y colonización europea en América y su impacto sobre las sociedades americanas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'eje_contenido', 'El impacto de Occidente sobre las sociedades americanas', 'Identificación de las instituciones de gobierno creadas por el orden colonial español en América.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(15, 'eje_contenido', 'El impacto de Occidente sobre las sociedades americanas', 'Comprensión de la organización de la economía extractiva en relación con la explotación minera en América y su impacto en el ambiente y en la sociedad.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 89-90'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación y contraste de modos de vida y prácticas sociales en distintos contextos culturales, con referencia a sus rutinas diarias, trabajos y celebraciones.', 'pda_2025', 1, 'Reconocer y valorar la diversidad de orígenes, prácticas culturales y variedades lingüísticas del inglés; establecer comparaciones con la propia cultura, e identificar y cuestionar estereotipos, para promover una convivencia sensible y responsable en las diferencias.', '["Brinda información personal propia y de otras/os, sobre gustos, rutinas, actividades de tiempo libre y formas de movilidad, trabajos y celebraciones, estableciendo comparaciones con la información aportada por compañeras/os o personas de otros lugares.","Comparte información sobre trabajos en su entorno (preferencias, posibilidades, habilidades y condiciones) y los compara con otros lugares del mundo.","Busca información sobre celebraciones, festividades y efemérides locales y nacionales y compara aspectos relevantes con los de otras culturas (tipo de celebración, dónde se desarrolla, momento del año y algunas actividades típicas).","Utiliza diferentes unidades de tiempo (los momentos del día, la hora, los días de la semana) para expresar rutinas diarias de manera adecuada, según el contexto.","Reconoce la diversidad presente en opiniones, gustos y modos de vivir, en producciones orales y escritas."]', 'PdA p. 64'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Exploración de la diversidad de usos, costumbres, rutinas y actividades recreativas en distintos contextos, y en vínculo con la valoración del ambiente.', 'pda_2025', 1, 'Reconocer y valorar la diversidad de orígenes, prácticas culturales y variedades lingüísticas del inglés; establecer comparaciones con la propia cultura, e identificar y cuestionar estereotipos, para promover una convivencia sensible y responsable en las diferencias.', '["Explica las costumbres y los modos de vida en distintos lugares de su país y del mundo.","Relaciona actividades cotidianas y de recreación, en nuestras culturas y en otras.","Describe sus preferencias y obligaciones en torno a las actividades cotidianas y las de tiempo libre, y las compara con otros contextos.","Describe formas de reciclaje y reconoce su valor para un presente y futuro sostenible."]', 'PdA p. 64'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Exploración de la diversidad de modos de comunicación en entornos digitales, y valoración del uso responsable de las tecnologías.', 'pda_2025', 1, 'Reconocer y valorar la diversidad de orígenes, prácticas culturales y variedades lingüísticas del inglés; establecer comparaciones con la propia cultura, e identificar y cuestionar estereotipos, para promover una convivencia sensible y responsable en las diferencias.', '["Utiliza el registro apropiado (formal o informal), según el tipo de comunicación.","Reconoce distintos canales de comunicación (e-mails formales e informales, folletos de publicidad) y sus características básicas (uso de emoticones, abreviaturas y reglas de netiquette).","Identifica y compara diferentes redes sociales, y cómo puede socializar a través de ellas.","Promueve el uso responsable de las tecnologías, para proteger la intimidad propia y de las demás personas."]', 'PdA p. 65'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Desarrollo progresivo de la comprensión de preguntas e instrucciones de creciente complejidad, tales como las requeridas para realizar tareas.', 'pda_2025', 1, 'Comprender el sentido global e identificar información específica en textos orales, de creciente complejidad, provenientes de diversas fuentes, utilizando diferentes estrategias con la guía de la/el docente.', '["Realiza las actividades o tareas áulicas de acuerdo con las instrucciones de la/del docente","Comprende preguntas abiertas y cerradas (yes-no y wh-questions) que formula la/el docente.","Identifica palabras clave y detalles, en instrucciones o preguntas que incluyen más de un paso."]', 'PdA p. 68'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento del propósito y contenido principal en textos orales breves, como conversaciones, llamadas telefónicas o descripciones en programas informativos.', 'pda_2025', 1, 'Comprender el sentido global e identificar información específica en textos orales, de creciente complejidad, provenientes de diversas fuentes, utilizando diferentes estrategias con la guía de la/el docente.', '["Infiere el tema y el propósito comunicativo (describir, informar, ordenar) en un audio claro y pausado, por ejemplo, una llamada telefónica.","Reconoce datos específicos en anuncios simples de transporte (línea, parada, horario) y realiza la acción adecuada.","Identifica información específica en textos orales (fechas y lugares de eventos, actividades, celebraciones) a partir de temas trabajados y resuelve consignas en función de ello."]', 'PdA p. 68'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Desarrollo de estrategias de escucha comprensiva, como la formulación de hipótesis, la inferencia y la asociación de información visual, gestual y contextual, para comprender textos orales de circulación social.', 'pda_2025', 1, 'Comprender el sentido global e identificar información específica en textos orales, de creciente complejidad, provenientes de diversas fuentes, utilizando diferentes estrategias con la guía de la/el docente.', '["Anticipa, con ayuda de imágenes o títulos, el tema de un texto antes de escuchar su lectura.","Formula hipótesis guiada/o por la/el docente, sobre el contenido de un texto, a partir del título, las imágenes, los sonidos del contexto de enunciación y sus conocimientos previos.","Deduce el significado de palabras o frases desconocidas, a partir de imágenes, gestos y elementos del contexto de enunciación.","Infiere el tema general de un texto oral a partir de la comprensión de palabras clave, imágenes y referencias contextuales."]', 'PdA p. 69'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interpretación global de textos literarios simples en lengua inglesa, y apreciación de su valor estético, creativo y lúdico.', 'pda_2025', 1, 'Comprender el sentido global e identificar información específica en textos orales, de creciente complejidad, provenientes de diversas fuentes, utilizando diferentes estrategias con la guía de la/el docente.', '["Colabora en actividades grupales e individuales de escucha de textos literarios, y reconoce información general y específica con algún apoyo por parte de la/del docente.","Identifica la trama general y los temas que se abordan en textos literarios relacionados con situaciones conocidas, a partir de palabras o estructuras simples.","Reconoce aspectos estéticos en los textos literarios trabajados, como la descripción de personajes y lugares."]', 'PdA p. 69'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interacción oral básica en situaciones del aula, con mayor autonomía, a partir de preguntas, instrucciones y consignas frecuentes.', 'pda_2025', 1, 'Participar en la producción oral de textos simples, con diversos propósitos, e interactuar en situaciones cotidianas de intercambio de ideas e información que incluyan algunos recursos paraverbales y no verbales, adecuados a la situación comunicativa, al destinatario y al propósito.', '["Interactúa oralmente en situaciones cotidianas del aula, respondiendo a consignas y preguntas frecuentes.","Formula preguntas simples y da respuestas breves, para resolver dudas o intercambiar información sobre tareas escolares."]', 'PdA p. 72'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Participación en interacciones propias de situaciones comunicativas cotidianas, en ámbitos escolares y sociales, y con creciente autonomía.', 'pda_2025', 1, 'Participar en la producción oral de textos simples, con diversos propósitos, e interactuar en situaciones cotidianas de intercambio de ideas e información que incluyan algunos recursos paraverbales y no verbales, adecuados a la situación comunicativa, al destinatario y al propósito.', '["Responde preguntas (Wh-questions) sobre temas conocidos, como sus actividades cotidianas, utilizando oraciones sencillas.","Participa en intercambios orales sencillos con la/el docente o con sus compañeras/os, a partir de una función comunicativa que requiere alguna de las estructuras trabajadas sobre los temas tratados, desarrollando, gradualmente, mayor fluidez y precisión gramatical.","Realiza preguntas para obtener información adicional, mostrando interés por el contenido.","Propone sugerencias o expresa intenciones, con oraciones básicas que evidencian mayor autonomía en la interacción oral."]', 'PdA p. 72'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Presentación oral de trabajos simples, con mayor extensión y precisión, sobre sí misma/o, personas cercanas o temas conocidos, a partir del uso de las estructuras trabajadas.', 'pda_2025', 1, 'Participar en la producción oral de textos simples, con diversos propósitos, e interactuar en situaciones cotidianas de intercambio de ideas e información que incluyan algunos recursos paraverbales y no verbales, adecuados a la situación comunicativa, al destinatario y al propósito.', '["Realiza presentaciones orales breves sobre sí misma/o, incorporando información personal, gustos y rutinas diarias.","Describe a compañeras/os o personas cercanas, incluyendo características físicas y de personalidad, a partir del uso del vocabulario incorporado.","Presenta información organizada sobre objetos, lugares o animales relacionados con temas del aula, usando conectores simples.","Participa en presentaciones grupales, respetando turnos de habla, y colaborando en la organización del contenido."]', 'PdA p. 73'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Participación en actividades grupales más estructuradas, como diálogos extendidos, dramatizaciones, representaciones o lecturas guiadas.', 'pda_2025', 1, 'Participar en la producción oral de textos simples, con diversos propósitos, e interactuar en situaciones cotidianas de intercambio de ideas e información que incluyan algunos recursos paraverbales y no verbales, adecuados a la situación comunicativa, al destinatario y al propósito.', '["Interpreta roles en dramatizaciones breves, que incluyen información básica sobre hobbies, rutinas o experiencias, a partir del uso de oraciones claras.","Participa en actividades orales que requieren pedir ayuda, proponer ideas o expresar acuerdo, empleando recursos paraverbales (entonación, pausas) y no verbales (gestos, contacto visual) para acompañar la interacción.","Memoriza y representa oralmente personajes en dramatizaciones sencillas."]', 'PdA p. 73'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión global y específica de textos escritos en distintos soportes y con distintos propósitos, relacionados con situaciones de la vida cotidiana, escolar y familiar, que incluyen consignas e instrucciones, como artículos digitales, descripciones, relatos, direcciones, menúes, narraciones, cartelería en lugares públicos.', 'pda_2025', 1, 'Leer y comprender textos variados, cortos y simples, ficcionales y no ficcionales, sobre temas familiares y de cultura general con diferentes propósitos comunicativos; haciendo uso de estrategias de lectura conocidas.', '["Desarrolla tareas más complejas, a partir de la lectura de consignas escritas simples, acompañadas de íconos/ imágenes.","Interpreta la idea global de un texto simple y breve a partir de la selección de títulos de cada sección, con el apoyo de imágenes, y acompañadas/os por la/el docente.","Identifica ideas específicas de un texto simple y breve, relacionadas con palabras conocidas y transparentes, y sobre temáticas trabajadas, con mayor autonomía."]', 'PdA p. 76'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Exploración de pistas visuales, temáticas y lingüístico-discursivas, para construir sentidos del texto.', 'pda_2025', 1, 'Leer y comprender textos variados, cortos y simples, ficcionales y no ficcionales, sobre temas familiares y de cultura general con diferentes propósitos comunicativos; haciendo uso de estrategias de lectura conocidas.', '["Anticipa el tema general de textos simples y breves, a partir de imágenes, títulos y subtítulos, con mayor autonomía.","Identifica palabras simples y compuestas, mayormente conocidas y transparentes, para inferir significados de palabras o expresiones presentes en el texto y su idea general.","Reconoce el propósito general del texto (describir, relatar, informar, ordenar, sugerir, invitar, opinar), con ayuda docente.","Identifica, con ayuda docente, la organización básica de un texto breve (inicio, desarrollo, cierre), para comprender mejor las ideas.","Identifica información clave en avisos y publicaciones comerciales (precio final, descuentos, cuotas/intereses, condiciones de devolución) y decide si el mensaje es publicitario o informativo."]', 'PdA p. 77'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación de sentidos globales de textos literarios variados, y en vínculo con otras lenguas, como historietas, cómics, cuentos breves, poemas, descripciones, y de otros textos, como entrevistas o noticias adaptadas, con apoyatura de material visual.', 'pda_2025', 1, 'Leer y comprender textos variados, cortos y simples, ficcionales y no ficcionales, sobre temas familiares y de cultura general con diferentes propósitos comunicativos; haciendo uso de estrategias de lectura conocidas.', '["Infiere el significado global de una historia o poema a partir de palabras conocidas y transparentes y de imágenes, con ayuda docente.","Lee fragmentos de textos narrativos en voz alta, a partir de un audio o un modelo provisto por la/el docente.","Reconoce expresiones literarias simples, en historietas y fragmentos de cuentos breves, con la ayuda docente.","Identifica información específica en textos literarios, como acciones principales o relaciones entre personajes, a partir de conocimientos previos."]', 'PdA p. 77'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación progresiva de conectores y marcadores discursivos, en narraciones simples y secuencias de eventos.', 'pda_2025', 1, 'Leer y comprender textos variados, cortos y simples, ficcionales y no ficcionales, sobre temas familiares y de cultura general con diferentes propósitos comunicativos; haciendo uso de estrategias de lectura conocidas.', '["Ordena cronológicamente eventos de una narración breve, a partir de imágenes, marcadores temporales y de la comprensión general del texto.","Reconoce frases de secuencia más elaboradas, como in the first place, then, at the end, en cuentos u otras narraciones trabajadas en clase."]', 'PdA p. 77'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Elaboración de textos breves sobre temas conocidos, como descripciones, entrevistas, infografías o publicaciones digitales, con la apoyatura de modelos y guías.', 'pda_2025', 1, 'Escribir textos de variada complejidad sobre diversos temas; tener en cuenta el proceso de producción; respetar las convenciones de la lengua inglesa escrita y hacer uso de manera procesual de estrategias de escritura.', '["Redacta breves descripciones o comentarios para publicaciones digitales, sobre temáticas cotidianas, con la apoyatura de modelos.","Emplea vocabulario relacionado con el tema para escribir entrevistas, cuadros comparativos u otros textos breves.","Aporta ideas en la escritura colaborativa de textos sencillos y revisa los aportes de sus compañeras/os, a partir de modelos.","Escribe textos simples, en papel o formato digital, considerando el propósito comunicativo y el contenido a desarrollar."]', 'PdA p. 81'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de expresiones estructuradas, para compartir preferencias y opiniones simples sobre temas cotidianos, con reflexión acompañada, sobre las convenciones de la lengua escrita.', 'pda_2025', 1, 'Escribir textos de variada complejidad sobre diversos temas; tener en cuenta el proceso de producción; respetar las convenciones de la lengua inglesa escrita y hacer uso de manera procesual de estrategias de escritura.', '["Redacta textos breves, donde combina frases para expresar opiniones, gustos y preferencias, a través del uso de conectores básicos (I like reading books; I don’t enjoy watching TV, but I love listening to music).","Reconoce convenciones básicas de la lengua escrita, como el uso de mayúsculas en nombres propios y títulos, y fórmulas de apertura y cierre en correos o mensajes.","Emplea signos de puntuación y ortografía, para separar oraciones e ideas en textos simples."]', 'PdA p. 81'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Desarrollo progresivo de estrategias de escritura, como la planificación, la revisión y la reformulación de textos simples, a partir de esquemas provistos, con apoyo docente.', 'pda_2025', 1, 'Escribir textos de variada complejidad sobre diversos temas; tener en cuenta el proceso de producción; respetar las convenciones de la lengua inglesa escrita y hacer uso de manera procesual de estrategias de escritura.', '["Interpreta la estructura de una guía o plan previo, para organizar ideas y desarrollar textos simples.","Sigue un plan, proporcionado por la/el docente, para redactar textos con un propósito específico.","Produce una primera versión del texto como borrador y realiza ajustes básicos a partir de las correcciones y feedback proporcionados por la/el docente.","Explica algún cambio realizado en el texto a partir de la retroalimentación recibida.","Ajusta el texto a partir del feedback recibido, incorporando correcciones sobre contenido, vocabulario o estructura."]', 'PdA p. 82'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento y comparación, con ayuda de la/del docente, de relaciones entre sonidos y ortografía del inglés, en palabras y frases breves, y de formas de entonación frecuentes en enunciados simples, en contraste con el español.', 'pda_2025', 1, 'Identificar, reflexionar y sistematizar aspectos fundamentales del funcionamiento de la lengua extranjera, de manera inductiva, en uso y contextualizada, a partir de textos orales y escritos que son parte de situaciones comunicativas concretas.', '["Identifica y compara con ayuda docente, sonidos vocálicos y consonánticos en palabras y frases breves, relacionando su pronunciación con la ortografía.","Reconoce y comienza a reproducir patrones básicos de entonación, en frases y preguntas frecuentes, a partir de modelos compartidos."]', 'PdA p. 85'),
(16, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de expresiones y formas frecuentes del inglés, en relación con estructuras del español, para ampliar recursos lingüísticos y construir enunciados sobre situaciones cotidianas.', 'pda_2025', 1, 'Identificar, reflexionar y sistematizar aspectos fundamentales del funcionamiento de la lengua extranjera, de manera inductiva, en uso y contextualizada, a partir de textos orales y escritos que son parte de situaciones comunicativas concretas.', '["Identifica verbos y expresiones de tiempo (every day, at the moment) para comprender y comunicar eventos de la vida cotidiana.","Reconoce y utiliza la forma plural de sustantivos (regular and irregular forms), en contextos vinculados con la alimentación saludable.","Usa, con mayor autonomía, combinaciones frecuentes de verbos y sustantivos o actividades cotidianas (collocations) en presente (go shopping, do homework, have dinner).","Utiliza afirmaciones, interrogaciones y negaciones en tiempo presente (Simple Present), para hablar sobre acciones cotidianas y describir eventos y situaciones.","Reconoce y utiliza el verbo modal can para pedir permiso, solicitar favores y expresar posibilidad, en afirmaciones, preguntas y negaciones.","Reconoce y utiliza el tiempo verbal Present Continuous en afirmaciones, negaciones e interrogaciones, para hablar de acciones que se están desarrollando en ese momento.","Brinda información sobre actividades cotidianas y celebraciones, utilizando there is / there are con expresiones de cantidad."]', 'PdA p. 85'),
(16, 'objetivo', 'Objetivo', 'Desarrollar gradual y progresivamente estrategias de comprensión y producción de textos orales y escritos, ficcionales y no ficcionales a través del reconocimiento de la organización textual, la comprensión del léxico, el sentido del texto, mediante la gestión de situaciones comunicativas orales y escritas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(16, 'objetivo', 'Objetivo', 'Desarrollar habilidades lingüísticas, pragmáticas, discursivas, estratégicas y sociolingüísticas para la comprensión y la producción de textos orales y escritos en forma gradual y progresiva, a partir del abordaje de textos de estructura simple y de complejidad creciente, respondiendo a consignas de una o más instrucciones.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(16, 'objetivo', 'Objetivo', 'Aplicar gradualmente los recursos tecnológicos que facilitan el proceso de aprendizaje del inglés, de acuerdo con los formatos seleccionados.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(16, 'objetivo', 'Objetivo', 'Formarse progresivamente como lector autónomo, mediante el acceso a textos informativos de interés general y al discurso literario, a través de la interacción con distintos géneros adaptados al nivel de los estudiantes.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(16, 'objetivo', 'Objetivo', 'Fortalecer la reflexión en relación con las capacidades requeridas para el aprendizaje de la lengua en los aspectos metacognitivo, metacomunicativo, metalingüístico e intercultural.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(16, 'objetivo', 'Objetivo', 'Desarrollar progresivamente estrategias para regular logros y dificultades en la comprensión y producción de textos orales y escritos, la adquisición gradual de habilidades lingüísticas, pragmáticas, discursivas, estratégicas y sociolingüísticas, y la formación intercultural.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(16, 'objetivo', 'Objetivo', 'Desarrollar gradualmente las actitudes vinculadas con las relaciones interpersonales, la confianza en sus propias posibilidades, la relación con el conocimiento y el respeto por lo diferente.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(16, 'eje_contenido', 'Oralidad (hablar)', 'Participación activa en intercambios de complejidad creciente sobre temáticas abordadas relacionadas con la experiencia del estudiante y que le son significativas (con énfasis gradual en la fluidez y precisión gramatical).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(16, 'eje_contenido', 'Oralidad (hablar)', 'Uso de fórmulas sociales, vocabulario y expresiones idiomáticas pertinentes en intercambios cotidianos, formales e informales, teniendo en cuenta los recursos no verbales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109');
INSERT INTO `curriculum_contenidos` (`espacio_id`, `tipo`, `titulo`, `descripcion`, `fuente`, `vigente`, `meta`, `indicadores`, `pagina`) VALUES
(16, 'eje_contenido', 'Oralidad (hablar)', 'Reconocimiento y uso de los aspectos lingüísticos, pragmáticos y sociolingüísticos para la producción de textos orales de acuerdo con las temáticas abordadas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(16, 'eje_contenido', 'Oralidad (escuchar)', 'Adquisición y enriquecimiento de estrategias de comprensión de textos orales relacionados con la experiencia del estudiante y que le son significativos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(16, 'eje_contenido', 'Escritura', 'Producción de diálogos cortos de complejidad creciente, narraciones con descripciones sencillas en forma de párrafo, postales y/o cartas informales, e-mails.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(16, 'eje_contenido', 'Lectura', 'Comprensión de la información global y específica (skimming, scanning) de textos sencillos relacionados con temáticas abordadas y del interés y necesidad de los estudiantes, para extraer la información requerida.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(16, 'eje_contenido', 'Lectura', 'Exploración de los diferentes tipos textuales (diálogo, relato breve, publicidad, folleto) y reconocimiento de sus propósitos y modos de distribución de la información, de acuerdo con el contexto de la situación.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(16, 'eje_contenido', 'Lectura', 'Práctica de comprensión de textos literarios de dificultad creciente implementando estrategias de complejidad gradual.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(16, 'eje_contenido', 'Temáticas sugeridas', 'La vida personal y social: celebraciones personales, locales y nacionales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(16, 'eje_contenido', 'Temáticas sugeridas', 'Participación en situaciones de lectura de textos literarios: comics, historietas, relatos, poesías, canciones, cuentos cortos adaptados al nivel del estudiante.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 105-109'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Reconocimiento del entorno natural y artificial/cultural como espacio susceptible de ser interpretado y/o intervenido estéticamente (paisajes visuales), a través de diferentes recursos visuales (safaris fotográficos, aplicaciones digitales, realidad aumentada, entre otros).', 'pda_2025', 1, 'Construir una perspectiva que integre los componentes del código visual en diferentes experiencias, prácticas y producciones artísticas contemporáneas, para desarrollar lecturas divergentes de las intencionalidades expresivo-comunicativas y de la valoración del patrimonio cultural.', '["Observa, a través de registros mediados por tecnologías (videos, imágenes satelitales, uso de visores, apuntes gráficos, fotografías, entre otros), en caso de ser posible, el entorno urbano y/o natural, para reconocer características de diferentes zonas y/o barrios de la ciudad de Córdoba y de otras ciudades.","Identifica vinculaciones entre entornos y producciones artísticas, avanzando en la conceptualización de “construcciones culturales”.","Formula hipótesis sobre las diferentes funciones comunicativo-culturales que pueden tener las obras artísticas en el espacio público.","Identifica la saturación visual y su relación con la industria publicitaria, para construir nociones vinculadas con la contaminación visual del paisaje.","Distingue entre imágenes con movimiento real de aquellas con movimiento ilusorio o aparente (fenómenos de ilusión óptica), y sus funciones en el espacio urbano.","Evidencia su percepción del espacio a través de las nociones de proximidad/lejanía, superposición de formas y horizonte del paisaje urbano y/o natural."]', 'PdA p. 62'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Análisis de producciones visuales, propias y ajenas, con observación de la diversidad simbólica y las intenciones comunicativas, para identificar las decisiones tomadas a lo largo del proceso de producción y establecer relaciones entre la intencionalidad comunicativa y la producción de sentido estético.', 'pda_2025', 1, 'Construir una perspectiva que integre los componentes del código visual en diferentes experiencias, prácticas y producciones artísticas contemporáneas, para desarrollar lecturas divergentes de las intencionalidades expresivo-comunicativas y de la valoración del patrimonio cultural.', '["Identifica y nombra componentes formales y compositivos utilizados en su producción, reconociendo su efecto visual y expresivo a través de un vocabulario técnico adecuado.","Describe su proceso creativo, para evidenciar las decisiones técnicas adoptadas y cómo estas expresan su intención estética y comunicativa.","Reflexiona sobre su proceso de producción, identifica decisiones estéticas o temáticas que le resultaron significativas y expresa sus motivaciones personales.","Comparte su valoración personal sobre las producciones de pares o artistas (locales, nacionales o internacionales) y reconoce elementos que le generan identificación, extrañamiento o cuestionamiento","Expresa su mirada crítica sobre los resultados obtenidos, interpretando las características visuales de su obra en diálogo con movimientos artísticos o referentes abordados.","Interpreta visualmente, de forma diferenciada, los sentidos literales y metafóricos de las imágenes observadas, proponiendo hipótesis desde su perspectiva sensible y cultural."]', 'PdA p. 62'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Participación reflexiva en encuentros, muestras y espectáculos, dentro y fuera de la escuela, para valorar las producciones artísticas de diversos lenguajes visuales (plateros, fotógrafos, ceramistas, tejedores, ilustradores, artesanos, escenógrafos, entre otros) que conforman el patrimonio cultural local, provincial y nacional.', 'pda_2025', 1, 'Construir una perspectiva que integre los componentes del código visual en diferentes experiencias, prácticas y producciones artísticas contemporáneas, para desarrollar lecturas divergentes de las intencionalidades expresivo-comunicativas y de la valoración del patrimonio cultural.', '["Indaga vivencialmente acerca de las producciones artísticas que integran el patrimonio cultural local, provincial y nacional, como parte del ejercicio de una ciudadanía cultural plena.","Describe las características de los diversos lenguajes artísticos, sus similitudes y diferencias, como parte del patrimonio cultural local.","Reconoce el valor artístico y cultural de variadas producciones y prácticas, y su vinculación con la identidad cultural.","Argumenta, de manera oral o escrita, acerca de los sentidos estético-comunicativos de las prácticas y producciones vivenciadas."]', 'PdA p. 63'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Análisis de propuestas culturales presentes en su entorno inmediato, para favorecer la identificación de algunos de los circuitos de producción (talleres, cursos), exhibición (centros culturales, galerías, centros vecinales) y circulación (ferias, eventos especiales, concursos) artístico-culturales.', 'pda_2025', 1, 'Construir una perspectiva que integre los componentes del código visual en diferentes experiencias, prácticas y producciones artísticas contemporáneas, para desarrollar lecturas divergentes de las intencionalidades expresivo-comunicativas y de la valoración del patrimonio cultural.', '["Indaga a través de fuentes diversas (páginas web oficiales y/o privadas, publicidades, artículos periodísticos, entrevistas a referentes —vecinas/os, familiares, entre otros— ) acerca de los espacios artísticos-culturales cercanos, sus características, propuestas, horarios y otra información relevante.","Desarrolla dispositivos comunicacionales analógicos y/o digitales (folletos, afiches publicitarios, vídeos promocionales, podcast, entre otros) para compartir la información relevada.","Participa de instancias escolares de socialización y difusión de producciones desarrolladas.","Compara y valora similitudes y diferencias entre las distintas prácticas y lenguajes artísticos (visuales, audiovisuales, performáticos) presentes en su entorno inmediato, para evidenciar su interpretación.","Reflexiona acerca de las propuestas, posibilidades de acceso y la participación de la oferta cultural próxima y su variedad."]', 'PdA p. 63'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Indagación sobre producciones visuales propias y ajenas (imágenes fijas o en movimiento), reconocimiento de los factores culturales presentes (tensiones culturales, hibridaciones, entre otras) y establecimiento de vínculos entre la propia sensibilidad y otras posibilidades estético-expresivas.', 'pda_2025', 1, 'Construir una perspectiva que integre los componentes del código visual en diferentes experiencias, prácticas y producciones artísticas contemporáneas, para desarrollar lecturas divergentes de las intencionalidades expresivo-comunicativas y de la valoración del patrimonio cultural.', '["Realiza lecturas personales de una misma obra y reconoce las sensaciones, los recuerdos o las ideas que le provoca.","Diferencia entre el significado literal y el metafórico en producciones visuales, vinculando esos sentidos con su propia experiencia.","Compara, con actitud reflexiva y respetuosa, producciones ajenas e identifica decisiones estéticas, recursos expresivos y sentidos construidos, reconociendo la diversidad cultural.","Identifica elementos visuales que expresan la interacción cultural entre pueblos originarios, afrodescendientes, europeos, entre otros, tanto históricos como contemporáneos.","Reconoce expresiones artísticas que dialogan con memorias colectivas, territorios, conflictos sociales, problemáticas de género y diversidades.","Expresa su mirada sobre los vínculos entre arte, identidad y pertenencia cultural, en diferentes regiones."]', 'PdA p. 64'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Aproximación a prácticas de diferentes culturas (de pueblos originarios, latinoamericanas, afrodescendientes, europeas, entre otras) presentes en el entorno cercano, para identificar vínculos entre arte, territorio, memoria e identidad y vivenciar, a través de registros audiovisuales (documentales, cortometrajes), fotográficos, el rol social del arte en su comunidad.', 'pda_2025', 1, 'Construir una perspectiva que integre los componentes del código visual en diferentes experiencias, prácticas y producciones artísticas contemporáneas, para desarrollar lecturas divergentes de las intencionalidades expresivo-comunicativas y de la valoración del patrimonio cultural.', '["Reconoce elementos visuales que expresan tradiciones, tensiones o hibridaciones culturales, en prácticas de diferentes regiones.","Establece relaciones entre producciones visuales y contextos territoriales, sociales o históricos, con una mirada reflexiva.","Participa, con compromiso y respeto, en experiencias culturales (rituales, eventos festivos, entre otros) e interpreta sentidos simbólicos y/o comunicativos.","Elabora producciones visuales, textuales o digitales, que expresan una perspectiva crítica acerca del valor del arte en su comunidad.","Identifica expresiones culturales locales, como formas de construcción de identidad y memoria colectiva."]', 'PdA p. 64'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Indagación en torno a prácticas y/o producciones visuales de variadas épocas, espacios, géneros y estilos, y detección de características formales, compositivas y expresivas que despierten su interés,curiosidad,reflexión y le permitan construir interpretaciones situadas acerca de las diferentes maneras de ver el mundo y de representarlo.', 'pda_2025', 1, 'Construir conocimientos significativos en relación con la identidad y la valoración del patrimonio cultural, comprendiendo el sentido de las prácticas y producciones artísticas en el marco del contexto sociohistórico y cultural en el que se producen.', '["Identifica y describe elementos compositivos (relación figurafondo, equilibrio visual, entre otros) y componentes expresivo-comunicativos (lo connotado, lo denotado, entre otros), en obras de diferentes contextos.","Reconoce y reflexiona sobre el papel de la/del espectadora/or o público en cada producción y/o práctica abordada, y analiza cómo su presencia o ausencia modifica el sentido de la obra en diferentes contextos.","Compara y valora similitudes y diferencias en el tratamiento estético-visual y sus funciones en la representación de la figura humana en las obras de arte, publicidades y medios de comunicación e identifica entre retratos naturalistas y representaciones estilizadas (geometrización, síntesis, exaltación de rasgos, entre otras).","Analiza y evalúa las características del arte urbano (monumentos, murales, esténcil, grafiti, entre otros) mediante registros propios o ajenos, y/o recorridos físicos y/o virtuales, y construye la noción de arte urbano, diferenciando entre el arte en el espacio público y el espacio privado.","Reflexiona acerca de los modos de representación de los paisajes urbanos, rurales y naturales (de artistas viajeras/os del siglo XIX, paisajistas cordobesas/es, artistas contemporáneas/os, entre otros) y las representaciones idealizadas (Xul Solar, Gyula Kosice, entre otros), para detectar características representativas."]', 'PdA p. 65'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Valoración de las prácticas y producciones artísticas que integran el patrimonio cultural local, provincial y nacional, como parte del ejercicio de una ciudadanía cultural plena.', 'pda_2025', 1, 'Construir conocimientos significativos en relación con la identidad y la valoración del patrimonio cultural, comprendiendo el sentido de las prácticas y producciones artísticas en el marco del contexto sociohistórico y cultural en el que se producen.', '["Identifica factores que determinan el valor artístico (trayectoria, legitimación, entre otros) y cultural de variadas producciones artísticas.","Reconoce la vinculación entre producciones, identidad cultural y contextos de producción, circulación y exhibición.","Construye progresivamente, desde lo experimentado, el respeto por la diversidad cultural y sus manifestaciones.","Ensaya argumentaciones, orales y/o escritas, para expresar la diferencia entre el concepto de visión (como acto fisiológico) y la noción de mirada (como construcción cultural), a través del uso de ejemplos que recupera de obras y/o prácticas estudiadas."]', 'PdA p. 66'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Reflexión crítica acerca de la relación entre las temáticas de las prácticas artísticas y los contextos culturales de circulación (el barrio, el entorno urbano, el entorno rural, la provincia, el país, la región, las redes sociales, entre otros), a través de diferentes épocas y geografías.', 'pda_2025', 1, 'Construir conocimientos significativos en relación con la identidad y la valoración del patrimonio cultural, comprendiendo el sentido de las prácticas y producciones artísticas en el marco del contexto sociohistórico y cultural en el que se producen.', '["Relaciona los contextos con las posibilidades estético-expresivas y temáticas de las manifestaciones artísticas que albergan.","Detecta similitudes y diferencias entre las prácticas y las producciones artísticas, según el contexto.","Reconoce la construcción de metáforas en lo observado y la noción de poéticas, en función de las temáticas abordadas.","Utiliza aplicaciones digitales y de realidad aumentada para conocer estéticas urbanas del pasado y del presente, en distintas ciudades del mundo."]', 'PdA p. 66'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Reflexión crítica acerca de la relación entre las imágenes visuales, los contextos y los circuitos de circulación (museos, clubes, teatros, plazas, calles, cine, redes sociales, entre otros), con especial énfasis en los medios de comunicación.', 'pda_2025', 1, 'Construir conocimientos significativos en relación con la identidad y la valoración del patrimonio cultural, comprendiendo el sentido de las prácticas y producciones artísticas en el marco del contexto sociohistórico y cultural en el que se producen.', '["Identifica las prácticas culturales que desarrolla individualmente, con su grupo de pares y/o con su familia.","Describe los factores (económicos, psicológicos, sociales, culturales, entre otros) que determinan sus elecciones de prácticas y consumos culturales.","Indaga, de acuerdo con sus intereses personales, acerca de procesos creativos de artistas locales, nacionales y latinoamericanas/os y reconoce las relaciones entre contexto, técnica y discurso visual (ámbitos y herramientas de la creación contemporánea).","Analiza los aspectos éticos y estéticos en la difusión y circulación de imágenes, como imagen pública y privada, consentimiento expreso para la difusión de imágenes, respeto por las diferencias, libertad de expresión y censura.","Problematiza la circulación de imágenes (la fotografía, la fotocopia, los memes, las modificaciones con aplicaciones de IA, entre otras) a través de las plataformas digitales, en el mundo contemporáneo.","Establece relaciones entre circulación de imágenes y prácticas intimidatorias (bullying, ciberacoso, grooming, entre otras) por medio de las tecnológicas digitales."]', 'PdA p. 66'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Análisis de los procesos de producción artística, decisiones autorales e intencionalidades comunicativas, según las dimensiones históricas, sociales, culturales y políticas, a partir de sus aspectos formales y estéticos.', 'pda_2025', 1, 'Construir conocimientos significativos en relación con la identidad y la valoración del patrimonio cultural, comprendiendo el sentido de las prácticas y producciones artísticas en el marco del contexto sociohistórico y cultural en el que se producen.', '["Reconoce las relaciones entre el contexto histórico-social y las temáticas abordadas en obras artísticas de distintas épocas y culturas.","Analiza cómo las decisiones autorales en una obra (técnica, formato, temática, tratamiento estético) responden o reaccionan frente a las problemáticas sociales, políticas o culturales de su tiempo.","Interpreta el rol del arte como medio de comunicación, denuncia, resistencia o transformación social, a partir del análisis de producciones artísticas contextualizadas.","Establece comparaciones entre producciones artísticas de distintos contextos, e identifica las continuidades o rupturas en relación con los discursos sociales, culturales y/o políticos que expresan.","Ensaya argumentaciones acerca del sentido y la función social de las obras analizadas, integrando referencias al contexto y al lenguaje artístico."]', 'PdA p. 67'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Indagación sobre las formas de representación de la figura humana (retratos, autorretratos, cuerpo completo, estereotipos, estática, en movimiento, entre otras), en diferentes contextos y períodos históricos.', 'pda_2025', 1, 'Construir conocimientos significativos en relación con la identidad y la valoración del patrimonio cultural, comprendiendo el sentido de las prácticas y producciones artísticas en el marco del contexto sociohistórico y cultural en el que se producen.', '["Explora la noción de canon estético y representaciones de género estereotipadas e invisibilizadas, en diferentes producciones.","Reconoce las diversas representaciones e intencionalidades en el uso de la figura humana.","Demuestra una mirada crítica en los análisis que desarrolla acerca de las representaciones vinculadas con la figura humana.","Participa en debates sobre las representaciones estereotipadas de género, el lugar asignado en los circuitos de producción artística y el rol en la construcción identitaria."]', 'PdA p. 67'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Realización de producciones bidimensionales exploratorias (dibujos, pinturas, grabados, collage, fotografías, entre otras) utilizando diversos materiales y soportes (analógicos, digitales, convencionales, reutilizables, recuperados) a partir de diferentes estrategias constructivas, en busca de una imagen propia.', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Reconoce, en diversas producciones artísticas (cuadros, fotografías, murales) y entornos cotidianos (avenidas, paisajes), los elementos formales de la perspectiva (línea de horizonte, puntos de fuga, posición de la/del observadora/or, entre otros).","Implementa el uso de la perspectiva para representar el mundo que la/o rodea y los escenarios imaginarios.","Experimenta con el grabado y sus diferentes variantes (monocopia, sellos, xilografía, entre otras).","Investiga las posibilidades estéticas de técnicas fotográficas antiguas y sostenibles, como cianotipia, antotipia, cromotipia, entre otras.","Explora diferentes estrategias constructivas a partir del uso del color (mancha, transparencia, veladuras, mezclas, tono, contraste, entre otras), de la textura (visual, táctil, propia, generada), del collage, la fotografía, el fotomontaje, reconociendo las similitudes y diferencias de sus posibilidades expresivas, estéticas y formales (paleta pigmentaria, paleta gráfica, paleta lumínica).","Construye, progresivamente, una imagen propia en cada producción bidimensional desarrollada."]', 'PdA p. 68'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Organización de la composición y selección de opciones con mayores niveles de intencionalidad estética, entre las formas, los espacios y los grados de relación (simple-simple, complejo-simple, complejo-complejo).', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Indaga acerca de la noción de equilibrio visual, por medio de la experimentación con diferentes variantes (simétrico, asimétrico, radial).","Ensaya composiciones bidimensionales, atendiendo a la organización intencional de las formas (figurativas y no figurativas, entre otras), los espacios, los indicadores y los grados de relación (figura simple o compleja sobre fondos simples o complejos y variantes).","Ordena las composiciones, considerando tamaños del plano, marco, encuadre, formas, luces y sombras.","Explora las tipografías e íconos, como elementos estéticos y narrativos, en las imágenes seriadas.","Experimenta las posibilidades del registro fotográfico secuencial para la representación o ilusión de movimiento, a partir del uso de diferentes tipos de encuadre y de su relación con el contenido significativo de la imagen.","Describe las decisiones compositivas tomadas a lo largo del proceso creativo, se hace preguntas o responde sobre posibles alternativas, proponiendo modificaciones o ajustes y evidenciando sus intencionalidades expresivas."]', 'PdA p. 68'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Experimentación de las cualidades formales y expresivas de materiales, herramientas, soportes, técnicas y procedimientos propios del lenguaje visual, en la representación bidimensional, tanto analógica como digital.', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Combina procedimientos, materialidades y soportes, en función de sus aportes expresivos y simbólicos a lo creado.","Identifica características y usos diversos de las herramientas gráficas y pictóricas, analógicas y digitales.","Relaciona técnicas con los materiales y sus posibilidades plásticas y visuales, y los diferentes componentes con el todo.","Crea herramientas no convencionales para el dibujo, la pintura y las impresiones, de pequeño, mediano y gran formato.","Recupera materiales en desuso y de elementos orgánicos, y reconoce sus cualidades, posibilidades estéticas y de afectación ambiental."]', 'PdA p. 69'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Participación en actividades grupales de producción artística que potencien la socialización, el diálogo y la argumentación, inspiradas en prácticas contemporáneas.', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Trabaja con sus pares ocupando diferentes roles, sin distinción de género, para producir colaborativamente y promoviendo la resolución conjunta de conflictos creativos y/o de ideas divergentes.","Respeta las opiniones de pares, expresa la propia y construye acuerdos de trabajo colaborativo.","Explora las posibilidades del cuerpo como soporte y contenido expresivo en el arte contemporáneo, así como las alternativas que proponen las tecnologías de proyección y ampliación de la imagen (por ejemplo, mapping).","Reconoce las características del tableau vivant, como práctica artística performática, en la que se resignifican obras del pasado.","Selecciona obras artísticas para su apropiación y resignificación considerando sentidos, gestos y contextos."]', 'PdA p. 69'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Creación de dibujos, pinturas, grabados, collage, fotografías, fotomontajes, stopmotion, y vídeos mediante la utilización de diversos materiales y soportes (analógicos, digitales, convencionales, reutilizables, recuperados, no convencionales) y reconocimiento de la dimensión procesual de toda producción artística.', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Reconoce las cualidades del color, como tono, saturación, valor, y explora sus variantes a través de manchas, transparencias, veladuras, mezclas, entre otras.","Juega con diferentes texturas, visuales y táctiles, para enriquecer y complejizar sus producciones, tanto analógicas como digitales.","Emplea los elementos del lenguaje fotográfico y audiovisual (planos, encuadre, ángulos de visión, ley de los tercios, ley de la mirada, entre otros) en producciones con intencionalidad estético-expresiva.","Desarrolla historietas identificando sus elementos formales (viñetas, globos, cartelas, entre otros) y sus posibilidades narrativas y expresivas, en formatos analógicos y/o digitales.","Utiliza la técnica de la perspectiva con diferentes grados de complejidad (a uno, dos y tres puntos de fuga, caballera, isométrica, entre otras) y proyecta instalaciones y/o intervenciones en el espacio.","Avanza en la consolidación de una imagen propia en cada producción bidimensional que desarrolla, a partir del uso de diversas materialidades y soportes, distinguiendo los diferentes momentos del proceso creativo propio y el de sus pares."]', 'PdA p. 70'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Elección de diferentes criterios compositivos para sus producciones, con mayores niveles de intencionalidad estética, vinculada con el uso de formas figurativas y no figurativas, espacios llenos y vacíos, relación entre figura y fondo, equilibrio visual, entre otros.', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Experimenta con diversos criterios compositivos, atendiendo a indicadores espaciales y formales (organización, tamaños y orientación del plano; encuadre; formas, luces, sombras, marco).","Distribuye las formas en el plano a partir de diferentes estrategias (superposición, yuxtaposición, entre otras), para generar la ilusión de cercanía o distancia a través de la distorsión, la deformación expresiva, el extrañamiento, los diferentes tamaños, la variación de la escala.","Explica los criterios compositivos usados en sus producciones cuando opera con figuras y fondos, como, por ejemplo, la dirección (relación entre la posición de las figuras respecto del límite de la imagen) y el intervalo (medida del espacio entre las figuras), evidenciando decisiones tomadas y posibles modificaciones o mejoras.","Utiliza técnicas de calado, troquelado, collage, haciendo uso de diseños en positivo, negativo y fragmentos.","Distingue entre tipos de figuras y formas (abiertas, como las integradas parcial o totalmente al fondo; cerradas, como las aisladas del fondo mediante la presencia de un contorno continuo) y la relación entre el soporte y los elementos visuales.","Incorpora nociones de simetría (aparente, radial, axial, rotacional, traslacional) y asimetría en sus producciones."]', 'PdA p. 70'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Empleo estratégico, en diferentes producciones visuales, de componentes, materiales, herramientas, soportes, técnicas, recursos y procedimientos propios del lenguaje visual, en el espacio bidimensional analógico y/o digital.', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Utiliza diferentes materiales, herramientas, soportes, técnicas y procedimientos —analógicos y digitales— y reconoce sus cualidades formales y expresivas, en función de sus intenciones creativas.","Conoce y hace uso de los elementos característicos de la historieta (viñetas, globos, onomatopeyas, cartelas, entre otros).","Construye una imagen personal de acuerdo con el propio imaginario y las habilidades técnicas adquiridas.","Adquiere experiencia y destreza en la manipulación de materiales, para generar formas singulares e improntas personales que evidencian las marcas gestuales.","Identifica marcas de la gestualidad y la factura, como el trazo, la pincelada, los empastes, entre otros, y su aporte a la creación gráfico-pictórica."]', 'PdA p. 71'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Participación en actividades grupales de producción artística que vinculen problemáticas comunitarias con espacios institucionales, internos y/o externos.', 'pda_2025', 1, 'Conocer y producir representaciones bidimensionales en soportes analógicos y digitales, reconociendo la singularidad de los recursos materiales, los procedimientos, las técnicas gráfico-pictóricas y su potencialidad expresivo-comunicativa.', '["Trabaja con sus pares, ocupando diferentes roles, sin distinción de género, para producir acuerdos de trabajo colaborativo en proyectos interdisciplinarios.","Argumenta oralmente sus opiniones sobre la propuesta temática a desarrollar y respeta opiniones diferentes.","Realiza un trabajo procesual, reconociendo y respetando los tiempos de desarrollo para cada etapa.","Explora el arte textil contemporáneo con el uso de materiales y técnicas tradicionales de pueblos originarios y los combina con materiales no convencionales (como plástico, celuloide, cables, mediante anudados, trenzados) para reconocer los cruces culturales e identitarios vinculados con la producción artística.","Indaga recursos técnicos no tradicionales en producciones artísticas contemporáneas, como el uso de fotocopias, impresiones láser o inkjet , en la confección de historietas de edición limitada, libros de artistas seriados, fanzines, entre otras creaciones vinculadas con los derechos humanos, la niñez y la juventud."]', 'PdA p. 71'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Realización de exploraciones espaciales (interiores, exteriores, tamaños, volúmenes, luces, sombras, formas) por medio de ejercicios con bocetos, programas de diseño, estructuras en pequeños formatos —maquetas, cajas escenográficas— entre otros.', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Experimenta con procedimientos propios de la tridimensionalidad y los volúmenes (agrupar, reducir, yuxtaponer, superponer, adicionar, sustraer, encastrar, entre otros).","Descubre las posibilidades narrativas que brinda la resignificación de objetos, espacios, sonidos, movimientos corporales.","Relaciona producciones escultóricas u objetos resignificados, con fuentes de luz y espacios de emplazamiento, como una unidad expresiva.","Distingue diversos procedimientos compositivos en la producción volumétrico/espacial.","Selecciona y hace uso de espacios, objetos, sonidos o textos, según sus cualidades narrativas, simbólicas y de relación con la historia o respecto de la sensación que se quiere comunicar."]', 'PdA p. 72'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Reconocimiento de cualidades formales y expresivas de materiales, técnicas y procedimientos propios del lenguaje visual, en la representación tridimensional.', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Relaciona materiales y procedimientos técnicos para su tratamiento en el desarrollo de representaciones tridimensionales, de acuerdo con sus características (volúmenes, espacio, tamaños, formas, interiores, exteriores, entre otras).","Identifica técnicas de manipulación (amasado, plegado, encastre, entre otras) y materiales donde se emplean, según sus intenciones estético-expresivas.","Manipula los diferentes elementos, materiales, soportes, técnicas y procedimientos propios del lenguaje visual en la tridimensión y reconoce sus cualidades formales y expresivas."]', 'PdA p. 72'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Exploración de diferentes herramientas digitales para la planificación y el desarrollo de composiciones tridimensionales.', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Descubre la imagen y las experiencias inmersivas, a través de las posibilidades estéticas de la “realidad simulada” y la “realidad aumentada”.","Combina procedimientos en la producción de intervenciones en el espacio arquitectónico (físico o simulado) y sobre el propio cuerpo (a través de máscaras y vestuarios, entre otros).","Determina y utiliza el encuadre, la luz y el movimiento, en función de la intención representativa de las escenas configuradas."]', 'PdA p. 73'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Realización de un proyecto artístico interdisciplinario y colaborativo en el espacio institucional — interior o exterior— con objetos, volúmenes, luces, colores, tiempos, entre otros elementos.', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Crea, en colaboración con sus pares, a partir de acuerdos y roles definidos, sin distinción de género, producciones artísticas espaciales.","Desarrolla bocetos, maquetas preliminares y pruebas con materiales, antes de la ejecución definitiva, para anticipar y ensayar decisiones alternativas.","Explora experiencias artísticas performáticas, como la interacción de lo visual con otros lenguajes (música, teatro, literatura, cine).","Construye lo planificado y lo emplaza en el espacio/ entorno elegido.","Incorpora, progresivamente, la dimensión procesual en sus proyectos artísticos."]', 'PdA p. 73'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Realización de construcciones espaciales en diferentes entornos (dentro del aula, fuera de ella, en plazas, entre otros) y en función de temáticas variadas.', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Desarrolla instalaciones por ensambles, objetuales, móviles con diversos materiales (cajas, desechos, bultos, telas, píxeles, luces, entre otros)","Genera producciones espaciales, identifica sus diferentes posibilidades de organización, y distingue diversos procedimientos compositivos.","Experimenta con el espacio (interiores, exteriores) y sus posibilidades de organización (grados de orden, desorden o caos), con materiales no convencionales y genera paisajes visuales, sonoros, táctiles, multisensoriales.","Explora la policromía y la modificación del color de los materiales en la tridimensión, las sombras propias y las proyectadas en el entorno."]', 'PdA p. 73'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Selección de materiales y procedimientos técnicos adecuados para el desarrollo de construcciones tridimensionales, en sus diferentes variantes.', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Elige materiales que le permitan dar forma, a través del agregado o la supresión de diferentes cantidades.","Trabaja con materiales que le permiten liberar gradualmente la forma en el tallado, por ejemplo el poliuretano, denominado comercialmente como esponja (usando tijeras de punta fina para obtener formas) o el jabón.","Experimenta con diferentes materiales que le permiten desarrollar esculturas de bulto, alto y bajo relieve, para el tratamiento del volumen, el modelado y/o tallado de modo/s (por ejemplo, cóncavo, convexo, hueco, sólido, entrantes, salientes, abierto, cerrado).","Explora el tratamiento lateral, frontal, integral del volumen, según opte por una producción de bulto o un relieve."]', 'PdA p. 74'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Representación virtual del espacio, generando la ilusión de entrar en un nuevo tipo de plano con propiedades diferentes, de manera analógica y/o digital.', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Explora las posibilidades expresivas de la realidad virtual y sus propiedades.","Experimenta con las ilusiones ópticas, las anamorfosis e interactúa con el cuerpo como soporte y materialidad en el espacio.","Expresa su opinión sobre las sensaciones y/o ideas que experimenta, a partir de las exploraciones desarrolladas."]', 'PdA p. 74'),
(17, 'eje_contenido', 'Artes Visuales (por ciclo)', 'Desarrollo de un proyecto analítico sobre contenidos plásticos y visuales tridimensionales (que implique dispositivos, contexto de producción, exposición y recepción, entre otras posibilidades).', 'pda_2025', 1, 'Conocer y producir representaciones tridimensionales mediante la exploración de materiales tradicionales e innovadores, atendiendo a sus cualidades expresivo-comunicativas y adaptándolas al contexto económico, social y cultural.', '["Selecciona, según sus preferencias, la producción de una/un artista, una corriente artística y/o fenómeno estético-visual contemporáneo que hace uso del espacio.","Investiga procesos de producción, técnicas, materiales, circulación y recepción de obras tridimensionales.","Analiza producciones tridimensionales y contempla la dimensión creativa, expositiva y de recepción.","Trabaja en colaboración con sus pares, a partir de acuerdos y roles definidos, sin distinción de género."]', 'PdA p. 74'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Análisis y comprensión de las diferentes formas de organización rítmica, melódica, textural, tímbrica y formal de los diversos discursos musicales, para la comunicación de la experiencia sonora.', 'pda_2025', 1, 'Reconocer la música como una representación cultural, identificando elementos, estructuras y características propias de los lenguajes musicales, para crear composiciones mediante tecnologías, instrumentos y objetos sonoros.', '["Explora la diversidad de formas en que diferentes culturas crean, interpretan y transmiten sus músicas y reconoce la pluralidad de lenguajes sonoros.","Relaciona las cualidades del sonido y el uso del silencio con los lenguajes musicales y acuerda formas colectivas de comunicarlo en repertorios y creaciones simples.","Incorpora el uso de términos como pulso, compás, movimiento melódico, silencio, para describir fragmentos musicales.","Reconoce diferentes grafías para representar los elementos discursivos de los lenguajes sonoro-musicales y considera a las organizaciones rítmicas y melódicas.","Distingue el sonido del ruido y reconoce su valor expresivo y comunicativo."]', 'PdA p. 129'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Construcción de nociones rítmicas, melódicas y armónicas, y exploración de las relaciones entre los elementos de un discurso musical, a través de la práctica instrumental, vocal y la escucha activa.', 'pda_2025', 1, 'Reconocer la música como una representación cultural, identificando elementos, estructuras y características propias de los lenguajes musicales, para crear composiciones mediante tecnologías, instrumentos y objetos sonoros.', '["Diferencia, a través de juegos con percusión corporal, patrones rítmicos con divisiones binarias y ternarias, polirritmias y otras acentuaciones.","Reconoce patrones de claves afrolatinas (clave de son, de rumba, de candombe, entre otras), a través de actividades lúdicas y escucha activa.","Explora secuencias melódicas a partir de la experimentación con escalas, modos y patrones melódicos de diferentes repertorios.","Identifica las funciones rítmicas, melódicas y armónicas de los instrumentos y objetos sonoros, en los repertorios que interpreta o escucha.","Explora, a través de juegos de percepción y de la práctica instrumental, las funciones armónicas como la tensión, el reposo y otras posibles asociaciones en repertorios diversos."]', 'PdA p. 129'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Exploración de los lenguajes sonoro-musicales, a través del uso de instrumentos tradicionales, cotidiáfonos, objetos sonoros y/o tecnologías.', 'pda_2025', 1, 'Reconocer la música como una representación cultural, identificando elementos, estructuras y características propias de los lenguajes musicales, para crear composiciones mediante tecnologías, instrumentos y objetos sonoros.', '["Experimenta el sonido y sus posibilidades de transformación tímbrica a través de instrumentos, objetos sonoros y/o herramientas tecnológicas.","Compara las posibilidades expresivas de instrumentos acústicos, electrónicos y digitales.","Utiliza herramientas tecnológicas, en caso de ser posible, para crear sonidos y organizarlos de acuerdo con los elementos constitutivos de la música, explicando cómo lo hace.","Indaga medios analógicos, digitales y/o gráficos para registrar material sonoro e ideas musicales."]', 'PdA p. 130'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Construcción colectiva de un discurso común, para nombrar, describir y analizar diferentes músicas, integrando vocabulario técnico en referencia a la procedencia cultural de los repertorios y las experiencias sonoras abordadas.', 'pda_2025', 1, 'Reconocer la música como una representación cultural, identificando elementos, estructuras y características propias de los lenguajes musicales, para crear composiciones mediante tecnologías, instrumentos y objetos sonoros.', '["Comunica las características rítmicas y melódicas de repertorios trabajados, reconociendo su procedencia.","Establece relaciones entre sus preferencias musicales y los elementos sonoros que las sustentan.","Incorpora términos para argumentar la elección de repertorios en la creación de listas de reproducción personales.","Compara cómo diferentes formas de hablar sobre la música reflejan distintas miradas, tradiciones o experiencias (por ejemplo, la forma en que se describe el canto en una copla vs en un tema de freestyle)."]', 'PdA p. 130'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Integración de los elementos del discurso musical en prácticas instrumentales y reconocimiento del resultado expresivo de la combinación sonora.', 'pda_2025', 1, 'Reconocer la música como una representación cultural, identificando elementos, estructuras y características propias de los lenguajes musicales, para crear composiciones mediante tecnologías, instrumentos y objetos sonoros.', '["Relaciona patrones rítmicos, con los géneros musicales que interpreta (por ejemplo: chacarera, zamba, malambo, cueca, cumbia, pop, rock, trap, entre otros).","Incorpora las claves latinoamericanas y sus variaciones, para ordenar la rítmica de los géneros musicales en los que se insertan (salsa, son, rumba, candombe, samba, bossa nova, entre otros).","Experimenta a través de la práctica de distintos repertorios, las sonoridades que generan las diferentes escalas (mayores, menores, modales, pentatónicos).","Toma decisiones musicales (inicio, dinámica, tempo) en composiciones colectivas, justificando sus elecciones desde lo expresivo y lo funcional.","Indaga páginas web con cancioneros, para interpretar repertorios cantados con acompañamiento instrumental."]', 'PdA p. 130'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Reconocimiento y combinación de los elementos constitutivos de la música, a través de la improvisación con instrumentos tradicionales y digitales.', 'pda_2025', 1, 'Reconocer la música como una representación cultural, identificando elementos, estructuras y características propias de los lenguajes musicales, para crear composiciones mediante tecnologías, instrumentos y objetos sonoros.', '["Participa en improvisaciones individuales o grupales y genera frases musicales a partir de sonidos, ritmos y melodías espontáneas.","Identifica, en sus propias improvisaciones, elementos de los lenguajes musicales (el pulso, la dirección del movimiento melódico, claves rítmicas, entre otros).","Experimenta con modelos de improvisación de preguntas y respuestas, sobre bases con distintas métricas.","Integra recursos de sampleo y secuencias pregrabadas en producciones grupales.","Utiliza métodos de registro para reutilizar y combinar material producido, o para evaluar posibles cambios/ mejoras en su producción."]', 'PdA p. 131'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Apropiación progresiva de las posibilidades sonoras de la voz hablada y cantada.', 'pda_2025', 1, 'Comprender las características de la voz humana, analizando diferentes técnicas vocales, para utilizarlas expresivamente en la interpretación de diversos repertorios, de manera individual y colectiva.', '["Participa en vocalizaciones grupales, apropiándose de técnicas básicas de respiración, emisión y resonancia vocal.","Reconoce, a partir de la escucha de cantantes de su interés, los diferentes usos de la voz hablada y cantada.","Diferencia sensaciones corporales al utilizar su voz, en distintas extensiones vocales, y elige cantar en el rango que más cómodo le sienta.","Experimenta y compara formas de emisión vocal en repertorios, y reconoce intenciones expresivas básicas.","Incorpora arreglos a dos o más voces y sostiene su propia línea, en coordinación con el grupo."]', 'PdA p. 132'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Desarrollo de la expresión vocal como herramienta que contribuye a la construcción de identidades.', 'pda_2025', 1, 'Comprender las características de la voz humana, analizando diferentes técnicas vocales, para utilizarlas expresivamente en la interpretación de diversos repertorios, de manera individual y colectiva.', '["Canta diversos repertorios en forma individual y colectiva, y muestra mayor seguridad al expresarse.","Identifica los cambios de su voz y la de sus pares, y los reconoce como parte de su crecimiento.","Reflexiona, desde una perspectiva de género, sobre la diversidad de voces en el marco del canto colectivo (por ejemplo, historización sobre el surgimiento de las categorías vocales y su vinculación con estereotipos de género)."]', 'PdA p. 132'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Exploración estilística de repertorios musicales a través del canto individual y colectivo.', 'pda_2025', 1, 'Comprender las características de la voz humana, analizando diferentes técnicas vocales, para utilizarlas expresivamente en la interpretación de diversos repertorios, de manera individual y colectiva.', '["Interpreta, en la práctica del canto, melodías de distintos estilos, y comprende las posibilidades de su voz.","Identifica, en la práctica vocal, características estilísticas y culturales de las voces, en los distintos géneros y estilos.","Experimenta la diversidad de formas de cantar, en repertorios de diferentes expresiones culturales (baguala, canto con caja, freestyle, trap, entre otros).","Reflexiona sobre las diferencias y similitudes vocales entre los repertorios explorados."]', 'PdA p. 132'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Experimentación de técnicas vocales y utilización de recursos expresivos vinculados con el análisis de géneros y estilos musicales.', 'pda_2025', 1, 'Comprender las características de la voz humana, analizando diferentes técnicas vocales, para utilizarlas expresivamente en la interpretación de diversos repertorios, de manera individual y colectiva.', '["Utiliza técnicas vocales de respiración, articulación y proyección, en interpretaciones colectivas e individuales.","Explora, a través de la técnica, recursos expresivos como dinámica y fraseo, en la interpretación de repertorios musicales de diferentes géneros y estilos.","Analiza interpretaciones de cantantes e identifica el uso intencional de técnicas vocales.","Reflexiona sobre su interpretación vocal e identifica, en el uso de técnicas y recursos expresivos, fortalezas y aspectos a mejorar."]', 'PdA p. 133'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Interpretación vocal como medio de expresión, comunicación personal y colectiva y valoración de la diversidad y el trabajo colaborativo.', 'pda_2025', 1, 'Comprender las características de la voz humana, analizando diferentes técnicas vocales, para utilizarlas expresivamente en la interpretación de diversos repertorios, de manera individual y colectiva.', '["Identifica los sentimientos que puede transmitir un determinado repertorio y utiliza la voz para interpretarlos de manera intencional, dentro y fuera del espacio áulico (actos escolares, encuentros con otras escuelas, espacios públicos).","Integra diferentes posibilidades sonoras de la voz y el cuerpo en distintos contextos expresivos.","Reconoce y acepta, en la diversidad de voces y posibilidades expresivas, las diferencias existentes y las considera como potencialidades."]', 'PdA p. 133'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Comunicación de sus preferencias musicales, para incorporar repertorios a través del canto individual y colectivo.', 'pda_2025', 1, 'Comprender las características de la voz humana, analizando diferentes técnicas vocales, para utilizarlas expresivamente en la interpretación de diversos repertorios, de manera individual y colectiva.', '["Propone canciones de distintos estilos y comprende sus posibilidades en la práctica del canto.","Relaciona características estéticas del canto individual y colectivo, con los géneros o estilos que le resultan interesantes.","Reconoce el carácter colectivo del canto, en distintos rituales culturales y expresiones comunitarias.","Reflexiona sobre cómo sus preferencias musicales influyen en su interpretación e identifica maneras de enriquecer su práctica vocal."]', 'PdA p. 133'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Desarrollo de la noción de textura, a través de actividades de percepción y producción musical colectiva.', 'pda_2025', 1, 'Participar en ensambles, atendiendo a la colaboración y sincronización entre las/os integrantes, utilizando instrumentos y aplicaciones móviles.', '["Explora y compara las texturas presentes en distintas formaciones musicales (orquesta, banda de rock, coro, ensamble de percusión).","Percibe los cambios y las combinaciones tímbricas, al superponer diferentes capas sonoras en la interpretación grupal.","Identifica, en los repertorios que escucha e interpreta, distintas texturas musicales (monofonía, melodía con acompañamiento, homofonía, polifonía).","Reconoce los roles melódicos, rítmicos y armónicos en los ensambles de los que participa."]', 'PdA p. 134'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Reconocimiento de la forma musical como guía, para incorporar pautas de sincronización y cohesión en la interpretación colectiva.', 'pda_2025', 1, 'Participar en ensambles, atendiendo a la colaboración y sincronización entre las/os integrantes, utilizando instrumentos y aplicaciones móviles.', '["Analiza, a través de la escucha activa y la interpretación de repertorios, las características rítmicas, melódicas y dinámicas de cada sección de la forma musical.","Identifica las diferentes secciones de la forma musical, en diversos géneros y estilos.","Anticipa y sincroniza entradas y salidas en la interpretación colectiva, corrige errores espontáneamente y reconoce elementos de la forma musical, para ajustar su interpretación al ensamble.","Reconoce, en el repertorio que interpreta, estructuras formales típicas de determinados géneros y estilos musicales."]', 'PdA p. 134'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Participación en ensambles vocales e instrumentales, explorando diferentes texturas para crear, colaborativamente, arreglos musicales sencillos.', 'pda_2025', 1, 'Participar en ensambles, atendiendo a la colaboración y sincronización entre las/os integrantes, utilizando instrumentos y aplicaciones móviles.', '["Vincula los diferentes géneros y estilos que interpreta con determinadas texturas (por ejemplo, la homofonía con el pop, el contrapunto con el folclore o el tango).","Explora la posibilidad de construir acordes, superponiendo melodías, con instrumentos o a través del canto.","Interviene en el ensamble y asume un rol musical para construir la textura (acompañamiento, melodía principal, contrapunto, entre otros).","Propone repertorios y asocia lo que escucha a las posibilidades interpretativas y tímbricas del ensamble."]', 'PdA p. 135'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Toma de decisiones colaborativas dentro del ensamble, en relación con la interpretación y la organización musical.', 'pda_2025', 1, 'Participar en ensambles, atendiendo a la colaboración y sincronización entre las/os integrantes, utilizando instrumentos y aplicaciones móviles.', '["Propone soluciones ante posibles dificultades que puedan surgir en las interpretaciones musicales colectivas.","Colabora en la construcción de acuerdos interpretativos (entradas, salidas, matices, articulaciones) y promueve la unidad y fluidez del ensamble.","Adapta la interpretación colectiva a la estructura formal propia del género o estilo musical.","Propone cambios o ajustes en la interpretación colectiva, basándose en la escucha activa y el trabajo colaborativo.","Asume con responsabilidad su rol dentro del ensamble.","Comprende que la colaboración entre las/os integrantes resulta indispensable para la producción musical colaborativa."]', 'PdA p. 135'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Exploración de diferentes herramientas y recursos que aporten a la conformación de ensambles musicales.', 'pda_2025', 1, 'Participar en ensambles, atendiendo a la colaboración y sincronización entre las/os integrantes, utilizando instrumentos y aplicaciones móviles.', '["Experimenta e investiga con sonoridades, instrumentos y/o dispositivos móviles, que aportan al ensamble.","Identifica las funciones de herramientas tecnológicas (metrónomo, sintetizadores, grabadoras) en la organización y sincronización del ensamble.","Reconoce las posibilidades creativas de combinar, en una producción musical, recursos tecnológicos con instrumentos tradicionales."]', 'PdA p. 135'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Valoración e indagación del patrimonio musical local, con reconocimiento y reflexión acerca de su papel en la construcción de las identidades.', 'pda_2025', 1, 'Apreciar el patrimonio musical a través de la escucha reflexiva de diversos géneros y estilos, analizando sus raíces culturales y los cambios a lo largo de la historia, reconociendo de qué manera contribuyen a la construcción de la identidad.', '["Identifica los géneros y estilos musicales presentes en su entorno cultural y los diferentes ámbitos en los que circulan (medios, festivales, bailes, espacios comunitarios, entre otros).","Reflexiona sobre cómo ciertas músicas expresan sentidos de pertenencia, memorias y diferencias culturales, y reconoce tensiones entre lo académico, lo popular y lo personal.","Analiza los repertorios patrios, vinculándolos con sucesos de representación histórica del pasado y de la actualidad.","Reconoce cómo las diversas manifestaciones musicales influyen en la construcción de su identidad y en la de las demás personas.","Elabora y comparte una lista de repertorios musicales, basándose en la escucha activa y sus gustos personales."]', 'PdA p. 136'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Reconocimiento del contexto cultural en el que se inscriben y transforman las producciones sonoras.', 'pda_2025', 1, 'Apreciar el patrimonio musical a través de la escucha reflexiva de diversos géneros y estilos, analizando sus raíces culturales y los cambios a lo largo de la historia, reconociendo de qué manera contribuyen a la construcción de la identidad.', '["Incorpora, a través de la escucha activa y crítica, repertorios que representan distintos contextos culturales, y comparte reflexiones sobre sus particularidades.","Distingue elementos característicos de músicas provenientes de diversas regiones o comunidades, y comparte reflexiones personales sobre lo que le generan o comunican.","Identifica las relaciones entre los géneros, estilos musicales y el entorno natural, social, geográfico e histórico en el que se inscriben."]', 'PdA p. 136'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Identificación de las diferentes formas de producir y reproducir sonidos a lo largo del tiempo.', 'pda_2025', 1, 'Apreciar el patrimonio musical a través de la escucha reflexiva de diversos géneros y estilos, analizando sus raíces culturales y los cambios a lo largo de la historia, reconociendo de qué manera contribuyen a la construcción de la identidad.', '["Analiza las diferentes formas de producir sonidos, desde métodos tradicionales, hasta tecnologías modernas (instrumentos acústicos, electrónicos, software musical).","Reconoce cómo las innovaciones tecnológicas han influido en la manera de producir y consumir música."]', 'PdA p. 136'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Asociación entre las características estéticas del patrimonio musical y el rol histórico, en la música, de personas con diferentes identidades de género (mujeres, varones, personas trans, entre otros).', 'pda_2025', 1, 'Apreciar el patrimonio musical a través de la escucha reflexiva de diversos géneros y estilos, analizando sus raíces culturales y los cambios a lo largo de la historia, reconociendo de qué manera contribuyen a la construcción de la identidad.', '["Analiza el rol de personas con diferentes identidades de género, en la música, a lo largo de la historia.","Contextualiza los cambios estéticos en los distintos repertorios musicales, en relación con la participación de personas con diferentes identidades de género."]', 'PdA p. 137'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Desarrollo de la reflexión crítica en relación con el patrimonio musical y sus implicancias sociales.', 'pda_2025', 1, 'Apreciar el patrimonio musical a través de la escucha reflexiva de diversos géneros y estilos, analizando sus raíces culturales y los cambios a lo largo de la historia, reconociendo de qué manera contribuyen a la construcción de la identidad.', '["Evalúa críticamente las influencias y el impacto de eventos históricos, sociales y culturales en el surgimiento y/o desarrollo de los distintos géneros musicales (por ejemplo, lo sucedido con el rock en el contexto de la última dictadura militar).","Contextualiza las producciones sonoras que escucha, y establece conexiones con los acontecimientos tecnológicos y las dinámicas culturales de la realidad actual.","Analiza cómo los diferentes géneros y estilos del patrimonio musical pueden vincularse con conflictos o transformaciones sociales."]', 'PdA p. 137'),
(17, 'eje_contenido', 'Música (por ciclo)', 'Análisis de las diferentes formas de producir y reproducir sonidos en la actualidad, considerando su impacto social (creación, distribución y consumo).', 'pda_2025', 1, 'Apreciar el patrimonio musical a través de la escucha reflexiva de diversos géneros y estilos, analizando sus raíces culturales y los cambios a lo largo de la historia, reconociendo de qué manera contribuyen a la construcción de la identidad.', '["Identifica, a través de la escucha activa, la incidencia de las tecnologías y sus usos en las distintas maneras de producir música, según diferentes contextos culturales.","Compara los cambios históricos y culturales, en las formas de producir y consumir música y destaca sus similitudes, diferencias y aportes a la creación musical.","Analiza las formas de consumo personal de la música (redes sociales, medios masivos, encuentros comunitarios, entre otras).","Reflexiona sobre el impacto social y cultural de las plataformas digitales, en la creación y el consumo musical."]', 'PdA p. 137'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Profundización de la relación entre apoyo y peso corporal, e identificación de las necesidades y variaciones del tono muscular.', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Explora caídas, deslizamientos y rodadas controladas, identificando los apoyos en cada acción.","Diferencia momentos de relajación y tensión en caídas suaves, frenadas o impulsos.","Integra peso, apoyos y variaciones de tono en secuencias de movimiento más complejas, combinando transiciones fluidas (caer–rodar–deslizar)."]', 'PdA p. 190'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Investigación de las posibilidades de ir contra la gravedad (equilibrios, saltos, giros) y posturas invertidas (medialuna, parada de manos, parada de cabeza, vela, arado, entre otras).', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Realiza saltos y giros simples, manteniendo la coordinación y la estabilidad en la conclusión del movimiento.","Experimenta posturas invertidas con asistencia o apoyos (pared, compañeras/os), y registra la respiración, la alineación y el uso seguro de la fuerza.","Integra equilibrios, saltos, giros y posturas invertidas, en secuencias de movimiento simples."]', 'PdA p. 190'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Reconocimiento de las calidades de movimiento (ligado, cortado, vibrar, suspender, torcer, etc) y su relación con las variantes de tensión-relajación, fuerza e intensidad.', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Identifica y reproduce distintas calidades de movimiento (ligado, cortado, vibrar, suspender, torcer).","Explora variaciones de tensión y relajación muscular, para generar cambios de fuerza, e intensidad en los movimientos.","Combina calidades de movimiento con variaciones de tensión-relajación, fuerza e intensidad, con transiciones conscientes entre una y otra."]', 'PdA p. 190'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Investigación de las posibilidades de contacto corporal con pares, e integración de soportes, arrastres, movimientos pendulares y la entrega consciente del peso en el lugar o en diferentes trayectorias espaciales.', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Explora el contacto corporal básico con una/un compañera/o, reconociendo apoyos simples y la confianza necesaria para compartir el peso en situaciones estáticas.","Realiza arrastres y movimientos pendulares con una/un compañera/o, experimentando la entrega y recepción consciente del peso en distintas trayectorias (verticales, diagonales, circulares).","Integra soportes, arrastres, pendulaciones y entrega de peso en exploraciones duales o grupales."]', 'PdA p. 191'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Exploración y regulación de las tensiones corporales para favorecer la alineación desde el centro, para el desarrollo de una relación consciente y eficiente entre esfuerzo, peso, flujo energético y movimiento.', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Explora e integra la regulación de tensiones corporales, para mantener la alineación y equilibrio durante el movimiento.","Experimenta el uso del centro corporal (zona abdominal/lumbar/pélvica), como sostén y punto de partida del movimiento.","Regula el flujo energético en tanto consigue diferenciar entre energía continua y libre, o controlada y contenida en la ejecución de los movimientos de su danza.","Ajusta dinámicamente el esfuerzo, el peso y el flujo energético, para optimizar la expresividad de cada movimiento.","Diferencia entre movimientos que requieren entrega al peso y otros que necesitan suspensión o impulso."]', 'PdA p. 191'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Investigar la relación con el suelo, explorando formas de entrar y salir de él mediante la generación de espirales, a partir de la conexión entre el centro y las extremidades.', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Experimenta, de manera consciente, la relación con el suelo y ejecuta entradas y salidas fluidas, distribuyendo eficientemente el peso.","Reconoce cómo el uso de espirales facilita el pasaje entre niveles y favorece la continuidad en las transiciones.","Explora secuencias que implican giros, torsiones o espirales, como principios organizadores del movimiento.","Utiliza el centro como punto de partida para mover brazos, piernas o cabeza de forma coordinada."]', 'PdA p. 191'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Experimentación de las calidades de movimiento, distinguiendo los factores que las componen (tiempo, peso, flujo y espacio), así como su relación con las variantes de tensión-relajación, fuerza e intensidad.', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Explora e investiga, de manera consciente, distintas calidades de movimiento (ligado, cortado, vibratoria, suspender, torcer, entre otras) en la práctica de la danza.","Regula la tensión, relajación, fuerza e intensidad necesaria para cada movimiento, ampliando sus posibilidades expresivas.","Relaciona ciertas calidades con combinaciones específicas de los factores que la componen (por ejemplo, vibratorio equivale a la sumatoria de rápido, restringido y directo)."]', 'PdA p. 192'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Complejización del uso de elementos técnicos (saltos, giros, roladas, deslizadas, entre otros), en vínculo con el contacto corporal con pares, integrando tomas, agarres y soportes con formas de traslación en el espacio.', 'pda_2025', 1, 'Indaga las variantes de tensión-relajación, global y segmentaria, y su implicancia en el estudio del movimiento a favor o en contra de la gravedad, en combinación con elementos técnicos como saltos, giros, roladas y deslizadas.', '["Ejecuta movimientos reconociendo los elementos técnicos (saltos, giros, roladas, deslizadas).","Aplica, en la interacción con sus pares, tomas, agarres y soportes de manera segura.","Combina diversos elementos técnicos a partir de desplazamientos y traslaciones en el espacio, en frases de movimiento de complejidad avanzada."]', 'PdA p. 192'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Conceptualización de una idea compleja de cuerpo desde diversas líneas teóricas para su abordaje, como cuerpo jerarquizado (división mente-cuerpo), cuerpo fragmentario (una sumatoria de partes), cuerpo holístico (un sistema de sistemas que se interrelacionan).', 'pda_2025', 1, 'Comprender un concepto complejo de cuerpo, tanto teórica como prácticamente, reconociendo su importancia en la construcción identitaria, el valor cultural de sus manifestaciones expresivas y el disfrute del movimiento.', '["Reconoce y describe diferentes concepciones del cuerpo, a partir de la información presentada.","Compara las distintas perspectivas, identificando similitudes, diferencias y modos en que cada una organiza la idea de cuerpo.","Comprende y relaciona las concepciones teóricas con experiencias corporales concretas, evidenciando dónde es posible apreciarlas."]', 'PdA p. 193'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Exploración de la relación cuerpo-mente-emoción y del vínculo con el entorno, a partir del movimiento expresivo y subjetivo, así como de la toma de conciencia de la presencia de huesos, músculos, articulaciones, respiración, flujo energético.', 'pda_2025', 1, 'Comprender un concepto complejo de cuerpo, tanto teórica como prácticamente, reconociendo su importancia en la construcción identitaria, el valor cultural de sus manifestaciones expresivas y el disfrute del movimiento.', '["Explora movimientos a partir de sensaciones, percepciones, imágenes poéticas, pensamientos o emociones.","Expresa sensaciones y emociones surgidas del movimiento.","Reconoce y nombra los huesos, los músculos y las articulaciones que se involucran en diferentes movimientos."]', 'PdA p. 193'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Reflexión sobre la autoimagen y su relación con el movimiento (torpeza, inseguridad, potencia, exploración), y desnaturalización de modelos hegemónicos (cuerpos delgados, fuertes, ágiles, normados).', 'pda_2025', 1, 'Comprender un concepto complejo de cuerpo, tanto teórica como prácticamente, reconociendo su importancia en la construcción identitaria, el valor cultural de sus manifestaciones expresivas y el disfrute del movimiento.', '["Participa en conversaciones grupales desde el respeto a la diversidad corporal","Relaciona las elaboraciones y sus reflexiones sobre imagen corporal surgidas en el grupo a partir del movimiento.","Valora y respeta la diversidad de corporalidades presentes en el grupo, participando en experiencias de movimiento que amplían las posibilidades expresivas, más allá de modelos hegemónicos."]', 'PdA p. 193'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Historización del concepto de cuerpo y su vínculo con la(s) danza(s) a lo largo del tiempo.', 'pda_2025', 1, 'Comprender un concepto complejo de cuerpo, tanto teórica como prácticamente, reconociendo su importancia en la construcción identitaria, el valor cultural de sus manifestaciones expresivas y el disfrute del movimiento.', '["Reconoce relatos e imágenes históricas, que muestran diferentes concepciones del cuerpo y la danza (por ejemplo, ritual, social, escénico).","Compara distintas concepciones del cuerpo.","Argumenta y relaciona, críticamente, cómo las concepciones históricas del cuerpo influyen en las formas actuales de entender y practicar la danza."]', 'PdA p. 194'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Profundización de la relación cuerpo-mente-emoción en el movimiento expresivo y subjetivo, con la incorporación de objetos de diferentes texturas, formas, colores, tamaños, peso y sonoridad y valorando su relación con el cuerpo y el movimiento.', 'pda_2025', 1, 'Comprender un concepto complejo de cuerpo, tanto teórica como prácticamente, reconociendo su importancia en la construcción identitaria, el valor cultural de sus manifestaciones expresivas y el disfrute del movimiento.', '["Explora el movimiento expresivo, a partir del uso de objetos variados.","Investiga el movimiento con objetos, diferenciando las posibilidades expresivas que brinda cada uno (textura, forma, peso, color, sonoridad).","Expresa sus pensamientos, sentires y emociones a partir del movimiento que realiza con objetos."]', 'PdA p. 194'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Reconocimiento del movimiento en su dimensión física y como lenguaje identitario que configura modos de estar en el mundo, así como de presentarse frente a otras/os.', 'pda_2025', 1, 'Comprender un concepto complejo de cuerpo, tanto teórica como prácticamente, reconociendo su importancia en la construcción identitaria, el valor cultural de sus manifestaciones expresivas y el disfrute del movimiento.', '["Observa y describe tanto de manera oral como escrita, movimientos propios y de otras/os, reconociendo su dimensión física y poética/expresiva.","Explora y experimenta gestos/modos de moverse, como forma de expresión identitaria.","Reflexiona y comunica ideas, deseos y/o conceptos, a través del propio movimiento/la propia danza."]', 'PdA p. 194'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Exploración del espacio personal (parcial y total), y diferenciación respecto de la proximidad con el propio cuerpo, del espacio compartido con otras/os y del general (del aula, la sala o escenario).', 'pda_2025', 1, 'Construir un abordaje relacional del espacio (personal, parcial y total), integrando los niveles y planos, trayectorias y direcciones.', '["Explora y reconoce las zonas limítrofes del propio espacio (cerca/lejos, periferia/centro), regulando la proximidad con sus pares.","Explora el espacio personal y compartido a través de desplazamientos.","Utiliza, de manera consciente, el espacio total (aula, sala o escenario)."]', 'PdA p. 195'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Exploración de los niveles espaciales (alto, medio, bajo), en relación con los planos corporales, las trayectorias y direcciones posibles.', 'pda_2025', 1, 'Construir un abordaje relacional del espacio (personal, parcial y total), integrando los niveles y planos, trayectorias y direcciones.', '["Explora y diferencia los niveles espaciales (alto, medio, bajo).","Relaciona los niveles espaciales con planos corporales y direcciones, en movimientos individuales o grupales.","Integra trayectorias y desplazamientos variados en los distintos niveles espaciales."]', 'PdA p. 195'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Investigación de las posibilidades del espacio, desde un abordaje relacional, en propuestas de improvisación tanto individuales como grupales.', 'pda_2025', 1, 'Construir un abordaje relacional del espacio (personal, parcial y total), integrando los niveles y planos, trayectorias y direcciones.', '["Explora el espacio de manera individual e identifica niveles, direcciones y trayectorias básicas.","Interactúa con el espacio en relación con otras/os y ajusta su movimiento a distancias, cercanías y configuraciones grupales.","Integra el uso relacional del espacio en improvisaciones colectivas, con especial atención a la propia presencia y la de las/os demás."]', 'PdA p. 195'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Experimentación de desplazamientos y posturas en el nivel bajo, medio y alto, variando la orientación y profundidad en diferentes trayectorias y direcciones (creación de recorridos en línea recta, curva, zigzag, espiral u otras).', 'pda_2025', 1, 'Construir un abordaje relacional del espacio (personal, parcial y total), integrando los niveles y planos, trayectorias y direcciones.', '["Explora y reconoce diferencias de orientación y profundidad, en desplazamientos y posturas en los tres niveles (bajo, medio y alto).","Varía e integra cambios de nivel, posturas, trayectorias y direcciones (recta, curva, zigzag, espiral, entre otras) en sus desplazamientos.","Ejecuta recorridos espaciales, combinando niveles, orientaciones y trayectorias, de manera intencionada y expresiva."]', 'PdA p. 196'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Percepción y registro de las características del espacio físico habitado en la práctica de danza, como sus dimensiones, forma, superficie, altura y niveles, límites y fronteras, iluminación y visibilidad, condiciones ambientales, entre otras.', 'pda_2025', 1, 'Reconocer los diferentes ámbitos donde la danza se manifiesta —espacios físicos, escénicos, comunitarios y digitales— reconociendo sus transformaciones, limitaciones y potencialidades, según el contexto en que se practiquen o escenifiquen, tanto en lo concreto como en lo simbólico.', '["Describe características del espacio físico (dimensiones, forma, superficie, altura y niveles).","Percibe e Identifica variables (iluminación, temperatura, entre otras), en el espacio donde se desarrolla la práctica.","Vincula, conscientemente, características y particularidades del espacio físico en la práctica del movimiento."]', 'PdA p. 197'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Consideración de lo concreto y lo simbólico del espacio para bailar, con atención tanto a las condiciones materiales de cada ámbito, como a los significados culturales y expresivos que se construyen en ellos.', 'pda_2025', 1, 'Reconocer los diferentes ámbitos donde la danza se manifiesta —espacios físicos, escénicos, comunitarios y digitales— reconociendo sus transformaciones, limitaciones y potencialidades, según el contexto en que se practiquen o escenifiquen, tanto en lo concreto como en lo simbólico.', '["Identifica las características materiales del espacio y sus límites.","Reflexiona sobre los significados simbólicos y culturales del espacio, y los relaciona con la experiencia de la danza.","Integra lo concreto y lo simbólico del espacio en propuestas de movimiento."]', 'PdA p. 197'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Exploración y reflexión para la danza (video-danza, performance, redes sociales), entendiendo sus potencialidades, límites, y precauciones.', 'pda_2025', 1, 'Reconocer los diferentes ámbitos donde la danza se manifiesta —espacios físicos, escénicos, comunitarios y digitales— reconociendo sus transformaciones, limitaciones y potencialidades, según el contexto en que se practiquen o escenifiquen, tanto en lo concreto como en lo simbólico.', '["Reconoce las características del espacio digital (plataformas, formatos, visibilidad, alcance, entre otras).","Identifica los límites y precauciones necesarias al crear o compartir danza en entornos digitales.","Dispone creativamente de los recursos digitales en propuestas de movimiento o performance."]', 'PdA p. 197'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Distinguir tipos de espacio: espacio físico (lugar real donde se danza), espacio de práctica (disposición y organización para el trabajo corporal) y espacio escénico (configuración estética y simbólica para la presentación).', 'pda_2025', 1, 'Reconocer los diferentes ámbitos donde la danza se manifiesta —espacios físicos, escénicos, comunitarios y digitales— reconociendo sus transformaciones, limitaciones y potencialidades, según el contexto en que se practiquen o escenifiquen, tanto en lo concreto como en lo simbólico.', '["Reconoce los distintos tipos de espacio y señala ejemplos de espacio físico, de práctica y escénico.","Distingue funciones y características de cada tipo de espacio, en relación con la danza o la práctica corporal.","Idea y proyecta espacios donde podría desarrollarse la práctica corporal o producciones artístico-educativas (obras, muestras, clases, residencias, entre otras)."]', 'PdA p. 198'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Investigación de las posibilidades de resignificación del espacio físico, a partir de elementos escenotécnicos (luces, maquillaje, vestuario, escenografía, utilería, entre otros).', 'pda_2025', 1, 'Reconocer los diferentes ámbitos donde la danza se manifiesta —espacios físicos, escénicos, comunitarios y digitales— reconociendo sus transformaciones, limitaciones y potencialidades, según el contexto en que se practiquen o escenifiquen, tanto en lo concreto como en lo simbólico.', '["Reconoce los elementos escenotécnicos y sus funciones en el espacio físico, de un modo introductorio.","Analiza el efecto de los elementos escenotécnicos en la resignificación del espacio físico y su relación con la puesta en escena.","Diseña propuestas básicas de intervención del espacio físico utilizando elementos escenotécnicos."]', 'PdA p. 198'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Exploración y reflexión del espacio digital como espacio para la danza (video-danza, performance, redes sociales), entendiendo sus potencialidades, límites, y precauciones, con atención a la noción de autoría, plagio y reproducibilidad.', 'pda_2025', 1, 'Reconocer los diferentes ámbitos donde la danza se manifiesta —espacios físicos, escénicos, comunitarios y digitales— reconociendo sus transformaciones, limitaciones y potencialidades, según el contexto en que se practiquen o escenifiquen, tanto en lo concreto como en lo simbólico.', '["Reconoce el espacio digital como un lugar posible para llevar a cabo una danza y reflexiona sobre sus características, potencialidades y límites.","Analiza la influencia del espacio digital en la producción y difusión de la danza, considerando autoría, plagio y reproducibilidad.","Propone producciones de danza en el espacio digital, que integren las reflexiones surgidas en clase."]', 'PdA p. 198'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Desarrollo de la escucha, el acompañamiento entre pares y la construcción colectiva del movimiento, a través de composiciones basadas en intereses propios.', 'pda_2025', 1, 'Experimentar el vínculo cooperativo y desarrollar composiciones individuales, duales y colectivas en diferentes géneros y estilos locales, nacionales, regionales e internacionales, reconociendo diversos parámetros de la composición coreográfica como el canon, unísono, figura-fondo, pregunta-respuesta, entre otros.', '["Practica la escucha activa y la atención a las señales de sus pares durante la práctica danzada.","Ejercita el diálogo y la cooperación en la construcción de secuencias o composiciones conjuntas.","Intercambia ideas, de manera respetuosa, en instancias grupales de creación."]', 'PdA p. 199'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Creación de composiciones individuales, duales y grupales, reconociendo e implementando parámetros de la composición coreográfica (canon, unísono, figura/fondo, alternancia, sustracción, acumulación, entre otros).', 'pda_2025', 1, 'Experimentar el vínculo cooperativo y desarrollar composiciones individuales, duales y colectivas en diferentes géneros y estilos locales, nacionales, regionales e internacionales, reconociendo diversos parámetros de la composición coreográfica como el canon, unísono, figura-fondo, pregunta-respuesta, entre otros.', '["Reconoce parámetros básicos de composición coreográfica (canon, unísono, figura/fondo, alternancia, sustracción, acumulación).","Integra criterios de composición, en creaciones o composiciones duales y grupales.","Identifica y relaciona las características de las composiciones propias con las de sus pares. Pudiendo explicitarlas en debates, análisis escritos, observaciones, etc."]', 'PdA p. 199'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Aproximación y abordaje de manifestaciones de danzas locales, nacionales, regionales e internacionales, para favorecer la ampliación de referentes estéticos y culturales.', 'pda_2025', 1, 'Experimentar el vínculo cooperativo y desarrollar composiciones individuales, duales y colectivas en diferentes géneros y estilos locales, nacionales, regionales e internacionales, reconociendo diversos parámetros de la composición coreográfica como el canon, unísono, figura-fondo, pregunta-respuesta, entre otros.', '["Describe diversas manifestaciones de la danza en ámbitos locales, nacionales, regionales e internacionales.","Compara elementos estéticos y culturales que están presentes en diferentes manifestaciones de la danza.","Valora la diversidad de expresiones dancísticas, como parte del patrimonio cultural."]', 'PdA p. 199'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Profundización de la instancia compositiva, con desarrollo de la interdependencia, el diálogo corporal y la complementariedad, a partir de diversos intereses, aportes y de la organización conjunta.', 'pda_2025', 1, 'Experimentar el vínculo cooperativo y desarrollar composiciones individuales, duales y colectivas en diferentes géneros y estilos locales, nacionales, regionales e internacionales, reconociendo diversos parámetros de la composición coreográfica como el canon, unísono, figura-fondo, pregunta-respuesta, entre otros.', '["Identifica y diferencia los roles y aportes de cada participante en la composición.","Participa de propuestas compositivas que integran la diversidad de aportes, revisando o ajustando formas y secuencias en conjunto.","Participa en la creación de composiciones grupales que desarrollan la interdependencia, el diálogo corporal y la complementariedad."]', 'PdA p. 200'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Complejización de las composiciones coreográficas, con incorporación de las nociones de reversibilidad del movimiento (detenerse y regresar en cualquier punto), sincronía, contrapunto, aceleración y desaceleración, entre otras.', 'pda_2025', 1, 'Experimentar el vínculo cooperativo y desarrollar composiciones individuales, duales y colectivas en diferentes géneros y estilos locales, nacionales, regionales e internacionales, reconociendo diversos parámetros de la composición coreográfica como el canon, unísono, figura-fondo, pregunta-respuesta, entre otros.', '["Reconoce la posibilidad de detener un movimiento, volverlo al origen o retomarlo desde un punto previo.","Coordina movimientos, en simultáneo, e integra el contrapunto como recurso expresivo en las composiciones que produce con sus pares.","Varía la velocidad de los movimientos (aceleración y desaceleración), para generar contrastes y matices en la composición."]', 'PdA p. 200'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Utilización de referencias de diversos estilos/géneros de danza en composiciones propias.', 'pda_2025', 1, 'Experimentar el vínculo cooperativo y desarrollar composiciones individuales, duales y colectivas en diferentes géneros y estilos locales, nacionales, regionales e internacionales, reconociendo diversos parámetros de la composición coreográfica como el canon, unísono, figura-fondo, pregunta-respuesta, entre otros.', '["Reconoce características de distintos estilos/géneros de danza y selecciona elementos que se pueden incorporar en composiciones propias.","Integra elementos de diferentes estilos/géneros en sus composiciones y los adapta a su intención expresiva.","Crea composiciones que articulan, de manera consciente,referencias de diversos estilos/géneros."]', 'PdA p. 200'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Reconocimiento, valoración y respeto por la importancia del consentimiento en las interacciones durante la práctica de danza.', 'pda_2025', 1, 'Desarrollar prácticas de danza que consideren el consentimiento y el respeto de los límites en los vínculos con otras/os, y que cuestionen la generalización de roles tradicionales y su representación en diversas producciones y analizar cómo se ponen en juego estas relaciones en producciones apreciadas en diferentes soportes (video, imagen, función en vivo).', '["Reconoce y respeta la necesidad del consentimiento en las interacciones durante la práctica de danza.","Valora el consentimiento como principio fundamental para construir vínculos de cuidado y confianza.","Construye modos saludables de habitar el espacio compartido."]', 'PdA p. 201'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Problematización de los estereotipos de género y exploración de las posibilidades diversas de los roles, dentro de la práctica de la danza y la composición.', 'pda_2025', 1, 'Desarrollar prácticas de danza que consideren el consentimiento y el respeto de los límites en los vínculos con otras/os, y que cuestionen la generalización de roles tradicionales y su representación en diversas producciones y analizar cómo se ponen en juego estas relaciones en producciones apreciadas en diferentes soportes (video, imagen, función en vivo).', '["Reflexiona acerca de los estereotipos de género presentes en la danza y su influencia en la composición de movimientos.","Experimenta roles diversos en la práctica dancística, resignificando posibilidades expresivas.","Experimenta el movimiento desgenerizado, en composiciones individuales o grupales."]', 'PdA p. 201'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Análisis de videos, imágenes y obras, en vivo, y que contengan el lenguaje de la danza, reconociendo cómo se ponen en juego los roles en relación al género (ballet, tango, folklore, entre otras).', 'pda_2025', 1, 'Desarrollar prácticas de danza que consideren el consentimiento y el respeto de los límites en los vínculos con otras/os, y que cuestionen la generalización de roles tradicionales y su representación en diversas producciones y analizar cómo se ponen en juego estas relaciones en producciones apreciadas en diferentes soportes (video, imagen, función en vivo).', '["Describe los roles asociados al género en distintas manifestaciones de la danza (ballet, tango, folklore, entre otras).","Analiza cómo se articulan los roles en relación con el género, en videos, imágenes y obras en vivo.","Compara las diferencias y similitudes en la construcción de roles de género que se observan en diversas formas dancísticas."]', 'PdA p. 201'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Desarrollo de una práctica de danza consciente y reflexiva respecto del consentimiento,con incorporación de una perspectiva ética y crítica en los procesos creativos.', 'pda_2025', 1, 'Desarrollar prácticas de danza que consideren el consentimiento y el respeto de los límites en los vínculos con otras/os, y que cuestionen la generalización de roles tradicionales y su representación en diversas producciones y analizar cómo se ponen en juego estas relaciones en producciones apreciadas en diferentes soportes (video, imagen, función en vivo).', '["Reconoce el consentimiento como principio básico en la práctica de la danza.","Comunica los límites propios y respeta los ajenos, en propuestas compartidas de movimiento.","Reflexiona y analiza, críticamente, situaciones de la práctica de danza en las que aparecen relaciones de poder, roles o tensiones grupales."]', 'PdA p. 202'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Problematización de los estereotipos de género y exploración de las posibilidades diversas de los roles dentro de la práctica de la danza y la composición.', 'pda_2025', 1, 'Desarrollar prácticas de danza que consideren el consentimiento y el respeto de los límites en los vínculos con otras/os, y que cuestionen la generalización de roles tradicionales y su representación en diversas producciones y analizar cómo se ponen en juego estas relaciones en producciones apreciadas en diferentes soportes (video, imagen, función en vivo).', '["Reconoce estereotipos de género presentes en prácticas y representaciones de la danza.","Asume tanto la guía como el acompañamiento en danzas de pareja (alternancia del rol).","Explora y asume roles diversos en las danzas de pareja, priorizando el intercambio equitativo y la desjerarquización entre quienes bailan.","Participa en composiciones que distribuyen los roles de manera equitativa."]', 'PdA p. 202'),
(17, 'eje_contenido', 'Danza (por ciclo)', 'Investigación de movimientos relacionados con los roles en la experiencia de la danza (guía, partenaire, etc), desligados del género, y desmontando la asociación rol-género de sus elementos, (zapateos, levantadas, saltos, guías).', 'pda_2025', 1, 'Desarrollar prácticas de danza que consideren el consentimiento y el respeto de los límites en los vínculos con otras/os, y que cuestionen la generalización de roles tradicionales y su representación en diversas producciones y analizar cómo se ponen en juego estas relaciones en producciones apreciadas en diferentes soportes (video, imagen, función en vivo).', '["Investiga y reconoce los roles tradicionales en la danza y su asociación histórica al género.","Ejecuta movimientos correspondientes a distintos roles (guía, partenaire, zapateo, levantada, salto), sin vincularlos con identidades de género.","Reflexiona sobre la experiencia de habitar diferentes roles, desde una perspectiva de igualdad y diversidad."]', 'PdA p. 202'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Participación en experiencias sensoperceptivas para reconocer la multidimensionalidad del propio cuerpo y en relación a otras/os.', 'pda_2025', 1, 'Avanzar en la construcción del sujeto escénico, profundizando la conciencia corporal, vocal y espacial como instrumentos expresivos y comunicativos, en relación con el grupo, el espacio y la escena.', '["Reconoce, a partir de ejercicios y prácticas corporales, nociones de estructura ósea, tono muscular, postura, eje, apoyos, peso, entre otras.","Identifica la corporeidad como una construcción social y cultural, que integra aspectos físicos, afectivos, culturales, sociales, políticos.","Manifiesta una actitud de respeto en relación con la diversidad corporal.","Reconoce el cuerpo como caja de resonancia y explora diferentes posibilidades en el uso de la voz (tímbricas, de altura, intensidad, acentuación, pausas, rítmica de las palabras, proyección, articulación, entre otras).","Reconoce y respeta la diversidad corporal y expresiva del grupo, valorando la singularidad de cada participante en la creación escénica."]', 'PdA p. 276'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Utilización consciente del espacio escénico.', 'pda_2025', 1, 'Avanzar en la construcción del sujeto escénico, profundizando la conciencia corporal, vocal y espacial como instrumentos expresivos y comunicativos, en relación con el grupo, el espacio y la escena.', '["Diferencia tipos de espacios escénicos (italiano, isabelino, circular, caja negra, entre otros).","Reconoce los límites y los sectores que definen el espacio escénico (proscenio, bastidores, cuarta pared, entre otros).","Explora direcciones, niveles, distancias y trayectorias en relación con los otros y con los objetos.","Reconoce cómo las decisiones espaciales influyen en la comunicación teatral."]', 'PdA p. 276'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Acercamiento a la noción de presencia escénica, sosteniendo la atención y la energía durante la acción teatral.', 'pda_2025', 1, 'Avanzar en la construcción del sujeto escénico, profundizando la conciencia corporal, vocal y espacial como instrumentos expresivos y comunicativos, en relación con el grupo, el espacio y la escena.', '["Mantiene la atención y concentración durante las actividades escénicas, evitando dispersarse o abandonar la acción.","Sostiene la energía corporal y vocal durante el tiempo que dura la escena o improvisación.","Reconoce la importancia de la mirada, la postura y la disposición corporal para sostener la presencia escénica.","Adapta su nivel de energía y expresividad según la situación dramática o las consignas del grupo.","Participa activamente en la construcción del clima escénico, respondiendo de manera coherente a las acciones de los demás.","Identifica momentos de pérdida o quiebre de la atención, reflexionando sobre cómo recuperarla dentro del juego teatral."]', 'PdA p. 277'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Fortalecimiento de la autonomía interpretativa durante los ejercicios de representación.', 'pda_2025', 1, 'Avanzar en la construcción del sujeto escénico, profundizando la conciencia corporal, vocal y espacial como instrumentos expresivos y comunicativos, en relación con el grupo, el espacio y la escena.', '["Sostiene la atención y la presencia escénica durante el desarrollo de las acciones teatrales, sin depender permanentemente de la guía docente.","Toma decisiones interpretativas en relación con el personaje, la situación o el clima escénico, mostrando iniciativa y criterio propio.","Ajusta sus movimientos, gestos y tonos de voz en función del sentido de la escena o las indicaciones de sus pares y de la/el docente.","Participa activamente en la construcción colectiva de la puesta, asumiendo responsabilidades y compromisos con el proceso grupal."]', 'PdA p. 277'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Experimentación con partituras físicas y/o vocales para organizar secuencias de acciones que expresen intenciones, emociones o climas escénicos.', 'pda_2025', 1, 'Avanzar en la construcción del sujeto escénico, profundizando la conciencia corporal, vocal y espacial como instrumentos expresivos y comunicativos, en relación con el grupo, el espacio y la escena.', '["Diseña y ejecuta secuencias corporales y vocales coherentes con la intención expresiva de la escena o del personaje.","Identifica la relación entre las acciones físicas, la emoción y el espacio escénico, ajustando su interpretación según las necesidades dramáticas.","Explora variaciones de ritmo, intensidad, energía y pausa en su partitura física y vocal, reconociendo sus efectos en el espectador.","Participa en procesos de ensayo en los que analiza, ajusta y consolida su partitura en diálogo con el grupo y la dirección.","Integra los distintos planos expresivos (movimiento, voz, silencio, mirada, desplazamiento) de forma orgánica y con sentido comunicativo."]', 'PdA p. 277'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Reflexión sobre el propio proceso expresivo, reconociendo avances, dificultades y estrategias personales para el trabajo escénico y la comunicación teatral.', 'pda_2025', 1, 'Avanzar en la construcción del sujeto escénico, profundizando la conciencia corporal, vocal y espacial como instrumentos expresivos y comunicativos, en relación con el grupo, el espacio y la escena.', '["Describe y analiza su propio proceso de aprendizaje, identificando progresos en la expresión corporal, vocal y escénica.","Reconoce los desafíos o bloqueos personales que afectan su interpretación y propone estrategias para superarlos.","Escucha y valora las devoluciones de la/el docente y sus pares, integrándolas en su proceso de mejora.","Utiliza vocabulario específico del teatro (presencia, acción, partitura, ritmo, intención, clima, entre otros) para comunicar reflexiones sobre su trabajo.","Manifiesta una actitud crítica y constructiva hacia su producción y la de sus compañeras/os, comprendiendo el valor del proceso creativo colectivo."]', 'PdA p. 278'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Reconocimiento de la improvisación como práctica compleja, en la que se articulan ideas, acciones, materiales y estructura.', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Participa de prácticas de improvisación guiada, a partir de diferentes consignas y estímulos como objetos, imágenes, música, sonidos, palabras y textos breves.","Explora los elementos básicos del lenguaje teatral (acción, texto, cuerpo, espacio, objetos, sonido y luz), reconociendo su función expresiva dentro de la escena.","Participa activamente en improvisaciones teatrales, proponiendo ideas, acciones o personajes coherentes con la consigna.","Integra elementos corporales, vocales y materiales (objetos, sonidos, espacio) durante la improvisación, manteniendo una intención expresiva.","Reconoce, con guía docente, la importancia de la estructura en la improvisación (inicio, desarrollo, cierre).","Reflexiona sobre cómo las decisiones espontáneas generan sentido y organización dentro de la escena."]', 'PdA p. 279'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Reconocimiento del texto dramático como uno de los componentes del teatro.', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Identifica al texto dramático como un componente específico del hecho teatral, diferenciándolo de otros lenguajes artísticos (narrativo, poético, audiovisual).","Experimenta la dramaturgia desde la escritura o desde la composición escénica.","Relaciona el texto con la acción escénica, comprendiendo que las palabras cobran sentido en la representación y a través del cuerpo y la voz de los intérpretes.","Participa en lecturas dramatizadas, explorando cómo las intenciones, emociones y ritmos del texto se traducen en acciones teatrales.","Comenta de manera oral o escrita el vínculo entre lo escrito y lo actuado, expresando cómo el texto puede transformarse en escena.","Valora el texto dramático como punto de partida o material creativo dentro del proceso teatral, reconociendo que no es la única fuente de creación escénica."]', 'PdA p. 279'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Comprensión inicial de la relación entre texto y acción escénica, experimentando cómo las palabras, los gestos y los movimientos se integran en una situación teatral.', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Combina distintos recursos (voz, cuerpo, objetos, iluminación, música, etc.) para construir climas y significados escénicos.","Explora distintos modos de decir y actuar un texto, probando variaciones de tono, ritmo o intención.","Articula texto, cuerpo y desplazamiento en breves escenas o ejercicios teatrales.","Reconoce cómo los gestos, movimientos o silencios modifican el sentido de lo dicho.","Identifica la relación entre las palabras y las acciones dentro de la representación (qué se dice / qué se hace)."]', 'PdA p. 280'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Reflexión sobre las decisiones expresivas tomadas, reconociendo cómo los distintos elementos del lenguaje teatral contribuyen a construir sentido en la escena.', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Participa en instancias de diálogo y análisis grupal sobre las producciones realizadas.","Identifica los recursos utilizados (iluminación, espacio, vestuario, sonido, actuación) y su efecto expresivo.","Argumenta sus decisiones escénicas con vocabulario inicial del lenguaje teatral (personaje, acción, clima, espacio, ritmo).","Reconoce los aportes del grupo en la construcción colectiva del sentido teatral.","Muestra disposición para revisar y mejorar su trabajo a partir de observaciones propias o del grupo."]', 'PdA p. 280'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Integración consciente de los componentes del lenguaje teatral (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia) en la creación de escenas.', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Integra de manera coherente los distintos elementos del lenguaje teatral en una misma propuesta escénica.","Adapta recursos escénicos (espacio, luz, sonido, objetos, vestuario) a las necesidades expresivas del texto o la situación dramática.","Reconoce el valor expresivo y simbólico de cada componente del lenguaje teatral y su incidencia en la construcción de sentido.","Explica las decisiones tomadas respecto de los elementos utilizados en la creación escénica.","Evalúa críticamente la relación entre los recursos escénicos empleados y el efecto expresivo logrado en la escena."]', 'PdA p. 280'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Exploración de la relación entre dramaturgia, puesta en escena y espectador.', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Reconoce cómo las decisiones estéticas inciden en la comunicación del sentido teatral.","Experimenta con diversas estructuras dramatúrgicas y compositivas, incorporando variaciones en los modos de narrar, representar y construir personajes.","Identifica el propósito comunicativo de una escena y analiza cómo se construye el vínculo con el público.","Advierte cómo las elecciones dramatúrgicas y de puesta en escena condicionan la percepción del espectador.","Participa en instancias de reflexión grupal sobre la recepción de las producciones, proponiendo ajustes en función del impacto observado.","Comenta, con vocabulario específico, cómo el montaje escénico modifica el sentido del texto o la acción dramática."]', 'PdA p. 281'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Diseño de producciones teatrales colectivas, asumiendo diferentes roles (actuación, dirección, escenografía, iluminación, sonido, dramaturgia) y comprendiendo su interdependencia dentro del hecho teatral.', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Reflexiona oralmente sobre su experiencia y reconoce aprendizajes en relación con las dimensiones organizativas, comunicativas, afectivas, entre otras.","Participa activamente en el diseño y desarrollo de producciones colectivas, asumiendo responsabilidades específicas dentro del grupo.","Comprende y respeta los roles y funciones dentro del proceso de producción teatral.","Explica cómo las decisiones de cada rol inciden en el resultado de la puesta en escena.","Evalúa el trabajo grupal, reconociendo fortalezas, dificultades y aprendizajes surgidos del proceso colaborativo."]', 'PdA p. 281'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Diseño, producción y presentación de proyectos escénicos interdisciplinarios, integrando distintos lenguajes (audiovisual, literario, visual, corporal, musical).', 'pda_2025', 1, 'Consolidar el dominio del lenguaje teatral, profundizando en la exploración y articulación de sus componentes (texto, acción, espacio, escenografía, iluminación, sonido, vestuario, dirección y dramaturgia), comprendiendo sus interrelaciones y valorando sus posibilidades expresivas como medios para la creación escénica y la comunicación de sentido.', '["Reflexiona sobre los procesos de producción, circulación y recepción del hecho teatral.","Integra de manera coherente distintos lenguajes en la planificación y realización de una propuesta escénica.","Diferencia la especificidad del lenguaje teatral de otros lenguajes artísticos/expresivos.","Selecciona y combina recursos expresivos de diferentes disciplinas para construir una narrativa o atmósfera escénica unificada.","Evalúa críticamente el proceso de integración interdisciplinaria, identificando logros, tensiones y decisiones.","Reflexiona sobre el valor del trabajo interdisciplinario como forma contemporánea de creación teatral y como medio para representar problemáticas sociales, culturales o simbólicas."]', 'PdA p. 281'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Reconocimiento del teatro como proyecto que, como tal, se planifica, se ensaya, se revisa y se comunica a otras/os.', 'pda_2025', 1, 'Afianzar los procesos de creación colectiva, reconociendo el valor del trabajo grupal, construyendo criterios de análisis, apreciación y valoración estética fundamentada.', '["Participa activamente en la planificación de pequeñas producciones teatrales, aportando ideas para personajes, escenas o materiales.","Reconoce el ensayo como parte del proceso creativo, mostrando disposición a repetir, mejorar o ajustar su actuación.","Valora la importancia del trabajo grupal y de la preparación previa antes de mostrar una escena al público.","Identifica momentos del proceso teatral (ensayo, representación, intercambio con el público).","Reflexiona con guía docente sobre los pasos realizados y los aprendizajes alcanzados durante la experiencia teatral."]', 'PdA p. 282'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Experimentación colectiva de escritura dramatúrgica.', 'pda_2025', 1, 'Afianzar los procesos de creación colectiva, reconociendo el valor del trabajo grupal, construyendo criterios de análisis, apreciación y valoración estética fundamentada.', '["Reconoce diferentes posibilidades de abordar la escritura teatral, como dramaturgia de grupo, de actrices/ actores, de directoras/es, de autoras/es, entre otras.","Escribe nuevos textos teatrales a partir del registro de improvisaciones, ensayos, ejercicios de juego teatral, asumiendo decisiones en relación con la estructura y el contenido."]', 'PdA p. 282'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Construcción de poéticas propias en producciones grupales.', 'pda_2025', 1, 'Afianzar los procesos de creación colectiva, reconociendo el valor del trabajo grupal, construyendo criterios de análisis, apreciación y valoración estética fundamentada.', '["Produce, de manera grupal, una propuesta escénica singular en la que integra aprendizajes sobre la improvisación, juego teatral y la composición escénica con las nociones de poéticas y micropoéticas.","Recupera las características de las poéticas teatrales indagadas para incorporarlas en la propia producción.","Reflexiona acerca de posiciones éticas y políticas asumidas, por ejemplo, en el abordaje o tratamiento de la violencia, la discriminación, el poder, el género, entre otras."]', 'PdA p. 282'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Construcción de la convención y las reglas propias de ficción, representación y /o metáfora, en las producciones grupales.', 'pda_2025', 1, 'Afianzar los procesos de creación colectiva, reconociendo el valor del trabajo grupal, construyendo criterios de análisis, apreciación y valoración estética fundamentada.', '["Construye, de manera grupal, una micropoética a partir de la práctica y la producción.","Acuerda en relación con el uso del espacio y el tiempo, el registro de actuación, los criterios de ficción o no ficción, la manera en que se establece el vínculo con el público, los criterios de representación, la cercanía o distancia con la realidad contextual del grupo, entre otros.","Manifiesta las intenciones del grupo y explicita las concepciones que subyacen en las producciones teatrales creadas, tanto acerca de las maneras de hacer teatro, como sobre las temáticas que se proponen."]', 'PdA p. 283'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Sistematización del trabajo grupal mediante la planificación, el ensayo y la revisión crítica.', 'pda_2025', 1, 'Afianzar los procesos de creación colectiva, reconociendo el valor del trabajo grupal, construyendo criterios de análisis, apreciación y valoración estética fundamentada.', '["Reconoce la importancia de la organización, la cooperación y la autoevaluación en la práctica escénica.","Participa activamente en la planificación del proceso teatral, aportando ideas y acordando objetivos, tareas y cronogramas con el grupo.","Sostiene una actitud de compromiso y constancia durante los ensayos, demostrando disposición para mejorar su desempeño y el del grupo.","Participa en instancias de revisión crítica, identificando avances, dificultades y posibles mejoras en las producciones teatrales.","Escucha y valora las observaciones del docente y de sus pares, proponiendo modificaciones o ajustes en función de los acuerdos colectivos.","Expresa reflexiones fundamentadas sobre el proceso de creación, reconociendo el valor de la planificación, la cooperación y la evaluación compartida."]', 'PdA p. 283'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Valoración del teatro como espacio de encuentro y construcción colectiva de conocimiento.', 'pda_2025', 1, 'Afianzar los procesos de creación colectiva, reconociendo el valor del trabajo grupal, construyendo criterios de análisis, apreciación y valoración estética fundamentada.', '["Reconoce el valor del trabajo teatral colectivo como experiencia de aprendizaje compartido y de construcción conjunta de sentido.","Relaciona la práctica teatral con otras experiencias de conocimiento, identificando cómo el teatro favorece la reflexión sobre la realidad, la comunicación y la convivencia.","Expresa con argumentos personales cómo el teatro contribuye al desarrollo de habilidades sociales, expresivas y cognitivas.","Valora al teatro como una práctica que integra lo sensible, lo intelectual y lo social, reconociéndolo como un espacio para pensar, sentir y construir colectivamente."]', 'PdA p. 283'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Reconocimiento de las características del fenómeno teatral a lo largo de la historia.', 'pda_2025', 1, 'Pensar y analizar el teatro como un fenómeno social, político y cultural, reconociendo sus vínculos con los contextos históricos y con otras manifestaciones artísticas contemporáneas.', '["Identifica hitos o etapas relevantes en la historia del teatro (por ejemplo, teatro griego, clásico, contemporáneo,entre otros).","Reconoce transformaciones en las formas de representar y en la relación entre actores y público, según los distintos contextos históricos.","Compara representaciones teatrales de diferentes épocas, observando cambios en temas, estilos o espacios escénicos.","Expresa de forma oral o escrita ideas sobre cómo el teatro manifiesta los valores, conflictos o visiones del mundo de su tiempo."]', 'PdA p. 284'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Reconocimiento del teatro como práctica vinculada con las costumbres, creencias y modos de expresión de diferentes sociedades.', 'pda_2025', 1, 'Pensar y analizar el teatro como un fenómeno social, político y cultural, reconociendo sus vínculos con los contextos históricos y con otras manifestaciones artísticas contemporáneas.', '["Observa y describe manifestaciones teatrales o rituales presentes en su contexto o en otras culturas.","Reconoce el teatro como una práctica social que comunica ideas, emociones y valores colectivos.","Establece relaciones entre manifestaciones teatrales y costumbres, celebraciones o ritos juegode diferentes pueblos.","Identifica cómo las obras o escenas teatrales pueden representar modos de vida, creencias o problemáticas sociales."]', 'PdA p. 284'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Lectura grupal de textos teatrales como posibilidad de ingresar a la representación de la alteridad y acceder a concepciones de mundo, diversidad de personas, culturas, realidades.', 'pda_2025', 1, 'Pensar y analizar el teatro como un fenómeno social, político y cultural, reconociendo sus vínculos con los contextos históricos y con otras manifestaciones artísticas contemporáneas.', '["Se acerca a la lectura de textos teatrales de diferentes características.","Reconoce, en las escenas u obras leídas; temáticas, épocas y territorios de producción.","Valora la multiplicidad de sentidos singulares y situados que se desprenden de la lectura.","Reconoce la perspectiva de género en la historia de la dramaturgia, tanto en las representaciones sociales de las obras leídas.","Explora la lectura en voz alta y reconstruye, a través de escenas, las situaciones leídas."]', 'PdA p. 285'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Exploración de relaciones entre el teatro y otras artes.', 'pda_2025', 1, 'Pensar y analizar el teatro como un fenómeno social, político y cultural, reconociendo sus vínculos con los contextos históricos y con otras manifestaciones artísticas contemporáneas.', '["Identifica elementos compartidos entre el teatro y otras disciplinas artísticas (música, plástica, literatura, cine, danza).","Reconoce influencias visuales, sonoras o narrativas de otras artes en producciones teatrales observadas o realizadas en clase.","Participa en actividades donde se integran distintos lenguajes artísticos, mostrando disposición para experimentar combinaciones expresivas.","Explica de manera sencilla cómo la integración de distintos lenguajes enriquece la comunicación escénica."]', 'PdA p. 285'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Identificación de las relaciones entre poéticas teatrales y contextos históricos.', 'pda_2025', 1, 'Pensar y analizar el teatro como un fenómeno social, político y cultural, reconociendo sus vínculos con los contextos históricos y con otras manifestaciones artísticas contemporáneas.', '["Comprende cómo los estilos, temáticas y lenguajes responden a las transformaciones sociales, ideológicas y artísticas de su tiempo.","Reconoce características de distintas poéticas teatrales (realista, épica, absurda, performática, entre otras.) y las vincula con su contexto histórico, social y cultural de origen.","Establece relaciones entre los temas, personajes o conflictos representados y los acontecimientos o debates de la época.","Compara producciones teatrales de diferentes períodos, analizando cómo cada una expresa valores, visiones del mundo o problemáticas sociales.","Utiliza vocabulario específico para describir rasgos estilísticos, estéticos y contextuales de las obras analizadas."]', 'PdA p. 285'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Reconocimiento del teatro contemporáneo como espacio de diálogo interdisciplinario, explorando vínculos con otras artes y con los discursos sociales actuales.', 'pda_2025', 1, 'Pensar y analizar el teatro como un fenómeno social, político y cultural, reconociendo sus vínculos con los contextos históricos y con otras manifestaciones artísticas contemporáneas.', '["Identifica elementos de otras disciplinas artísticas (música, danza, artes visuales, cine, performance, producciones audiovisuales) en producciones teatrales contemporáneas.","Analiza cómo el teatro actual dialoga con problemáticas sociales (género, diversidad, ambiente, memoria, tecnología, identidad, entre otras).","Participa en experiencias de creación interdisciplinaria, integrando recursos de distintas artes para construir sentido escénico.","Explica cómo las producciones contemporáneas amplían el lenguaje teatral y la relación con el público."]', 'PdA p. 286'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Valoración del teatro como medio de expresión y participación ciudadana.', 'pda_2025', 1, 'Pensar y analizar el teatro como un fenómeno social, político y cultural, reconociendo sus vínculos con los contextos históricos y con otras manifestaciones artísticas contemporáneas.', '["Reconoce el valor del teatro como espacio de reflexión, denuncia o transformación social.","Participa en debates o puestas en común sobre el papel del arte en la construcción de ciudadanía y derechos culturales.","Analiza ejemplos de teatro comunitario, político o documental, identificando sus finalidades expresivas y sociales.","Expresa ideas personales sobre cómo el teatro puede intervenir en su contexto cercano, promoviendo actitudes de respeto, empatía y compromiso colectivo."]', 'PdA p. 286'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Elaboración de reflexiones y/o análisis, utilizando vocabulario específico del lenguaje teatral (personaje, escena, público, actuación, escenario, entre otros).', 'pda_2025', 1, 'Fortalecer la interpretación y análisis crítico de producciones teatrales, promoviendo la formulación de valoraciones argumentadas.', '["Utiliza palabras del campo teatral para describir lo que observa o realiza (por ejemplo, personaje, escena, público).","Comenta lo que le gustó o no de una representación, explicando las razones.","Reconoce elementos básicos de una obra o juego teatral y los menciona en sus apreciaciones.","Escucha las opiniones de sus compañeras/os, respetando diferentes puntos de vista.","Expresa emociones o sensaciones vinculadas con la experiencia teatral de manera oral o escrita."]', 'PdA p. 287'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Identificación de recursos teatrales que generan determinados efectos (por ejemplo, luces que crean climas, gestos que provocan risa, sonidos que acompañan emociones).', 'pda_2025', 1, 'Fortalecer la interpretación y análisis crítico de producciones teatrales, promoviendo la formulación de valoraciones argumentadas.', '["Observa y reconoce recursos expresivos que influyen en la escena (gestos, tonos, luces, sonidos).","Relaciona un recurso con su efecto, comentando cómo contribuye a provocar emoción, sorpresa o risa.","Explora de manera experimental la creación de climas escénicos mediante el uso de voz, movimiento, objetos o iluminación simple.","Participa en conversaciones grupales identificando qué elementos ayudan a comunicar mejor una idea o emoción.","Valora la intencionalidad artística tras las decisiones expresivas del grupo o de los artistas observados."]', 'PdA p. 287'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Identificación de intenciones expresivas, personajes, acciones, climas y uso de recursos del lenguaje teatral (luz, sonido, espacio, objetos, vestuario).', 'pda_2025', 1, 'Fortalecer la interpretación y análisis crítico de producciones teatrales, promoviendo la formulación de valoraciones argumentadas.', '["Reconoce y describe personajes, acciones principales y climas que se generan en una representación.","Identifica intenciones expresivas (divertir, emocionar, asustar, sorprender) en las producciones teatrales observadas o creadas.","Observa y comenta el uso de recursos escénicos (luz, sonido, vestuario, objetos) y su relación con el sentido de la escena.","Diferencia entre escenas realistas, simbólicas o imaginarias, mostrando comprensión de distintos modos expresivos.","Participa en intercambios grupales, aportando ideas personales sobre lo que percibe en las producciones."]', 'PdA p. 288'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Ampliación del vocabulario disciplinar del teatro en el análisis del hecho escénico.', 'pda_2025', 1, 'Fortalecer la interpretación y análisis crítico de producciones teatrales, promoviendo la formulación de valoraciones argumentadas.', '["Comprende y emplea el vocabulario disciplinar, en forma oral o escrita, para el análisis del hecho escénico y la relación con sus propias ideas.","Utiliza un vocabulario teatral más preciso al describir o analizar producciones.","Emplea términos teatrales para comunicar ideas propias o realizar comentarios sobre lo observado.","Reconoce palabras del lenguaje teatral en materiales o conversaciones del aula y las aplica correctamente en contextos nuevos.","Relaciona conceptos con experiencias teatrales concretas (por ejemplo, “esa escena tenía un conflicto”, “la música ayudaba a crear climas”)."]', 'PdA p. 288'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Reconocimiento del valor simbólico y expresivo de los recursos escénicos, comprendiendo cómo contribuyen a comunicar emociones, ideas o mensajes en una representación.', 'pda_2025', 1, 'Fortalecer la interpretación y análisis crítico de producciones teatrales, promoviendo la formulación de valoraciones argumentadas.', '["Identifica la intención comunicativa detrás del uso de ciertos recursos escénicos.","Explica con sus palabras cómo determinados elementos ayudan a transmitir una emoción o sentido.","Explora, en sus propias producciones, el uso expresivo de materiales, objetos, vestuarios o sonidos con sentido simbólico.","Reconoce el uso expresivo de los recursos teatrales.","Reflexiona sobre cómo los recursos escénicos enriquecen la escena y generan significados más complejos."]', 'PdA p. 288'),
(17, 'eje_contenido', 'Teatro (por ciclo)', 'Reflexión crítica y colaborativa sobre el proceso y el producto teatral, identificando logros, desafíos y posibles cambios o mejoras.', 'pda_2025', 1, 'Fortalecer la interpretación y análisis crítico de producciones teatrales, promoviendo la formulación de valoraciones argumentadas.', '["Participa activamente en instancias de revisión grupal, proponiendo mejoras y reconociendo avances del grupo.","Identifica logros personales y colectivos, valorando el trabajo conjunto.","Comenta con respeto las dificultades encontradas durante el proceso creativo.","Sugiere alternativas o nuevas ideas para resolver problemas o enriquecer la puesta.","Escucha las opiniones de los demás y ajusta su actuación o propuesta en función del intercambio grupal.","Reconoce la importancia del proceso de ensayo y revisión como parte esencial del trabajo teatral."]', 'PdA p. 289'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Explicitación de la coexistencia de tecnologías diferentes (en complejidad, recursos, insumos, usos, entre otras) en una sociedad.', 'pda_2025', 1, 'Problematizar y valorar las intervenciones tecnológicas, en el marco de la construcción de subjetividades y ciudadanías, identificando cómo estas interpelan y transforman las prácticas sociales, culturales, económicas y laborales.', '["Distingue que, para una misma actividad, pueden emplearse tecnologías diferentes, según el contexto.","Compara el uso de distintas tecnologías para una misma tarea, considerando su eficiencia, los saberes requeridos, los insumos y recursos necesarios.","Reconoce que, en una misma sociedad, coexisten tecnologías diversas, con diferentes niveles de complejidad y aplicaciones (por ejemplo, en una comunidad rural, tecnologías simples como el riego por goteo coexisten con maquinaria agrícola robotizada).","Visibiliza los aportes hechos por mujeres y diversidades de género, en la historia de la tecnología."]', 'PdA p. 106'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de la creciente potencialidad de las tecnologías disponibles y su contraste con las condiciones de vida de la ciudadanía.', 'pda_2025', 1, 'Problematizar y valorar las intervenciones tecnológicas, en el marco de la construcción de subjetividades y ciudadanías, identificando cómo estas interpelan y transforman las prácticas sociales, culturales, económicas y laborales.', '["Analiza distintos sistemas tecnológicos, reconociendo los beneficios en salud, calidad de vida y capacidad de acción (por ejemplo, el marcapaso, transfusión de sangre, expediciones espaciales), así como también los perjuicios que pueden generarse (por ejemplo, los sistemas tecnológicos para elaborar alimentos ultraprocesados o químicos agrícolas nocivos para la salud).","Contrasta diferentes contextos (urbanos, rurales, escolares, comunitarios) respecto del acceso y uso de tecnologías.","Reflexiona acerca de las tensiones entre el desarrollo tecnológico y las condiciones de vida de distintas comunidades, considerando las desigualdades de acceso, las oportunidades laborales, educativas y sociales."]', 'PdA p. 107'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión del ejercicio de la ciudadanía en los entornos digitales (redes sociales, mensajería, plataformas de contenido multimedia y videojuegos), en los que también se reconocen y deben respetarse derechos y responsabilidades, tanto propias como de otras personas.', 'pda_2025', 1, 'Problematizar y valorar las intervenciones tecnológicas, en el marco de la construcción de subjetividades y ciudadanías, identificando cómo estas interpelan y transforman las prácticas sociales, culturales, económicas y laborales.', '["Analiza y reflexiona acerca de la implicancia de compartir información en entornos digitales, considerando su incidencia en la construcción de la identidad (propia y ajena) y la importancia del consentimiento, e incorporando, además, la reflexión sobre la difusión de noticias falsas (fake news) y sus efectos en la vida social.","Reconoce que los discursos de odio y la violencia de género adquieren características particulares en los entornos digitales, dada la falta de regulación de la información, la posibilidad de anonimato y la viralización.","Reconoce la existencia de un conjunto de leyes que protegen y hacen referencia al consentimiento de ciudadanas/os respecto al uso de los datos personales (por ejemplo, Ley 25.326 y Ley 27.736, ambas nacionales, y Ley 9.380, provincial).","Analiza cómo las construcciones sociales sobre la feminidad y la masculinidad se manifiestan en los entornos digitales, en los que se reproduce y/o refuerza prejuicios, estereotipos, discriminación de las distintas maneras de ser mujer, varón u otras identidades de género.","Identifica que los programas, al ser producciones humanas, reflejan valores, percepciones e interpretaciones de quienes los crearon y, por lo tanto, incorporan sesgos."]', 'PdA p. 107'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interpretación de las relaciones entre tecnología, sociedad, cultura y economía, reconociendo su interrelación e incidencia en la vida cotidiana y promoviendo una mirada crítica.', 'pda_2025', 1, 'Problematizar y valorar las intervenciones tecnológicas, en el marco de la construcción de subjetividades y ciudadanías, identificando cómo estas interpelan y transforman las prácticas sociales, culturales, económicas y laborales.', '["Analiza casos en los que los cambios tecnológicos han modificado prácticas culturales y viceversa.","Distingue los cambios en el desarrollo productivo y el surgimiento de nuevos sectores económicos, asociados a la evolución tecnológica.","Reconoce qué decisiones económicas y/o sociales alientan o desalientan distintos desarrollos tecnológicos.","Valora las tecnologías situadas, tecnologías entrañables, tecnologías alternativas y tecnologías para la inclusión social, reconociendo que consideran las condiciones sociales y productivas en las cuales se producen."]', 'PdA p. 108'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de los nuevos perfiles laborales y del cambio en los roles de las personas, en relación con la evolución tecnológica y el aumento, en escala y complejidad, de los procesos productivos.', 'pda_2025', 1, 'Problematizar y valorar las intervenciones tecnológicas, en el marco de la construcción de subjetividades y ciudadanías, identificando cómo estas interpelan y transforman las prácticas sociales, culturales, económicas y laborales.', '["Compara el rol de las personas en procesos industriales, en línea y flexibles, considerando el nivel de automatización.","Reconoce cómo la fragmentación del proceso requiere saberes más específicos y tareas más especializadas.","Explica cómo la organización del trabajo influye en las condiciones laborales y en la participación de las personas en los procesos.","Compara los roles laborales tradicionales con los actuales, destacando cómo las tecnologías han redefinido o creado nuevas funciones en el trabajo (por ejemplo, operadores de sistemas automatizados, programadores, entre otros).","Analiza cómo el aumento en la escala de producción y la complejidad técnica requieren otras formas de organización y colaboración de las personas (por ejemplo, trabajo en red, especialización, supervisión remota, trabajo por proyectos).","Analiza cómo los roles de género influyen en el acceso y la participación en los perfiles laborales, en el marco de la equidad y la inclusión."]', 'PdA p. 108'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reflexión sobre el consumo y producción de energía en Argentina y en el mundo, considerando los factores que los condicionan, el acceso equitativo y la sostenibilidad.', 'pda_2025', 1, 'Problematizar y valorar las intervenciones tecnológicas, en el marco de la construcción de subjetividades y ciudadanías, identificando cómo estas interpelan y transforman las prácticas sociales, culturales, económicas y laborales.', '["Indaga sobre las diferencias de consumo de energía en distintas sociedades.","Reconoce factores sociales, económicos, geográficos y tecnológicos, que influyen en adoptar un proceso de producción de energía u otro.","Reflexiona sobre los desafíos de acceso, distribución equitativa y sostenibilidad, en el uso de la energía a nivel global.","Reconoce cómo el consumo cotidiano de energía incide en la vida de las personas y genera situaciones de vulnerabilidad frente a cortes o interrupciones en el suministro.","Analiza las alternativas tecnológicas que contribuyen a reducir los impactos ambientales, considerando su viabilidad técnica y social."]', 'PdA p. 108'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reflexión acerca de las consecuencias sociales y ambientales de la obsolescencia, así como de la cultura del consumo.', 'pda_2025', 1, 'Problematizar y valorar las intervenciones tecnológicas, en el marco de la construcción de subjetividades y ciudadanías, identificando cómo estas interpelan y transforman las prácticas sociales, culturales, económicas y laborales.', '["Caracteriza la obsolescencia programada como una estrategia de diseño del fabricante, que limita, intencionalmente, la vida útil del producto, para promover el consumo — ya sea por el uso de materiales de menor calidad, limitación de su reparabilidad, interrupción intencional de su funcionalidad, discontinuidad en las actualizaciones de software—.","Identifica que las industrias de software y hardware se retroalimentan, para generar una obsolescencia prematura.","Compara la vida útil de diferentes productos tecnológicos, considerando las consecuencias de su reemplazo rápido.","Identifica los efectos de la obsolescencia programada en la sociedad, en el ambiente y en las economías locales.","Reflexiona sobre las implicancias sociales de la cultura de consumo y su relación con la generación de residuos (por ejemplo, evaluar cómo las campañas de marketing de productos electrónicos contribuyen a una mayor generación de residuos tecnológicos).","Reflexiona acerca de la influencia de redes sociales, publicidad y consumo, de otras personas, en las decisiones propias sobre estas cuestiones.","Reconoce que las/os consumidoras/es tienen derechos y responsabilidades legales."]', 'PdA p. 109'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de las tecnologías computacionales desde una perspectiva histórica, en relación con las diferentes brechas sociales que generan, en particular la desigualdad de género.', 'pda_2025', 1, 'Problematizar y valorar las intervenciones tecnológicas, en el marco de la construcción de subjetividades y ciudadanías, identificando cómo estas interpelan y transforman las prácticas sociales, culturales, económicas y laborales.', '["Reflexiona sobre el desarrollo de la computación, con una mirada atenta a las desigualdades de género.","Identifica las formas que adquiere la desigualdad de género en Internet (menor participación y representatividad, violencias, entre otras).","Reconoce cómo afecta la brecha digital a mujeres y disidencias y que, a su vez, estas tienen menor representatividad en la industria del software.","Identifica la importancia del desarrollo de software como respuesta a los intereses y necesidades de todas las personas, incluidos los grupos no hegemónicos.","Reconoce contenidos digitales que, al circular de forma masiva, reproducen estereotipos de género.","Identifica distintas modalidades de vulneración de derechos sexuales en entornos digitales, como difusión no consentida de material íntimo, acoso virtual, grooming, sextorsión, deepfake sexual."]', 'PdA p. 109'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de procesos tecnológicos cuyo flujo principal es la materia, enfatizando en las distintas transformaciones energéticas que se requieren en las operaciones.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Identifica las formas de energía involucradas en el funcionamiento de productos o procesos tecnológicos (mecánica, térmica, radiante, química, eléctrica, entre otras).","Describe las transformaciones de energía que ocurren durante las distintas operaciones técnicas de un proceso.","Reconoce las energías residuales y su impacto ambiental, evaluando el grado de aprovechamiento energético del proceso.","Relaciona las transformaciones energéticas con la eficiencia del proceso, proponiendo mejoras para optimizar el rendimiento y reducir efectos negativos en el ambiente.","Representa gráficamente el flujo de información en un proceso, utilizando diagramas o mapas que integran materia, energía e información."]', 'PdA p. 118'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Explicación de los procesos cuyo flujo principal es la energía.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Identifica artefactos donde el flujo principal es la energía (por ejemplo, motores, dínamo, lámparas, entre otros).","Enuncia procesos tecnológicos cuyo producto final es la energía (por ejemplo, gas, biocombustibles o electricidad), considerando las transformaciones, el transporte y el almacenamiento.","Describe las operaciones técnicas de un proceso cuyo flujo principal es la energía, destacando las operaciones que generan residuos o emisiones contaminantes (por ejemplo, etapa de enfriamiento del reactor, combustión de gas en las plantas térmicas, entre otras).","Analiza procesos de producción de energías “alternativas” y “limpias”, nacionales y extranjeras, reconociendo sus efectos sociales, económicos y ambientales.","Reflexiona sobre el impacto ambiental de los sistemas de transporte (redes de alta tensión, gasoductos, transporte de combustibles) identificando las fuentes de contaminación generadas en cada caso."]', 'PdA p. 118'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de los procesos de producción, transporte, distribución y conservación de la energía eléctrica.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Identifica los esquemas generales de funcionamiento de los procesos de generación de energía eléctrica, encontrando las operaciones comunes entre proceso distintos (por ejemplo, entre las centrales hidroeléctricas y las centrales eólicas).","Describe la estructura y función de los distintos dispositivos de generación, transporte, distribución y conservación de la energía eléctrica (como generadores, turbinas, acumuladores y transformadores, entre otros).","Analiza los procesos de producción de energía eléctrica en Argentina, y los vincula con los recursos y aspectos geográficos."]', 'PdA p. 119'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Participación en experiencias grupales que representen diversas tipologías de producción industrial.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Indaga acerca de las características de distintos procesos de producción industrial y las relaciona con los productos obtenidos.","Desarrolla la experiencia grupal, asignando roles e identificando las etapas del proceso industrial representado.","Participa de experiencias grupales de planificación e implementación de procesos de producción en escala escolar, tomando decisiones respecto de su organización.","Evalúa las decisiones tomadas en la planificación del proceso, considerando la tipología de producción (por ejemplo, en serie, por lote, o por proyecto)."]', 'PdA p. 119'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de los factores que influyen en el diseño de productos tecnológicos, considerando aspectos sociales, económicos y culturales.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Compara cómo diferentes contextos (sociales, culturales, económicos) influyen en el diseño de un mismo tipo de producto tecnológico.","Analiza la relación entre las necesidades de las/os usuarias/os y las decisiones de diseño.","Reconoce la importancia de la accesibilidad, usabilidad y sostenibilidad, en el diseño de productos tecnológicos.","Analiza el proceso de diseño de distintos productos tecnológicos, para identificar las intenciones de diseño (resolver un problema de accesibilidad, facilitar una tarea, ganancias económicas) y los actores interesados (empresas, usuarios, Estado).","Distingue procesos de diseño planificados (razón técnica), de procesos basados en exploraciones asistemáticas (predominio del ensayo y error por sobre la planificación).","Reflexiona sobre factores sociales, económicos y culturales que influyen en el diseño de un producto."]', 'PdA p. 119'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de los procesos de extracción y procesamiento de recursos para la generación de energía.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Identifica los recursos naturales utilizados para la generación de energía, diferenciando las fuentes naturales de energía no renovables (combustibles fósiles), de las fuentes naturales renovables (sol, viento, agua, entre otras).","Describe las etapas de extracción y procesamiento de recursos energéticos, reconociendo los medios técnicos, el rol de las personas y la disponibilidad del recurso.","Analiza los desafíos técnicos y ambientales en la sustitución de recursos para los procesos de energía alternativa.","Relaciona la explotación de distintos recursos, según el contexto social, económico y geográfico (por ejemplo, la extracción de litio en el norte argentino para baterías eléctricas)."]', 'PdA p. 120'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación de las funciones de los sensores en los sistemas y procesos automáticos.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Reconoce diferentes tipos de sensores, diferenciando la variable que miden (de temperatura, humedad, nivel de agua, entre otras) y los principios de funcionamiento (mecánicos, eléctricos, electrónicos).","Relaciona los sensores de un artefacto con la automatización de tareas.","Compara los procesos automáticos con y sin sensores, en términos de eficiencia y precisión en su funcionamiento.","Participa de experiencias de construcción de sensores “caseros”, con elementos mecánicos o circuitos simples (por ejemplos, sistemas con flotantes, detector de agua con un circuito abierto, entre otros)."]', 'PdA p. 120'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Exploración de la estructura y el comportamiento de sistemas automáticos con controladores, identificando las partes del sistema.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Identifica los distintos dispositivos de control para sistemas automáticos mecánicos, eléctricos, hidráulicos y neumáticos, ejemplificando con sus aplicaciones (por ejemplo, sistemas con levas y los sistemas mecánicos a cuerda).","Observa y describe el funcionamiento de controladores mediante programas de simulaciones o prototipos escolares (por ejemplo, en situaciones como encendido/ apagado de luces, regulación de temperatura o velocidad).","Explica cómo los sistemas automáticos permiten realizar tareas repetitivas o de precisión, analizando sus ventajas frente a los sistemas manuales, en términos de eficiencia, esfuerzo y calidad del resultado.","Toma decisiones sobre el tipo de control a emplear en un sistema automático (temporizador, programador cíclico, interruptores en serie o paralelo), justificando su elección según las necesidades del proceso."]', 'PdA p. 120'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación y análisis de la estructura y funcionamiento de motores (eléctricos, a combustión) que transforman la energía en movimiento.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Identifica los componentes principales de diferentes tipos de motores (eléctricos, a combustión, hidráulicos, neumáticos, entre otros).","Explica los principios de funcionamiento de los motores, describiendo las transformaciones de energía involucradas.","Compara el funcionamiento y las características de distintos tipos de motores (eléctricos, a combustión, hidráulicos, neumáticos, entre otros).","Describe las aplicaciones prácticas de diversos motores en distintos contextos (en vehículos, maquinaria industrial, electrodomésticos, entre otros).","Analiza la eficiencia energética de los motores, considerando su rendimiento y consumo."]', 'PdA p. 121'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Utilización de los instrumentos de medición y de los sistemas de unidades.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Utiliza instrumentos de medición con mayor precisión, aplicando correctamente el sistema internacional de unidades (SI), sus múltiplos y submúltiplos.","Interpreta y registra mediciones utilizando unidades adecuadas, ajustándose al tipo de variable física involucrada (longitud, temperatura, masa, tensión, corriente, entre otras).","Compara mediciones entre distintos sistemas de unidades (por ejemplo, de pulgadas a milímetros), aplicando conversiones cuando es necesario.","Evalúa la incertidumbre o posibles errores en las mediciones, reconociendo las limitaciones de los instrumentos utilizados.","Relaciona las mediciones obtenidas con los procesos técnicos observados, justificando su uso dentro de una práctica experimental o de control."]', 'PdA p. 121'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión de procedimientos básicos para la instalación y configuración de sistemas operativos libres.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Reconoce la existencia de diversas distribuciones de sistemas GNU/Linux.","Identifica los requisitos mínimos de hardware (RAM, procesador, espacio en disco) para la instalación de sistemas operativos.","Utiliza herramientas propias del proceso de instalación de un sistema operativo (por ejemplo, obtención de una imagen ISO y creación de un medio de instalación booteable).","Justifica la elección de un sistema operativo (privativo o libre), basándose en las necesidades de la/del usuaria/o, o en el propósito de la máquina."]', 'PdA p. 121'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión de las especificaciones técnicas del hardware, para optimizar el rendimiento de una computadora según las necesidades.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Identifica de qué manera se relacionan los componentes, tanto de hardware como de software, en el desarrollo de una tarea específica (por ejemplo, el uso de los recursos —RAM, procesador— cuando se ejecuta una determinada aplicación).","Interpreta especificaciones técnicas de distintos componentes.","Analiza las especificaciones de hardware que se necesitan para la ejecución de aplicaciones, hipotetizando qué mejoras podrían optimizar su uso (por ejemplo, evaluar si se podrá o no instalar un juego en un determinado equipo, y decidir si aumenta la cantidad de memoria RAM mejoraría su rendimiento).","Clasifica distintos dispositivos de almacenamiento según su tipo (magnético, óptico o electrónico) y describe ventajas y limitaciones en términos de capacidad, velocidad, durabilidad y portabilidad.","Compara diferentes dispositivos de almacenamiento, en base a la cantidad de información que almacena."]', 'PdA p. 122'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión del modo en que las computadoras almacenan y codifican información, mediante la representación en binario.', 'pda_2025', 1, 'Comprender procesos y sistemas tecnológicos en sus contextos (natural, histórico, sociocultural), identificando operaciones (de transformación, transporte, distribución, almacenamiento o recuperación) sobre los materiales, la energía y la información, y los modos en que se energizan, administran, controlan y automatizan.', '["Comprende que un código binario es un sistema con dos posibilidades, como encendido/apagado o blanco/ negro, cero/uno, que puede utilizarse para representar información.","Identifica que toda la información que se procesa y almacena en una computadora (texto, imágenes o video) es representable a través de combinaciones de unos y ceros.","Identifica la necesidad de representar la información utilizando dígitos binarios (unos y ceros), basándose en la característica de los impulsos eléctricos que se utilizan en el hardware de la computadora.","Identifica que los dígitos binarios expresan los estados de presencia o ausencia de electricidad en un cable, o magnetismo, en diferentes componentes.","Codifica información que se encuentra en distintos formatos (texto, imagen, números) usando el sistema binario.","Relaciona la cantidad de bits usados en la codificación, con la cantidad de información que se puede representar."]', 'PdA p. 122'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de las propiedades de los medios de transmisión de señales, y de su vinculación con el rendimiento de los sistemas, en alcance, velocidad y cantidad de información a transmitir.', 'pda_2025', 1, 'Comprender sistemas de información y comunicación a partir de las operaciones claves de recolección, representación, almacenamiento, transformación y transmisión de datos e información, así como también de los protocolos y artefactos involucrados en su funcionamiento.', '["Compara diferentes medios de transmisión (cables conductores de cobre, cable coaxil, ondas de radio, fibras ópticas,) reconociendo condiciones de propagación (refracción, absorción, dispersión, entre otras), alcance, velocidad o cantidad de información simultánea a transmitir.","Comprende que el ancho de banda es la cantidad de datos que se puede transportar a través de un medio de transmisión.","Evalúa el impacto de las condiciones del entorno (como la interferencia electromagnética, los obstáculos físicos o la distancia).","Reconoce que los sistemas de comunicación (como la telefonía móvil o los sistemas satelitales) emplean combinaciones de medios de transmisión."]', 'PdA p. 129');
INSERT INTO `curriculum_contenidos` (`espacio_id`, `tipo`, `titulo`, `descripcion`, `fuente`, `vigente`, `meta`, `indicadores`, `pagina`) VALUES
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de los procesos de transmisión de información a distancia, reconociendo la finalidad de las operaciones de retransmisión, amplificación y conmutación.', 'pda_2025', 1, 'Comprender sistemas de información y comunicación a partir de las operaciones claves de recolección, representación, almacenamiento, transformación y transmisión de datos e información, así como también de los protocolos y artefactos involucrados en su funcionamiento.', '["Diferencia los procesos de retransmisión y conmutación, identificando que la retransmisión permite volver a transmitir una señal (para mejorar la calidad de la señal o ampliar su alcance), y que la conmutación es un proceso que implica el establecimiento de una línea de comunicación (para aumentar el número de emisores / receptores).","Reconoce el funcionamiento y propósito de actuadores electrónicos (relés, amplificadores, repetidores), en sistemas de comunicación analógicos.","Reconoce la amplificación como el proceso de aumentar la potencia o amplitud de una señal, como en un amplificador de sonido o de radio.","Asocia el proceso de retransmisión con la amplificación de señal.","Reconoce que las técnicas de retransmisión permiten alcanzar mayores distancias, por ejemplo, las torres intermedias en la telegrafía óptica o los satélites repetidores."]', 'PdA p. 129'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión de la estructura y funcionamiento de Internet, reconociendo el protocolo IP.', 'pda_2025', 1, 'Comprender sistemas de información y comunicación a partir de las operaciones claves de recolección, representación, almacenamiento, transformación y transmisión de datos e información, así como también de los protocolos y artefactos involucrados en su funcionamiento.', '["Identifica los hitos más importantes de la historia de Internet.","Advierte la convergencia que existe entre los sistemas de telefonía e internet.","Reconoce los enlaces físicos sobre los que se construye Internet a nivel mundial, como los cables de enlace submarino, enlaces satelitales, entre otros.","Identifica el proceso de fragmentación, enrutamiento y reconstrucción de datos en redes, reconociendo que cada paquete puede seguir una ruta diferente.","Utiliza simuladores de redes para representar la asignación de IP y el flujo de paquetes, mediante modelos visuales.","Caracteriza las principales métricas de rendimiento en redes (ancho de banda, latencia, tasa de transferencia) y emplea herramientas para su medición en una red.","Reconoce que las redes de computadoras requieren de infraestructura de red (cables y dispositivos) y protocolos de comunicación, como el IP."]', 'PdA p. 130'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimientos de las prácticas que se realizan para proteger los datos digitales.', 'pda_2025', 1, 'Comprender sistemas de información y comunicación a partir de las operaciones claves de recolección, representación, almacenamiento, transformación y transmisión de datos e información, así como también de los protocolos y artefactos involucrados en su funcionamiento.', '["Identifica por qué la información en una red es vulnerable a accesos no autorizados.","Gestiona contraseñas, y las almacena de manera segura (por ejemplo, software gestor de contraseñas).","Utiliza el bloqueo y restricción de acceso a dispositivos.","Identifica el valor de realizar copias de seguridad en dispositivos externos.","Compara escenarios con y sin medidas de seguridad (por ejemplo, red Wi-Fi doméstica sin contraseña vs. red con métodos de autenticación como WPA3).","Reflexiona sobre el uso de medidas biométricas en los sistemas de autenticación y registro de identidad, reconociendo la importancia del resguardo de dichos datos."]', 'PdA p. 130'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de cómo las operaciones que realizaban las personas en los medios de comunicación a distancia, han sido delegadas en operadores o actuadores.', 'pda_2025', 1, 'Comprender sistemas de información y comunicación a partir de las operaciones claves de recolección, representación, almacenamiento, transformación y transmisión de datos e información, así como también de los protocolos y artefactos involucrados en su funcionamiento.', '["Identifica casos donde las tareas humanas, como retransmitir, conmutar o amplificar señales, fueron reemplazadas por dispositivos automáticos como relés, amplificadores o centrales telefónicas electromecánicas (por ejemplo, la persona que opera el telégrafo o la/el técnica/o de radio).","Indaga sobre el uso del relé en los primeros procesos de retransmisión automática, reemplazando a las personas.","Reflexiona sobre el vínculo entre la automatización de operaciones en la comunicación y las tareas de las personas (por ejemplo, la desaparición de quien opera manualmente las centrales telefónicas)."]', 'PdA p. 130'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Resolución de problemas de diseño de procesos tecnológicos automatizados.', 'pda_2025', 1, 'Complejizar alternativas de solución que impliquen procesos de diseño y de desarrollo de productos tecnológicos en respuesta a problemas de la comunidad cercana, teniendo en cuenta la viabilidad, la incidencia en el contexto social y la sostenibilidad.', '["Analiza problemas relacionados con la necesidad de automatizar alguna tarea o proceso realizado por las personas.","Diseña y construye sistemas automáticos, que permiten resolver una tarea con menor intervención de las personas.","Identifica las tareas de control y experimenta con controladores (mecánico, hidráulico, neumático, eléctrico, y electrónico) para automatizar alguna de las tareas (control del nivel de agua por medio de flotantes, accionamiento de una palanca por cambio de peso, sensor de humedad para controlar un sistema de riego, entre otras).","Selecciona dispositivos y herramientas adecuadas para diseñar soluciones tecnológicas automatizadas, justificando su elección.","Representa gráficamente el diseño del proceso automatizado, incluyendo la interacción de sus componentes (sensores, actuadores, controladores).","Reflexiona críticamente sobre el diseño implementado, evaluando su eficacia y su impacto social y ambiental."]', 'PdA p. 137'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Participación en experiencias de diseño de programadores cíclicos.', 'pda_2025', 1, 'Complejizar alternativas de solución que impliquen procesos de diseño y de desarrollo de productos tecnológicos en respuesta a problemas de la comunidad cercana, teniendo en cuenta la viabilidad, la incidencia en el contexto social y la sostenibilidad.', '["Reconoce que un programador cíclico permite automatizar tareas repetitivas mediante la ejecución secuenciada de acciones.","Participa en el diseño y construcción de programadores tipo cíclico (mecánicos y/o eléctricos), para automatizar tareas sencillas (por ejemplo, el encendido intermitente de luces, el movimiento de una figura o una barrera levadiza).","Identifica las funciones que cumplen los distintos componentes del sistema (por ejemplo, levas, ejes, interruptores).","Evalúa la efectividad de los sistemas automáticos con sensores, proponiendo mejoras en el diseño o la programación, según el comportamiento observado."]', 'PdA p. 137'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Resolución de problemas de diseño de sistemas de transmisión de la información a distancia, de base eléctrica, seleccionando componentes, códigos y protocolos.', 'pda_2025', 1, 'Complejizar alternativas de solución que impliquen procesos de diseño y de desarrollo de productos tecnológicos en respuesta a problemas de la comunidad cercana, teniendo en cuenta la viabilidad, la incidencia en el contexto social y la sostenibilidad.', '["Analiza situaciones donde la comunicación se puede establecer mediante un sistema eléctrico.","Participa de la construcción de un circuito telegráfico básico, empleando componentes eléctricos sencillos o herramientas digitales de simulación.","Diseña y aplica códigos (como el código Morse), para transmitir mensajes de manera clara y ordenada.","Reconoce la necesidad de acordar protocolos para organizar y controlar el intercambio de información.","Evalúa el funcionamiento del sistema diseñado, identificando dificultades y proponiendo mejoras técnicas o comunicativas."]', 'PdA p. 138'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Diseño colaborativo de algoritmos que se implementan en un lenguaje de programación y que responden a requerimientos de la/del usuaria/o.', 'pda_2025', 1, 'Complejizar alternativas de solución que impliquen procesos de diseño y de desarrollo de productos tecnológicos en respuesta a problemas de la comunidad cercana, teniendo en cuenta la viabilidad, la incidencia en el contexto social y la sostenibilidad.', '["Identifica diferentes tipos de usuarias/os, sus necesidades y expectativas.","Participa activamente en la recopilación de requerimientos de la/del usuaria/o, utilizando técnicas como entrevistas, encuestas, análisis de casos, entre otras.","Reelabora una situación problemática, a partir de los requerimientos de la/del usuaria/o.","Incorpora elementos del lenguaje de programación a la resolución de problemas, de acuerdo con los requerimientos de la/del usuaria/o, combinando diferentes estructuras de control como secuenciales, ciclos, alternativas condicionales y ciclos controlados por una condición; constantes y variables de distinto tipo; manejo de eventos controlados e interacciones con la/el usuaria/o; funciones y procedimientos."]', 'PdA p. 138'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Modularización de programas, a partir del reconocimiento, uso y creación de funciones.', 'pda_2025', 1, 'Desarrollar programas que utilicen la modularidad, manejo de eventos, estructuras de control y de datos, y que consideren criterios de legibilidad y eficacia en relación con sus objetivos, aplicando las habilidades de testeo, depuración y corrección.', '["Reconoce que la utilización de procedimientos y funciones con parámetros permite la reutilización y modularización de las soluciones.","Comprende que una función realiza una tarea específica y devuelve un valor.","Comprende el significado de una función con parámetros como una transformación de información, reconociendo la relación entre los argumentos (datos de entrada) y el resultado (datos de salida).","Identifica la necesidad y la utilidad de los parámetros como mecanismo para proveer información a funciones mediante argumentos, que le permiten, a su vez, ser aplicada en distintas instancias de un mismo problema.","Utiliza funciones para expresar el programa de forma más simple y legible.","Diferencia entre la definición de la función (que incorpora un nuevo operador al lenguaje) y su uso, mediante la aplicación a argumentos específicos."]', 'PdA p. 142'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Verificación de programas, con identificación y corrección de errores básicos (sintácticos o lógicos simples), y comparación entre resultados obtenidos y previstos.', 'pda_2025', 1, 'Desarrollar programas que utilicen la modularidad, manejo de eventos, estructuras de control y de datos, y que consideren criterios de legibilidad y eficacia en relación con sus objetivos, aplicando las habilidades de testeo, depuración y corrección.', '["Reconoce los tipos de datos de los argumentos de un comando o función para identificar errores de ejecución.","Modifica argumentos de un procedimiento o función para explorar variaciones en su comportamiento.","Colabora con el equipo en la depuración del código, aportando ideas para resolver problemas.","Reflexiona sobre los errores recurrentes y propone estrategias para evitarlos en el futuro.","Distingue entre errores de sintaxis que no permiten la ejecución del programa y los errores lógicos que surgen en tiempo de ejecución."]', 'PdA p. 142'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Modelización de información mediante tipos de datos básicos.', 'pda_2025', 1, 'Desarrollar programas que utilicen la modularidad, manejo de eventos, estructuras de control y de datos, y que consideren criterios de legibilidad y eficacia en relación con sus objetivos, aplicando las habilidades de testeo, depuración y corrección.', '["Identifica el concepto de tipo de datos asociado a las expresiones (por ejemplo, números, cadenas, colores, booleanos).","Relaciona el tipo de dato con las operaciones que tiene asociadas (por ejemplo, los números se pueden sumar, las cadenas se pueden concatenar, los booleanos se pueden combinar en disyunciones o conjunciones).","Anticipa sobre el tipo de dato que necesita una expresión.","Identifica el tipo de dato involucrado en los parámetros de un procedimiento o función."]', 'PdA p. 143'),
(18, 'eje_contenido', 'Progresiones de Aprendizaje', 'Modelado de entidades del mundo real, a partir del uso de planillas que funcionan como forma básica de base de datos.', 'pda_2025', 1, 'Desarrollar programas que utilicen la modularidad, manejo de eventos, estructuras de control y de datos, y que consideren criterios de legibilidad y eficacia en relación con sus objetivos, aplicando las habilidades de testeo, depuración y corrección.', '["Reconoce que, para un mismo fenómeno, se puede obtener una variedad de datos, valorando el uso de distintas herramientas de recolección (por ejemplo, registros manuales, encuestas, extracción de datos de fuentes como datasets y bases de datos).","Recolecta, clasifica y procesa datos, utilizando herramientas disponibles en las planillas de cálculo (filtrado, operaciones y cálculos, gráficos, entre otras).","Organiza datos de entidades con atributos en tablas, utilizando una estructura adecuada (filas para entidades y columnas para atributos).","Deduce qué entidades representan determinados registros, interpretando su estructura a partir de sus atributos y organización.","Reconoce que las planillas de cálculo pueden funcionar como una forma básica de base de datos, aproximándose a su concepto.","Reconoce, en el proceso de recolección y procesamiento de los datos, la toma de decisiones que están involucradas."]', 'PdA p. 143'),
(18, 'objetivo', 'Objetivo', 'Identificar y analizar procesos tecnológicos de su entorno y los productos que de ellos resultan y relacionarlos con las prácticas concretas de producción y uso de los mismos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'objetivo', 'Objetivo', 'Resolver situaciones problemáticas, considerando los procesos tecnológicos que intervienen en su planteo y resolución.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'objetivo', 'Objetivo', 'Planificar, ejecutar y evaluar procesos tecnológicos utilizando insumos y medios técnicos, con las medidas adecuadas para la seguridad de las personas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'objetivo', 'Objetivo', 'Comprender -a partir de su utilización y valoración- los modos de representación y comunicación que participan en la construcción del conocimiento tecnológico y que permiten otorgarle especificidad.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'objetivo', 'Objetivo', 'Incorporar crítica y progresivamente criterios para actuar en los procesos tecnológicos, garantizando la seguridad social, la salud de las personas y la sustentabilidad ambiental.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'objetivo', 'Objetivo', 'Valorar el desarrollo histórico de la tecnología, identificando los cambios producidos, aquéllos inventos que impactaron en la sociedad y el rol creativo de hombres y mujeres en estos procesos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'objetivo', 'Objetivo', 'Incrementar la curiosidad y el interés por los procesos tecnológicos, los medios técnicos que participan, sus productos resultantes y la disposición final de los residuos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'objetivo', 'Objetivo', 'Manipular materiales y usar herramientas en la construcción de procesos, objetos y estructuras simples.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'eje_contenido', 'Procesos tecnológicos', 'Análisis de procesos cuyo flujo principal es la materia, poniendo énfasis en las distintas transformaciones energéticas que se requieren en las operaciones.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'eje_contenido', 'Procesos tecnológicos', 'Análisis y diferenciación de los procesos cuyo flujo principal es la energía.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'eje_contenido', 'Procesos tecnológicos', 'Resolución de problemas de diseño de procesos tecnológicos automatizados.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'eje_contenido', 'Medios técnicos', 'Análisis e identificación de las transformaciones energéticas en los medios técnicos asociándolas a las operaciones que las originan o que producen.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'eje_contenido', 'Medios técnicos', 'Utilización de los instrumentos de medición y de los sistemas de unidades.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'eje_contenido', 'Medios técnicos', 'Identificación de artefactos que funcionan con sensores; modos de circulación de la información y elementos que constituyen el sistema.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'eje_contenido', 'La tecnología como proceso sociocultural', 'Identificación, diferenciación, análisis de las tareas que realizan las personas en los procesos tecnológicos y sus implicancias sociales, laborales, económicas, políticas, culturales, etc.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'eje_contenido', 'La tecnología como proceso sociocultural', 'Utilización y análisis de diferentes maneras de comunicar la información técnica correspondiente a un proceso, identificando la finalidad y los destinatarios para su selección y desarrollo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(18, 'eje_contenido', 'La tecnología como proceso sociocultural', 'Uso de las TIC como herramienta para elaborar, producir y comunicar la información técnica comparándolas con diversos soportes y sistemas de representación.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 179-184'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de los derechos humanos en la Constitución Nacional y en las principales declaraciones y convenciones del derecho transnacional, comprendiendo su génesis histórica y los contextos políticos de producción.', 'pda_2025', 1, 'Reconocerse a sí misma/o y a las/os otras/os como sujetos de derechos y obligaciones, comprendiendo los derechos humanos establecidos transnacionalmente, así como algunos derechos civiles, políticos y sociales de las/os jóvenes como ciudadanas/os, conquistados en la historia argentina, junto a los procedimientos e instituciones que garantizan su protección y promoción.', '["Identifica diferentes DD.HH. y las normativas internacionales que los protegen, por ejemplo, la Declaración Universal de DD.HH., los Pactos de Derechos Civiles, Políticos, Sociales, Tratados y convenciones interamericanas, contra toda forma de discriminación — étnica, mujer—, entre otras.","Comprende los contextos históricos y políticos que les dieron origen, así como los actores sociales intervinientes.","Diseña, en forma individual o colectiva, una producción creativa, utilizando medios analógicos o digitales, para promover la defensa y el ejercicio de los derechos humanos en su comunidad."]', 'PdA p. 109'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reflexión sobre las violaciones a los derechos humanos en la historia argentina y latinoamericana reciente, y en la actualidad bajo gobiernos democráticos y dictaduras.', 'pda_2025', 1, 'Reconocerse a sí misma/o y a las/os otras/os como sujetos de derechos y obligaciones, comprendiendo los derechos humanos establecidos transnacionalmente, así como algunos derechos civiles, políticos y sociales de las/os jóvenes como ciudadanas/os, conquistados en la historia argentina, junto a los procedimientos e instituciones que garantizan su protección y promoción.', '["Identifica la incorporación normativa de derechos humanos en el Derecho argentino.","Reconoce y describe casos de violaciones a los derechos humanos en Argentina y/o Latinoamérica, tanto durante dictaduras, como en gobiernos democráticos.","Releva, en su localidad/comunidad, violaciones de derechos humanos ocurridas durante la última dictadura y analiza su persistencia en la actualidad.","Advierte el impacto de estas violaciones de derechos, a corto y largo plazo, en las víctimas, las comunidades y la sociedad en general.","Reflexiona críticamente sobre el papel de la memoria, la justicia y la reparación, en la construcción de una sociedad democrática que respete los derechos humanos.","Indaga acerca de la acción de los movimientos de derechos humanos en Córdoba, en particular, y en Argentina, en general, y su accionar para la defensa y promoción de estos derechos en el pasado y el presente, redactando textos de difusión (declaraciones de principios, cartas a las autoridades, entre otros).","Investiga sobre los juicios de Lesa Humanidad en Argentina, con énfasis en aquellos desarrollados en Córdoba, y reflexiona sobre la importancia de su continuidad."]', 'PdA p. 110'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de los principales derechos civiles, políticos, sociales, económicos y culturales, presentes en normativas nacionales y provinciales, y reflexión sobre las responsabilidades del Estado en su cumplimiento, vulneración o ampliación.', 'pda_2025', 1, 'Reconocerse a sí misma/o y a las/os otras/os como sujetos de derechos y obligaciones, comprendiendo los derechos humanos establecidos transnacionalmente, así como algunos derechos civiles, políticos y sociales de las/os jóvenes como ciudadanas/os, conquistados en la historia argentina, junto a los procedimientos e instituciones que garantizan su protección y promoción.', '["Compara y clasifica las características distintivas de los diferentes tipos de derechos, analizando leyes (provinciales/nacionales) que los reconocen jurídicamente.","Comprende los distintos tipos de derechos como resultado de la participación social y política de diferentes individuos y colectivos, reflexionando sobre las posibilidades de ampliación o vulneración.","Examina los modos de intervención necesarios por parte del Estado (por ejemplo, políticas públicas educativas, sanitarias, ambientales, de empleo, de protección social, seguridad pública y seguridad ciudadana, entre otras), para la efectivización de los distintos derechos."]', 'PdA p. 110'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Investigación de prácticas ciudadanas y diferentes formas de reclamo, que involucren mecanismos formales e informales de participación, para la protección y/o ampliación de derechos civiles, políticos, sociales, económicos, culturales y colectivos, valorándolos como parte constitutiva de la democracia participativa.', 'pda_2025', 1, 'Participar democráticamente en acciones de ciudadanía local comprometidas con el desarrollo sostenible, que sean significativas para las juventudes y se aproximen a experiencias de ciudadanía global, a través de la apropiación (o no) de tecnologías digitales.', '["Busca información y realiza ejercicios efectivos de participación ciudadana individuales o de colectivos sociales, enfatizando en los contextos locales.","Identifica, en diferentes casos y/o prácticas, los mecanismos institucionales de demanda de derechos, diferenciándolos de los procedimientos informales o sociales, así como de las generaciones de derechos que involucran.","Reflexiona sobre la importancia de la participación para el ejercicio y la ampliación de derechos, estableciendo comparaciones con las formas de participación de la democracia representativa."]', 'PdA p. 112'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Diseño y realización de propuestas de intervención ciudadana, a partir de la identificación de problemáticas locales que afecten al desarrollo sostenible.', 'pda_2025', 1, 'Participar democráticamente en acciones de ciudadanía local comprometidas con el desarrollo sostenible, que sean significativas para las juventudes y se aproximen a experiencias de ciudadanía global, a través de la apropiación (o no) de tecnologías digitales.', '["Identifica y selecciona problemáticas relacionadas con el desarrollo sostenible que afectan a su comunidad, (como la gestión de residuos, acceso al agua potable, inundaciones, desigualdad en relación con el acceso a la educación de calidad, a la salud integral , prevención comunitaria de delitos, entre otras), analizando sus causas y consecuencias.","Diseña una propuesta de intervención ciudadana donde releva datos, genera contenidos y los comparte con autoridades locales y de su comunidad (por ejemplo, ferias, foros, actos, concursos educativos, entre otros), por medio de la utilización de tecnologías digitales y/o analógicas."]', 'PdA p. 112'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Participación en comunidades digitales vinculadas con problemáticas que afecten el desarrollo sostenible, relevantes para las/os adolescentes en sus contextos locales, valorando fortalezas y limitaciones para el ejercicio de derechos.', 'pda_2025', 1, 'Participar democráticamente en acciones de ciudadanía local comprometidas con el desarrollo sostenible, que sean significativas para las juventudes y se aproximen a experiencias de ciudadanía global, a través de la apropiación (o no) de tecnologías digitales.', '["Interviene en plataformas digitales (como foros, redes sociales, blogs, grupos de chat, entre otros) en cuestiones relacionadas con la agenda de desarrollo sostenible, compartiendo información, opiniones y experiencias locales.","Examina, de forma crítica, cómo se ejercen los derechos involucrados en la agenda del desarrollo sostenible, identificando sus principales fortalezas y desafíos."]', 'PdA p. 113'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión de leyes y fallos judiciales que reconocen, efectivizan o amplían derechos, como resultado de conflictos y consensos entre diferentes actores sociales y el Estado.', 'pda_2025', 1, 'Analizar críticamente los orígenes y sentidos de las normas sociales para la convivencia, indagar sobre los fundamentos éticos y democráticos de las leyes, —comprendiéndolas como construcciones históricas que resultan de negociaciones y consensos entre diferentes actores sociales— y asumir, de manera progresiva, el compromiso de respetarlas y hacerlas respetar.', '["Indaga sobre normativas, sentencias o programas estatales —nacionales, provinciales o locales—, que garantizan derechos vinculados con la vida cotidiana (por ejemplo, la ley de alcohol cero al volante, normativas de seguridad eléctrica, fallos judiciales vinculados el acceso a la salud o la inclusión escolar de personas con discapacidad, entre otros).","Investiga casos de conquista jurídicas más amplias (como el derecho a las tierras reclamado por pueblos originarios, la vivienda digna o la Asignación Universal por Hijo), identificando a los actores sociales involucrados.","Entiende la relación entre conquistas jurídicas y procesos de participación ciudadana, atravesados por conflictos de intereses, posturas políticas y valores en disputa."]', 'PdA p. 115'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento del origen democrático de las leyes que regulan la convivencia ciudadana, comprendiendo sus procedimientos y valorando su legitimidad, en contraste con formas de gobierno dictatoriales.', 'pda_2025', 1, 'Analizar críticamente los orígenes y sentidos de las normas sociales para la convivencia, indagar sobre los fundamentos éticos y democráticos de las leyes, —comprendiéndolas como construcciones históricas que resultan de negociaciones y consensos entre diferentes actores sociales— y asumir, de manera progresiva, el compromiso de respetarlas y hacerlas respetar.', '["Comprende que las leyes son el resultado de un proceso participativo que involucra a representantes elegidas/os por el pueblo, y expresa consensos sociales.","Identifica las principales etapas de dicho proceso, por ejemplo, propuesta, debate parlamentario, aprobación, sanción del poder ejecutivo (promulgación o veto).","Reflexiona sobre la obligatoriedad del cumplimiento de leyes construidas democráticamente como expresión de la voluntad popular, comparándolas con otras surgidas en gobiernos de facto."]', 'PdA p. 115'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Conocimiento de aspectos centrales de las leyes de tránsito —locales y provinciales—, comprendiendo su importancia en el uso de la vía pública, a través de situaciones problematizadoras y/o casos de la comunidad.', 'pda_2025', 1, 'Analizar críticamente los orígenes y sentidos de las normas sociales para la convivencia, indagar sobre los fundamentos éticos y democráticos de las leyes, —comprendiéndolas como construcciones históricas que resultan de negociaciones y consensos entre diferentes actores sociales— y asumir, de manera progresiva, el compromiso de respetarlas y hacerlas respetar.', '["Explica las características más relevantes de algunas normas de tránsito, incluyendo la circulación de vehículos, personas y animales.","Realiza simulaciones, en espacios locales, a partir de juegos de roles, para reconocer los derechos y obligaciones de las/os ciudadanas/os en la construcción de un tránsito seguro, responsable e inclusivo."]', 'PdA p. 116'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Desarrollo de estrategias y utilización de criterios para interpretar, difundir y publicar contenidos, de manera responsable, respetuosa y segura, en Internet y en entornos digitales.', 'pda_2025', 1, 'Asumir una posición personal argumentada en debates sobre situaciones conflictivas, casos dilemáticos o temáticas controversiales (ambiente, género y sexualidad, tecnologías digitales,trabajo, salud y adicciones, desarrollo sostenible, seguridad, entre otras) vinculadas con las juventudes, identificando actores y grupos sociales involucrados, y reflexionando sobre valores y derechos respetados o vulnerados.', '["Incorpora habilidades críticas en relación con la información, distingue información corroborada y desinformación, y evalúa la autenticidad de los contenidos antes de compartirlos, utilizando herramientas informáticas y fuentes confiables.","Realiza prácticas seguras en relación con la privacidad, por ejemplo, verifica configuraciones de privacidad, evita compartir datos personales sin analizar términos y condiciones de uso, entre otros.","Reflexiona sobre las consecuencias éticas de sus interacciones digitales,en publicaciones y contenidos compartidos.","Asume actitudes de respeto a la privacidad, diversidad, dignidad y los derechos de las/os demás, evita discursos violentos (como bullying y/o acoso) y solicita consentimientos explícitos para publicar contenidos privados.","Toma decisiones progresivamente críticas y autónomas, analizando las presiones del grupo o tendencias virales."]', 'PdA p. 119'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Problematización de la relación entre tecnologías digitales y ambiente, reflexionando sobre las consecuencias de su uso masivo y cotidiano para el desarrollo sostenible.', 'pda_2025', 1, 'Asumir una posición personal argumentada en debates sobre situaciones conflictivas, casos dilemáticos o temáticas controversiales (ambiente, género y sexualidad, tecnologías digitales,trabajo, salud y adicciones, desarrollo sostenible, seguridad, entre otras) vinculadas con las juventudes, identificando actores y grupos sociales involucrados, y reflexionando sobre valores y derechos respetados o vulnerados.', '["Propone preguntas y cuestiona representaciones dominantes y naturalizadas sobre las tecnologías digitales, como su supuesta “inmaterialidad” o materialidad liviana, la ausencia de impacto ambiental de los dispositivos digitales, entre otras.","Investiga propuestas de colectivos críticos que vinculan las tecnologías digitales y el ambiente, como la obsolescencia programada, la reutilización/reciclaje de componentes tecnológicos, los proyectos tecno-solidarios (por ejemplo, el movimiento de los “cyber cirujas”, la economía circular u otros similares)."]', 'PdA p. 119'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Discusión argumentada sobre el sexting como práctica social de las/os adolescentes, vinculada con el ejercicio de derechos a la sexualidad, y en tensión con posibles riesgos para el cuidado de la intimidad y el derecho a la privacidad, a la libertad o al condicionamiento del grupo de pares, entre otros, a partir de situaciones problematizadoras.', 'pda_2025', 1, 'Asumir una posición personal argumentada en debates sobre situaciones conflictivas, casos dilemáticos o temáticas controversiales (ambiente, género y sexualidad, tecnologías digitales,trabajo, salud y adicciones, desarrollo sostenible, seguridad, entre otras) vinculadas con las juventudes, identificando actores y grupos sociales involucrados, y reflexionando sobre valores y derechos respetados o vulnerados.', '["Comprende las características distintivas del sexting, diferenciándolo de otras prácticas en entornos digitales vinculadas con la privacidad.","Reconoce al sexting como una expresión del derecho a la sexualidad y la libertad, para explorar su identidad sexual, vincularse íntimamente y decidir, de manera responsable y consciente, sobre su cuerpo.","Dialoga, de manera crítica, sobre riesgos de dichas prácticas (difusión de imágenes sin consentimiento, manipulación de contenidos con aplicaciones de IA, acoso, humillación pública y daño emocional, entre otros).","Problematiza posibles presiones del grupo de pares, y reflexiona sobre la libertad de elección y el bienestar.","Participa en debates o foros, tomando una posición personal autónoma y fundamentada, a partir de información y reflexiones colectivas."]', 'PdA p. 120'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de las diferentes dimensiones de la sexualidad, abordando aspectos de una educación sexual integral relativos al cuidado de sí misma/o y de las/os otras/os, el placer, el amor y la responsabilidad, desde una perspectiva de género.', 'pda_2025', 1, 'Reconocer la diversidad como aquello que enriquece la convivencia en ámbitos escolares, sociales y espacios virtuales, a través de la puesta en valor de experiencias colectivas, normativas e identidades (de género, étnicas, socioculturales, políticas), para revertir representaciones estereotipadas, prejuiciosas y discriminatorias.', '["Identifica diferentes aspectos (biológicos, emocionales y éticos) presentes en la construcción de la identidad sexual y en las prácticas sexuales.","Analiza, de manera crítica, usos, costumbres y mandatos asociados a prácticas sexuales de las/os jóvenes.","Reflexiona acerca de los fundamentos de sus elecciones personales y sus consecuencias en los proyectos vitales.","Identifica principios de igualdad y responsabilidad de sus conductas, amparadas por derechos sexuales reproductivos y no reproductivos, entre otros.","Comprende derechos básicos vinculados con la sexualidad (a la información, a la salud, a la protección, entre otros), así como con las responsabilidades (respeto mutuo, consentimiento, límites personales, comunicación abierta entre pares y adultos, decisiones informadas sobre su bienestar, entre otras)."]', 'PdA p. 122'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento y realización de acciones para prevenir y erradicar formas de violencia por razones de género, de clase, étnicas, en los ámbitos público y privado, problematizando concepciones sobre la otredad.', 'pda_2025', 1, 'Reconocer la diversidad como aquello que enriquece la convivencia en ámbitos escolares, sociales y espacios virtuales, a través de la puesta en valor de experiencias colectivas, normativas e identidades (de género, étnicas, socioculturales, políticas), para revertir representaciones estereotipadas, prejuiciosas y discriminatorias.', '["Identifica diferentes formas del ejercicio de la violencia de género (física, discursiva, simbólica), así como los discursos y representaciones patriarcales y binarias de la sexualidad y el género.","Reconoce y cuestiona las estructuras sociales que generan desigualdades y disputas de poder entre géneros, así como prácticas y discursos que establecen lo normal/anormal de las identidades de género y cuerpos binarios.","Conoce y propone acciones que contribuyen al cumplimiento de la Ley 26.485 de Protección Integral, para prevenir, sancionar y erradicar la violencia contra las mujeres.","Indaga sobre acciones promovidas por colectivos de adolescentes y jóvenes para prevenir y erradicar las violencias institucionales (marchas de la gorra, contra el gatillo fácil, entre otras)","Valora las prácticas de participación y reclamo de derechos de diferentes colectivos sociales, vinculadas con la prevención y erradicación de las violencias."]', 'PdA p. 123'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento y discusión de representaciones estereotipadas sobre la diversidad, presentes en los diseños de las tecnologías digitales y aplicaciones de I.A.', 'pda_2025', 1, 'Reconocer la diversidad como aquello que enriquece la convivencia en ámbitos escolares, sociales y espacios virtuales, a través de la puesta en valor de experiencias colectivas, normativas e identidades (de género, étnicas, socioculturales, políticas), para revertir representaciones estereotipadas, prejuiciosas y discriminatorias.', '["Identifica y examina estereotipos y prejuicios —clasistas, étnicos, de género, entre otros — en los formatos, configuraciones y otros componentes de dispositivos y tecnologías digitales (videojuegos, aplicaciones y asistentes virtuales con voz femenina, chatbot de I.A).","Reconoce la no neutralidad y presencia de sesgos en relación con la diversidad de algunas tecnologías digitales de uso cotidiano de las/os jóvenes.","Revisa su propio uso de tecnologías digitales y reflexiona acerca de cómo sus decisiones pueden contribuir a cuestionar estereotipos y prejuicios presentes en ellas."]', 'PdA p. 123'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Conocimiento de la Constitución Nacional y la Constitución de la Provincia de Córdoba, a partir de sus estructuras, principales artículos y mecanismos de participación política, analizando las relaciones de jerarquía normativa entre los diferentes textos constitucionales.', 'pda_2025', 1, 'Comprender la configuración del sistema político argentino, provincial y municipal, a partir de los marcos constitucionales que los sustentan —reconociéndolos como contratos sociales e históricos— distinguiendo las competencias básicas de los poderes del Estado y sus principales órganos, reflexionando sobre su importancia para la participación ciudadana y los derechos humanos, en situaciones del presente y de la historia reciente.', '["Explica la organización general, los diferentes componentes, los artículos más relevantes y las formas de ejercicio de los derechos políticos presentes en los textos constitucionales.","Comprende la subordinación jurídico-política de la Constitución de la Provincia de Córdoba a la Constitución Nacional, a través de casos de conflictos entre normativas."]', 'PdA p. 124'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reflexión ética sobre la importancia de las constituciones, como marcos jurídicos y garantes de la participación ciudadana y los derechos humanos, a partir de análisis de casos y situaciones en la actualidad y en el pasado reciente.', 'pda_2025', 1, 'Comprender la configuración del sistema político argentino, provincial y municipal, a partir de los marcos constitucionales que los sustentan —reconociéndolos como contratos sociales e históricos— distinguiendo las competencias básicas de los poderes del Estado y sus principales órganos, reflexionando sobre su importancia para la participación ciudadana y los derechos humanos, en situaciones del presente y de la historia reciente.', '["Considera a las diferentes constituciones como sistemas de protección de la ciudadanía, ante diversas formas de relaciones de poder.","Compara casos, historias de vida, situaciones sociales, pasadas y presentes, donde se respetaron o vulneraron derechos y garantías constitucionales.","Expone oralmente, argumentando posiciones personales sobre la importancia de la Constitución Nacional en la vida cotidiana y en la construcción de una sociedad democrática."]', 'PdA p. 125'),
(19, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión de la Constitución Nacional, provincial y cartas orgánicas municipales como contratos sociales que resultaron de conflictos y consensos entre diversos actores sociales a lo largo de la historia, indagando en los proyectos de país/provincia/municipio que las sustentan.', 'pda_2025', 1, 'Comprender la configuración del sistema político argentino, provincial y municipal, a partir de los marcos constitucionales que los sustentan —reconociéndolos como contratos sociales e históricos— distinguiendo las competencias básicas de los poderes del Estado y sus principales órganos, reflexionando sobre su importancia para la participación ciudadana y los derechos humanos, en situaciones del presente y de la historia reciente.', '["Interpreta los textos constitucionales nacionales, provinciales y municipales como normas que resultaron de acuerdos sociales, se modificaron y se pueden seguir transformando con el tiempo.","Discierne intereses y proyectos políticos de diversos actores sociales que incidieron en la producción de los textos constitucionales."]', 'PdA p. 125'),
(19, 'objetivo', 'Objetivo', 'Analizar críticamente los discursos hegemónicos y mensajes imperantes en los medios masivos de comunicación en relación con las prácticas de consumo e identificación.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'objetivo', 'Objetivo', 'Reconocer los actores y grupos involucrados en situaciones conflictivas y ponderar la legitimidad de sus opiniones, sentimientos, perspectivas e intereses.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'objetivo', 'Objetivo', 'Tomar posición crecientemente crítica y argumentativa frente a problemas de ciudadanía de la Argentina y la Provincia de Córdoba, a partir de conocer la historia y postulados fundamentales de diferentes corrientes ideológicas y tendencias políticas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'objetivo', 'Objetivo', 'Utilizar criterios de justicia y solidaridad al deliberar sobre problemáticas vinculadas con los Derechos Humanos, el ejercicio de la ciudadanía y problemáticas presentadas en los medios de comunicación o manifiestas en el entorno social.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'objetivo', 'Objetivo', 'Desarrollar la reflexión crítica y la deliberación argumentativa en torno a temas relevantes de la realidad social: Sexualidad, Tecnologías de la Información y la Comunicación.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'objetivo', 'Objetivo', 'Interpretar situaciones de injusticia, discriminación y exclusión, en relación con los principios normativos por los cuales deben ser denunciadas y revertidas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'objetivo', 'Objetivo', 'Reconocer las funciones básicas del Estado en una sociedad democrática y la necesidad de un orden jurídico justo y legítimo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'objetivo', 'Objetivo', 'Identificar y utilizar diversos mecanismos de participación en la esfera pública con los que cuentan, en el país y en la Provincia de Córdoba, para reclamar por sus derechos o tomar parte en la deliberación sobre el orden normativo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'eje_contenido', 'Reflexión ética', 'Comprensión del carácter conflictivo e histórico de las relaciones sociales y políticas, a partir de identificar actores, contrastando sus intereses y derechos, sus valores y principios.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'eje_contenido', 'Reflexión ética', 'Análisis crítico de discursos emitidos desde las Tecnologías de Información y Comunicación (los medios de comunicación masiva, Internet, videojuegos, publicidades, juegos de computadora, series de televisión, redes virtuales, entre otros), identificando valores vigentes, concepciones de la felicidad, relaciones de poder, contenidos violentos y estereotipos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'eje_contenido', 'Construcción histórica de las identidades', 'Fundamentación teórica de valores como justicia, igualdad y paz, a partir de su reconocimiento en situaciones donde tengan vigencia y en situaciones donde primen relaciones de injusticia, desigualdad o violencia.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'eje_contenido', 'Construcción histórica de las identidades', 'Lectura crítica de la pluralidad, expresiones culturales, cosmovisiones y sistemas valorativos, generando espacios de convivencia y participación para la difusión y defensa de derechos identitarios.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'eje_contenido', 'Construcción histórica de las identidades', 'Análisis y valoración de las formas de resistencia y defensa de la dignidad, generadas por parte de los grupos subordinados –poblaciones en situación de pobreza, migrantes y otros sectores excluidos- ante diferentes formas de prejuicio, maltrato y discriminación.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'eje_contenido', 'Derechos y participación', 'Conocimiento básico de la Constitución Nacional, su estructura y principales artículos; las reformas constitucionales y las rupturas del orden constitucional.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'eje_contenido', 'Derechos y participación', 'Conocimiento de la organización federal del Estado y la división e interdependencia de poderes del Estado, en cada uno de sus niveles.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'eje_contenido', 'Derechos y participación', 'Reconocimiento de los derechos humanos en la Constitución Nacional y en las principales declaraciones y convenciones del derecho transnacional.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(19, 'eje_contenido', 'Intervención sociocomunitaria', 'Integración de saberes para la comprensión de problemas sociocomunitarios y su conceptualización teórica a partir de la experiencia.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 161-164'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis crítico de las configuraciones sociales y culturales que influyen en la percepción y la expresión de la propia corporeidad, para valorar la multiplicidad de capacidades y posibilidades motrices, propias y de los demás.', 'pda_2025', 1, 'Construir una corporeidad consciente, mediante la aplicación combinada de habilidades y capacidades físicas, en un amplio repertorio de prácticas motrices, para resolver desafíos con autonomía y creatividad, transferir soluciones a diversas situaciones y habilitar la comunicación corporal en el marco de la inclusión y valoración de la diversidad, en todas sus expresiones.', '["Analiza y argumenta cómo los cambios y continuidades corporales, propios de la adolescencia, influyen en la percepción de sí misma/o y en la relación con la/el otra/o, en las prácticas motrices.","Construye su conciencia corporal al identificar y expresar con claridad las capacidades y posibilidades motrices propias de la conclusión de cada práctica.","Utiliza constructivamente la retroalimentación sobre sus acciones motrices, al identificar errores y proponer cambios en su estrategia.","Reflexiona sobre los patrones hegemónicos de belleza y su influencia en la corporalidad, a partir de prácticas vinculadas con la cultura del cuerpo y del movimiento.","Reconoce las dificultades que limitan la participación de personas con discapacidad en prácticas motrices y diseña propuestas para favorecer su inclusión.","Cuestiona los mensajes hegemónicos que los medios de comunicación divulgan sobre las prácticas corporales y motrices, expresando su opinión en intercambios con otras/os","Valora relaciones igualitarias, respetuosas y responsables entre los géneros, en prácticas corporales y motrices.","Reflexiona críticamente sobre mitos vinculados a la limitaciones en la realización de prácticas corporales durante el ciclo menstrual y reconoce que su influencia puede variar en cada cuerpo y en cada persona.","Reconoce las barreras sociales que limitan la participación de personas con discapacidad en prácticas motrices y diseña propuestas para favorecer su inclusión."]', 'PdA p. 83'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Vivencia, experimentación e identificación de prácticas corporales y motrices que promuevan el desarrollo de capacidades condicionales.', 'pda_2025', 1, 'Construir una corporeidad consciente, mediante la aplicación combinada de habilidades y capacidades físicas, en un amplio repertorio de prácticas motrices, para resolver desafíos con autonomía y creatividad, transferir soluciones a diversas situaciones y habilitar la comunicación corporal en el marco de la inclusión y valoración de la diversidad, en todas sus expresiones.', '["Establece relaciones y diferencias entre las distintas capacidades condicionales y valora su desarrollo para el bienestar de las personas.","Identifica y expresa los cambios fisiológicos que experimenta el cuerpo durante diferentes esfuerzos.","Reconoce escalas subjetivas de esfuerzo, para monitorear y comunicar la intensidad de su trabajo y establecer relaciones con sus capacidades físicas y límites personales.","Identifica la capacidad condicional que se prioriza en una actividad motriz y ajusta su esfuerzo, de forma consciente, para alcanzar el objetivo propuesto.","Diferencia sensaciones corporales (fatiga, respiración) asociadas a respuestas fisiológicas, propias de esfuerzos aeróbicos y anaeróbicos.","Explica características y posibilidades de desarrollo de la fuerza en la adolescencia.","Reconoce la importancia de la flexibilidad, en la prevención de lesiones, y la mejora de la amplitud de movimiento, en acciones específicas.","Diferencia velocidad de reacción, de velocidad de desplazamiento.","Practica la respiración consciente en situaciones de reposo, esfuerzo y recuperación."]', 'PdA p. 84'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento y aplicación de capacidades coordinativas, para resolver problemas motores que requieran el ajuste corporal a los cambios del entorno inmediato.', 'pda_2025', 1, 'Construir una corporeidad consciente, mediante la aplicación combinada de habilidades y capacidades físicas, en un amplio repertorio de prácticas motrices, para resolver desafíos con autonomía y creatividad, transferir soluciones a diversas situaciones y habilitar la comunicación corporal en el marco de la inclusión y valoración de la diversidad, en todas sus expresiones.', '["Conceptualiza la capacidad motora de coordinación, reconoce su clasificación e identifica su importancia, para ampliar la disponibilidad y eficacia en las acciones motrices.","Identifica y denomina la/s capacidad/es coordinativa/s específica/s (por ejemplo, equilibrio, ritmo, orientación) que permiten resolver una tarea motriz.","Practica tareas coordinativas con diferentes presiones (tiempo, carga física y psíquica, complejidad, organización y variabilidad), integradas a las habilidades motoras.","Ajusta su postura corporal para mantener el control y la estabilidad en situaciones motrices dinámicas, y completar la acción propuesta.","Sincroniza sus acciones motrices con estímulos externos (ej como la música, el rebote de una pelota o el ritmo de una/un compañera/o), para lograr una ejecución precisa y fluida.","Responde rápidamente a los cambios espaciales del entorno (por ejemplo, trayectorias de objetos o desplazamientos de compañeras/os, adversarias/os) y adapta su dirección y posición para coordinar con ellas/os.","Integra movimientos de diferentes partes del cuerpo, de manera coordinada, para ejecutar habilidades compuestas, y adecua sus acciones al espacio y a las demandas inmediatas de la tarea."]', 'PdA p. 84'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Aplicación de habilidades motoras específicas y compuestas en prácticas corporales variadas, y reconocimiento de su utilidad y transferencia a otros contextos o actividades.', 'pda_2025', 1, 'Construir una corporeidad consciente, mediante la aplicación combinada de habilidades y capacidades físicas, en un amplio repertorio de prácticas motrices, para resolver desafíos con autonomía y creatividad, transferir soluciones a diversas situaciones y habilitar la comunicación corporal en el marco de la inclusión y valoración de la diversidad, en todas sus expresiones.', '["Identifica y explica modos de ejecución y aplicación de habilidades motrices, para un desempeño adecuado y seguro en las prácticas corporales.","Selecciona y aplica la habilidad motora más apropiada para resolver problemas motrices variables (por ejemplo, un tipo de pase, un tipo de agarre o una forma de desplazamiento), propios de una tarea o de una situación de juego.","Ajusta la ejecución de una habilidad específica en función de los cambios rápidos en el entorno, en situaciones de incertidumbre, eligiendo la alternativa más adecuada.","Adapta y transforma creativamente sus acciones motrices, ante la variabilidad del entorno y la dinámica de las situaciones ludomotrices.","Propone y ejemplifica la transferencia de una habilidad motora a otras situaciones de la vida cotidiana o a diferentes deportes y actividades físicas.","Diseña y aplica soluciones motrices en equipo, con coordinación de acciones y habilidades, para mejorar el rendimiento grupal y resolver problemas motrices.","Reflexiona sobre la frustración y/o el enojo, propios y de sus pares, que surgen al enfrentar dificultades o errores en la práctica motriz, buscando comprender su sentido y las formas de tramitarlos colectivamente."]', 'PdA p. 85'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de hábitos de vida activos y saludables, para optimizar su bienestar corporal y motriz.', 'pda_2025', 1, 'Valorar la importancia de incorporar prácticas corporales sistemáticas y sostenibles como parte de un proyecto de vida saludable, con análisis de hábitos diversos y de los efectos anatómicos, fisiológicos, socio-afectivos propios de estas prácticas.', '["Identifica modos de vida saludables, orientados a la valoración de la salud como responsabilidad individual y colectiva.","Reconoce cómo la alimentación, la hidratación y el descanso influyen en el desarrollo y la recuperación de la condición motriz, y explica su impacto en el rendimiento deportivo y en la salud.","Registra cómo varían su ritmo cardíaco y respiratorio según la práctica corporal, reconoce los efectos en su cuerpo y toma decisiones a partir de esos datos, con o sin el uso de dispositivos o aplicaciones digitales.","Registra y valora sus propias posibilidades y limitaciones físicas, y a partir de ello, ajusta las actividades, para construir hábitos saludables sostenibles a lo largo de su vida.","Reflexiona sobre cómo sus acciones y decisiones, relacionadas con hábitos de vida activos y saludables, afectan en su estado emocional y en las sus relaciones con las/os demás."]', 'PdA p. 89'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión de las posibilidades del movimiento articular y de la variación postural, en distintas situaciones motrices, y relación de estas dinámicas con la función del sistema locomotor.', 'pda_2025', 1, 'Valorar la importancia de incorporar prácticas corporales sistemáticas y sostenibles como parte de un proyecto de vida saludable, con análisis de hábitos diversos y de los efectos anatómicos, fisiológicos, socio-afectivos propios de estas prácticas.', '["Nombra y demuestra los movimientos articulares, explicando cómo la limitación o ampliación de su rango de movimiento influye en la ejecución eficiente de una acción motriz específica.","Comprende la postura como una organización dinámica del cuerpo y explica su relación con el espacio, el tiempo, las emociones, las intenciones y el entorno sociocultural del movimiento.","Explica y ejemplifica acerca de cómo la modificación intencional del rango de movimiento de una articulación altera la variabilidad y el control de su postura corporal, al resolver un desafío motriz.","Analiza adaptaciones posturales del ser humano a lo largo de la historia, y su influencia en la calidad de vida.","Cuestiona la creencia popular de la “mala postura” y argumenta la importancia de la variabilidad postural y el movimiento consciente, para el bienestar neuro-músculo-esquelético.","Analiza su postura durante tareas cotidianas (sentarse, levantar objetos, usar dispositivos), y ajusta el cuerpo, al respetar la diversidad de posiciones “correctas” posibles.","Valora la importancia de incorporar el cuidado postural, como un hábito fundamental para mantener un estilo de vida activo y prevenir dolencias a largo plazo."]', 'PdA p. 89'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Exploración y conocimiento de elementos constitutivos de diferentes danzas y expresiones artísticas de movimiento, como danzas, expresión corporal, expresión artística de movimiento, entre otros.', 'pda_2025', 1, 'Resolver situaciones problemáticas en prácticas corporales ludomotrices, recreativas, expresivas, y de iniciación deportiva escolar, y consolidando su autonomía en la toma de decisiones, mediante el diseño y aplicación de estrategias y tácticas en el marco del juego limpio, la inclusión y la equidad de género.', '["Reconoce elementos de prácticas expresivas, como ritmo, niveles en el espacio, trayectorias, comunicación, entre otras.","Distingue bailes típicos y danzas populares de la cultura latinoamericana e identifica rasgos distintivos y contexto cultural.","Elabora grupalmente coreografías, expresando sentimientos y emociones.","Realiza prácticas creativo-expresivas que favorecen la dinámica positiva del grupo y promueven la desinhibición y la integración.","Diseña y ejecuta coreografías grupales que expresan sentimientos y emociones, incorporando elementos del lenguaje corporal y de la música.","Reconoce las limitaciones que imponen los estereotipos de género en las prácticas expresivas y propone formas de participación libres de esos condicionamientos."]', 'PdA p. 94'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reflexión crítica sobre la recreación como un fenómeno cultural y un espacio para la inclusión y el encuentro con la diversidad.', 'pda_2025', 1, 'Resolver situaciones problemáticas en prácticas corporales ludomotrices, recreativas, expresivas, y de iniciación deportiva escolar, y consolidando su autonomía en la toma de decisiones, mediante el diseño y aplicación de estrategias y tácticas en el marco del juego limpio, la inclusión y la equidad de género.', '["Analiza diversas prácticas recreativas e interpreta cómo expresan, reproducen o desafían las normas sociales, los roles de género y la valoración de la diversidad.","Propone y aplica ajustes creativos en las prácticas recreativas, y fundamenta de qué modo, esas adaptaciones, favorecen la inclusión de la diversidad corporal y funcional.","Investiga y explica cómo el tiempo libre y los espacios de recreación se distribuyen de forma desigual en distintos grupos sociales, y elabora acciones colectivas para promover el acceso equitativo a la recreación."]', 'PdA p. 94'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación y resolución de desafíos motrices complejos, en prácticas deportivas escolares centradas en la ejecución en entornos estables, como las atléticas, gimnásticas, acuáticas, entre otras.', 'pda_2025', 1, 'Resolver situaciones problemáticas en prácticas corporales ludomotrices, recreativas, expresivas, y de iniciación deportiva escolar, y consolidando su autonomía en la toma de decisiones, mediante el diseño y aplicación de estrategias y tácticas en el marco del juego limpio, la inclusión y la equidad de género.', '["Aplica habilidades específicas de las prácticas atléticas de pista y campo, y ajusta progresivamente su coordinación, fuerza y ritmo de ejecución.","Identifica dificultades durante los desafíos motrices y selecciona estrategias de ajuste para alcanzar el objetivo de la tarea.","Integra destrezas básicas de la gimnasia (rol adelante y atrás, giros, saltos, equilibraciones, medialuna y vertical), en secuencias que demuestran control corporal y seguridad.","Aplica principios técnicos fundamentales en la ejecución de acciones motrices, reconociendo su relación con la eficacia y seguridad del movimiento.","Utiliza la terminología específica de las prácticas, para describir, analizar o explicar los desafíos motrices que enfrenta.","Afianza habilidades específicas propias de uno o más estilos de nado, ajusta la coordinación de la respiración con el movimiento y se desplaza con fluidez y eficiencia, en diferentes distancias y situaciones que incluyen cambios de posición, giros sobre diferentes ejes y nado subacuático, con control de la orientación espacial, según las posibilidades de implementación de cada institución.","Analiza cómo la alta activación o baja motivación influyen en la precisión, el ritmo y el control postural, durante la resolución motriz."]', 'PdA p. 94'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación y análisis de los elementos constitutivos de las prácticas de iniciación deportiva de situación, con reconocimiento de su interacción en entornos cambiantes.', 'pda_2025', 1, 'Resolver situaciones problemáticas en prácticas corporales ludomotrices, recreativas, expresivas, y de iniciación deportiva escolar, y consolidando su autonomía en la toma de decisiones, mediante el diseño y aplicación de estrategias y tácticas en el marco del juego limpio, la inclusión y la equidad de género.', '["Analiza los elementos constitutivos de diversos juegos modificados, y explica cómo los cambios en el objetivo, las reglas, los roles, el espacio, el móvil/implemento o las interacciones motrices, modifican en las estrategias y las decisiones tácticas durante el juego.","Distingue las acciones de ataque y defensa, e identifica los roles y subroles que intervienen en los juegos de oposición y cooperación-oposición.","Analiza cómo las reglas del juego orientan las decisiones, condicionan las acciones posibles y determinan la dinámica colectiva del juego.","Reconoce que el espacio de juego, junto con la presencia de oponentes y compañeras/os, constituye un entorno variable que exige ajustes continuos en las acciones motrices.","Diseña y adapta juegos modificados, ajustando reglas y roles, según los objetivos propuestos y las necesidades del grupo.","Resuelve conflictos surgidos por diferencias en la interpretación de las reglas o por la intensidad emocional del juego, y argumenta las decisiones tomadas en función del bienestar y el disfrute colectivo."]', 'PdA p. 95'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Ajuste de sus acciones motrices en prácticas de iniciación deportiva de situación, mediante la selección de la acción táctica más adecuada para resolver los desafíos que surgen durante el juego.', 'pda_2025', 1, 'Resolver situaciones problemáticas en prácticas corporales ludomotrices, recreativas, expresivas, y de iniciación deportiva escolar, y consolidando su autonomía en la toma de decisiones, mediante el diseño y aplicación de estrategias y tácticas en el marco del juego limpio, la inclusión y la equidad de género.', '["Diseña y reajusta estrategias tácticas individuales en juegos modificados de oposición, sin cooperación (tenis 1 vs. 1, golf ), anticipando las acciones del oponente y seleccionando la respuesta más eficaz para alcanzar el objetivo.","Adapta y define estrategias en prácticas de lucha o combate codificadas, identifica fortalezas y vulnerabilidades de su oponente, y ejecuta acciones orientadas al control, la seguridad personal y la de su adversaria/o.","Realiza ajustes en sus movimientos y decisiones frente a los cambios repentinos del entorno o las acciones de su oponente, y demuestra adaptabilidad y control, en tiempo real.","Reconoce diferentes lógicas y estructuras de juego (de blanco y diana, cancha dividida o muro, invasión, campo y bate) y aplica principios tácticos propios de los en juegos modificados y juegos reducidos.","Conoce y aplica habilidades motoras específicas y compuestas de la práctica deportiva seleccionada en situaciones abiertas e inestables.","Resuelve situaciones en prácticas de iniciación deportiva de cooperación y oposición, emplea medios tácticos grupales y avanza en la comunicación motriz con su equipo.","Resuelve situaciones problemáticas en juegos motores acuáticos con habilidades motrices combinadas, y reconoce la importancia de la cooperación y la comunicación con el grupo, según las posibilidades de implementación de cada institución.","Crea y acepta acuerdos colectivos para llegar al objetivo propuesto."]', 'PdA p. 95'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de los aportes y beneficios de prácticas corporales-motrices, alternativas y emergentes, para la cultura del cuerpo y del movimiento.', 'pda_2025', 1, 'Resolver situaciones problemáticas en prácticas corporales ludomotrices, recreativas, expresivas, y de iniciación deportiva escolar, y consolidando su autonomía en la toma de decisiones, mediante el diseño y aplicación de estrategias y tácticas en el marco del juego limpio, la inclusión y la equidad de género.', '["Identifica prácticas corporales y motrices diferentes a las de su entorno, vinculadas con distintos contextos locales, regionales, culturales, reconociendo su valor en la construcción de la cultura del cuerpo y del movimiento.","Compara las formas en que las prácticas alternativas (como slackline, calistenia o acroyoga) redefinen las nociones de capacidad, riesgo y belleza corporal frente a las prácticas convencionales, valorando la diversidad de movimientos y expresiones que ofrecen.","Investiga prácticas corporales y motrices urbanas, como Skateboarding, BMX, Parkour, Rollerblading, entre otras, y analiza sus significados sociales, culturales y motrices en la vida cotidiana.","Analiza y aplica la lógica interna y las reglas de un deporte alternativo (por ejemplo Ultimate Frisbee, Kin-Ball, Goalball), demostrando comprensión al modificar o crear estrategias que promueven la participación equitativa dentro del juego."]', 'PdA p. 96'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis del papel del deporte en la construcción de identidades (nacional, local, de género), e identificación de cómo los eventos y figuras deportivas influyen en el sentido de pertenencia.', 'pda_2025', 1, 'Resolver situaciones problemáticas en prácticas corporales ludomotrices, recreativas, expresivas, y de iniciación deportiva escolar, y consolidando su autonomía en la toma de decisiones, mediante el diseño y aplicación de estrategias y tácticas en el marco del juego limpio, la inclusión y la equidad de género.', '["Analiza y explica cómo la participación o la celebración de eventos deportivos masivos (Juegos Olímpicos, Mundiales, entre otros) fortalece la identidad cultural, generando un sentido de pertenencia y orgullo en la comunidad o el país.","Investiga y analiza el rol de deportistas destacadas/os de Córdoba o de la Argentina como referentes culturales que influyen en la identidad juvenil y colectiva.","Debate cómo el deporte puede reforzar o desafiar estereotipos de género, y argumenta con ejemplos de deportistas que rompen barreras y promueven la equidad en el ámbito deportivo.","Investiga la historia de un deporte o un equipo local o nacional y valora cómo su trayectoria contribuye a la construcción de la identidad y la memoria colectiva de una región o país.","Analiza cómo los deportistas y los eventos del deporte adaptado o paralímpico muestran que todas las personas pueden participar y destacarse en el deporte, explicando cómo esto ayuda a construir una identidad más inclusiva y respetuosa."]', 'PdA p. 96'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Desarrollo de la responsabilidad personal, social y ambiental en las prácticas motrices, mediante la aplicación de normas de seguridad, acuerdos de convivencia y principios de cuidado del entorno, para un disfrute consciente y sostenible.', 'pda_2025', 1, 'Adaptar su disponibilidad motriz a diversos ambientes e identificar los desafíos y oportunidades que estos ofrecen, para ejercer conciencia ambiental en el diseño e implementación de prácticas motrices seguras, sostenibles y responsables con el entorno.', '["Acuerda y valora normas de interacción y seguridad para garantizar el cuidado y la prevención de accidentes.","Cumple y promueve acuerdos de convivencia del grupo que prioricen la conservación y el uso sostenible del espacio natural, para mantener un clima de respeto, seguridad y disfrute compartido en las prácticas motrices.","Identifica y explica la diferencia entre un impacto ecológico positivo y uno negativo generado por una práctica motriz (como un juego o una caminata), y propone una acción simple para reducir el daño ambiental.","Aplica los principios básicos de “cero residuos” en las actividades al aire libre, con manejo responsable de los desechos y respeto por la flora, la fauna y el entorno natural.","Se involucra en prácticas corporales en el ambiente, asumiendo un rol responsable con ella/él misma/o, comprometiéndose con la gestión de residuos, la preservación de la biodiversidad y la reducción del impacto ambiental."]', 'PdA p. 102'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Aplicación de habilidades motrices y técnicas básicas vinculadas con la vida en la naturaleza, como nudos y orientación nocturna, con reconocimiento de riesgos y desafíos del entorno, para garantizar la seguridad y la autonomía en la práctica.', 'pda_2025', 1, 'Adaptar su disponibilidad motriz a diversos ambientes e identificar los desafíos y oportunidades que estos ofrecen, para ejercer conciencia ambiental en el diseño e implementación de prácticas motrices seguras, sostenibles y responsables con el entorno.', '["Reconoce técnicas y procedimientos adecuados para desenvolverse de manera responsable y sostenible en el ambiente (caminar sin dañar el sendero, acampar sin dejar impacto, orientarse en la naturaleza, y elegir la indumentaria adecuada).","Ejecuta con seguridad nudos fundamentales (como el ocho, el ballestrinque o el as de guía), en tareas funcionales específicas (asegurar materiales, montar estructuras rústicas o realizar simulaciones de rescate).","Aplica métodos de orientación nocturna (como el uso de estrellas, linterna, mapa o referencias lumínicas) para ubicarse con seguridad y autonomía, reconociendo el desafío que implica la falta de luz natural.","Identifica los riesgos y desafíos del entorno (como la inestabilidad del terreno, los cambios climáticos o la necesidad de primeros auxilios) y aplica procedimientos de seguridad y autocuidado para reducir la probabilidad de accidentes."]', 'PdA p. 103'),
(20, 'eje_contenido', 'Progresiones de Aprendizaje', 'Intervención efectiva ante situaciones de emergencia, mediante la aplicación de protocolos básicos de primeros auxilios, con autonomía en la toma de decisiones orientadas a la seguridad colectiva.', 'pda_2025', 1, 'Adaptar su disponibilidad motriz a diversos ambientes e identificar los desafíos y oportunidades que estos ofrecen, para ejercer conciencia ambiental en el diseño e implementación de prácticas motrices seguras, sostenibles y responsables con el entorno.', '["Comprende el protocolo institucional de actuación ante emergencias e identifica los roles y responsabilidades que intervienen en su aplicación.","Coordina las acciones del grupo (como la asignación de tareas y la comunicación), para garantizar una respuesta rápida, organizada y segura ante una determinada situación.","Inicia la cadena de supervivencia en situaciones simuladas (activación del sistema de emergencia, reanimación básica, manejo de heridas) y prioriza las acciones necesarias bajo presión.","Evalúa la escena de una emergencia para identificar riesgos secundarios y toma decisiones que priorizan la seguridad propia, de la víctima y de las/os demás."]', 'PdA p. 103'),
(20, 'objetivo', 'Objetivo', 'Explorar y comprender el cuerpo sexuado y el movimiento propio en la unidad y diversidad de sus múltiples dimensiones.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'objetivo', 'Objetivo', 'Aceptar las posibilidades de acción, comunicación y expresión y los límites posibles en la manifestación singular de la producción corporal y motriz.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'objetivo', 'Objetivo', 'Adquirir las herramientas y procedimientos necesarios para la construcción autónoma y responsable de su proyecto de vida saludable, apropiándose del conocimiento, práctica y disfrute de actividades físicas lúdicas, deportivas y expresivas, tomando conciencia de las acciones que favorecen y perjudican el cuidado de la salud.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'objetivo', 'Objetivo', 'Aprender a jugar y competir en distintos ámbitos, en el marco de los diversos tipos de juegos, apropiándose progresivamente de su lógica, organización y sentido, construyendo e internalizando normas y reglas de trabajo en equipo, a partir del acuerdo colectivo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'objetivo', 'Objetivo', 'Reconocer en la práctica lúdica y deportiva el valor del juego cooperativo, el esfuerzo compartido y la resolución colectiva de problemas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'objetivo', 'Objetivo', 'Adoptar medidas necesarias para la propia seguridad y la de los demás en la práctica de actividades de la vida en la naturaleza.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'objetivo', 'Objetivo', 'Reflexionar críticamente sobre el ambiente y sus problemáticas favoreciendo el uso responsable para un desarrollo sustentable.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'objetivo', 'Objetivo', 'Valorar la experiencia estética de moverse, manifestando el lenguaje y el movimiento corporal expresivo en comunicación con otros y de modo creativo, despojándose de prejuicios culturales y sociales de género.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices referidas a la disponibilidad de sí mismo', 'Reconocimiento de los accidentes más frecuentes como producto de la participación en prácticas corporales y motrices y los procedimientos adecuados para la aplicación de los primeros auxilios.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices referidas a la disponibilidad de sí mismo', 'Exploración, valoración y experimentación (saber intuitivo) de prácticas corporales y motrices que promueven el desarrollo de capacidades condicionales e intermedias.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices referidas a la disponibilidad de sí mismo', 'Definición de una posición critica, responsable y constructiva en relación con los mensajes que los medios de comunicación divulgan acerca de las actividades corporales y motrices dominantes.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices en interacción con otros', 'Conocimiento, modificación y experimentación de juegos de lógica cooperativa.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices en interacción con otros', 'Resolución de situaciones tácticas-estratégicas en los juegos modificados.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices en el ambiente', 'Reflexión crítica acerca de la problemática ambiental y sobre el compromiso en cuanto a su cuidado.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices en interacción con otros', 'Afirmación de las aptitudes para el juego y la práctica deportiva, con actitud lúdica y sentido solidario/cooperativo.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices en el ambiente', 'Acuerdo y valoración de normas de interacción, higiene y seguridad para garantizar el cuidado y la prevención de accidentes.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(20, 'eje_contenido', 'Prácticas corporales, motrices y ludomotrices en el ambiente', 'Creación de actividades ludomotrices, individuales y grupales, para el desempeño eficaz, placentero y equilibrado en el ambiente.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 147-151'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Confrontación, en intercambios orales, de información sobre situaciones relevantes a nivel social.', 'pda_2025', 1, 'Poner en juego convenciones genéricas y estrategias de cortesía en intercambios orales sobre problemáticas cotidianas.', '["Intercambia información y opiniones sobre problemáticas sociales propuestas por la/el docente o las/os estudiantes.","Contrasta información a partir de la consulta de textos de diferentes medios periodísticos (entrevistas, noticias).","Compara y sistematiza los diferentes puntos de vista, a partir del análisis de la información y de la opinión, por ejemplo, la confiabilidad de la fuente de información, la presencia o ausencia del agente (construcciones impersonales, la voz pasiva o de sujeto expreso), el uso de subjetivemas.","Comenta y relaciona, con la colaboración de la/del docente, la información relevada, para comprender puntos de vista."]', 'PdA p. 84'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reflexión y uso de recursos verbales de cortesía.', 'pda_2025', 1, 'Poner en juego convenciones genéricas y estrategias de cortesía en intercambios orales sobre problemáticas cotidianas.', '["Identifica recursos verbales de cortesía en enunciados ajenos, en particular el uso, como subjetivemas, de distintas clases de palabras y construcciones impersonales.","Emplea recursos de cortesía en situaciones de confrontación de ideas."]', 'PdA p. 84'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Fundamentación de interpretaciones a partir de la puesta en relación de conocimientos sobre subgéneros organizados a partir del eje de lo real (fantástico, épica, policial, entre otros), con características inherentes a la función de los personajes.', 'pda_2025', 1, 'Leer obras literarias de diversos subgéneros, seleccionados a partir del eje de lo real, y poner en juego conocimientos sobre procedimientos literarios, en la definición de preferencias y el establecimiento de relaciones con otros lenguajes artísticos.', '["Incorpora los rasgos de la heroicidad en la fundamentación de sus interpretaciones de relatos épicos, de ciencia ficción u otros.","Identifica personajes característicos de determinados subgéneros, como el investigador y el compañero en el policial clásico, o el objeto mágico en los relatos maravillosos.","Reconoce las funciones narrativas de diferentes personajes, como el oponente en el relato maravilloso o el policial, o el beneficiario en el relato épico, entre otros."]', 'PdA p. 87'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reflexión sobre el aporte de la disposición gráfica del poema en la producción de sentidos y de efectos estéticos.', 'pda_2025', 1, 'Leer obras literarias de diversos subgéneros, seleccionados a partir del eje de lo real, y poner en juego conocimientos sobre procedimientos literarios, en la definición de preferencias y el establecimiento de relaciones con otros lenguajes artísticos.', '["Explora diferentes disposiciones gráficas de textos poéticos (caligramas, poesía en prosa, ruptura de la linealidad, ruptura del margen izquierdo).","Relaciona la disposición gráfica con los efectos estéticos y de sentido del texto poético.","Recomienda sus preferencias fundamentándolas en la relación poesía-imagen."]', 'PdA p. 88'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Establecimiento de relaciones intertextuales a partir de la configuración de distintas funciones de los personajes, entre obras literarias y obras en otros lenguajes artísticos (escultura, pintura, fotografía).', 'pda_2025', 1, 'Leer obras literarias de diversos subgéneros, seleccionados a partir del eje de lo real, y poner en juego conocimientos sobre procedimientos literarios, en la definición de preferencias y el establecimiento de relaciones con otros lenguajes artísticos.', '["Organiza itinerarios de lectura en torno a sus preferencias sobre diversos tipos de personajes.","Investiga la pervivencia de personajes literarios en otros lenguajes estéticos.","Compara el abordaje de un personaje literario, en la obra literaria y en otro lenguaje, sobre la base de la potencialidad expresiva de cada uno."]', 'PdA p. 88'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Distinción autónoma de algunos aspectos de la fluidez lectora en la escucha de la lectura expresiva de poemas, por parte de la/del docente u otras/os lectoras/es.', 'pda_2025', 1, 'Leer con expresividad en situaciones de lectura para otras/os, con empleo de recursos no verbales. 1.er año', '["Escucha la lectura expresiva de poemas por parte de distintas/os lectoras/es, mientras sigue la lectura en su propio texto.","Reconoce cambios en la oralización del texto respecto del contenido, por ejemplo, el ritmo y la velocidad de lectura de recursos sonoros, la entonación según el tipo de oración, aumento de la velocidad de lectura para transmitir ansiedad o contrariedad, entre otros."]', 'PdA p. 89'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Adecuación de diversos aspectos de la lectura en voz alta a las características de los textos poéticos.', 'pda_2025', 1, 'Leer con expresividad en situaciones de lectura para otras/os, con empleo de recursos no verbales. 1.er año', '["Practica el aspecto de la fluidez lectora que necesita mejorar, a partir de las orientaciones de la/del docente.","Escucha leer a compañeras/os y colabora, con la ayuda de la/del docente, en caso de eventuales dificultades.","Graba la lectura en voz alta de poemas y los comparte, por ejemplo en entornos digitales."]', 'PdA p. 89'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Afianzamiento de la vinculación entre aspectos paraverbales y no verbales, y la lectura en voz alta de textos teatrales.', 'pda_2025', 1, 'Leer con expresividad en situaciones de lectura para otras/os, con empleo de recursos no verbales. 1.er año', '["Analiza el contenido de las didascalias y lo pone en relación con los parlamentos de los personajes.","Reconoce, en la escucha de teatro leído, cómo se expresan en la voz las orientaciones de las didascalias.","Analiza, a partir de la toma de notas, los gestos y la postura de los cuerpos como posibilidades expresivas, en relación con el contenido de los textos escuchados."]', 'PdA p. 90'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Puesta en juego de recursos expresivos variados en la lectura en voz alta de textos teatrales.', 'pda_2025', 1, 'Leer con expresividad en situaciones de lectura para otras/os, con empleo de recursos no verbales. 1.er año', '["Pone en juego recursos paraverbales en la lectura de textos teatrales para otras/os, en situaciones presenciales.","Atiende a las indicaciones sobre gestualidad, postura del cuerpo, voz y estados de ánimo, en las didascalias de los textos teatrales.","Observa escenas grabadas de lectura en voz alta de textos teatrales y corrige el uso de recursos paraverbales y no verbales."]', 'PdA p. 91'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Indagación de las posibilidades estructurales del lenguaje en la escritura de invención.', 'pda_2025', 1, 'Producir textos ficcionales que pongan en juego rasgos textuales acordes al género y rasgos lingüísticos, y que desplieguen la potencialidad expresiva y estética del lenguaje.', '["Lee textos que juegan con el plano estructural del lenguaje e identifica en qué consiste la condición lúdica de paralelismos, hipérbaton, ambigüedades estructurales, entre otros recursos.","Explora la reformulación de las estructuras relevadas para eliminar la ambigüedad o recuperar el orden natural de la oración.","Usa, en el marco de la escritura colectiva y grupal de textos, juegos del lenguaje basados en la estructura."]', 'PdA p. 95'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Diseño de personajes heroicos en la escritura de textos narrativos.', 'pda_2025', 1, 'Producir textos ficcionales que pongan en juego rasgos textuales acordes al género y rasgos lingüísticos, y que desplieguen la potencialidad expresiva y estética del lenguaje.', '["Releva en textos leídos las características que definen la heroicida.","Contrasta las características relevadas con las ofrecidas por aplicaciones de inteligencia artificial.","Resuelve problemas de reflexión y reformulación en relación con: • la nominación del héroe, • la descripción física y del carácter, • la expresión de su voz (a través del discurso directo o indirecto), • las motivaciones y acciones en relación con otros personajes y con el colectivo al que representa, • el tipo de pruebas a superar, la clase de acciones que despliega para superarlas.","Resuelve problemas orientados a reflexionar sobre el sistema verbal con eje en el pasado (pretéritos perfecto simple, imperfecto, pluscuamperfecto y condicional), uso de pronombres relativos como recurso cohesivo, las correlaciones verbales, espaciales y temporales en el discurso indirecto; la tildación de pronombres interrogativos y exclamativos en estilo indirecto; casos especiales (sino/si no, demás/de más, entre otros).","Pone en juego las características que definen la heroicidad, en la construcción del protagonista de sus relatos."]', 'PdA p. 96'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Escritura de textos dramáticos poniendo en juego los recursos lingüísticos y textuales característicos del texto teatral.', 'pda_2025', 1, 'Producir textos ficcionales que pongan en juego rasgos textuales acordes al género y rasgos lingüísticos, y que desplieguen la potencialidad expresiva y estética del lenguaje.', '["Resuelve problemas de reformulación orientados al análisis del tiempo verbal; las clases de palabras y construcciones para describir lugares y personajes de la escena.","Utiliza paréntesis y participios, gerundios, adjetivos, adverbios, construcciones preposicionales en las didascalias para expresar gestualidad, estados de ánimo, modos de moverse de los personajes, entre otras.","Emplea, en los parlamentos, diferentes personas gramaticales, en particular, primera y segunda.","Recrea formulaciones propias, desarrolladas por otras/ os, o por aplicaciones de inteligencia artificial, para explorar otros modos de expresar los segmentos característicos del texto teatral.","Realiza aportes, en situaciones de interacción y producción colectiva, para organizar, en entornos digitales, los conocimientos sobre recursos lingüísticos y textuales estudiados, por medio de tutoriales.","Usa la información sistematizada en la revisión y eventual corrección de los propios textos en situaciones de coevaluación y autoevaluación."]', 'PdA p. 96'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Búsqueda, selección, y escucha o lectura de fuentes de información pertinentes al tema a exponer.', 'pda_2025', 1, 'Producir exposiciones orales y escritas con diversos propósitos, que pongan en juego recursos lingüísticos y textuales adecuados al género.', '["Aborda textos expositivos de diferentes géneros referidos a temas de la lengua y la literatura, por ejemplo, los alcances semánticos del adjetivo “orgánico”, la diversificación de géneros seriados, la autoría en el ámbito de la literatura, entre otros temas.","Resuelve problemas de comprensión a partir de la relectura de partes o de la totalidad del texto y del intercambio con compañeras/os y la/el docente.","Participa en intercambios con compañeras/os y la/el docente acerca de la información transmitida, en exposiciones presenciales o audiovisuales (plantea preguntas, identifica temas y relaciones temáticas, pide aclaraciones y/o repeticiones)."]', 'PdA p. 99'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Selección y apropiación de la información que transmiten textos expositivos.', 'pda_2025', 1, 'Producir exposiciones orales y escritas con diversos propósitos, que pongan en juego recursos lingüísticos y textuales adecuados al género.', '["Integra la información seleccionada en un nuevo texto, en el marco de la escritura colaborativa digital.","Usa la escritura como estrategia de estudio a partir de la reorganización de la información relevante del texto en gráficos, cuadros, esquemas o en listados de palabras o expresiones clave."]', 'PdA p. 100'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de las características de la puesta en escena de la exposición en tanto género de la oralidad.', 'pda_2025', 1, 'Producir exposiciones orales y escritas con diversos propósitos, que pongan en juego recursos lingüísticos y textuales adecuados al género.', '["Toma nota del uso de recursos paraverbales y no verbales, y de los apoyos usados en presentaciones audiovisuales.","Analiza, con compañeras/os y la/el docente, a partir de sus notas, los propósitos de los recursos paraverbales, no verbales y gráficos utilizados en las presentaciones orales.","Elabora apoyos visuales, para colaborar con la comprensión del auditorio y apoyos escritos, para organizar y afianzar la información."]', 'PdA p. 100'),
(21, 'eje_contenido', 'Progresiones de Aprendizaje', 'Desarrollo de exposiciones orales con incorporación de diversos recursos verbales, paraverbales y no verbales característicos del registro formal.', 'pda_2025', 1, 'Producir exposiciones orales y escritas con diversos propósitos, que pongan en juego recursos lingüísticos y textuales adecuados al género.', '["Regula, con la colaboración de la/del docente, el ajuste al tiempo de la exposición, la entonación y el volumen de la voz.","Emplea, durante la exposición, ordenadores textuales para presentar cada subtema, vocabulario específico preciso y recursos del registro formal.","Articula su exposición con el apoyo gráfico preparado."]', 'PdA p. 100'),
(21, 'objetivo', 'Objetivo', 'Apropiarse de prácticas de lenguaje diversas que le permitan una participación cada vez más plena en el contexto, tanto escolar como extraescolar.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'objetivo', 'Objetivo', 'Apropiarse de las formas de expresión que caracterizan los diferentes tipos de textos e intercambios formales, significarlas en función del contexto y reflexionar sobre sus efectos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'objetivo', 'Objetivo', 'Ampliar y fortalecer su capacidad de expresar y compartir emociones, ideas, conocimientos y opiniones por medio de la lengua oral y escrita.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'objetivo', 'Objetivo', 'Utilizar el lenguaje de manera cada vez más libre, personal y autónoma para reconstruir y comunicar la experiencia propia y crear mundos de ficción.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'objetivo', 'Objetivo', 'Desarrollar su capacidad para interactuar, narrar, exponer y debatir utilizando cada vez con mayor fluidez y adecuación la lengua oral.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'objetivo', 'Objetivo', 'Consolidar su interés por saber más acerca de la lengua y de la literatura para conocer y comprender mejor el mundo y a sí mismos e imaginar mundos posibles.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'objetivo', 'Objetivo', 'Comprender, valorar y fundamentar la lectura literaria como experiencia receptiva, comunicativa y productiva.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'objetivo', 'Objetivo', 'Participar en prácticas que le permitan iniciarse en el conocimiento del campo cultural de la literatura.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'eje_contenido', 'Comprensión y producción oral', 'Desempeño participativo en situaciones de intercambio dialógico: conversaciones, discusiones y debates sobre temas polémicos diversos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'eje_contenido', 'Comprensión y producción oral', 'Organización de estructura y contenido en las exposiciones.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'eje_contenido', 'Comprensión y producción oral', 'Sistematización de estrategias básicas para formular opiniones, construir y enunciar argumentos y proporcionar pruebas a partir de consulta de fuentes diversas y elaboraciones personales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'eje_contenido', 'Lectura y producción escrita', 'Construcción (a partir de la lectura asidua) de saberes específicos en relación con géneros discursivos propios del ámbito personal, social, académico (notas en revistas especializadas, artículos de divulgación científica, informes, recensiones, monografías).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'eje_contenido', 'Lectura y producción escrita', 'Producción de textos narrativos (relatos de experiencias y viajes, anécdotas, autobiografías, biografías, reseñas históricas, crónicas) atendiendo a la variación de las voces narrativas, la caracterización de personas y personajes, épocas, ambientes y culturas, la organización (episodios y sucesos, marco espacio temporal; secuencia lógica y cronológica lineal y no lineal).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'eje_contenido', 'Literatura', 'Escucha, lectura e interpretación de cuentos y novelas (realistas, maravillosos, de misterio, policiales, fantásticos, históricos, de ciencia ficción) de diferentes épocas y procedencias.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'eje_contenido', 'Literatura', 'Escucha, lectura e interpretación de poesía de tradición oral (coplas, romances) y de autores regionales, nacionales y universales.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'eje_contenido', 'Reflexión sobre el lenguaje, la lengua (sistema, norma y uso) y los textos', 'Ampliación de repertorio de verbos introductorios.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(21, 'eje_contenido', 'Reflexión sobre el lenguaje, la lengua (sistema, norma y uso) y los textos', 'Conocimiento de la ortografía correspondiente al vocabulario cotidiano y escolar.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 10-19'),
(22, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis y escritura algebraica de las propiedades de la potenciación de números enteros y racionales, con exponente entero.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Elabora, a partir de ejemplos, la propiedad distributiva de la potenciación con respecto a la multiplicación y división exacta de números enteros con exponente natural.","Produce y justifica las propiedades de producto y cociente de potencias y potencia de potencia, con base entera y exponente natural.","Elabora, a partir de ejemplos, la propiedad distributiva de la potenciación con respecto a la multiplicación y división exacta de números enteros con exponente entero.","Produce y justifica las propiedades de producto y cociente de potencias y potencia de potencia, con base entera y exponente entero.","Selecciona las propiedades de la potenciación que permiten resolver cálculos de potencias de expresiones fraccionarias y decimales con exponente entero, y justifica la elección realizada.","Elabora con otros/as expresiones algebraicas para comunicar las propiedades de la potenciación de números racionales con exponente entero."]', 'PdA p. 56'),
(22, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de la suma, la resta, la multiplicación, la división y la potenciación con números racionales (positivos, negativos y cero) en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Selecciona la forma de representación de los números racionales (fraccionaria, decimal y notación científica) según el cálculo a realizar y justifica su elección.","Selecciona y justifica las propiedades de las operaciones que facilitan la resolución de cálculos.","Lee una situación, selecciona la información relevante y busca, en distintas fuentes, la información que falta para resolverla.","Selecciona y justifica la operación (suma, resta. multiplicación, división, potenciación) que permite resolver las situaciones leídas."]', 'PdA p. 57'),
(22, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de la radicación de números racionales positivos, con índice natural en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Operar con números enteros y racionales en situaciones extra e intramatemáticas, y expresar algebraicamente propiedades de las operaciones y relaciones numéricas con números naturales.', '["Reconoce a la radicación como la operación inversa de la potenciación al determinar raíces exactas de números naturales al determinar el lado de un cuadrado y la arista de un cubo conociendo su área y su volumen, respectivamente.","Encuadra entre dos números enteros las raíces de números racionales positivos.","Reconoce y explica expresiones decimales infinitas no periódicas, a partir del cálculo de raíces de números racionales positivos, con calculadora."]', 'PdA p. 57'),
(22, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis de variaciones lineales y = ax + b, presentadas en textos, tablas, gráficos y fórmulas, en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Modelizar situaciones vinculadas a las relaciones de proporcionalidad directa e inversa y variaciones lineales.', '["Lee una situación (en textos, tablas y gráficos), selecciona la información relevante y/o busca, en distintas fuentes, la información que falta para resolver la situación.","Explica semejanzas y diferencias entre variaciones lineales y relaciones de proporcionalidad directa.","Reconoce y explica variaciones lineales en base a la interpretación de textos, tablas, gráficos y fórmulas.","Interpreta y comunica características del gráfico (creciente, decreciente, constante) de las variaciones lineales, a partir de los parámetros de la fórmula y = ax+b.","Relaciona parámetros de la fórmula y = ax+b con la representación gráfica (pendiente, ordenada al origen y cero) en situaciones que se modelizan con variaciones lineales.","Produce y justifica la validez de las fórmulas que representan variaciones lineales presentadas en textos, tablas y gráficos."]', 'PdA p. 60'),
(22, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de sistemas de dos ecuaciones lineales con dos incógnitas en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Modelizar situaciones vinculadas a las relaciones de proporcionalidad directa e inversa y variaciones lineales.', '["Interpreta que cada ecuación del tipo ax + by = c (con a y b ≠ 0) tiene infinitas soluciones y se representan mediante una recta en el sistema de coordenadas cartesianas.","Justifica la validez de las soluciones de sistemas de dos ecuaciones lineales con dos incógnitas, a partir de la representación de rectas en el sistema de coordenadas cartesianas."]', 'PdA p. 60'),
(22, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de fórmulas para resolver situaciones de permutaciones, variaciones y combinaciones, sin repetición de elementos.', 'pda_2025', 1, 'Cuantificar la incertidumbre recurriendo a las nociones de probabilidad clásica y comunicar información estadística.', '["Explica la diferencia entre el principio de adición para conjuntos disjuntos (o mutuamente excluyentes) y el principio multiplicativo, al determinar el total de casos en situaciones de combinatoria.","Elabora, explica y compara fórmulas propias y de otras/ os que permiten determinar el total de casos, en situaciones de combinatoria, sin repetición de elementos.","Lee una situación, selecciona la fórmula más adecuada (de permutación, variación y combinación) para resolverla, y justifica la elección realizada."]', 'PdA p. 63'),
(22, 'eje_contenido', 'Progresiones de Aprendizaje', 'Cuantificación de la probabilidad clásica de eventos a partir del uso de fórmulas para la determinación de espacios muestrales finitos.', 'pda_2025', 1, 'Cuantificar la incertidumbre recurriendo a las nociones de probabilidad clásica y comunicar información estadística.', '["Lee una situación extramatemática y reconoce la necesidad de recurrir al uso de fórmulas de combinatoria para el cálculo de la probabilidad clásica de eventos, en situaciones donde no es posible listar el total de casos posibles (espacio muestral) y de casos favorables de un evento aleatorio.","Emplea y explica la descomposición de un evento —en dos o más, mutuamente excluyentes— para obtener su probabilidad como suma de probabilidades de cada uno de estos eventos.","Anticipa y verifica que la probabilidad del espacio muestral es 1, a partir de la suma de las probabilidades de los eventos mutuamente excluyentes que lo componen.","Comunica la información que proporciona la probabilidad obtenida en el contexto del experimento aleatorio."]', 'PdA p. 63'),
(22, 'eje_contenido', 'Progresiones de Aprendizaje', 'Análisis conjunto de datos recolectados de dos variables estadísticas cualitativas y cuantitativas discretas.', 'pda_2025', 1, 'Cuantificar la incertidumbre recurriendo a las nociones de probabilidad clásica y comunicar información estadística.', '["Lee una situación extramatemática y construye tablas de doble entrada para representar las frecuencias absolutas de dos variables cualitativas y/o cuantitativas discretas.","Organiza datos recolectados en tablas de doble entrada para representar las frecuencias absolutas y la relativa porcentual de dos variables cualitativas y/o cuantitativas discretas, apelando al uso de software cuando sea posible.","Justifica la elección del gráfico estadístico más apropiado para presentar la información conjunta de dos variables cualitativas y/o cuantitativas discretas.","Elabora textos que integran tablas de doble entrada y gráficos de barras con información estadística conjunta de dos variables cualitativas y/o cuantitativas discretas."]', 'PdA p. 64'),
(22, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interpretación del teorema de Pitágoras en situaciones extra e intramatemáticas.', 'pda_2025', 1, 'Usar propiedades de polígonos convexos, criterios de congruencia y semejanza de triángulos, en situaciones de construcción de figuras geométricas y cálculo de áreas y volúmenes.', '["Identifica y explica la relación pitagórica entre los lados de un triángulo rectángulo, a través de la equivalencia de áreas.","Anticipa y verifica la existencia de ternas pitagóricas y las utiliza para la construcción de triángulos rectángulos.","Lee una situación, selecciona la información relevante y usa el teorema de Pitágoras para el cálculo de longitudes, distancias y áreas."]', 'PdA p. 67'),
(22, 'eje_contenido', 'Progresiones de Aprendizaje', 'Formulación de argumentaciones sobre condiciones de semejanza de triángulos, en situaciones de construcción y comunicación.', 'pda_2025', 1, 'Usar propiedades de polígonos convexos, criterios de congruencia y semejanza de triángulos, en situaciones de construcción de figuras geométricas y cálculo de áreas y volúmenes.', '["Reconoce y explica la relación de semejanza, a través de la construcción de ampliaciones y reducciones de figuras planas, apelando al uso de software, de ser posible.","Reconoce la información mínima necesaria sobre lados y ángulos para la construcción de triángulos semejantes.","Explicita los criterios de semejanza de triángulos.","Justifica la semejanza de figuras planas de tres o más lados a partir de propiedades de ángulos, proporcionalidad de lados y criterios de semejanza de triángulos."]', 'PdA p. 68'),
(22, 'eje_contenido', 'Progresiones de Aprendizaje', 'Uso de relaciones trigonométricas para el cálculo de longitudes de lados y amplitudes de ángulos de triángulos rectángulos.', 'pda_2025', 1, 'Usar propiedades de polígonos convexos, criterios de congruencia y semejanza de triángulos, en situaciones de construcción de figuras geométricas y cálculo de áreas y volúmenes.', '["Reconoce seno, coseno y tangente de ángulos agudos como razón entre las longitudes de lados de un triángulo rectángulo.","Selecciona la relación trigonométrica (seno, coseno y tangente de ángulos agudos) para el cálculo de longitudes de lados y amplitudes de ángulos en triángulos rectángulos, de acuerdo con la información disponible en el texto leído, y justifica la elección realizada."]', 'PdA p. 68'),
(22, 'objetivo', 'Objetivo', 'Usar números enteros y racionales para resolver problemas extramatemáticos e intramatemáticos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'objetivo', 'Objetivo', 'Usar expresiones algebraicas y analizar su equivalencia para resolver problemas extramatemáticos e intramatemáticos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'objetivo', 'Objetivo', 'Utilizar y analizar funciones- proporcionalidad directa, crecimiento lineal no proporcional y función cuadrática incompleta-, para resolver problemas extramatemáticos e intramatemáticos, recurriendo cuando sea posible al uso reflexivo de recursos tecnológicos y reconociendo el límite del modelo para comprender el problema.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'objetivo', 'Objetivo', 'Producir y analizar construcciones geométricas - utilizando cuando sea posible software geométrico- acudiendo a argumentos deductivos, según ciertas condiciones y propiedades puestas en juego, reconociendo el límite de las pruebas empíricas.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'objetivo', 'Objetivo', 'Organizar e interpretar datos estadísticos mediante tablas (de frecuencia, por intervalos) y gráficos, eligiendo la forma más adecuada.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'objetivo', 'Objetivo', 'Producir y validar enunciados sobre relaciones y propiedades numéricas y geométricas, sin recurrir a la constatación empírica.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'objetivo', 'Objetivo', 'Recurrir a nociones de probabilidad para cuantificar la incertidumbre.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'eje_contenido', 'Número y operaciones', 'Reconocimiento de insuficiencia de los números racionales para expresar la relación entre longitud de circunferencia y diámetro y entre los lados de un triángulo rectángulo e isósceles.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'eje_contenido', 'Número y operaciones', 'Exploración y explicación de propiedades - discretitud, densidad y aproximación a la idea de completitud- de los distintos conjuntos numéricos estableciendo relaciones de inclusión entre ellos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44');
INSERT INTO `curriculum_contenidos` (`espacio_id`, `tipo`, `titulo`, `descripcion`, `fuente`, `vigente`, `meta`, `indicadores`, `pagina`) VALUES
(22, 'eje_contenido', 'Número y operaciones', 'Análisis de las operaciones en Q y sus propiedades como extensión de las elaboradas en Z.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'eje_contenido', 'Número y operaciones', 'Uso de los diferentes tipos de cálculo, de las diferentes representaciones de números (incluido el porcentaje), de la proporcionalidad, para resolver problemas extramatemáticos (incluidos aquéllos en los que la información se presenta en tablas y gráficos).', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'eje_contenido', 'Álgebra y funciones', 'Interpretación de gráficos y fórmulas que representen variaciones lineales y no lineales (incluida la función cuadrática) en función del problema a resolver.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'eje_contenido', 'Álgebra y funciones', 'Análisis de variaciones lineales expresadas mediante gráficos y fórmulas e interpretación de sus parámetros.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'eje_contenido', 'Geometría y medida', 'Producción de argumentaciones con base en propiedades para justificar construcciones de rectas paralelas y perpendiculares usando la noción de lugar geométrico.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'eje_contenido', 'Geometría y medida', 'Uso de relación pitagórica para triángulos rectángulos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'eje_contenido', 'Geometría y medida', 'Utilización de razones trigonométricas para resolver problemas con triángulos rectángulos.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'eje_contenido', 'Estadística y probabilidad', 'Interpretación de significado de parámetros de posición (media aritmética, mediana y modo), identificando el más adecuado para describir la situación en estudio.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(22, 'eje_contenido', 'Estadística y probabilidad', 'Exploración de diferentes estrategias de combinatoria sin repetición- entre ellas el diagrama de árbol -para avanzar hacia la producción y uso de fórmulas de permutación, variación, y combinación para resolver problemas de cálculo de probabilidad.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 37-44'),
(23, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interpretación de la energía interna de un cuerpo como suma de las energías potencial y cinética de sus partículas, y construcción de la noción de temperatura como una magnitud asociada al movimiento de esas partículas.', 'pda_2025', 1, 'Analizar y explicar las dinámicas de transformación y transferencia de energía entre un sistema y su entorno, reconociendo variables macroscópicas y microscópicas e identificando los modos de producción energética en el país.', '["Relaciona el intercambio de energía mediante calor, con las variaciones de temperatura de un sistema, en el análisis de situaciones termodinámicas cotidianas.","Reconoce la temperatura como una propiedad intensiva y la energía interna como una propiedad extensiva.","Explica la variación de temperatura a partir de los cambios en el movimiento de las partículas que componen un objeto a nivel submicroscópico."]', 'PdA p. 114'),
(23, 'eje_contenido', 'Progresiones de Aprendizaje', 'Validación del equilibrio térmico como estado al que convergen los sistemas termodinámicos, a partir de la medición de temperaturas en procesos de enfriamiento o calentamiento de objetos por contacto con el medio, y de mezcla de sustancias a diferentes temperaturas.', 'pda_2025', 1, 'Analizar y explicar las dinámicas de transformación y transferencia de energía entre un sistema y su entorno, reconociendo variables macroscópicas y microscópicas e identificando los modos de producción energética en el país.', '["Reconoce la importancia de las escalas termométricas para la comparación de temperaturas entre dos objetos, en particular las escalas Celsius y Kelvin.","Reconoce y compara las escalas termométricas Celsius y Kelvin, identificando sus puntos de referencia y los contextos en que se utilizan.","Anticipa la temperatura final del sistema en situaciones de enfriamiento por contacto con el medio, y de mezclas de sustancias a distintas temperaturas.","Contrasta experimentalmente sus anticipaciones en diferentes sistemas termodinámicos, midiendo su temperatura durante procesos de intercambios de calor.","Reflexiona sobre la posibilidad que un sistema termodinámico se encuentre en la temperatura asociada al cero absoluto."]', 'PdA p. 115'),
(23, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión de la relación entre el material que compone un cuerpo respecto del cambio de temperatura y la dilatación que sufre.', 'pda_2025', 1, 'Analizar y explicar las dinámicas de transformación y transferencia de energía entre un sistema y su entorno, reconociendo variables macroscópicas y microscópicas e identificando los modos de producción energética en el país.', '["Realiza mediciones de longitudes, superficies y volúmenes de objetos, a distintas temperaturas, en situaciones reales o en simulaciones educativas, para caracterizar sus coeficientes de dilatación, y los coteja con los valores publicados en libros o sitios web.","Explica la necesidad de aplicar juntas de dilatación, en diferentes situaciones de la vida cotidiana.","Reconoce y explica la implicancia de la dilatación térmica en situaciones de la vida cotidiana, como por ejemplo, calentar la tapa metálica de un frasco para facilitar su apertura, los cambios en la afinación de las cuerdas de la guitarra por los cambios de temperatura, entre otros."]', 'PdA p. 115'),
(23, 'eje_contenido', 'Progresiones de Aprendizaje', 'Interpretación de la presión de un gas, desde el modelo cinético corpuscular, y reconocimiento de las relaciones entre las variables presión, temperatura y volumen.', 'pda_2025', 1, 'Analizar y explicar las dinámicas de transformación y transferencia de energía entre un sistema y su entorno, reconociendo variables macroscópicas y microscópicas e identificando los modos de producción energética en el país.', '["Reconoce la presión como la fuerza aplicada por unidad de superficie, identificando al pascal como unidad de medida.","Describe procesos de dilatación y variación de presión de un gas, utilizando el modelo cinético corpuscular.","Experimenta, en laboratorios reales o simuladores, procesos de variación de presión, temperatura y volumen de un gas, logrando explicar las relaciones entre estas variables, a partir de los resultados obtenidos.","Experimenta y genera anticipaciones sobre procesos de variación de la presión y el volumen de un gas, como consecuencia de la variación de la temperatura."]', 'PdA p. 115'),
(23, 'eje_contenido', 'Progresiones de Aprendizaje', 'Explicación de fenómenos naturales, a partir de las Leyes de Newton.', 'pda_2025', 1, 'Interpretar diferentes modelos sobre fenómenos físicos mecánicos y ondulatorios, analizando sus alcances y limitaciones explicativas, tanto en escalas astronómicas como cotidianas.', '["Reconoce la inercia en diversas situaciones cotidianas (por ejemplo, cinturón de seguridad, centrifugadora, entre otras).","Considera las implicancias de la acción de las fuerzas de rozamiento en situaciones de movimiento y reposo de la vida cotidiana.","Reconoce las relaciones entre la/s fuerza/s aplicada/s a un cuerpo, su masa y el cambio de velocidad, identificando al Newton como la unidad de medida de la fuerza.","Reconoce el carácter vectorial de las fuerzas, para comprender los modos en los que interactúan dos o más fuerzas aplicadas a un mismo objeto.","Utiliza las Leyes de Newton para el análisis de situaciones de la vida cotidiana, experiencias de laboratorio y/o simulaciones.","Reconoce el par de fuerzas acción-reacción, diferenciando sobre qué cuerpo se ejerce cada una.","Diseña y realiza experiencias para validar las Leyes de Newton y explica las conclusiones obtenidas."]', 'PdA p. 119'),
(23, 'eje_contenido', 'Progresiones de Aprendizaje', 'Comprensión acerca de que los fenómenos físicos pueden ser modelizados y descriptos a través de expresiones matemáticas, en particular, en lo que respecta a las Leyes de Newton y la conservación de la energía mecánica.', 'pda_2025', 1, 'Interpretar diferentes modelos sobre fenómenos físicos mecánicos y ondulatorios, analizando sus alcances y limitaciones explicativas, tanto en escalas astronómicas como cotidianas.', '["Realiza anticipaciones en base a cálculos sencillos, y los valida cualitativamente por medio de la experimentación.","Reconoce las unidades de medida asociadas a las cantidades intervinientes en la modelización de los fenómenos físicos (velocidad, aceleración, masa, fuerza, energía, posición).","Resuelve problemas sencillos sobre la conservación de la energía y las Leyes de Newton, por ejemplo, la caída de un cuerpo, la energía de un péndulo, entre otros, utilizando la noción de degradación de la energía.","Realiza experiencias y/o utiliza simulaciones educativas en las que se miden variables intervinientes en situaciones sobre conservación de la energía o sobre las Leyes de Newton.","Confronta los resultados obtenidos en experiencias y simulaciones sobre la conservación de la energía y las leyes de Newton con los de sus compañeras/os, valorando las diferencias de otras estrategias y posibilidades."]', 'PdA p. 119'),
(23, 'eje_contenido', 'Progresiones de Aprendizaje', 'Diferenciación de los conceptos de velocidad y aceleración en el análisis de movimientos sencillos.', 'pda_2025', 1, 'Interpretar diferentes modelos sobre fenómenos físicos mecánicos y ondulatorios, analizando sus alcances y limitaciones explicativas, tanto en escalas astronómicas como cotidianas.', '["Reconoce la necesidad de un sistema de referencia para describir movimientos.","Interpreta la velocidad como una magnitud que posee una cantidad, una dirección y un sentido, y la diferencia del concepto de rapidez.","Evidencia la relación entre el cambio de velocidad de un cuerpo y su aceleración.","Diferencia las unidades en la que se miden la aceleración y la velocidad.","Clasifica los movimientos según las características de la aceleración.","Interpreta gráficas de posición, velocidad y aceleración, en función del tiempo.","Identifica el área bajo la gráfica de velocidad como la distancia recorrida por un móvil."]', 'PdA p. 120'),
(23, 'eje_contenido', 'Progresiones de Aprendizaje', 'Descripción de las reacciones nucleares empleando el modelo atómico simplificado.', 'pda_2025', 1, 'Establecer relaciones causa-efecto en torno al cambio climático, reconociendo medidas de adaptación climática y otras alternativas viables para la sostenibilidad.', '["Diferencia los procesos de fisión y fusión nuclear, reconociendo en qué lugares ocurren, las condiciones necesarias y los usos.","Explica, utilizando esquemas simples, los procesos de fisión y fusión nuclear, con énfasis en la producción de energía.","Reconoce el rol de los isótopos radioactivos en el proceso de fisión nuclear."]', 'PdA p. 122'),
(23, 'eje_contenido', 'Progresiones de Aprendizaje', 'Valoración de las ventajas de la producción de energía eléctrica en centrales nucleares, incluyendo el análisis de riesgos y protocolos de seguridad.', 'pda_2025', 1, 'Establecer relaciones causa-efecto en torno al cambio climático, reconociendo medidas de adaptación climática y otras alternativas viables para la sostenibilidad.', '["Argumenta su posición en relación con la utilización de energía nuclear para la generación de energía eléctrica.","Compara la cantidad de energía que se puede obtener, por unidad de masa, entre la energía nuclear y la producida a partir de combustibles fósiles.","Compara los efectos producidos por la energía nuclear sobre el ambiente, con otras fuentes de energía, para analizar su incidencia en el cambio climático.","Reconoce algunos dispositivos o procedimientos de protección radiactiva.","Analiza casos de catástrofes en centrales nucleares, como por ejemplo las ocurridas en Chernobyl o Fukushima."]', 'PdA p. 122'),
(23, 'eje_contenido', 'Progresiones de Aprendizaje', 'Identificación de las centrales nucleares (de alta y baja potencia), tanto en Córdoba como en el resto del país, y su importancia en la matriz energética.', 'pda_2025', 1, 'Establecer relaciones causa-efecto en torno al cambio climático, reconociendo medidas de adaptación climática y otras alternativas viables para la sostenibilidad.', '["Reconoce instituciones vinculadas con la producción y gestión de centrales nucleares, CNEA, Núcleo Eléctrica, entre otras.","Elabora informes sobre la incidencia de la energía nuclear en el Sistema Nacional de Energía.","Indaga sobre la extracción, importación y tratamiento de compuestos de uranio y otros minerales involucrados en la energía nuclear.","Analiza el rol de Argentina en el desarrollo, uso pacífico y regulación de la energía nuclear, a nivel mundial."]', 'PdA p. 122'),
(23, 'eje_contenido', 'Progresiones de Aprendizaje', 'Reconocimiento de la aplicación de la energía nuclear en el campo de la medicina y de la investigación científica.', 'pda_2025', 1, 'Establecer relaciones causa-efecto en torno al cambio climático, reconociendo medidas de adaptación climática y otras alternativas viables para la sostenibilidad.', '["Identifica usos y aplicaciones de la energía nuclear, que contribuyen al diagnóstico y tratamiento de enfermedades y a los avances en investigación científica.","Argumenta sobre la importancia del uso de la energía nuclear, considerando las precauciones y cuidados asociados a sus procesos tecnológicos.","Indaga sobre los protocolos de seguridad utilizados en la producción de energía nuclear, tanto en reactores de baja como de alta potencia."]', 'PdA p. 123'),
(23, 'objetivo', 'Objetivo', 'Reconocer y valorar los aportes de las Ciencias Naturales a la sociedad a lo largo de la historia.', 'diseno_2011_2015', 0, NULL, NULL, 'pp. 63-66'),
