(66, 'eje_contenido', 'Organización y gestión agroambiental', 'Comprensión y manejo de la legislación en materia contable, fiscal, laboral y agraria.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 272-275'),
(66, 'eje_contenido', 'Organización y gestión agroambiental', 'Iniciación en el diseño y uso de estrategias de comercialización de los productos de la unidad de producción.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 272-275'),
(66, 'eje_contenido', 'Organización y gestión agroambiental', 'Valoración de las organizaciones como promotoras de desarrollo.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 272-275'),
(67, 'objetivo', 'Objetivo', 'Interpretar las bases conceptuales, los principios, las limitaciones y posibilidades de las aplicaciones de la biotecnología.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(67, 'objetivo', 'Objetivo', 'Identificar posibles soluciones biotecnológicas a la problemática de los sistemas agroambientales, a partir de fundamentos conceptuales, criterios y parámetros claros.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(67, 'objetivo', 'Objetivo', 'Reconocer aplicaciones biotecnológicas empleadas en sistemas agroambientales.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(67, 'objetivo', 'Objetivo', 'Reconocer la necesidad e importancia de abordar problemáticas inherentes y emergentes a la biotecnología.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(67, 'objetivo', 'Objetivo', 'Valorar la contribución de la biotecnología como disciplina científica a la mejora de sistemas agroambientales.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279');
INSERT INTO `curriculum_contenidos` (`espacio_id`, `tipo`, `titulo`, `descripcion`, `fuente`, `vigente`, `meta`, `indicadores`, `pagina`) VALUES
(67, 'eje_contenido', 'Biología molecular y celular', 'Comprensión del proceso de replicación del ADN.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(67, 'eje_contenido', 'Biología molecular y celular', 'Comprensión del mecanismo de traducción del código genético en la síntesis de proteínas.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(67, 'eje_contenido', 'Biología molecular y celular', 'Interpretación de las Leyes de Mendel.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(67, 'eje_contenido', 'Biotecnología tradicional', 'Interpretación y diferenciación de las fermentaciones láctica, alcohólica y acética; su utilización en las industrias.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(67, 'eje_contenido', 'Biotecnología tradicional', 'Comprensión de los aportes de la biotecnología y la biorremediación, a través de ejemplos y aplicaciones prácticas (los biofertilizantes, la fijación de nitrógeno simbiótica y no simbiótica, las micorrizas, los biotratamientos de suelos y de aguas contaminadas, el tratamiento de desechos, el biocombustible, la utilización de la biomasa).', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(67, 'eje_contenido', 'Biotecnología tradicional', 'Reconocimiento de las técnicas de mejora de cepas utilizadas en procesos de producción agropecuaria.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(67, 'eje_contenido', 'Ingeniería genética', 'Reconocimiento e interpretación de las técnicas del ADN recombinante.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(67, 'eje_contenido', 'Ingeniería genética', 'Caracterización y descripción de las estructuras y funciones de los organismos genéticamente modificados (OGM) y sus aplicaciones.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(67, 'eje_contenido', 'Ingeniería genética', 'Identificación de estrategias de conservación de la biodiversidad en sus diferentes escalas (ecosistemas, poblaciones, genes); bancos genéticos, colecciones vivas y otros.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(67, 'eje_contenido', 'Implicancias ecológicas, sociales y éticas de la biotecnología', 'Reconocimiento de la utilización de la Biotecnología en el ambiente; por ejemplo, para el tratamiento de residuos, eliminación de metales pesados, contaminación producida por herbicidas, pesticidas e insecticidas, etc.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(67, 'eje_contenido', 'Implicancias ecológicas, sociales y éticas de la biotecnología', 'Aproximación a las nociones de bioseguridad; riesgos ambientales en los cultivos transgénicos. La evaluación de riesgos para los agroecosistemas.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(67, 'eje_contenido', 'Implicancias ecológicas, sociales y éticas de la biotecnología', 'Reflexión acerca del impacto de los productos y procesos derivados de la ingeniería genética sobre la salud y el ambiente, y sus aspectos éticos.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 277-279'),
(68, 'eje_contenido', 'Producción Vegetal: Espacios de opción institucional - intencionalidad general', 'Estos espacios tienen la función de contextualizar, articular, profundizar y ampliar los aprendizajes y contenidos de la Formación Específica de cada Orientación.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Producción Vegetal: Espacios de opción institucional - intencionalidad', 'Este espacio ofrece la posibilidad de profundizar conocimientos en relación con las bases anátomo-morfológicas, fisiológicas y tecnológicas que sustentan un adecuado manejo de los sistemas de producción vegetal (por ejemplo, producción en viveros, producción hortícola, forestal, frutícola, ornamental).', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Producción Vegetal: Espacios de opción institucional - intencionalidad', 'Incorpora, además, conocimientos básicos sobre los procesos de comercialización de los productos obtenidos.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Producción Vegetal: Espacios de opción institucional - intencionalidad', 'Se propone, por otra parte, enfatizar la reflexión sobre el rol del hombre como transformador de los sistemas agroambientales de importancia regional.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Producción Vegetal: Espacios de opción institucional - ejes sugeridos', 'Modernas tecnologías agrícolas.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Producción Vegetal: Espacios de opción institucional - ejes sugeridos', 'Producciones convencionales y alternativas.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Producción Vegetal: Espacios de opción institucional - ejes sugeridos', 'Impacto ambiental de las producciones agrícolas.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Producción Vegetal: Espacios de opción institucional - ejes sugeridos', 'Procesos de comercialización.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Producción Animal: Espacios de opción institucional - intencionalidad general', 'Estos espacios tienen la función de contextualizar, articular, profundizar y ampliar los aprendizajes y contenidos de la Formación Específica de cada Orientación.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Producción Animal: Espacios de opción institucional - intencionalidad', 'Este espacio ofrece la posibilidad de profundizar las bases anátomo-morfológicas, fisiológicas y tecnológicas que sustentan un adecuado manejo de los sistemas de producción animal (por ejemplo, los sistemas de producción avícola, apícola, cunícula, de pequeños rumiantes, de bovinos).', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Producción Animal: Espacios de opción institucional - intencionalidad', 'Incorpora, además, conocimientos básicos sobre los procesos de comercialización de los productos obtenidos.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Producción Animal: Espacios de opción institucional - intencionalidad', 'Se propone, por otra parte, enfatizar la reflexión sobre el rol del hombre como transformador de los sistemas agroambientales de importancia regional.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Producción Animal: Espacios de opción institucional - ejes sugeridos', 'Modernas tecnologías en producción animal.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Producción Animal: Espacios de opción institucional - ejes sugeridos', 'Producciones convencionales y alternativas.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Producción Animal: Espacios de opción institucional - ejes sugeridos', 'Impacto ambiental de la producción animal.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Producción Animal: Espacios de opción institucional - ejes sugeridos', 'Procesos de comercialización.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Industrialización: Espacios de opción institucional - intencionalidad general', 'Estos espacios tienen la función de contextualizar, articular, profundizar y ampliar los aprendizajes y contenidos de la Formación Específica de cada Orientación.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Industrialización: Espacios de opción institucional - intencionalidad', 'Este espacio pretende la profundización en los procesos agro y foresto-industriales de importancia regional, la comprensión y explicación de problemáticas vinculadas con los principales productos, procesos y servicios agroindustriales y el reconocimiento de buenas prácticas aplicadas a la industrialización.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Industrialización: Espacios de opción institucional - ejes sugeridos', 'Modernas tecnologías de industrialización agroambiental.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Industrialización: Espacios de opción institucional - ejes sugeridos', 'Procesos agroindustriales.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Industrialización: Espacios de opción institucional - ejes sugeridos', 'Impacto ambiental de la industrialización.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Industrialización: Espacios de opción institucional - ejes sugeridos', 'Comercialización y marketing.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Ambiente, Desarrollo y Sociedad: Espacios de opción institucional - intencionalidad general', 'Estos espacios tienen la función de contextualizar, articular, profundizar y ampliar los aprendizajes y contenidos de la Formación Específica de cada Orientación.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Ambiente, Desarrollo y Sociedad: Espacios de opción institucional - ejes sugeridos', 'Agro, ambiente y sociedad.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Ambiente, Desarrollo y Sociedad: Espacios de opción institucional - ejes sugeridos', 'Desarrollo y soberanía alimentaria.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Ambiente, Desarrollo y Sociedad: Espacios de opción institucional - ejes sugeridos', 'Principales paradigmas productivos.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Ambiente, Desarrollo y Sociedad: Espacios de opción institucional - ejes sugeridos', 'Sistemas agroambientales y elementos socio-económico-culturales del contexto y otros estructurales que faciliten o dificulten el mejoramiento de la calidad de vida.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Ambiente, Desarrollo y Sociedad: Espacios de opción institucional - ejes sugeridos', 'Diseño de pautas de intervención agroambiental que recuperen criterios de desarrollo sustentable/sostenible.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Administración de Organizaciones Agroambientales: Espacios de opción institucional - intencionalidad general', 'Estos espacios tienen la función de contextualizar, articular, profundizar y ampliar los aprendizajes y contenidos de la Formación Específica de cada Orientación.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Administración de Organizaciones Agroambientales: Espacios de opción institucional - intencionalidad', 'Este espacio propone abordar saberes vinculados con el planeamiento, la organización, la coordinación, la dirección y el control de organizaciones agroambientales con la intención de que los estudiantes profundicen sobre la dinámica de su funcionamiento y puedan reconocer las relaciones que se establecen entre éstas y las comunidades de referencia.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Administración de Organizaciones Agroambientales: Espacios de opción institucional - intencionalidad', 'Es destacable el análisis de vínculos entre comercio y ambiente, reflexión sobre la viabilidad de proyectos considerando la economía y el ambiente, planificación de sistemas agroambientales, principios de sustentabilidad, gestión estratégica de pequeñas organizaciones agropecuarias, responsabilidad social de las organizaciones, exigencias de certificación, entre otras.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Administración de Organizaciones Agroambientales: Espacios de opción institucional - ejes sugeridos', 'Utilización racional de recursos naturales.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Administración de Organizaciones Agroambientales: Espacios de opción institucional - ejes sugeridos', 'Elaboración de productos derivados del agro.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Administración de Organizaciones Agroambientales: Espacios de opción institucional - ejes sugeridos', 'Desarrollo sustentable/sostenible de las organizaciones agro-ambientales.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287'),
(68, 'eje_contenido', 'Administración de Organizaciones Agroambientales: Espacios de opción institucional - ejes sugeridos', 'Responsabilidad social de las organizaciones.', 'diseno_2011_2015', 1, NULL, NULL, 'pp. 283-287');
